import { getDoc, getDocs, query, limit as fbLimit } from "firebase/firestore";
import { paths, SUMMARY_KEYS, ANALYSIS_KEYS } from "../../../db/paths";
import type { DiagnosticCheck, DiagnosticRunner } from "./types";

function firestorePath(boardId: string, kind: string, key: string) {
  return `boards/${boardId}/${kind}/${key}`;
}

export const runAiSearchDiagnostics: DiagnosticRunner = async (boardId) => {
  const results: DiagnosticCheck[] = [];

  const measurementPath = firestorePath(boardId, "summaries", SUMMARY_KEYS.measurement);
  let latestRunId: string | null = null;

  try {
    const snap = await getDoc(paths.summary(boardId, SUMMARY_KEYS.measurement));
    if (!snap.exists()) {
      results.push({ id: "ai-measurement", label: "summaries/measurement 문서 존재", status: "fail", detail: `[${measurementPath}] 측정 요약이 없습니다. V3 측정을 먼저 실행해주세요.` });
    } else {
      const data = snap.data() as any;
      latestRunId = data?.run?.id || null;
      const hasAnalysis = !!data?.analysis;
      const topKeys = Object.keys(data ?? {}).join(", ");
      results.push({ id: "ai-measurement", label: "summaries/measurement 문서 존재", status: "pass", detail: `[${measurementPath}] run.id: ${latestRunId ?? "N/A"}, analysis: ${hasAnalysis ? "있음" : "없음"}, top-keys: ${topKeys}` });

      // Show analysis top-level keys
      if (data?.analysis) {
        const analysisKeys = Object.keys(data.analysis).join(", ");
        results.push({ id: "ai-analysis-keys", label: "analysis 필드 목록", status: "pass", detail: `analysis.{${analysisKeys}}` });
      }

      // Check both locations for queryBreakdown
      const wrd = data?.analysis?.weeklyReportData;
      const qbFromWrd = wrd?.queryBreakdown || [];
      const qbFromTop = data?.analysis?.queryBreakdown || [];

      results.push({
        id: "ai-qb-source",
        label: "queryBreakdown 위치 확인",
        status: (qbFromWrd.length > 0 || qbFromTop.length > 0) ? "pass" : "fail",
        detail: `analysis.weeklyReportData.queryBreakdown: ${qbFromWrd.length}개, analysis.queryBreakdown: ${qbFromTop.length}개`,
      });

      // Use whichever has data (prefer top-level as it's the canonical source)
      const queryBreakdown = qbFromTop.length > 0 ? qbFromTop : qbFromWrd;

      results.push({ id: "ai-qb", label: "queryBreakdown (쿼리별 결과)", status: queryBreakdown.length > 0 ? "pass" : "fail", detail: `${queryBreakdown.length}개 쿼리 (source: ${qbFromTop.length > 0 ? "analysis.queryBreakdown" : "analysis.weeklyReportData.queryBreakdown"})` });

      if (queryBreakdown.length > 0) {
        // Dump first item's keys and values for debugging
        const sample = queryBreakdown[0];
        const sampleKeys = Object.keys(sample).join(", ");
        results.push({ id: "ai-qb-schema", label: "queryBreakdown[0] 필드 목록", status: "pass", detail: `{${sampleKeys}}` });

        // Show first item's actual values
        const sampleValues = Object.entries(sample)
          .map(([k, v]) => `${k}: ${JSON.stringify(v)}`)
          .join(" | ");
        results.push({ id: "ai-qb-sample", label: "queryBreakdown[0] 실제 값", status: "pass", detail: sampleValues });

        // Check gptRate / geminiRate
        const qbSource = qbFromTop.length > 0 ? "analysis.queryBreakdown" : "analysis.weeklyReportData.queryBreakdown";
        const qbPath = `[${measurementPath}] → ${qbSource}`;
        const gptMentioned = queryBreakdown.filter((q: any) => (q.gptRate ?? 0) > 0).length;
        const geminiMentioned = queryBreakdown.filter((q: any) => (q.geminiRate ?? 0) > 0).length;
        results.push({ id: "ai-qb-gpt", label: "GPT 언급 쿼리 (gptRate > 0)", status: gptMentioned > 0 ? "pass" : "warn", detail: `${gptMentioned}/${queryBreakdown.length}개 — ${qbPath}` });
        results.push({ id: "ai-qb-gemini", label: "Gemini 언급 쿼리 (geminiRate > 0)", status: geminiMentioned > 0 ? "pass" : "warn", detail: `${geminiMentioned}/${queryBreakdown.length}개 — ${qbPath}` });
      }
    }
  } catch (err: any) {
    results.push({ id: "ai-measurement", label: "summaries/measurement 조회", status: "fail", detail: `[${measurementPath}] 에러: ${err.message}` });
  }

  // analyses/ai-search
  const aiSearchPath = firestorePath(boardId, "analyses", ANALYSIS_KEYS.aiSearch);
  try {
    const snap = await getDoc(paths.analysis(boardId, ANALYSIS_KEYS.aiSearch));
    results.push({
      id: "ai-search-doc",
      label: "analyses/ai-search 문서 존재",
      status: snap.exists() ? "pass" : "warn",
      detail: snap.exists() ? `[${aiSearchPath}] keys: ${Object.keys(snap.data()!).slice(0, 8).join(", ")}` : `[${aiSearchPath}] AI 검색 분석 문서가 없습니다.`,
    });
  } catch (err: any) {
    results.push({ id: "ai-search-doc", label: "analyses/ai-search 조회", status: "fail", detail: `[${aiSearchPath}] 에러: ${err.message}` });
  }

  // measurement results (individual query results)
  if (latestRunId) {
    const resultsPath = `boards/${boardId}/analyses/v3/measurements/${latestRunId}/results`;
    try {
      const snap = await getDocs(query(paths.v3MeasurementResults(boardId, latestRunId), fbLimit(5)));
      let sampleDetail = "";
      if (snap.docs.length > 0) {
        const first = snap.docs[0].data() as any;
        sampleDetail = ` | sample keys: ${Object.keys(first).join(", ")}`;
      }
      results.push({
        id: "ai-results",
        label: `measurement results (run: ${latestRunId.slice(0, 8)}...)`,
        status: snap.docs.length > 0 ? "pass" : "warn",
        detail: `[${resultsPath}] ${snap.docs.length}개 샘플 조회 (limit 5)${sampleDetail}`,
      });
    } catch (err: any) {
      results.push({ id: "ai-results", label: "measurement results 조회", status: "fail", detail: `[${resultsPath}] 에러: ${err.message}` });
    }
  }

  return results;
};
