// @ts-nocheck — V3 측정 카드: 1000 calls 실제 측정 (GPT + Gemini), SSE 진행률, Claude 분석.
//   ClientV4Input 안에서 사용됨. 다른 메뉴는 영향 없음.
import { useEffect, useRef, useState } from "react";
import { useParams } from "react-router-dom";
import { useQuery, useQueryClient } from "@tanstack/react-query";
import {
  PlayCircle, Loader2, CheckCircle2, AlertTriangle, Clock, Cpu, Zap, BarChart3,
  ChevronDown, ChevronUp, RefreshCw, X,
} from "lucide-react";
import { v3MeasurementApi } from "./dataHub";
import { forceFailCommand } from "../../db/commands";
import { subscribeActiveV3Run } from "../../db/portalV3";
import type { RunDoc } from "../../db/collections";

const isDev = import.meta.env.DEV;
const SAMPLE_OPTIONS = isDev ? [2, 30, 50, 80] : [30, 50, 80];
const DEFAULT_SAMPLE_COUNT = isDev ? 2 : 50;

const DAY_LABELS = ["일", "월", "화", "수", "목", "금", "토"];
const STATUS_LABEL: Record<string, string> = {
  pending: "대기 중",
  running: "측정 중",
  analyzing: "분석 중",
  complete: "완료",
  partial: "부분 완료",
  failed: "실패",
};
const STATUS_TONE: Record<string, string> = {
  pending: "text-amber-300",
  running: "text-blue-300",
  analyzing: "text-teal-300",
  complete: "text-emerald-300",
  partial: "text-amber-300",
  failed: "text-red-300",
};

export function V3MeasurementCard() {
  const { id: onboardingId } = useParams<{ id: string }>();
  const qc = useQueryClient();

  // 현재 활성 run (running/analyzing 상태)
  const [activeRunId, setActiveRunId] = useState<string | null>(null);
  const activeRunIdRef = useRef(activeRunId);
  activeRunIdRef.current = activeRunId;
  const [progress, setProgress] = useState<{ completed: number; failed: number; total: number; status: string; message: string } | null>(null);
  const [showHistory, setShowHistory] = useState(false);
  // ★ Step 4 — SSE 재접속 상태
  const [reconnectState, setReconnectState] = useState<{ attempt: number; max: number } | null>(null);
  const [giveUp, setGiveUp] = useState(false);
  // ★ Stuck 감지 — progress 가 3분 이상 변하지 않으면 stuck 으로 판단
  const [stuckSince, setStuckSince] = useState<number | null>(null);
  const [lastSeenCompleted, setLastSeenCompleted] = useState<number>(-1);
  const [forceCompleting, setForceCompleting] = useState(false);
  // ★ 재분석 상태 + 결과
  const [sampleCount, setSampleCount] = useState(DEFAULT_SAMPLE_COUNT);
  const [reanalyzing, setReanalyzing] = useState(false);
  const [reanalyzeResult, setReanalyzeResult] = useState<any>(null);
  const [reanalyzeError, setReanalyzeError] = useState<string | null>(null);
  const [showReanalyzeLogs, setShowReanalyzeLogs] = useState(false);

  // 최신 done analysis + 스케줄
  const latestQ = useQuery({
    queryKey: ["portalV3", "v3-latest", onboardingId],
    queryFn: () => v3MeasurementApi.getLatest(onboardingId!),
    enabled: !!onboardingId,
    refetchInterval: activeRunId ? false : 30_000,
  });
  const scheduleQ = useQuery({
    queryKey: ["portalV3", "v3-schedule", onboardingId],
    queryFn: () => v3MeasurementApi.getSchedule(onboardingId!),
    enabled: !!onboardingId,
  });
  const runsQ = useQuery({
    queryKey: ["portalV3", "v3-runs", onboardingId],
    queryFn: () => v3MeasurementApi.listRuns(onboardingId!, 10),
    enabled: !!onboardingId,
    refetchInterval: activeRunId ? 10_000 : false,
  });

  // Firestore 실시간 리스너 — running/analyzing run 을 즉시 감지
  // 초기 로딩이 끝났는지 구분하기 위해 activeRunChecked 플래그 사용
  const [activeRunChecked, setActiveRunChecked] = useState(false);
  useEffect(() => {
    if (!onboardingId) return;
    setActiveRunChecked(false);
    const unsub = subscribeActiveV3Run(onboardingId, (run) => {
      setActiveRunChecked(true);
      if (run && !activeRunIdRef.current) {
        setActiveRunId(run.id);
        setProgress({
          completed: run.completedItems ?? 0,
          failed: run.failedItems ?? 0,
          total: run.totalItems ?? 0,
          status: run.status,
          message: STATUS_LABEL[run.status] || run.status,
        });
      }
    });
    return () => unsub();
  }, [onboardingId]);

  // SSE 연결 (자동 재접속 포함)
  useEffect(() => {
    if (!activeRunId) return;
    setReconnectState(null);
    setGiveUp(false);

    const ctl = v3MeasurementApi.connectStream(onboardingId!, activeRunId, {
      onStarted: (e) => {
        setProgress((p) => ({
          completed: 0, failed: 0,
          total: e.data?.total ?? p?.total ?? 0,
          status: "running",
          message: e.data?.message || "측정 시작",
        }));
      },
      onProgress: (data) => {
        setProgress((p) => ({
          completed: data.completed,
          failed: data.failed,
          total: data.total,
          status: p?.status || "running",
          message: `${data.completed} / ${data.total} 완료${data.failed > 0 ? ` (실패 ${data.failed})` : ""}`,
        }));
      },
      onMeasurementDone: (e) => {
        setProgress((p) => p ? { ...p, status: "analyzing", message: "Claude 분석 시작..." } : null);
      },
      onAnalyzing: () => {
        setProgress((p) => p ? { ...p, status: "analyzing", message: "강점/약점/감성 분석 중..." } : null);
      },
      onAnalysisDone: () => {
        setProgress((p) => p ? { ...p, status: "complete", message: "완료" } : null);
        setTimeout(() => {
          setActiveRunId(null);
          setProgress(null);
          setReconnectState(null);
          qc.invalidateQueries({ queryKey: ["portalV3", "v3-latest", onboardingId] });
          qc.invalidateQueries({ queryKey: ["portalV3", "v3-runs", onboardingId] });
        }, 2000);
      },
      onFailed: (e) => {
        setProgress((p) => p ? { ...p, status: "failed", message: e.data?.error || "측정 실패" } : null);
        setTimeout(() => {
          setActiveRunId(null);
          setReconnectState(null);
          qc.invalidateQueries({ queryKey: ["portalV3", "v3-runs", onboardingId] });
        }, 3000);
      },
      onReconnecting: (attempt, max) => {
        setReconnectState({ attempt, max });
      },
      onReconnected: () => {
        setReconnectState(null);
      },
      onGiveUp: () => {
        setReconnectState(null);
        setGiveUp(true);
      },
      onClosed: () => {
        // SSE stream 자체가 종료됐을 때
      },
    });
    return () => ctl.close();
  }, [activeRunId, onboardingId, qc]);

  // ★ Stuck detection — progress 가 3분 이상 변하지 않으면 stuck 판정
  useEffect(() => {
    if (!activeRunId || !progress) {
      setStuckSince(null);
      setLastSeenCompleted(-1);
      return;
    }
    if (progress.status === "complete" || progress.status === "failed") {
      setStuckSince(null);
      return;
    }
    const currentDone = progress.completed + progress.failed;
    if (currentDone !== lastSeenCompleted) {
      setLastSeenCompleted(currentDone);
      setStuckSince(Date.now());
    }
  }, [activeRunId, progress, lastSeenCompleted]);

  const STUCK_THRESHOLD_MS = 3 * 60 * 1000;
  const isStuck = !!(stuckSince && activeRunId && progress
    && progress.status !== "complete" && progress.status !== "failed"
    && (Date.now() - stuckSince) > STUCK_THRESHOLD_MS);

  // Re-render every 30s to update stuck detection
  const [, setTick] = useState(0);
  useEffect(() => {
    if (!activeRunId) return;
    const t = setInterval(() => setTick((n) => n + 1), 30_000);
    return () => clearInterval(t);
  }, [activeRunId]);

  const handleForceComplete = async () => {
    if (!onboardingId || !activeRunId) return;
    if (!confirm(
      "현재 측정을 강제로 중단합니다.\n\n" +
      `완료된 ${progress?.completed ?? 0}/${progress?.total ?? 0}건의 결과는 저장되지 않습니다.\n` +
      "중단 후 새로 측정을 시작할 수 있습니다.\n\n진행할까요?"
    )) return;

    setForceCompleting(true);
    try {
      await forceFailCommand(onboardingId, activeRunId);
      setActiveRunId(null);
      setProgress(null);
      setStuckSince(null);
      qc.invalidateQueries({ queryKey: ["portalV3", "v3-runs", onboardingId] });
      qc.invalidateQueries({ queryKey: ["portalV3", "v3-latest", onboardingId] });
    } catch (err: any) {
      alert(`강제 종료 실패: ${err?.message || err}`);
    } finally {
      setForceCompleting(false);
    }
  };

  const handleStart = async () => {
    if (!onboardingId || activeRunId) return;
    try {
      const result = await v3MeasurementApi.start(onboardingId, {
        engines: ["gpt", "gemini"],
        sampleCount,
      });
      setActiveRunId(result.runId);
      setProgress({
        completed: 0,
        failed: 0,
        total: result.estimatedCalls,
        status: "pending",
        message: `${result.estimatedCalls} calls 대기 중... (예상 ${result.estimatedDurationMin}분)`,
      });
      qc.invalidateQueries({ queryKey: ["portalV3", "v3-runs", onboardingId] });
    } catch (err: any) {
      const msg = err?.message || "측정 시작 실패";
      if (msg.includes("NO_QUERIES")) {
        alert("고객 인풋의 must-win 쿼리를 먼저 입력하고 저장해주세요.");
      } else if (msg.includes("ALREADY_RUNNING")) {
        alert("이미 측정이 진행 중입니다.");
      } else {
        alert(`측정 시작 실패: ${msg}`);
      }
    }
  };

  const latest = latestQ.data;
  const schedule = scheduleQ.data?.schedule;
  const runs = runsQ.data?.runs || [];
  const totalCalls = 10 * 2 * sampleCount;

  const progressPct = progress && progress.total > 0
    ? Math.round((progress.completed / progress.total) * 100)
    : 0;

  return (
    <section className="rounded-2xl border-2 border-[var(--shell-accent)]/30 bg-[var(--shell-accent)]/5 p-5">
      {/* Header */}
      <div className="mb-4">
        <div className="flex items-center gap-2 text-sm font-semibold text-[var(--shell-text)]">
          <span className="text-amber-300">⭐</span> 측정 설정 — 실제 {totalCalls.toLocaleString()} calls (GPT + Gemini)
        </div>
        <div className="mt-1 text-[11px] leading-5 text-[var(--shell-text-muted)]">
          위에 입력한 쿼리 (최대 10개) × GPT + Gemini × {sampleCount}회 = {totalCalls.toLocaleString()} calls 를 실제로 실행합니다.
          결과는 Claude 로 분석해 강점·약점·중립·감성 분포를 자동 추출합니다.
        </div>
      </div>

      {/* 고정 설정 표시 */}
      <div className="grid gap-3 sm:grid-cols-4">
        <SettingDisplay icon={<Clock className="h-3.5 w-3.5" />} label="측정 주기" value="매주 자동 + 즉시 측정" />
        <div className="rounded-lg border border-[var(--shell-border)] bg-[var(--shell-panel)]/50 px-3 py-2">
          <div className="flex items-center gap-1 text-[10px] uppercase tracking-wider text-[var(--shell-text-soft)]">
            <Zap className="h-3.5 w-3.5" /> 샘플 수
          </div>
          <select
            value={sampleCount}
            onChange={(e) => setSampleCount(Number(e.target.value))}
            disabled={!!activeRunId}
            className="mt-1 w-full rounded border border-[var(--shell-border)] bg-[var(--shell-panel)] px-1.5 py-0.5 text-xs font-medium text-[var(--shell-text)] disabled:opacity-50"
          >
            {SAMPLE_OPTIONS.map((n) => (
              <option key={n} value={n}>엔진당 {n}회</option>
            ))}
          </select>
        </div>
        <SettingDisplay icon={<Cpu className="h-3.5 w-3.5" />} label="AI 엔진" value="GPT + Gemini" />
        <SettingDisplay icon={<BarChart3 className="h-3.5 w-3.5" />} label="분석 모델" value="Claude Haiku" />
      </div>

      {/* 자동 실행 스케줄 설정 (편집 가능) */}
      <V4ScheduleEditor onboardingId={onboardingId!} schedule={schedule} onUpdated={() => scheduleQ.refetch()} />

      {/* 즉시 측정 + 진행률 */}
      <div className="mt-4">
        {!activeRunId && !activeRunChecked && (
          <div className="flex w-full items-center justify-center gap-2 rounded-xl border border-[var(--shell-border)] bg-[var(--shell-panel)]/50 py-3 text-sm text-[var(--shell-text-muted)]">
            <Loader2 className="h-4 w-4 animate-spin" />
            측정 상태 확인 중...
          </div>
        )}
        {!activeRunId && activeRunChecked && (
          <button
            type="button"
            onClick={handleStart}
            disabled={!onboardingId}
            className="flex w-full items-center justify-center gap-2 rounded-xl bg-[var(--shell-accent)] py-3 text-sm font-medium text-white hover:opacity-90 disabled:opacity-50"
          >
            <PlayCircle className="h-5 w-5" />
            지금 즉시 측정 시작 ({totalCalls.toLocaleString()} calls)
          </button>
        )}

        {activeRunId && progress && (
          <div className="rounded-xl border border-[var(--shell-border)] bg-[var(--shell-panel)] p-4">
            <div className="flex items-center justify-between gap-3">
              <div className="flex items-center gap-2 text-sm font-medium text-[var(--shell-text)]">
                {progress.status === "failed" ? (
                  <AlertTriangle className="h-4 w-4 text-red-400" />
                ) : progress.status === "complete" ? (
                  <CheckCircle2 className="h-4 w-4 text-emerald-400" />
                ) : (
                  <Loader2 className="h-4 w-4 animate-spin text-blue-300" />
                )}
                <span className={STATUS_TONE[progress.status] || ""}>
                  {STATUS_LABEL[progress.status] || progress.status}
                </span>
                <span className="text-[var(--shell-text-muted)]">— {progress.message}</span>
              </div>
              <div className="text-sm font-mono text-[var(--shell-text-muted)]">
                {progress.completed} / {progress.total}
              </div>
            </div>
            <div className="mt-2.5 h-2 overflow-hidden rounded-full bg-[var(--shell-panel-soft)]">
              <div
                className={`h-full transition-all duration-300 ${
                  progress.status === "failed" ? "bg-red-400" :
                  progress.status === "complete" ? "bg-emerald-400" :
                  progress.status === "analyzing" ? "bg-teal-400" :
                  "bg-blue-400"
                }`}
                style={{ width: `${progressPct}%` }}
              />
            </div>
            <div className="mt-1.5 flex justify-between text-[10px] text-[var(--shell-text-soft)]">
              <span>{progressPct}%</span>
              {progress.failed > 0 && <span className="text-red-300">실패 {progress.failed}건</span>}
            </div>

            {/* ★ Step 4 — SSE 재접속 상태 */}
            {reconnectState && (
              <div className="mt-2 flex items-center gap-1.5 rounded-lg border border-amber-500/30 bg-amber-500/5 px-2.5 py-1.5 text-[10px] text-amber-300">
                <Loader2 className="h-3 w-3 animate-spin" />
                <span>연결 끊김 — 재접속 시도 중 ({reconnectState.attempt}/{reconnectState.max})... 측정은 백엔드에서 계속 진행됩니다.</span>
              </div>
            )}
            {giveUp && (
              <div className="mt-2 flex items-center gap-1.5 rounded-lg border border-red-500/30 bg-red-500/5 px-2.5 py-1.5 text-[10px] text-red-300">
                <AlertTriangle className="h-3 w-3" />
                <span>실시간 연결 실패 — 측정은 백엔드에서 계속 진행됩니다. 잠시 후 페이지를 새로고침해주세요.</span>
              </div>
            )}

            {/* Stuck 감지 경고 + 강제 종료 버튼 */}
            {isStuck && (
              <div className="mt-2 rounded-lg border border-amber-500/30 bg-amber-500/5 p-3">
                <div className="flex items-start gap-2">
                  <AlertTriangle className="mt-0.5 h-4 w-4 shrink-0 text-amber-400" />
                  <div className="flex-1">
                    <div className="text-xs font-medium text-amber-300">
                      측정이 {Math.floor((Date.now() - (stuckSince || 0)) / 60_000)}분 이상 멈춰 있습니다
                    </div>
                    <div className="mt-1 text-[10px] text-amber-200/70">
                      {progress?.completed}/{progress?.total} 완료 후 진행되지 않고 있습니다.
                      백엔드에서 API 호출이 타임아웃되었을 수 있습니다.
                    </div>
                    <button
                      type="button"
                      onClick={handleForceComplete}
                      disabled={forceCompleting}
                      className="mt-2 flex items-center gap-1.5 rounded-lg border border-red-500/40 bg-red-500/10 px-3 py-1.5 text-[11px] font-medium text-red-300 hover:bg-red-500/20 disabled:opacity-50"
                    >
                      {forceCompleting ? <Loader2 className="h-3 w-3 animate-spin" /> : <X className="h-3 w-3" />}
                      {forceCompleting ? "강제 종료 중..." : "측정 강제 종료"}
                    </button>
                  </div>
                </div>
              </div>
            )}
          </div>
        )}
      </div>

      {/* 최신 분석 결과 미리보기 */}
      {!activeRunId && latest?.analysis && (
        <div className="mt-4 rounded-xl border border-emerald-500/30 bg-emerald-500/5 p-4">
          <div className="flex flex-wrap items-center justify-between gap-2">
            <div className="flex items-center gap-2 text-xs font-medium text-emerald-300">
              <CheckCircle2 className="h-3.5 w-3.5" /> 최신 측정 결과
              <span className="text-[var(--shell-text-soft)]">
                ({new Date(latest.run!.completedAt!).toLocaleString()})
              </span>
            </div>
            {/* ★ 재분석 버튼 */}
            <button
              type="button"
              disabled={reanalyzing}
              onClick={async () => {
                if (!confirm(
                  "기존 측정 답변을 그대로 두고, 현재 브랜드 정보 (별칭/경쟁사 도메인 등) 로 다시 매칭 + Claude 재분석합니다.\n\n새 측정 API 호출은 없습니다 (비용 0).\n약 30초 ~ 1분 소요."
                )) return;
                setReanalyzing(true);
                setReanalyzeResult(null);
                setReanalyzeError(null);
                setShowReanalyzeLogs(false);
                try {
                  const result = await v3MeasurementApi.reanalyze(onboardingId!, latest.run!.id);
                  setReanalyzeResult(result);
                  qc.invalidateQueries({ queryKey: ["portalV3", "v3-latest", onboardingId] });
                  qc.invalidateQueries({ queryKey: ["portalV3", "v3-runs", onboardingId] });
                  qc.invalidateQueries({ queryKey: ["portalV3", "v3-run-results"] });
                } catch (err: any) {
                  setReanalyzeError(`재분석 실패: ${err?.message || err}`);
                } finally {
                  setReanalyzing(false);
                }
              }}
              className="flex items-center gap-1.5 rounded-lg border border-emerald-500/40 bg-emerald-500/10 px-3 py-1.5 text-[11px] font-medium text-emerald-300 hover:bg-emerald-500/20 disabled:opacity-50"
              title="현재 브랜드 정보로 기존 측정 답변을 다시 매칭. 새 측정 비용 없음."
            >
              {reanalyzing ? <Loader2 className="h-3.5 w-3.5 animate-spin" /> : <RefreshCw className="h-3.5 w-3.5" />}
              {reanalyzing ? "재분석 중... (30초~1분)" : "재분석 (별칭 반영)"}
            </button>
          </div>
          <div className="mt-2.5 grid gap-3 sm:grid-cols-3">
            <Metric label="자사 언급률" value={`${parseFloat(latest.analysis.brandMentionRate).toFixed(1)}%`} sub={`${latest.analysis.brandMentionCount} / ${latest.run?.totalItems ?? "?"} 답변`} />
            <Metric label="GPT 언급률" value={`${(latest.analysis.engineBreakdown?.gpt?.rate || 0).toFixed(1)}%`} sub={`${latest.analysis.engineBreakdown?.gpt?.count || 0}/${latest.analysis.engineBreakdown?.gpt?.total || 0}`} />
            <Metric label="Gemini 언급률" value={`${(latest.analysis.engineBreakdown?.gemini?.rate || 0).toFixed(1)}%`} sub={`${latest.analysis.engineBreakdown?.gemini?.count || 0}/${latest.analysis.engineBreakdown?.gemini?.total || 0}`} />
          </div>
          <div className="mt-3 text-[11px] text-[var(--shell-text-muted)]">
            강점 Top: {latest.analysis.strengths?.[0]?.point || "-"} ({latest.analysis.strengths?.[0]?.count || 0}회) ·
            약점 Top: {latest.analysis.weaknesses?.[0]?.point || "-"} ({latest.analysis.weaknesses?.[0]?.count || 0}회) ·
            경쟁사 1위: {latest.analysis.competitorBreakdown?.[0]?.name || "-"} ({latest.analysis.competitorBreakdown?.[0]?.count || 0}회)
          </div>
          {/* ★ 재분석 진행 중 표시 */}
          {reanalyzing && (
            <div className="mt-3 rounded-lg border border-blue-500/30 bg-blue-500/5 p-3 text-[11px]">
              <div className="flex items-center gap-2 text-blue-300">
                <Loader2 className="h-3.5 w-3.5 animate-spin" />
                <span className="font-medium">재분석 진행 중...</span>
              </div>
              <ul className="mt-1.5 space-y-0.5 text-[10px] text-[var(--shell-text-muted)] pl-5">
                <li>1/4 — brand 컨텍스트 로드 (자사 별칭 + 경쟁사 도메인 등)</li>
                <li>2/4 — 기존 답변 {latest.run?.totalItems || 1000}건 로드</li>
                <li>3/4 — 키워드 매칭 다시 실행 (보통 5-10초)</li>
                <li>4/4 — Claude 종합 분석 (강점/약점/감성, 보통 15-40초)</li>
              </ul>
              <div className="mt-1.5 text-[10px] text-blue-200/70 pl-5">
                보통 30초~1분 소요. 페이지를 떠나도 백엔드에서 계속 처리됩니다.
              </div>
            </div>
          )}

          {/* ★ 재분석 결과 카드 */}
          {reanalyzeResult && (
            <div className="mt-3 rounded-xl border border-emerald-500/40 bg-emerald-500/5 p-3.5">
              <div className="flex items-start justify-between gap-2">
                <div className="flex items-center gap-2 text-xs font-semibold text-emerald-300">
                  <CheckCircle2 className="h-4 w-4" /> 재분석 완료 ({(reanalyzeResult.durationMs / 1000).toFixed(1)}초)
                </div>
                <button
                  onClick={() => setReanalyzeResult(null)}
                  className="rounded p-0.5 text-[var(--shell-text-soft)] hover:bg-[var(--shell-panel-soft)] hover:text-[var(--shell-text)]"
                >
                  <X className="h-3.5 w-3.5" />
                </button>
              </div>
              <div className="mt-2 text-[11px] text-[var(--shell-text-muted)]">{reanalyzeResult.message}</div>
              <div className="mt-3 grid grid-cols-3 gap-2 text-[11px]">
                <div className="rounded-lg border border-[var(--shell-border)] bg-[var(--shell-panel)] p-2.5">
                  <div className="text-[9px] uppercase tracking-wider text-[var(--shell-text-soft)]">Before</div>
                  <div className="mt-1 text-lg font-mono font-semibold text-[var(--shell-text-muted)]">
                    {reanalyzeResult.stats.before.brandMentionRate.toFixed(1)}%
                  </div>
                  <div className="text-[10px] text-[var(--shell-text-soft)]">
                    {reanalyzeResult.stats.before.brandMentionCount} / {reanalyzeResult.stats.before.total}
                  </div>
                </div>
                <div className="rounded-lg border border-emerald-500/40 bg-emerald-500/10 p-2.5">
                  <div className="text-[9px] uppercase tracking-wider text-emerald-300/80">After</div>
                  <div className="mt-1 text-lg font-mono font-semibold text-emerald-300">
                    {reanalyzeResult.stats.after.brandMentionRate.toFixed(1)}%
                  </div>
                  <div className="text-[10px] text-emerald-300/80">
                    {reanalyzeResult.stats.after.brandMentionCount} / {reanalyzeResult.stats.after.total}
                  </div>
                </div>
                <div className={`rounded-lg border p-2.5 ${
                  reanalyzeResult.stats.delta.ratePct > 0.1 ? "border-emerald-500/40 bg-emerald-500/10" :
                  reanalyzeResult.stats.delta.ratePct < -0.1 ? "border-red-500/40 bg-red-500/10" :
                  "border-[var(--shell-border)] bg-[var(--shell-panel)]"
                }`}>
                  <div className="text-[9px] uppercase tracking-wider text-[var(--shell-text-soft)]">Δ Delta</div>
                  <div className={`mt-1 text-lg font-mono font-semibold ${
                    reanalyzeResult.stats.delta.ratePct > 0.1 ? "text-emerald-300" :
                    reanalyzeResult.stats.delta.ratePct < -0.1 ? "text-red-300" :
                    "text-[var(--shell-text-muted)]"
                  }`}>
                    {reanalyzeResult.stats.delta.ratePct > 0 ? "+" : ""}{reanalyzeResult.stats.delta.ratePct.toFixed(1)}%p
                  </div>
                  <div className="text-[10px] text-[var(--shell-text-soft)]">
                    {reanalyzeResult.stats.delta.count > 0 ? "+" : ""}{reanalyzeResult.stats.delta.count}건
                  </div>
                </div>
              </div>
              <div className="mt-2 flex flex-wrap gap-3 text-[10px] text-[var(--shell-text-soft)]">
                <span>↑ 미언급→언급: <span className="text-emerald-300">+{reanalyzeResult.stats.delta.flippedToMentioned}건</span></span>
                <span>↓ 언급→미언급: <span className="text-red-300">−{reanalyzeResult.stats.delta.flippedToNotMentioned}건</span></span>
                <span>자사 표기 {reanalyzeResult.brandNames.length}개 사용</span>
              </div>
              <div className="mt-2 flex flex-wrap gap-1">
                {reanalyzeResult.brandNames.map((n: string, i: number) => (
                  <span key={i} className="rounded-full border border-[var(--shell-border)] bg-[var(--shell-panel)] px-2 py-0.5 text-[9px] text-[var(--shell-text)]">{n}</span>
                ))}
              </div>
              {Array.isArray(reanalyzeResult.logs) && reanalyzeResult.logs.length > 0 && (
                <div className="mt-3">
                  <button
                    onClick={() => setShowReanalyzeLogs(!showReanalyzeLogs)}
                    className="flex items-center gap-1 text-[10px] text-[var(--shell-text-muted)] hover:text-[var(--shell-text)]"
                  >
                    {showReanalyzeLogs ? <ChevronUp className="h-3 w-3" /> : <ChevronDown className="h-3 w-3" />}
                    단계별 로그 ({reanalyzeResult.logs.length}줄)
                  </button>
                  {showReanalyzeLogs && (
                    <pre className="mt-1.5 max-h-48 overflow-auto rounded-lg border border-[var(--shell-border)] bg-[var(--shell-panel)] p-2 text-[9px] font-mono leading-4 text-[var(--shell-text-muted)] whitespace-pre-wrap">
{reanalyzeResult.logs.join("\n")}
                    </pre>
                  )}
                </div>
              )}
              <div className="mt-2 text-[10px] text-[var(--shell-text-soft)]">
                💡 Dashboard / 분석 보고서 / 개선 방향 — 모두 새 수치로 자동 갱신됨.
              </div>
            </div>
          )}

          {reanalyzeError && (
            <div className="mt-3 flex items-start gap-2 rounded-lg border border-red-500/30 bg-red-500/5 px-3 py-2 text-[11px] text-red-300">
              <AlertTriangle className="mt-0.5 h-3.5 w-3.5 shrink-0" />
              <div className="flex-1">{reanalyzeError}</div>
              <button onClick={() => setReanalyzeError(null)} className="shrink-0 text-red-300/60 hover:text-red-300">
                <X className="h-3 w-3" />
              </button>
            </div>
          )}
        </div>
      )}

      {/* ★ 실패 진단 카드 — 최근 run 에 실패가 있으면 자동 표시 */}
      {!activeRunId && runs.length > 0 && (runs[0].failedItems ?? 0) > 0 && (
        <V4ErrorDiagnostic
          boardId={onboardingId!}
          runId={runs[0].id}
          totalFailed={runs[0].failedItems ?? 0}
          onRetry={() => {
            v3MeasurementApi.retryFailed(onboardingId!).then((r) => {
              setActiveRunId(r.runId);
              setProgress({
                completed: (runs[0].completedItems ?? 0) - (runs[0].failedItems ?? 0),
                failed: 0,
                total: runs[0].totalItems ?? 0,
                status: "running",
                message: `재시도 시작 — ${r.retryCount}건 재실행`,
              });
              qc.invalidateQueries({ queryKey: ["portalV3", "v3-runs", onboardingId] });
            }).catch((err: any) => {
              const msg = err?.message || "재시도 실패";
              if (msg.includes("ALREADY_RUNNING")) {
                alert("이미 측정이 진행 중입니다.");
              } else if (msg.includes("NO_FAILED")) {
                alert("재시도할 실패 calls 가 없습니다.");
              } else {
                alert(`재시도 실패: ${msg}`);
              }
            });
          }}
        />
      )}

      {/* 과거 실행 이력 */}
      {runs.length > 0 && (
        <div className="mt-4">
          <button
            type="button"
            onClick={() => setShowHistory(!showHistory)}
            className="flex w-full items-center justify-between rounded-lg border border-[var(--shell-border)] bg-[var(--shell-panel)]/50 px-3 py-2 text-xs text-[var(--shell-text-muted)] hover:text-[var(--shell-text)]"
          >
            <span>최근 측정 이력 ({runs.length})</span>
            {showHistory ? <ChevronUp className="h-3.5 w-3.5" /> : <ChevronDown className="h-3.5 w-3.5" />}
          </button>
          {showHistory && (
            <ul className="mt-2 space-y-1">
              {runs.map((r: RunDoc) => (
                <li key={r.id} className="flex items-center justify-between rounded-lg border border-[var(--shell-border)] bg-[var(--shell-panel-soft)] px-3 py-2 text-[11px]">
                  <div className="flex items-center gap-2">
                    <span className={STATUS_TONE[r.status] || ""}>{STATUS_LABEL[r.status] || r.status}</span>
                    <span className="text-[var(--shell-text)]">{r.completedItems ?? 0}/{r.totalItems ?? 0}</span>
                  </div>
                  <span className="text-[var(--shell-text-soft)]">
                    {r.completedAt ? new Date(r.completedAt).toLocaleString() : new Date(r.startedAt).toLocaleString()}
                  </span>
                </li>
              ))}
            </ul>
          )}
        </div>
      )}
    </section>
  );
}

function V4ErrorDiagnostic({ boardId, runId, totalFailed, onRetry }: { boardId: string; runId: string; totalFailed: number; onRetry?: () => void }) {
  const { data, isLoading } = useQuery({
    queryKey: ["portalV3", "v3-errors", boardId, runId],
    queryFn: () => v3MeasurementApi.getErrors(boardId, runId),
    staleTime: 60_000,
  });

  if (isLoading || !data) {
    return (
      <div className="mt-4 rounded-xl border border-amber-500/30 bg-amber-500/5 p-4">
        <div className="flex items-center gap-2 text-xs text-amber-300">
          <Loader2 className="h-3.5 w-3.5 animate-spin" /> 실패 {totalFailed}건 — 진단 정보 불러오는 중...
        </div>
      </div>
    );
  }

  const isCritical = data.diagnosis.severity === "critical";
  const tone = isCritical
    ? "border-red-500/40 bg-red-500/5 text-red-200"
    : "border-amber-500/30 bg-amber-500/5 text-amber-200";

  return (
    <div className={`mt-4 rounded-xl border p-4 ${tone}`}>
      <div className="flex items-start gap-2">
        <AlertTriangle className={`mt-0.5 h-4 w-4 shrink-0 ${isCritical ? "text-red-400" : "text-amber-400"}`} />
        <div className="min-w-0 flex-1">
          <div className="text-xs font-semibold">
            진단: {data.diagnosis.summary}
          </div>

          {/* 엔진별 카운트 */}
          <div className="mt-2 grid gap-2 sm:grid-cols-2">
            {Object.entries(data.byEngine).map(([engine, stats]) => {
              const allFailed = stats.failed === stats.total && stats.total > 0;
              return (
                <div
                  key={engine}
                  className={`rounded-lg border px-3 py-2 text-[11px] ${
                    allFailed ? "border-red-500/40 bg-red-500/10" : "border-[var(--shell-border)] bg-[var(--shell-panel)]/40"
                  }`}
                >
                  <div className="flex items-center justify-between">
                    <span className="font-semibold uppercase text-[var(--shell-text)]">{engine}</span>
                    <span className={allFailed ? "text-red-300" : "text-[var(--shell-text-muted)]"}>
                      {stats.failed === 0 ? (
                        <span className="text-emerald-300">정상 ({stats.done}/{stats.total})</span>
                      ) : stats.failed === stats.total ? (
                        <span className="text-red-300">전체 실패 ({stats.failed}/{stats.total})</span>
                      ) : (
                        <span>부분 실패 ({stats.failed}/{stats.total})</span>
                      )}
                    </span>
                  </div>
                </div>
              );
            })}
          </div>

          {/* 자동 진단 제안 */}
          {data.diagnosis.suggestions.length > 0 && (
            <ul className="mt-3 space-y-1.5 text-[11px]">
              {data.diagnosis.suggestions.map((s, i) => (
                <li key={i} className="flex gap-1.5">
                  <span className="shrink-0">→</span>
                  <span className="text-[var(--shell-text)]">{s}</span>
                </li>
              ))}
            </ul>
          )}

          {/* ★ 남은 횟수 재시도 버튼 — API 키 등을 고친 다음 누름 */}
          {onRetry && totalFailed > 0 && (
            <div className="mt-3 flex items-center gap-2 border-t border-current/20 pt-3">
              <button
                type="button"
                onClick={onRetry}
                className="flex items-center gap-1.5 rounded-lg bg-[var(--shell-accent)] px-3 py-1.5 text-xs font-medium text-white hover:opacity-90"
              >
                <PlayCircle className="h-3.5 w-3.5" />
                실패한 {totalFailed}건만 재시도
              </button>
              <span className="text-[10px] text-[var(--shell-text-muted)]">
                (전체 재시도 아님 — 이미 성공한 calls 는 유지)
              </span>
            </div>
          )}

          {/* 원본 에러 메시지 (상위 3개) */}
          {data.topErrors.length > 0 && (
            <details className="mt-3 text-[10px]">
              <summary className="cursor-pointer text-[var(--shell-text-soft)] hover:text-[var(--shell-text-muted)]">
                원본 에러 메시지 보기 ({data.topErrors.length}종)
              </summary>
              <ul className="mt-2 space-y-1.5">
                {data.topErrors.slice(0, 5).map((err, i) => (
                  <li key={i} className="rounded border border-[var(--shell-border)] bg-[var(--shell-panel)] px-2.5 py-1.5 font-mono">
                    <div className="flex items-center justify-between">
                      <span className="text-[var(--shell-text-soft)]">{err.engine.toUpperCase()}</span>
                      <span className="text-[var(--shell-text-muted)]">{err.count}건</span>
                    </div>
                    <div className="mt-1 break-all text-[var(--shell-text)]">{err.message}</div>
                  </li>
                ))}
              </ul>
            </details>
          )}
        </div>
      </div>
    </div>
  );
}

