// ─── V3 자동 측정 스케줄 편집 (default OFF + 토글/요일/시각) ──────────
function V4ScheduleEditor({ onboardingId, schedule, onUpdated }: {
  onboardingId: string;
  schedule: any | undefined;
  onUpdated: () => void;
}) {
  const [enabled, setEnabled] = useState(false);
  const [dayOfWeek, setDayOfWeek] = useState(1);  // 월요일
  const [hourOfDay, setHourOfDay] = useState(9);  // 09:00
  const [dirty, setDirty] = useState(false);
  const [saving, setSaving] = useState(false);
  const [saveMsg, setSaveMsg] = useState<{ ok: boolean; text: string } | null>(null);

  // server 상태 → 로컬 상태 동기화 (한 번)
  useEffect(() => {
    if (schedule) {
      setEnabled(!!schedule.enabled);
      setDayOfWeek(schedule.dayOfWeek ?? 1);
      setHourOfDay(schedule.hourOfDay ?? 9);
      setDirty(false);
    }
  }, [schedule]);

  const save = async () => {
    setSaving(true); setSaveMsg(null);
    try {
      await v3MeasurementApi.updateSchedule(onboardingId, { enabled, dayOfWeek, hourOfDay });
      setSaveMsg({ ok: true, text: "저장되었습니다." });
      setDirty(false);
      onUpdated();
      setTimeout(() => setSaveMsg(null), 2500);
    } catch (err: any) {
      setSaveMsg({ ok: false, text: err?.message || "저장 실패" });
    } finally {
      setSaving(false);
    }
  };

  if (!schedule) {
    return (
      <div className="mt-3 rounded-xl border border-[var(--shell-border)] bg-[var(--shell-panel)]/50 px-3 py-2 text-[11px] text-[var(--shell-text-muted)]">
        스케줄 정보 불러오는 중...
      </div>
    );
  }

  return (
    <div className="mt-3 rounded-xl border border-[var(--shell-border)] bg-[var(--shell-panel)]/50 p-3">
      {/* On/Off + 즉시 상태 */}
      <div className="flex flex-wrap items-center justify-between gap-3">
        <div className="flex items-center gap-3">
          <label className="flex cursor-pointer items-center gap-2 select-none">
            <input
              type="checkbox"
              checked={enabled}
              onChange={(e) => { setEnabled(e.target.checked); setDirty(true); }}
              className="h-4 w-4 rounded border-[var(--shell-border)]"
            />
            <span className="text-xs font-semibold text-[var(--shell-text)]">자동 측정 활성화</span>
          </label>
          {enabled ? (
            <span className="rounded-full bg-emerald-500/15 px-2 py-0.5 text-[10px] text-emerald-300">ON</span>
          ) : (
            <span className="rounded-full bg-neutral-500/15 px-2 py-0.5 text-[10px] text-neutral-400">OFF</span>
          )}
        </div>
        <div className="text-[10px] text-[var(--shell-text-soft)]">
          {!enabled && "체크 해제 상태 — 매주 자동 측정 안 됨"}
          {enabled && schedule.lastRunAt && `마지막 자동 실행: ${new Date(schedule.lastRunAt).toLocaleString()}`}
        </div>
      </div>

      {/* 활성 시: 요일 + 시각 + 다음 실행 */}
      {enabled && (
        <div className="mt-3 grid gap-2 sm:grid-cols-3">
          <label className="block">
            <div className="mb-1 text-[10px] uppercase tracking-wider text-[var(--shell-text-soft)]">측정 요일</div>
            <select
              value={dayOfWeek}
              onChange={(e) => { setDayOfWeek(Number(e.target.value)); setDirty(true); }}
              className="w-full rounded-lg border border-[var(--shell-border)] bg-[var(--shell-panel)] px-3 py-2 text-sm text-[var(--shell-text)]"
            >
              {DAY_LABELS.map((label, i) => (
                <option key={i} value={i}>{label}요일</option>
              ))}
            </select>
          </label>
          <label className="block">
            <div className="mb-1 text-[10px] uppercase tracking-wider text-[var(--shell-text-soft)]">측정 시각 (KST)</div>
            <select
              value={hourOfDay}
              onChange={(e) => { setHourOfDay(Number(e.target.value)); setDirty(true); }}
              className="w-full rounded-lg border border-[var(--shell-border)] bg-[var(--shell-panel)] px-3 py-2 text-sm text-[var(--shell-text)]"
            >
              {Array.from({ length: 24 }, (_, i) => (
                <option key={i} value={i}>{String(i).padStart(2, "0")}:00</option>
              ))}
            </select>
          </label>
          <div className="flex flex-col">
            <div className="mb-1 text-[10px] uppercase tracking-wider text-[var(--shell-text-soft)]">다음 자동 실행</div>
            <div className="flex-1 rounded-lg border border-[var(--shell-border)] bg-[var(--shell-panel-soft)] px-3 py-2 text-xs text-[var(--shell-text-muted)]">
              {schedule.nextRunAt
                ? new Date(schedule.nextRunAt).toLocaleString()
                : (dirty ? "저장 시 계산됨" : "—")}
            </div>
          </div>
        </div>
      )}

      {/* 저장 버튼 + 메시지 */}
      <div className="mt-3 flex items-center justify-between gap-3">
        <div className="text-[10px] text-[var(--shell-text-soft)]">
          {enabled
            ? `매주 ${DAY_LABELS[dayOfWeek]}요일 ${String(hourOfDay).padStart(2, "0")}:00 KST 에 1000 calls 자동 실행`
            : "자동 측정은 OFF 상태 — 위 체크박스를 켜고 요일/시각(KST)을 설정 후 '스케줄 저장'."}
        </div>
        <div className="flex items-center gap-2">
          {saveMsg && (
            <span className={`text-[11px] ${saveMsg.ok ? "text-emerald-300" : "text-red-300"}`}>
              {saveMsg.ok ? "✓ " : "⚠ "}{saveMsg.text}
            </span>
          )}
          <button
            type="button"
            onClick={save}
            disabled={saving || !dirty}
            className="flex items-center gap-1.5 rounded-lg bg-[var(--shell-accent)] px-3 py-1.5 text-xs font-medium text-white hover:opacity-90 disabled:opacity-40"
          >
            {saving && <Loader2 className="h-3 w-3 animate-spin" />}
            스케줄 저장
          </button>
        </div>
      </div>
    </div>
  );
}
