import { getDoc } from "firebase/firestore";
import { paths, ANALYSIS_KEYS, SUMMARY_KEYS } from "../../../db/paths";
import type { DiagnosticCheck, DiagnosticRunner } from "./types";

export const runWebsiteDiagnostics: DiagnosticRunner = async (boardId) => {
  const results: DiagnosticCheck[] = [];

  // analyses/website
  try {
    const snap = await getDoc(paths.analysis(boardId, ANALYSIS_KEYS.website));
    if (!snap.exists()) {
      results.push({ id: "web-analysis", label: "analyses/website 문서 존재", status: "fail", detail: "웹사이트 분석 결과가 없습니다. 측정이 완료된 후 생성됩니다." });
    } else {
      const data = snap.data() as any;
      results.push({ id: "web-analysis", label: "analyses/website 문서 존재", status: "pass", detail: `keys: ${Object.keys(data).slice(0, 8).join(", ")}` });

      // Lighthouse raw data: raw/v1/lighthouse/{desktop,mobile}
      for (const preset of ["desktop", "mobile"] as const) {
        try {
          const lhSnap = await getDoc(paths.rawLighthouse(boardId, preset));
          if (lhSnap.exists()) {
            const lh = lhSnap.data() as any;
            const scoreEntries = lh.scores
              ? Object.entries(lh.scores).map(([k, v]) => `${k}: ${v != null ? Math.round(Number(v) * 100) : "N/A"}`).join(", ")
              : "scores 필드 없음";
            results.push({ id: `web-lh-${preset}`, label: `Lighthouse ${preset}`, status: "pass", detail: `${scoreEntries} (url: ${lh.url || "N/A"})` });
          } else {
            results.push({ id: `web-lh-${preset}`, label: `Lighthouse ${preset}`, status: "warn", detail: `raw/v1/lighthouse/${preset} 문서 없음` });
          }
        } catch (e: any) {
          results.push({ id: `web-lh-${preset}`, label: `Lighthouse ${preset}`, status: "fail", detail: `조회 에러: ${e.message}` });
        }
      }

    }
  } catch (err: any) {
    results.push({ id: "web-analysis", label: "analyses/website 조회", status: "fail", detail: `에러: ${err.message}` });
  }

  // analyses/seo-audit — SEO/GEO 점수 및 검사 결과의 실제 저장소
  try {
    const snap = await getDoc(paths.analysis(boardId, ANALYSIS_KEYS.seoAudit));
    if (!snap.exists()) {
      results.push({ id: "web-seo-audit", label: "analyses/seo-audit 문서 존재", status: "warn", detail: "SEO 감사 결과가 없습니다." });
      results.push({ id: "web-seo", label: "SEO 검사 데이터", status: "warn", detail: "seo-audit 문서 없음 — 측정 완료 후 생성됩니다." });
      results.push({ id: "web-geo", label: "GEO 검사 데이터", status: "warn", detail: "seo-audit 문서 없음 — 측정 완료 후 생성됩니다." });
    } else {
      const d = snap.data() as any;
      results.push({ id: "web-seo-audit", label: "analyses/seo-audit 문서 존재", status: "pass", detail: `pages: ${d.pagesAnalyzed ?? "N/A"}, checks: ${d.checks?.length ?? 0}건, violations: ${d.violations?.length ?? 0}건` });

      const hasSeo = d.seoScore != null || d.checks?.length > 0;
      results.push({
        id: "web-seo",
        label: "SEO 검사 데이터",
        status: hasSeo ? "pass" : "warn",
        detail: hasSeo
          ? `seoScore: ${d.seoScore ?? "N/A"}, checks: ${d.checks?.length ?? 0}건, recommendations: ${d.recommendations?.length ?? 0}건`
          : "seoScore 및 checks 데이터 없음",
      });

      const hasGeo = d.geoScore != null;
      results.push({
        id: "web-geo",
        label: "GEO 검사 데이터",
        status: hasGeo ? "pass" : "warn",
        detail: hasGeo
          ? `geoScore: ${d.geoScore ?? "N/A"}, siteChecks: ${d.siteChecks ? `llmsTxt=${d.siteChecks.hasLlmsTxt}, robots=${d.siteChecks.hasRobotsTxt}` : "N/A"}`
          : "geoScore 데이터 없음",
      });
    }
  } catch (err: any) {
    results.push({ id: "web-seo-audit", label: "analyses/seo-audit 조회", status: "fail", detail: `에러: ${err.message}` });
  }

  // analyses/geo-strategy — GEO 전략 분석
  try {
    const snap = await getDoc(paths.analysis(boardId, ANALYSIS_KEYS.geoStrategy));
    if (snap.exists()) {
      const d = snap.data() as any;
      const hasStrategy = !!d.data?.strategy?.headline;
      results.push({ id: "web-geo-strategy", label: "GEO 전략 분석", status: hasStrategy ? "pass" : "warn", detail: hasStrategy ? `headline: ${d.data.strategy.headline}` : "전략 데이터 불완전" });
    } else {
      results.push({ id: "web-geo-strategy", label: "GEO 전략 분석", status: "warn", detail: "analyses/geo-strategy 문서 없음" });
    }
  } catch (err: any) {
    results.push({ id: "web-geo-strategy", label: "GEO 전략 분석 조회", status: "fail", detail: `에러: ${err.message}` });
  }

  // summaries/site-health + CrUX (Core Web Vitals 원본)
  try {
    const snap = await getDoc(paths.summary(boardId, SUMMARY_KEYS.siteHealth));
    if (!snap.exists()) {
      results.push({ id: "web-summary", label: "summaries/site-health 문서 존재", status: "warn", detail: "문서 없음. SEO 워커가 아직 실행되지 않았거나 실패했을 수 있습니다." });
      results.push({ id: "web-crux", label: "CrUX Core Web Vitals", status: "warn", detail: "site-health 문서 없음 — CrUX 데이터 확인 불가" });
    } else {
      const d = snap.data() as any;
      const inner = d.data ?? d;
      const score = inner.score;
      results.push({ id: "web-summary", label: "summaries/site-health 문서 존재", status: "pass", detail: `score: ${score ?? "N/A"}, keys: ${Object.keys(inner).join(", ")}` });

      const lcp = inner.lcp;
      const inp = inner.inp;
      const cls = inner.cls;
      const hasCrux = lcp != null || inp != null || cls != null;

      if (hasCrux) {
        results.push({
          id: "web-crux",
          label: "CrUX Core Web Vitals",
          status: "pass",
          detail: `LCP: ${lcp ?? "N/A"}, INP: ${inp ?? "N/A"}, CLS: ${cls ?? "N/A"}`,
        });
      } else {
        results.push({
          id: "web-crux",
          label: "CrUX Core Web Vitals",
          status: "warn",
          detail: "site-health 문서에 lcp/inp/cls 필드 없음. 원인: (1) PAGESPEED_API_KEY 시크릿 미설정, (2) 사이트 트래픽 부족으로 CrUX 데이터 미수집, (3) PageSpeed API 호출 실패. 서버 로그에서 '[seo] CrUX fetch failed' 확인 필요.",
        });
      }

      // CrUX 개별 필드 세부 체크
      for (const [key, label] of [["lcp", "LCP (Largest Contentful Paint)"], ["inp", "INP (Interaction to Next Paint)"], ["cls", "CLS (Cumulative Layout Shift)"]] as const) {
        const val = inner[key];
        results.push({
          id: `web-crux-${key}`,
          label: `CrUX ${label}`,
          status: val != null ? "pass" : "warn",
          detail: val != null ? `값: ${val}` : `${key} 없음`,
        });
      }
    }
  } catch (err: any) {
    results.push({ id: "web-summary", label: "summaries/site-health 조회", status: "fail", detail: `에러: ${err.message}` });
  }

  return results;
};
