import React, { ReactNode, useMemo } from 'react';
import {
  CacheEngine,
  LocalCacheContext,
  LocalCacheContextValue,
  CacheKey,
} from '../LocalCacheContext';

interface LocalCacheProviderProps {
  children: ReactNode;
}

export const LocalCacheProvider: React.FC<LocalCacheProviderProps> = ({ children }) => {
  const value: LocalCacheContextValue = useMemo(
    () => ({
      getString: (key) => CacheEngine.getValue<string>(key),
      setString: (key, v, customTTL) => CacheEngine.setValue(key, v, customTTL),

      getNumber: (key) => CacheEngine.getValue<number>(key),
      setNumber: (key, v, customTTL) => CacheEngine.setValue(key, v, customTTL),

      getBoolean: (key) => CacheEngine.getValue<boolean>(key),
      setBoolean: (key, v, customTTL) => CacheEngine.setValue(key, v, customTTL),

      getObject: <T = any,>(key: CacheKey) => CacheEngine.getValue<T>(key),
      setObject: <T = any,>(key: CacheKey, v: T, customTTL?: number | null) =>
        CacheEngine.setValue(key, v, customTTL),

      remove: (key) => CacheEngine.remove(key),
      clearAll: () => CacheEngine.clearAll(),

      isExpired: (key) => CacheEngine.isExpired(key),
      getCacheStatus: () => CacheEngine.getCacheStatus(),
      printCacheDebug: () => CacheEngine.printCacheDebug(),
    }),
    []
  );

  return <LocalCacheContext.Provider value={value}>{children}</LocalCacheContext.Provider>;
};

        
// ============================
// Static API (no React required)
// ============================
export const LocalCache = {
  getString: (key: CacheKey) => CacheEngine.getValue<string>(key),
  setString: (key: CacheKey, value: string, customTTL?: number | null) =>
    CacheEngine.setValue(key, value, customTTL),

  getNumber: (key: CacheKey) => CacheEngine.getValue<number>(key),
  setNumber: (key: CacheKey, value: number, customTTL?: number | null) =>
    CacheEngine.setValue(key, value, customTTL),

  getBoolean: (key: CacheKey) => CacheEngine.getValue<boolean>(key),
  setBoolean: (key: CacheKey, value: boolean, customTTL?: number | null) =>
    CacheEngine.setValue(key, value, customTTL),

  getObject: <T = any,>(key: CacheKey) => CacheEngine.getValue<T>(key),
  setObject: <T = any,>(key: CacheKey, value: T, customTTL?: number | null) =>
    CacheEngine.setValue(key, value, customTTL),

  remove: (key: CacheKey) => CacheEngine.remove(key),
  clearAll: () => CacheEngine.clearAll(),
};
