// @ts-nocheck — V3 측정 히스토리 다운로드 관리 카드
//   - done 상태 measurement runs 의 개별 CSV + 일괄 삭제
//   - 저장 한도 200개 표시
//   - 삭제 전 미리보기 모달 (단일/일괄 공용)
import { useMemo, useState } from "react";
import { useParams } from "react-router-dom";
import { useQuery, useQueryClient } from "@tanstack/react-query";
import {
  Download, Trash2, AlertTriangle, Loader2, CheckSquare, Square,
  FileSpreadsheet, Clock,
} from "lucide-react";
import { v3MeasurementApi } from "./dataHub";
import { V3DeletePreviewModal } from "./V3DeletePreviewModal";

export function V3HistoryDownloadCard() {
  const { id: onboardingId } = useParams<{ id: string }>();
  const qc = useQueryClient();

  const [selectedIds, setSelectedIds] = useState<Set<string>>(new Set());
  const [bulkBusy, setBulkBusy] = useState<"delete" | null>(null);
  const [rowBusy, setRowBusy] = useState<Record<string, "download" | "delete" | null>>({});
  const [errMsg, setErrMsg] = useState<string | null>(null);
  const [okMsg, setOkMsg] = useState<string | null>(null);
  const [deleteModal, setDeleteModal] = useState<{ runIds: string[]; mode: "single" | "bulk" } | null>(null);

  const runsQ = useQuery({
    queryKey: ["portalV3", "v3-runs-history", onboardingId],
    queryFn: () => v3MeasurementApi.listRuns(onboardingId!, 200),
    enabled: !!onboardingId,
    staleTime: 30_000,
  });
  const storageQ = useQuery({
    queryKey: ["portalV3", "v3-storage", onboardingId],
    queryFn: () => v3MeasurementApi.getStorageStats(onboardingId!),
    enabled: !!onboardingId,
    staleTime: 30_000,
  });

  const allRuns = runsQ.data?.runs || [];
  const doneRuns = useMemo(() => allRuns.filter((r) => r.status === "complete" || r.status === "done"), [allRuns]);
  const stats = storageQ.data;

  const allSelected = doneRuns.length > 0 && doneRuns.every((r) => selectedIds.has(r.id));
  const someSelected = selectedIds.size > 0;

  const toggleAll = () => {
    if (allSelected) setSelectedIds(new Set());
    else setSelectedIds(new Set(doneRuns.map((r) => r.id)));
  };

  const toggleOne = (runId: string) => {
    setSelectedIds((prev) => {
      const next = new Set(prev);
      if (next.has(runId)) next.delete(runId);
      else next.add(runId);
      return next;
    });
  };

  const clearMessages = () => { setErrMsg(null); setOkMsg(null); };

  // 개별 CSV 다운로드 — analysis 에서 queryBreakdown 추출
  const handleSingleDownload = async (runId: string) => {
    clearMessages();
    setRowBusy((prev) => ({ ...prev, [runId]: "download" }));
    try {
      const { analysis } = await v3MeasurementApi.getAnalysis(onboardingId!, runId);
      if (!analysis) throw new Error("분석 결과를 찾을 수 없습니다.");
      const rows = (analysis.queryBreakdown ?? []).map((q: any) => [
        q.queryText || q.query, q.category || "",
        q.gptMentioned ? "Y" : "N", q.geminiMentioned ? "Y" : "N",
        `${q.brandRate ?? q.totalMentionRate ?? 0}%`,
      ]);
      const header = ["Query", "Category", "GPT Mentioned", "Gemini Mentioned", "Mention Rate"];
      const csv = [header, ...rows].map((r) => r.map((c: string) => `"${String(c).replace(/"/g, '""')}"`).join(",")).join("\n");
      const blob = new Blob(["\uFEFF" + csv], { type: "text/csv;charset=utf-8;" });
      const url = URL.createObjectURL(blob);
      const a = document.createElement("a");
      a.href = url;
      a.download = `v3-report-${runId}.csv`;
      a.click();
      URL.revokeObjectURL(url);
      setOkMsg("CSV 다운로드 시작");
      setTimeout(() => setOkMsg(null), 3000);
    } catch (err: any) {
      setErrMsg(err?.message || "다운로드 실패");
    } finally {
      setRowBusy((prev) => ({ ...prev, [runId]: null }));
    }
  };

  const handleSingleDeleteClick = (runId: string) => {
    clearMessages();
    setDeleteModal({ runIds: [runId], mode: "single" });
  };

  const handleBulkDeleteClick = () => {
    clearMessages();
    if (selectedIds.size === 0) { setErrMsg("삭제할 측정을 선택해주세요."); return; }
    setDeleteModal({ runIds: Array.from(selectedIds), mode: "bulk" });
  };

  const executeDelete = async (eligibleIds: string[]) => {
    if (eligibleIds.length === 0) return;
    setBulkBusy("delete");
    let okCount = 0;
    let failCount = 0;
    for (const runId of eligibleIds) {
      try {
        await v3MeasurementApi.deleteRun(onboardingId!, runId);
        okCount++;
      } catch { failCount++; }
    }
    setSelectedIds((prev) => {
      const next = new Set(prev);
      for (const id of eligibleIds) next.delete(id);
      return next;
    });
    setOkMsg(`${okCount}건 삭제됨${failCount > 0 ? ` (${failCount}건 실패)` : ""}.`);
    setTimeout(() => setOkMsg(null), 4000);
    qc.invalidateQueries({ queryKey: ["portalV3", "v3-runs-history", onboardingId] });
    qc.invalidateQueries({ queryKey: ["portalV3", "v3-storage", onboardingId] });
    qc.invalidateQueries({ queryKey: ["portalV3", "v3latest", onboardingId] });
    setBulkBusy(null);
  };

  return (
    <section className="rounded-2xl border border-[var(--shell-border)] bg-[var(--shell-panel)] p-5">
      <header className="mb-4 flex flex-wrap items-start justify-between gap-3">
        <div>
          <h2 className="text-sm font-semibold text-[var(--shell-text)]">
            측정 보고서 다운로드 관리
          </h2>
          <p className="mt-1 text-[11px] leading-5 text-[var(--shell-text-muted)]">
            즉시 측정 / 자동 측정으로 생성된 데이터를 개별 CSV 다운로드 또는 삭제.
            보관 한도 <strong>200개</strong>.
          </p>
        </div>
        {stats && (
          <div className="flex items-center gap-2 text-[10px]">
            <div className={`rounded-lg border px-2.5 py-1.5 ${
              stats.doneRuns >= stats.maxRuns
                ? "border-red-500/40 bg-red-500/10 text-red-200"
                : stats.doneRuns > stats.maxRuns * 0.8
                  ? "border-amber-500/40 bg-amber-500/10 text-amber-200"
                  : "border-[var(--shell-border)] bg-[var(--shell-panel-soft)] text-[var(--shell-text-muted)]"
            }`}>
              <div className="text-[9px] uppercase tracking-wider opacity-70">저장됨</div>
              <div className="text-sm font-semibold tabular-nums">{stats.doneRuns} / {stats.maxRuns}</div>
            </div>
          </div>
        )}
      </header>

      {/* 일괄 액션 바 */}
      <div className="mb-3 flex flex-wrap items-center justify-between gap-2 rounded-lg border border-[var(--shell-border)] bg-[var(--shell-panel-soft)] p-2.5">
        <div className="flex items-center gap-2">
          <button
            type="button"
            onClick={toggleAll}
            disabled={doneRuns.length === 0}
            className="flex items-center gap-1.5 rounded-md border border-[var(--shell-border)] bg-[var(--shell-panel)] px-2.5 py-1.5 text-[11px] text-[var(--shell-text)] hover:bg-[var(--shell-panel-soft)] disabled:opacity-40"
          >
            {allSelected ? <CheckSquare className="h-3.5 w-3.5" /> : <Square className="h-3.5 w-3.5" />}
            {allSelected ? "전체 해제" : "전체 선택"}
          </button>
          <span className="text-[10px] text-[var(--shell-text-soft)]">
            선택: <strong className="text-[var(--shell-text)]">{selectedIds.size}</strong> / {doneRuns.length}개
          </span>
        </div>
        <div className="flex items-center gap-2">
          <button
            type="button"
            onClick={handleBulkDeleteClick}
            disabled={!someSelected || bulkBusy !== null}
            className="flex items-center gap-1.5 rounded-md border border-red-500/40 bg-red-500/10 px-3 py-1.5 text-[11px] font-medium text-red-300 hover:bg-red-500/20 disabled:opacity-40"
          >
            {bulkBusy === "delete" ? <Loader2 className="h-3.5 w-3.5 animate-spin" /> : <Trash2 className="h-3.5 w-3.5" />}
            선택 삭제
          </button>
        </div>
      </div>

      {/* 메시지 */}
      {okMsg && (
        <div className="mb-3 rounded-lg border border-emerald-500/30 bg-emerald-500/5 px-3 py-2 text-[11px] text-emerald-300">
          {okMsg}
        </div>
      )}
      {errMsg && (
        <div className="mb-3 flex items-start gap-1.5 rounded-lg border border-red-500/30 bg-red-500/5 px-3 py-2 text-[11px] text-red-300">
          <AlertTriangle className="mt-0.5 h-3.5 w-3.5 shrink-0" />
          <span>{errMsg}</span>
        </div>
      )}

      {/* 목록 */}
      {runsQ.isLoading && (
        <div className="rounded-lg border border-[var(--shell-border)] bg-[var(--shell-panel-soft)] px-3 py-6 text-center text-[11px] text-[var(--shell-text-muted)]">
          <Loader2 className="mx-auto mb-1.5 h-4 w-4 animate-spin" />
          측정 이력 불러오는 중...
        </div>
      )}

      {!runsQ.isLoading && doneRuns.length === 0 && (
        <div className="rounded-lg border border-[var(--shell-border)] bg-[var(--shell-panel-soft)] px-3 py-6 text-center text-[11px] text-[var(--shell-text-muted)]">
          완료된 측정이 없습니다. 측정 카드에서 새 측정을 시작해주세요.
        </div>
      )}

      {!runsQ.isLoading && doneRuns.length > 0 && (
        <div className="overflow-x-auto rounded-lg border border-[var(--shell-border)]">
          <table className="w-full min-w-[560px] text-[11px]">
            <thead className="bg-[var(--shell-panel-soft)]">
              <tr className="text-left text-[10px] uppercase tracking-wider text-[var(--shell-text-soft)]">
                <th className="px-2 py-2 w-10"></th>
                <th className="px-2 py-2">측정 일시</th>
                <th className="px-2 py-2">트리거</th>
                <th className="px-2 py-2 text-right">Calls</th>
                <th className="px-2 py-2">runId</th>
                <th className="px-2 py-2 text-right w-32">액션</th>
              </tr>
            </thead>
            <tbody>
              {doneRuns.map((r: any) => {
                const isSelected = selectedIds.has(r.id);
                const busy = rowBusy[r.id];
                return (
                  <tr
                    key={r.id}
                    className={`border-t border-[var(--shell-border)] ${isSelected ? "bg-[var(--shell-accent)]/5" : ""}`}
                  >
                    <td className="px-2 py-2">
                      <button type="button" onClick={() => toggleOne(r.id)} className="text-[var(--shell-text-muted)] hover:text-[var(--shell-text)]">
                        {isSelected ? <CheckSquare className="h-3.5 w-3.5 text-[var(--shell-accent)]" /> : <Square className="h-3.5 w-3.5" />}
                      </button>
                    </td>
                    <td className="px-2 py-2 text-[var(--shell-text)]">
                      <div className="flex items-center gap-1.5">
                        <Clock className="h-3 w-3 text-[var(--shell-text-soft)]" />
                        {r.completedAt ? new Date(r.completedAt).toLocaleString() : new Date(r.createdAt).toLocaleString()}
                      </div>
                    </td>
                    <td className="px-2 py-2">
                      <span className={`rounded-full px-1.5 py-0.5 text-[9px] ${
                        r.triggerType === "manual" ? "bg-blue-500/15 text-blue-300" : "bg-emerald-500/15 text-emerald-300"
                      }`}>
                        {r.triggerType === "manual" ? "수동" : "자동"}
                      </span>
                    </td>
                    <td className="px-2 py-2 text-right font-mono text-[var(--shell-text-muted)]">
                      {r.completedItems ?? r.totalItems ?? "—"}
                    </td>
                    <td className="px-2 py-2 font-mono text-[10px] text-[var(--shell-text-soft)]">
                      {r.id.slice(0, 8)}...
                    </td>
                    <td className="px-2 py-2 text-right">
                      <div className="flex items-center justify-end gap-1">
                        <button
                          type="button"
                          onClick={() => handleSingleDownload(r.id)}
                          disabled={busy !== null && busy !== undefined}
                          className="rounded p-1 text-[var(--shell-text-muted)] hover:bg-[var(--shell-panel-soft)] hover:text-[var(--shell-accent)] disabled:opacity-40"
                          title="이 측정 CSV 다운로드"
                        >
                          {busy === "download" ? <Loader2 className="h-3.5 w-3.5 animate-spin" /> : <FileSpreadsheet className="h-3.5 w-3.5" />}
                        </button>
                        <button
                          type="button"
                          onClick={() => handleSingleDeleteClick(r.id)}
                          disabled={busy !== null && busy !== undefined}
                          className="rounded p-1 text-[var(--shell-text-muted)] hover:bg-red-500/10 hover:text-red-300 disabled:opacity-40"
                          title="이 측정 삭제"
                        >
                          {busy === "delete" ? <Loader2 className="h-3.5 w-3.5 animate-spin" /> : <Trash2 className="h-3.5 w-3.5" />}
                        </button>
                      </div>
                    </td>
                  </tr>
                );
              })}
            </tbody>
          </table>
        </div>
      )}

      {/* 삭제 미리보기 모달 */}
      {deleteModal && onboardingId && (
        <V3DeletePreviewModal
          onboardingId={onboardingId}
          runIds={deleteModal.runIds}
          isOpen={true}
          onClose={() => setDeleteModal(null)}
          onConfirm={executeDelete}
          mode={deleteModal.mode}
        />
      )}
    </section>
  );
}
