// @ts-nocheck
// 고객 화면 4: AI 검색결과 분석 (실제 dk_v3_query_results).
// 기획서 Sheet 4: 쿼리 선택 + 엔진 필터 + 답변 원문 + 브랜드/경쟁사 하이라이트 + 통계.
import { useEffect, useMemo, useState } from "react";
import { useParams } from "react-router-dom";
import { useQuery } from "@tanstack/react-query";
import { ChevronLeft, ChevronRight, Loader2, Sparkles, FileText, Link2, AlertTriangle } from "lucide-react";
import { trendApi } from "./dataHub";
import { v3MeasurementApi } from "./dataHub";
import { HeaderDiagnosticButton } from "./V3DiagnosticPanel";
import { runAiSearchDiagnostics } from "./diagnostics/aiSearchDiagnostics";

export function PortalV3AiSearchAnalysis() {
  const { id } = useParams<{ id: string }>();
  const [engineFilter, setEngineFilter] = useState<"all" | "gpt" | "gemini">("all");
  const [selectedQueryIdx, setSelectedQueryIdx] = useState<number>(0);
  const [sampleCursor, setSampleCursor] = useState(0);

  // 브랜드/경쟁사 컨텍스트 (하이라이트용)
  const truthQ = useQuery({
    queryKey: ["portalV3", "brand-truth", id],
    queryFn: () => trendApi.getBrandTruth(id!),
    enabled: !!id,
  });
  // 최신 done run + analysis
  const latestQ = useQuery({
    queryKey: ["portalV3", "v3-latest", id],
    queryFn: () => v3MeasurementApi.getLatest(id!),
    enabled: !!id,
  });
  // 해당 run 의 결과들 (1000개) — 페이지네이션으로 100개씩
  const latestRunId = latestQ.data?.run?.id;
  const resultsQ = useQuery({
    queryKey: ["portalV3", "v3-run-results", latestRunId, engineFilter],
    queryFn: () => v3MeasurementApi.getResults(id!, latestRunId!, { limit: 1000, engine: engineFilter === "all" ? undefined : engineFilter }),
    enabled: !!id && !!latestRunId,
  });

  const truth: any = truthQ.data?.truth || {};
  const brandNames = useMemo(() => [truth.canonicalName, ...(truth.aliases || [])].filter(Boolean), [truth]);
  const competitors = useMemo(() => truth.importantCompetitors || [], [truth]);
  const competitorDomains: Record<string, string> = truth.competitorDomains || {};
  const queryCategories: Record<string, string> = truth.queryCategories || {};

  // 쿼리 목록 (analysis 의 queryBreakdown 우선, 없으면 brand-truth.mustWinQueries)
  const wrd = (latestQ.data?.analysis as any)?.weeklyReportData;
  const queries = useMemo(() => {
    if (wrd?.queryBreakdown?.length > 0) {
      return wrd.queryBreakdown.map((q: any) => ({
        text: q.queryText,
        index: q.queryIndex,
        category: q.category || queryCategories[q.queryText],
        brandRate: q.brandRate,
        gptRate: q.gptRate,
        geminiRate: q.geminiRate,
        avgPosition: q.avgMentionPosition,
      }));
    }
    return (truth.mustWinQueries || []).map((q: string, i: number) => ({
      text: q, index: i, category: queryCategories[q],
      brandRate: null, gptRate: null, geminiRate: null, avgPosition: null,
    }));
  }, [wrd, truth, queryCategories]);

  const selectedQuery = queries[selectedQueryIdx];

  // 선택된 쿼리의 결과만 필터
  const filteredSamples = useMemo(() => {
    const results = resultsQ.data?.results || [];
    return results.filter((r: any) =>
      r.queryIndex === selectedQuery?.index &&
      r.status === "done" &&
      r.answerText
    );
  }, [resultsQ.data, selectedQuery]);

  // 샘플 cursor 가 범위 밖이면 reset
  useEffect(() => {
    if (sampleCursor >= filteredSamples.length) setSampleCursor(0);
  }, [filteredSamples.length, sampleCursor]);

  const sample = filteredSamples[sampleCursor];

  return (
    <>
      {id && <HeaderDiagnosticButton boardId={id} title="AI Search Diagnostics" runner={runAiSearchDiagnostics} />}
      <div className="mx-auto max-w-6xl space-y-5 px-4 py-6">
        <header>
          <div className="text-xs uppercase tracking-[0.28em] text-[var(--shell-text-soft)]">Client / AI 검색결과 분석</div>
          <h1 className="mt-2 text-3xl font-semibold tracking-tight text-[var(--shell-text)]">AI 검색결과 분석</h1>
          <p className="mt-2 text-sm text-[var(--shell-text-muted)]">
            쿼리별 AI 답변 원문 + 브랜드/경쟁사 하이라이트 + 통계 요약.
            노란색=자사 멘션, 빨간색=경쟁사 멘션, 파란색=인용 URL.
          </p>
        </header>

        {(latestQ.isLoading || truthQ.isLoading) && (
          <div className="rounded-2xl border border-[var(--shell-border)] bg-[var(--shell-panel)] py-12 text-center text-sm text-[var(--shell-text-muted)]">
            <Loader2 className="mx-auto h-5 w-5 animate-spin" />
            <div className="mt-2">불러오는 중...</div>
          </div>
        )}

        {!latestQ.isLoading && !latestQ.data?.analysis && (
          <div className="rounded-2xl border-2 border-dashed border-[var(--shell-border)] bg-[var(--shell-panel)] p-8 text-center">
            <Sparkles className="mx-auto h-6 w-6 text-[var(--shell-text-soft)]" />
            <div className="mt-2 text-sm text-[var(--shell-text)]">측정 데이터가 없습니다</div>
            <div className="mt-1 text-[11px] text-[var(--shell-text-muted)]">
              "고객 인풋" 메뉴에서 측정을 먼저 실행해주세요.
            </div>
          </div>
        )}

        {latestQ.data?.analysis && queries.length > 0 && (
          <>
            {/* ★ 엔진 격차 분석 카드 — GPT vs Gemini 차이 큰 경우만 표시 */}
            <V3EngineGapCard wrd={wrd} />

            {/* 쿼리 셀렉터 */}
            <section className="rounded-2xl border border-[var(--shell-border)] bg-[var(--shell-panel)] p-4">
              <div className="mb-2 flex items-center justify-between">
                <div className="text-xs font-semibold text-[var(--shell-text)]">쿼리 선택 ({queries.length})</div>
                <div className="flex rounded-full border border-[var(--shell-border)] bg-[var(--shell-panel-soft)] p-0.5 text-[11px]">
                  {(["all", "gpt", "gemini"] as const).map((e) => (
                    <button
                      key={e}
                      onClick={() => setEngineFilter(e)}
                      className={`rounded-full px-3 py-1 transition ${engineFilter === e ? "bg-[var(--shell-accent)] text-white" : "text-[var(--shell-text-muted)] hover:text-[var(--shell-text)]"}`}
                    >
                      {e === "all" ? "전체" : e.toUpperCase()}
                    </button>
                  ))}
                </div>
              </div>

              <div className="grid grid-cols-1 gap-1.5 sm:grid-cols-2">
                {queries.map((q: any, i: number) => (
                  <button
                    key={i}
                    onClick={() => { setSelectedQueryIdx(i); setSampleCursor(0); }}
                    className={`flex items-center gap-2 rounded-lg border px-3 py-2 text-left text-xs transition ${
                      selectedQueryIdx === i
                        ? "border-[var(--shell-accent)] bg-[var(--shell-accent)]/10 text-[var(--shell-text)]"
                        : "border-[var(--shell-border)] bg-[var(--shell-panel-soft)] text-[var(--shell-text-muted)] hover:bg-[var(--shell-panel)]"
                    }`}
                  >
                    <span className="shrink-0 rounded-full bg-[var(--shell-panel)] px-1.5 py-0.5 text-[10px] font-medium">Q{i + 1}</span>
                    <span className="min-w-0 flex-1 truncate" title={q.text}>{q.text}</span>
                    {q.category && (
                      <span className="shrink-0 rounded-full bg-blue-500/15 px-1.5 py-0.5 text-[9px] text-blue-300">{q.category}</span>
                    )}
                    {q.brandRate !== null && (
                      <span className={`shrink-0 font-mono text-[10px] ${
                        q.brandRate >= 60 ? "text-emerald-300" :
                        q.brandRate >= 40 ? "text-amber-300" : "text-red-300"
                      }`}>
                        {q.brandRate?.toFixed(0)}%
                      </span>
                    )}
                  </button>
                ))}
              </div>
            </section>

            {selectedQuery && (
              <>
                {/* 쿼리 통계 카드 */}
                <section className="grid grid-cols-2 gap-2 md:grid-cols-4">
                  <Kpi label="자사 언급률" value={selectedQuery.brandRate !== null ? `${selectedQuery.brandRate.toFixed(1)}%` : "-"}
                       tone={selectedQuery.brandRate >= 60 ? "good" : selectedQuery.brandRate >= 40 ? "warn" : "bad"} />
                  <Kpi label="GPT 언급률" value={selectedQuery.gptRate !== null ? `${selectedQuery.gptRate.toFixed(1)}%` : "-"} tone="info" />
                  <Kpi label="Gemini 언급률" value={selectedQuery.geminiRate !== null ? `${selectedQuery.geminiRate.toFixed(1)}%` : "-"} tone="info" />
                  <Kpi label="평균 멘션 순위" value={selectedQuery.avgPosition != null ? selectedQuery.avgPosition.toFixed(1) : "-"} tone="info" />
                </section>

                {/* 원문 분석 */}
                {resultsQ.isLoading && (
                  <div className="rounded-2xl border border-[var(--shell-border)] bg-[var(--shell-panel)] py-12 text-center text-sm text-[var(--shell-text-muted)]">
                    <Loader2 className="mx-auto h-5 w-5 animate-spin" />
                  </div>
                )}

                {!resultsQ.isLoading && filteredSamples.length === 0 && (
                  <div className="rounded-2xl border border-dashed border-[var(--shell-border)] bg-[var(--shell-panel)]/40 p-8 text-center text-sm text-[var(--shell-text-muted)]">
                    이 쿼리/엔진 조합에 답변이 없습니다.
                  </div>
                )}

                {sample && (
                  <section className="rounded-2xl border border-[var(--shell-border)] bg-[var(--shell-panel)] p-5">
                    <div className="mb-3 flex items-center justify-between">
                      <div className="flex items-center gap-2">
                        <FileText className="h-4 w-4 text-[var(--shell-text-soft)]" />
                        <span className="text-sm font-semibold text-[var(--shell-text)]">AI 응답 원문</span>
                        <span className="rounded-full bg-[var(--shell-panel-soft)] px-2 py-0.5 text-[10px] font-medium text-[var(--shell-text-muted)]">
                          {sample.engine?.toUpperCase()}
                        </span>
                        {sample.brandMentioned && (
                          <span className="rounded-full bg-emerald-500/15 px-2 py-0.5 text-[10px] text-emerald-300">자사 언급 ✓</span>
                        )}
                        {typeof sample.mentionPosition === "number" && sample.mentionPosition > 0 && (
                          <span className="rounded-full bg-blue-500/15 px-2 py-0.5 text-[10px] text-blue-300">
                            {sample.mentionPosition}순위
                          </span>
                        )}
                        {sample.sentiment && (
                          <span className={`rounded-full px-2 py-0.5 text-[10px] ${
                            sample.sentiment === "positive" ? "bg-emerald-500/15 text-emerald-300" :
                            sample.sentiment === "negative" ? "bg-red-500/15 text-red-300" :
                            "bg-neutral-500/15 text-neutral-300"
                          }`}>
                            {sample.sentiment === "positive" ? "긍정" : sample.sentiment === "negative" ? "부정" : "중립"}
                          </span>
                        )}
                      </div>

                      {/* 샘플 cursor */}
                      <div className="flex items-center gap-1.5 text-[11px]">
                        <button
                          onClick={() => setSampleCursor((c) => Math.max(0, c - 1))}
                          disabled={sampleCursor === 0}
                          className="rounded p-1 text-[var(--shell-text-soft)] hover:bg-[var(--shell-panel-soft)] disabled:opacity-30"
                        >
                          <ChevronLeft className="h-3.5 w-3.5" />
                        </button>
                        <span className="text-[var(--shell-text-muted)]">
                          샘플 {sampleCursor + 1} / {filteredSamples.length}
                        </span>
                        <button
                          onClick={() => setSampleCursor((c) => Math.min(filteredSamples.length - 1, c + 1))}
                          disabled={sampleCursor >= filteredSamples.length - 1}
                          className="rounded p-1 text-[var(--shell-text-soft)] hover:bg-[var(--shell-panel-soft)] disabled:opacity-30"
                        >
                          <ChevronRight className="h-3.5 w-3.5" />
                        </button>
                      </div>
                    </div>

                    {/* 하이라이트된 답변 텍스트 */}
                    <div className="rounded-lg border border-[var(--shell-border)] bg-[var(--shell-panel-soft)] p-4 text-sm leading-7 text-[var(--shell-text)] max-h-[500px] overflow-y-auto">
                      <HighlightedText
                        text={sample.answerText || ""}
                        brandNames={brandNames}
                        competitors={competitors}
                      />
                    </div>

                    {/* 인용 URL */}
                    {(sample.references?.length > 0 || sample.brandCitedUrls?.length > 0 || Object.keys(sample.competitorCitedUrls || {}).length > 0) && (
                      <div className="mt-4">
                        <div className="mb-2 flex items-center gap-1.5 text-xs font-semibold text-[var(--shell-text)]">
                          <Link2 className="h-3.5 w-3.5" /> 인용 URL ({(sample.references || []).length})
                        </div>
                        <ul className="space-y-1">
                          {(sample.references || []).slice(0, 15).map((url: string, i: number) => {
                            const host = extractHost(url);
                            const isBrand = (sample.brandCitedUrls || []).includes(url);
                            const compName = Object.entries(sample.competitorCitedUrls || {}).find(([, urls]: any) =>
                              Array.isArray(urls) && urls.includes(url))?.[0];
                            return (
                              <li key={i} className="flex items-center gap-2 text-[11px]">
                                {isBrand ? (
                                  <span className="rounded-full bg-emerald-500/15 px-2 py-0.5 text-[9px] font-semibold text-emerald-300">자사</span>
                                ) : compName ? (
                                  <span className="rounded-full bg-red-500/15 px-2 py-0.5 text-[9px] font-semibold text-red-300">{compName}</span>
                                ) : (
                                  <span className="rounded-full bg-[var(--shell-panel-soft)] px-2 py-0.5 text-[9px] text-[var(--shell-text-muted)]">기타</span>
                                )}
                                <a href={url} target="_blank" rel="noopener noreferrer"
                                   className="truncate text-blue-300 hover:underline" title={url}>
                                  {host || url.slice(0, 60)}
                                </a>
                              </li>
                            );
                          })}
                        </ul>
                      </div>
                    )}
                  </section>
                )}

                {/* 통계 요약 — 도넛/감성/순위 */}
                {filteredSamples.length > 0 && (
                  <section className="grid gap-3 md:grid-cols-3">
                    {/* 멘션 vs 비멘션 */}
                    <StatCard title="멘션 / 비멘션">
                      <DonutBar
                        items={[
                          { label: "멘션", value: filteredSamples.filter((s: any) => s.brandMentioned).length, color: "bg-emerald-400" },
                          { label: "비멘션", value: filteredSamples.filter((s: any) => !s.brandMentioned).length, color: "bg-neutral-400" },
                        ]}
                      />
                    </StatCard>

                    {/* 감성 */}
                    <StatCard title="감성 분포">
                      <DonutBar
                        items={[
                          { label: "긍정", value: filteredSamples.filter((s: any) => s.sentiment === "positive").length, color: "bg-emerald-400" },
                          { label: "중립", value: filteredSamples.filter((s: any) => s.sentiment === "neutral").length, color: "bg-neutral-400" },
                          { label: "부정", value: filteredSamples.filter((s: any) => s.sentiment === "negative").length, color: "bg-red-400" },
                        ]}
                      />
                    </StatCard>

                    {/* 멘션 순서 — 단순 도넛 */}
                    <StatCard title="멘션 순서 (요약)">
                      <DonutBar
                        items={[
                          { label: "1순위", value: filteredSamples.filter((s: any) => s.mentionPosition === 1).length, color: "bg-emerald-400" },
                          { label: "2순위", value: filteredSamples.filter((s: any) => s.mentionPosition === 2).length, color: "bg-blue-400" },
                          { label: "3+", value: filteredSamples.filter((s: any) => s.mentionPosition >= 3).length, color: "bg-amber-400" },
                          { label: "미언급", value: filteredSamples.filter((s: any) => !s.mentionPosition).length, color: "bg-neutral-400" },
                        ]}
                      />
                    </StatCard>
                  </section>
                )}

                {/* ★ Phase 1-Sheet4 향상 — 멘션 순위 세분화 히스토그램 (1/2/3/4/5/6+/미언급) */}
                {filteredSamples.length > 0 && (
                  <section className="rounded-2xl border border-[var(--shell-border)] bg-[var(--shell-panel)] p-5">
                    <div className="mb-3 flex items-center justify-between">
                      <div>
                        <div className="text-sm font-semibold text-[var(--shell-text)]">멘션 순위 세분화 히스토그램</div>
                        <div className="mt-0.5 text-[11px] text-[var(--shell-text-muted)]">
                          답변에서 자사가 등장한 순서 — 1순위(빠를수록 추천)부터 6+ 또는 미언급까지.
                          1순위 비율이 핵심 KPI.
                        </div>
                      </div>
                      <div className="text-right">
                        <div className="text-[10px] text-[var(--shell-text-soft)]">1순위 추천률</div>
                        <div className={`text-2xl font-semibold ${
                          getRankRate(filteredSamples, 1) >= 30 ? "text-emerald-300" :
                          getRankRate(filteredSamples, 1) >= 10 ? "text-amber-300" :
                          "text-red-300"
                        }`}>
                          {getRankRate(filteredSamples, 1).toFixed(1)}%
                        </div>
                      </div>
                    </div>
                    <PositionHistogram samples={filteredSamples} />
                  </section>
                )}
              </>
            )}
          </>
        )}
      </div>
    </>
  );
}

// ─── Helpers ───────────────────────────────────────

function HighlightedText({ text, brandNames, competitors }: { text: string; brandNames: string[]; competitors: string[] }) {
  // 모든 매치 위치를 찾고 정렬 → 우선순위: brand > competitor
  const matches: Array<{ start: number; end: number; type: "brand" | "competitor"; label: string }> = [];
  const lower = text.toLowerCase();

  for (const name of brandNames.filter(Boolean)) {
    const needle = name.toLowerCase();
    if (!needle.trim()) continue;
    let idx = 0;
    while ((idx = lower.indexOf(needle, idx)) !== -1) {
      matches.push({ start: idx, end: idx + needle.length, type: "brand", label: name });
      idx += needle.length;
    }
  }
  for (const comp of competitors.filter(Boolean)) {
    const needle = comp.toLowerCase();
    if (!needle.trim()) continue;
    let idx = 0;
    while ((idx = lower.indexOf(needle, idx)) !== -1) {
      matches.push({ start: idx, end: idx + needle.length, type: "competitor", label: comp });
      idx += needle.length;
    }
  }

  // overlap 제거 (brand 우선)
  matches.sort((a, b) => a.start - b.start || (a.type === "brand" ? -1 : 1));
  const filtered: typeof matches = [];
  let lastEnd = -1;
  for (const m of matches) {
    if (m.start >= lastEnd) {
      filtered.push(m);
      lastEnd = m.end;
    }
  }

  if (filtered.length === 0) {
    return <span className="whitespace-pre-wrap">{text}</span>;
  }

  // 텍스트를 분할해서 렌더링
  const parts: JSX.Element[] = [];
  let cursor = 0;
  for (let i = 0; i < filtered.length; i++) {
    const m = filtered[i];
    if (m.start > cursor) {
      parts.push(<span key={`t-${i}`}>{text.slice(cursor, m.start)}</span>);
    }
    parts.push(
      <mark
        key={`m-${i}`}
        title={m.type === "brand" ? `자사: ${m.label}` : `경쟁사: ${m.label}`}
        className={`rounded px-0.5 ${
          m.type === "brand"
            ? "bg-yellow-400/40 text-yellow-100 font-semibold"
            : "bg-red-400/30 text-red-200 underline decoration-red-400/60"
        }`}
      >
        {text.slice(m.start, m.end)}
      </mark>
    );
    cursor = m.end;
  }
  if (cursor < text.length) {
    parts.push(<span key="t-end">{text.slice(cursor)}</span>);
  }

  return <span className="whitespace-pre-wrap">{parts}</span>;
}

function Kpi({ label, value, tone }: { label: string; value: string; tone: "good" | "warn" | "bad" | "info" }) {
  const t = {
    good: "border-emerald-500/30 bg-emerald-500/5 text-emerald-300",
    warn: "border-amber-500/30 bg-amber-500/5 text-amber-300",
    bad: "border-red-500/30 bg-red-500/5 text-red-300",
    info: "border-[var(--shell-border)] bg-[var(--shell-panel)] text-[var(--shell-text)]",
  }[tone];
  return (
    <div className={`rounded-xl border p-3 ${t}`}>
      <div className="text-[10px] uppercase tracking-wider opacity-70">{label}</div>
      <div className="mt-1 text-2xl font-semibold">{value}</div>
    </div>
  );
}

function StatCard({ title, children }: { title: string; children: React.ReactNode }) {
  return (
    <div className="rounded-2xl border border-[var(--shell-border)] bg-[var(--shell-panel)] p-4">
      <div className="text-xs font-semibold text-[var(--shell-text)]">{title}</div>
      <div className="mt-2.5">{children}</div>
    </div>
  );
}

function DonutBar({ items }: { items: Array<{ label: string; value: number; color: string }> }) {
  const total = items.reduce((s, i) => s + i.value, 0);
  if (total === 0) return <div className="text-[11px] text-[var(--shell-text-muted)]">데이터 없음</div>;

  return (
    <div className="space-y-2">
      <div className="flex h-3 w-full overflow-hidden rounded-full bg-[var(--shell-panel-soft)]">
        {items.map((it, i) => {
          const pct = (it.value / total) * 100;
          if (pct === 0) return null;
          return <div key={i} className={it.color} style={{ width: `${pct}%`, height: "100%" }} title={`${it.label}: ${it.value}`} />;
        })}
      </div>
      <ul className="space-y-0.5 text-[10px]">
        {items.map((it, i) => {
          const pct = total > 0 ? (it.value / total) * 100 : 0;
          return (
            <li key={i} className="flex items-center justify-between">
              <div className="flex items-center gap-1.5">
                <span className={`inline-block h-2 w-2 rounded-full ${it.color}`} />
                <span className="text-[var(--shell-text)]">{it.label}</span>
              </div>
              <span className="text-[var(--shell-text-muted)]">{it.value}건 ({pct.toFixed(1)}%)</span>
            </li>
          );
        })}
      </ul>
    </div>
  );
}

function extractHost(url: string): string | null {
  try { return new URL(url).hostname; } catch { return null; }
}

// ─── Phase 1-Sheet4 향상 — 멘션 순위 세분화 히스토그램 ─────
function getRankRate(samples: any[], targetRank: number): number {
  if (samples.length === 0) return 0;
  const count = samples.filter((s) => s.mentionPosition === targetRank).length;
  return (count / samples.length) * 100;
}

function PositionHistogram({ samples }: { samples: any[] }) {
  // 버킷: 1, 2, 3, 4, 5, 6+, 미언급
  const buckets = useMemo(() => {
    const result = [
      { label: "1순위", color: "bg-emerald-500", desc: "최우선 추천" },
      { label: "2순위", color: "bg-emerald-400", desc: "두번째 추천" },
      { label: "3순위", color: "bg-blue-400", desc: "" },
      { label: "4순위", color: "bg-blue-300", desc: "" },
      { label: "5순위", color: "bg-amber-300", desc: "" },
      { label: "6+",   color: "bg-amber-400", desc: "후순위" },
      { label: "미언급", color: "bg-neutral-400", desc: "자사 미등장" },
    ];
    const counts = [0, 0, 0, 0, 0, 0, 0];
    for (const s of samples) {
      const p = s.mentionPosition;
      if (typeof p !== "number" || p < 1) counts[6]++;
      else if (p === 1) counts[0]++;
      else if (p === 2) counts[1]++;
      else if (p === 3) counts[2]++;
      else if (p === 4) counts[3]++;
      else if (p === 5) counts[4]++;
      else counts[5]++;
    }
    return result.map((r, i) => ({ ...r, count: counts[i] }));
  }, [samples]);

  const total = buckets.reduce((s, b) => s + b.count, 0);
  const maxCount = Math.max(...buckets.map((b) => b.count), 1);

  return (
    <div className="space-y-2">
      {buckets.map((b, i) => {
        const pct = total > 0 ? (b.count / total) * 100 : 0;
        const barWidth = (b.count / maxCount) * 100;
        return (
          <div key={i} className="flex items-center gap-3">
            <div className="w-20 shrink-0">
              <div className="text-xs font-medium text-[var(--shell-text)]">{b.label}</div>
              {b.desc && <div className="text-[9px] text-[var(--shell-text-soft)]">{b.desc}</div>}
            </div>
            <div className="relative flex-1 overflow-hidden rounded-full bg-[var(--shell-panel-soft)]" style={{ height: 18 }}>
              <div
                className={`h-full transition-all ${b.color}`}
                style={{ width: `${barWidth}%` }}
              />
              {/* count label inside bar (if wide enough) or at right */}
              <div className="absolute inset-0 flex items-center px-2 text-[10px] font-medium text-[var(--shell-text)]">
                {b.count > 0 ? `${b.count}건` : ""}
              </div>
            </div>
            <div className="w-14 shrink-0 text-right font-mono text-[11px] text-[var(--shell-text-muted)]">
              {pct.toFixed(1)}%
            </div>
          </div>
        );
      })}
      <div className="mt-2 flex items-center justify-between border-t border-[var(--shell-border)] pt-2 text-[10px] text-[var(--shell-text-soft)]">
        <span>총 {total} 샘플</span>
        <span>
          상위 3 비율: {(buckets.slice(0, 3).reduce((s, b) => s + b.count, 0) / Math.max(total, 1) * 100).toFixed(1)}%
        </span>
      </div>
    </div>
  );
}

