import { getDoc, getDocs, query, limit as fbLimit, orderBy } from "firebase/firestore";
import { paths, SUMMARY_KEYS } from "../../../db/paths";
import type { DiagnosticCheck, DiagnosticRunner } from "./types";

export const runReportDiagnostics: DiagnosticRunner = async (boardId) => {
  const results: DiagnosticCheck[] = [];

  // summaries/measurement (latest run + analysis)
  try {
    const snap = await getDoc(paths.summary(boardId, SUMMARY_KEYS.measurement));
    if (!snap.exists()) {
      results.push({ id: "rpt-measurement", label: "summaries/measurement 문서 존재", status: "fail", detail: "측정 요약이 없습니다." });
    } else {
      const data = snap.data() as any;
      const runId = data?.run?.id;
      const hasAnalysis = !!data?.analysis;
      results.push({ id: "rpt-measurement", label: "summaries/measurement 문서 존재", status: "pass", detail: `run.id: ${runId ?? "N/A"}, analysis: ${hasAnalysis ? "있음" : "없음"}` });

      const wrd = data?.analysis?.weeklyReportData;
      results.push({
        id: "rpt-wrd",
        label: "weeklyReportData 존재",
        status: wrd ? "pass" : "fail",
        detail: wrd ? `globalEngine.totalQuestions: ${wrd?.globalEngine?.totalQuestions ?? "N/A"}, queryBreakdown: ${wrd?.queryBreakdown?.length ?? 0}개` : "보고서 생성에 필요한 weeklyReportData가 없습니다.",
      });
    }
  } catch (err: any) {
    results.push({ id: "rpt-measurement", label: "summaries/measurement 조회", status: "fail", detail: `에러: ${err.message}` });
  }

  // V3 weekly reports
  try {
    const snap = await getDocs(query(paths.v3WeeklyReports(boardId), orderBy("__name__", "desc"), fbLimit(5)));
    results.push({
      id: "rpt-weekly",
      label: "V3 주간 리포트 문서 수",
      status: snap.docs.length > 0 ? "pass" : "warn",
      detail: snap.docs.length > 0 ? `${snap.docs.length}개 (최근: ${snap.docs[0].id})` : "주간 리포트가 없습니다.",
    });
  } catch (err: any) {
    results.push({ id: "rpt-weekly", label: "V3 주간 리포트 조회", status: "warn", detail: `조회 실패 (컬렉션 미존재 가능): ${err.message}` });
  }

  // V3 monthly reports
  try {
    const snap = await getDocs(query(paths.v3MonthlyReports(boardId), orderBy("__name__", "desc"), fbLimit(3)));
    results.push({
      id: "rpt-monthly",
      label: "V3 월간 리포트 문서 수",
      status: snap.docs.length > 0 ? "pass" : "warn",
      detail: snap.docs.length > 0 ? `${snap.docs.length}개 (최근: ${snap.docs[0].id})` : "월간 리포트가 없습니다.",
    });
  } catch (err: any) {
    results.push({ id: "rpt-monthly", label: "V3 월간 리포트 조회", status: "warn", detail: `조회 실패 (컬렉션 미존재 가능): ${err.message}` });
  }

  return results;
};
