// ── V3 Measurement API — Firestore commands + readers ─────────────

function getUid(): string {
  const uid = auth.currentUser?.uid;
  if (!uid) throw new Error("로그인이 필요합니다.");
  return uid;
}

export const v3MeasurementApi = {
  start: async (boardId: string, opts?: { engines?: string[]; sampleCount?: number }): Promise<any> => {
    const uid = getUid();
    const engines = opts?.engines ?? ["gpt", "gemini"];
    const sampleCount = opts?.sampleCount ?? 50;
    const ref = await issueCommand(boardId, uid, "start_v3_measurement", { engines, sampleCount });
    const estimatedCalls = 10 * engines.length * sampleCount;
    return {
      runId: ref.id,
      status: "pending",
      estimatedCalls,
      estimatedDurationMin: Math.ceil(estimatedCalls / 120),
      cmdId: ref.id,
    };
  },
  retryFailed: async (boardId: string): Promise<any> => {
    const uid = getUid();
    const ref = await issueCommand(boardId, uid, "retry_v3_measurement", {});
    return { runId: ref.id, status: "running", retryCount: 0, cmdId: ref.id };
  },
  forceComplete: async (boardId: string, runId?: string): Promise<any> => {
    const uid = getUid();
    const ref = await issueCommand(boardId, uid, "force_complete_v3_measurement", { runId });
    return new Promise((resolve, reject) => {
      const unsub = onSnapshot(paths.command(boardId, ref.id), (snap) => {
        if (!snap.exists()) return;
        const data = snap.data();
        if (data.status === "complete") {
          unsub();
          resolve(data.result || { success: true });
        } else if (data.status === "failed") {
          unsub();
          reject(new Error(data.error || "강제 종료 실패"));
        }
      });
    });
  },
  reanalyze: async (boardId: string, runId?: string): Promise<any> => {
    const uid = getUid();
    const ref = await issueCommand(boardId, uid, "reanalyze_v3_measurement", { runId });
    return new Promise((resolve, reject) => {
      const unsub = onSnapshot(paths.command(boardId, ref.id), (snap) => {
        if (!snap.exists()) return;
        const data = snap.data();
        if (data.status === "complete") {
          unsub();
          resolve({
            runId: data.result?.runId ?? runId,
            brandNames: data.result?.brandNames ?? [],
            message: data.result?.message ?? "재분석 완료",
            rowsReprocessed: 0,
            stats: { before: { brandMentionCount: 0, total: 0, brandMentionRate: 0 }, after: { brandMentionCount: 0, total: 0, brandMentionRate: 0 }, delta: { count: 0, ratePct: 0, flippedToMentioned: 0, flippedToNotMentioned: 0 } },
            durationMs: 0,
            logs: [],
          });
        } else if (data.status === "failed") {
          unsub();
          reject(new Error(data.error || "재분석 실패"));
        }
      });
    });
  },
  getRun: async (boardId: string, runId: string): Promise<any> => {
    const run = await getV3Run(boardId, runId);
    return { run };
  },
  getAnalysis: async (boardId: string, runId: string): Promise<any> => {
    const analysis = await getV3Analysis(boardId, runId);
    return { analysis };
  },
  getErrors: async (boardId: string, runId: string): Promise<any> => {
    const run = await getV3Run(boardId, runId);
    if (!run) {
      return {
        runId, totalCalls: 0,
        byEngine: {}, topErrors: [],
        diagnosis: { severity: "ok", summary: "데이터 없음", suggestions: [] },
      };
    }
    const totalFailed = run.failedItems ?? 0;
    const totalCalls = run.totalItems ?? 0;
    const severity = totalFailed > totalCalls * 0.5 ? "critical" : totalFailed > 0 ? "warning" : "ok";
    return {
      runId,
      totalCalls,
      byEngine: {
        gpt: { total: Math.floor(totalCalls / 2), done: Math.floor((totalCalls - totalFailed) / 2), failed: Math.floor(totalFailed / 2), pending: 0 },
        gemini: { total: Math.ceil(totalCalls / 2), done: Math.ceil((totalCalls - totalFailed) / 2), failed: Math.ceil(totalFailed / 2), pending: 0 },
      },
      topErrors: [],
      diagnosis: {
        severity,
        summary: severity === "critical" ? "과반수 이상 실패" : severity === "warning" ? "일부 실패 발생" : "정상",
        suggestions: severity === "critical"
          ? ["API 키를 확인해주세요.", "네트워크 상태를 확인해주세요."]
          : [],
      },
    };
  },
  listRuns: async (boardId: string, limit?: number): Promise<any> => {
    return await getV3Runs(boardId, limit);
  },
  getLatest: async (boardId: string): Promise<any> => {
    return await getV3Latest(boardId);
  },
  getResults: async (boardId: string, runId: string, opts?: any): Promise<any> => {
    return getV3MeasurementResults(boardId, runId, opts);
  },
  getSchedule: async (boardId: string): Promise<any> => {
    const schedule = await getV3Schedule(boardId);
    return { schedule };
  },
  getMonthlyReport: async (boardId: string, yearMonth: string): Promise<any> => {
    const real = await getV3MonthlyReport(boardId, yearMonth);
    return { report: real };
  },
  generateMonthlyReport: async (boardId: string, yearMonth: string): Promise<string> => {
    const uid = auth.currentUser?.uid;
    if (!uid) throw new Error("Not authenticated");
    const ref = await issueCommand(boardId, uid, "generate_v3_monthly_report", { yearMonth });
    return ref.id;
  },
  updateSchedule: async (boardId: string, patch: any): Promise<any> => {
    const nextRunAt = patch.enabled
      ? computeNextWeeklyRunAtKst(patch.dayOfWeek ?? 1, patch.hourOfDay ?? 9).toISOString()
      : null;
    await saveV3Schedule(boardId, { ...patch, nextRunAt });
    const schedule = await getV3Schedule(boardId);
    return { schedule };
  },
  getTrend: async (boardId: string, count: number = 12): Promise<any> => {
    const runs = await getV3Runs(boardId, count);
    const candidateRuns = (runs?.runs || [])
      .filter((r: any) => r.status !== "pending")
      .sort((a: any, b: any) => {
        const aTime = a.completedAt || a.startedAt || "";
        const bTime = b.completedAt || b.startedAt || "";
        return new Date(aTime).getTime() - new Date(bTime).getTime();
      });

    const points: any[] = [];
    for (const run of candidateRuns) {
      const analysis = await getV3Analysis(boardId, run.id);
      if (!analysis) continue;
      const brandRate = parseFloat(analysis.brandMentionRate as any) || 0;
      const eb = analysis.engineBreakdown || {};
      const gptRate = eb.gpt?.rate || 0;
      const geminiRate = eb.gemini?.rate || 0;
      const engineTotal = Object.values(eb).reduce((sum: number, e: any) => sum + (e?.total || 0), 0);
      const wrdTotal = (analysis as any).weeklyReportData?.globalEngine?.totalQuestions || 0;
      const derivedTotal = (run as any).totalCalls || run.totalItems || engineTotal || wrdTotal || 1;
      points.push({
        date: run.completedAt || run.startedAt,
        runId: run.id,
        totalCalls: derivedTotal,
        brandRate,
        gptRate,
        geminiRate,
      });
    }
    return { points };
  },
  singleExcel: async (_boardId: string, _runId: string): Promise<any> => {
    throw new Error("엑셀 다운로드는 현재 Firestore 환경에서 지원되지 않습니다. CSV 다운로드를 사용해주세요.");
  },
  bulkExcelWithProgress: async (_boardId: string, _runIds: string[], _onProgress?: (status: any) => void): Promise<any> => {
    throw new Error("일괄 엑셀 다운로드는 현재 Firestore 환경에서 지원되지 않습니다.");
  },
  deleteRun: async (_boardId: string, _runId: string): Promise<void> => {
    throw new Error("측정 기록 삭제는 현재 Firestore 환경에서 지원되지 않습니다.");
  },
  previewDelete: async (boardId: string, runIds: string[]): Promise<any> => {
    const runs = await getV3Runs(boardId, 200);
    const allRuns = runs?.runs || [];
    const eligible: any[] = [];
    const blocked: any[] = [];
    for (const rid of runIds) {
      const run = allRuns.find((r: any) => r.id === rid);
      if (!run) continue;
      if (run.status === "running" || run.status === "analyzing") {
        blocked.push({ runId: rid, reason: "진행 중인 측정은 삭제할 수 없습니다." });
      } else {
        eligible.push({ runId: rid, completedAt: run.completedAt, totalCalls: (run as any).totalCalls || run.totalItems });
      }
    }
    return { eligible, blocked, totalEligible: eligible.length, totalBlocked: blocked.length };
  },
  getStorageStats: async (boardId: string): Promise<any> => {
    const runs = await getV3Runs(boardId, 200);
    const allRuns = runs?.runs || [];
    const doneRuns = allRuns.filter((r: any) => r.status === "complete" || r.status === "done");
    const oldest = doneRuns.length > 0 ? doneRuns[doneRuns.length - 1]?.completedAt : null;
    return { totalRuns: allRuns.length, doneRuns: doneRuns.length, maxRuns: 200, oldestRunDate: oldest };
  },
  connectStream: (boardId: string, runId: string, handlers: any) => {
    const runRef = paths.run(boardId, runId);
    const unsub = onSnapshot(runRef, (snap) => {
      if (!snap.exists()) return;
      const data = snap.data();
      const status = data.status as string;
      const completed = data.completedItems ?? 0;
      const failed = data.failedItems ?? 0;
      const total = data.totalItems ?? 0;

      if (status === "running") {
        handlers.onProgress?.({ completed, failed, total });
      } else if (status === "analyzing") {
        handlers.onMeasurementDone?.({ data: { completed, failed, total } });
        handlers.onAnalyzing?.();
      } else if (status === "complete") {
        handlers.onAnalysisDone?.();
      } else if (status === "failed") {
        handlers.onFailed?.({ data: { error: data.message || "측정 실패" } });
      }
    });
    return { close: () => unsub(), getReconnectCount: () => 0 };
  },
};

