export const v3RecommendationsApi = {
  list: async (boardId: string): Promise<any> => {
    return await getV3Recommendations(boardId);
  },
  generate: async (boardId: string): Promise<any> => {
    const uid = getUid();
    const ref = await issueCommand(boardId, uid, "generate_v3_recommendations", {});
    return new Promise((resolve, reject) => {
      const unsub = onSnapshot(paths.command(boardId, ref.id), (snap) => {
        if (!snap.exists()) return;
        const data = snap.data();
        if (data.status === "complete") {
          unsub();
          resolve({ generated: data.result?.generated ?? 0, runId: data.result?.runId ?? null });
        } else if (data.status === "failed") {
          unsub();
          reject(new Error(data.error || "추천 생성 실패"));
        }
      });
    });
  },
  convert: async (boardId: string, recId: string, override?: any): Promise<any> => {
    return await convertV3Recommendation(boardId, recId, override);
  },
  dismiss: async (boardId: string, recId: string): Promise<any> => {
    await dismissV3Recommendation(boardId, recId);
    return { recommendation: { id: recId, status: "dismissed", dismissedAt: new Date().toISOString() } };
  },
  snooze: async (boardId: string, recId: string, days?: number): Promise<any> => {
    const snoozedUntil = await snoozeV3Recommendation(boardId, recId, days ?? 7);
    return { recommendation: { id: recId, snoozedUntil } };
  },
  getHitRate: async (boardId: string): Promise<any> => {
    const { recommendations } = await getV3Recommendations(boardId);
    const converted = recommendations.filter((r: any) => r.status === "converted");
    const effective = converted.filter((r: any) => r.convertedActionId);
    return { totalConverted: converted.length, effective: effective.length, hitRate: converted.length > 0 ? Math.round((effective.length / converted.length) * 100) : 0 };
  },
  getHitRateTrend: async (boardId: string, months: number = 6): Promise<any> => {
    const { recommendations } = await getV3Recommendations(boardId);
    const { actions } = await getV3Actions(boardId);
    const actionMap = new Map(actions.map((a: any) => [a.id, a]));

    const now = new Date();
    const trend: Array<{ yearMonth: string; totalConverted: number; effective: number; hitRate: number }> = [];

    for (let i = months - 1; i >= 0; i--) {
      const d = new Date(now.getFullYear(), now.getMonth() - i, 1);
      const ym = `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, "0")}`;
      const nextMonth = new Date(d.getFullYear(), d.getMonth() + 1, 1).toISOString();
      const thisMonth = d.toISOString();

      const monthConverted = recommendations.filter((r: any) =>
        r.status === "converted" && r.convertedAt && r.convertedAt >= thisMonth && r.convertedAt < nextMonth,
      );
      const effective = monthConverted.filter((r: any) => {
        const action = actionMap.get(r.convertedActionId);
        return action && parseFloat(action.effectDelta) >= 1;
      });
      trend.push({
        yearMonth: ym,
        totalConverted: monthConverted.length,
        effective: effective.length,
        hitRate: monthConverted.length > 0 ? Math.round((effective.length / monthConverted.length) * 100) : 0,
      });
    }
    return { trend };
  },
  getLlmsTxtSuggestion: async (boardId: string): Promise<any> => {
    const truth = await getV3BrandTruth(boardId);
    if (!truth || (!truth.canonicalName && !(truth as any).siteName && !(truth as any).domain)) {
      return { suggestion: null };
    }
    const suggestion = generateLlmsTxtSuggestion(truth as Record<string, any>);
    return { suggestion };
  },
};

