import { useState, type ComponentType, type ReactNode } from "react";
import { ChevronDown } from "lucide-react";

interface InsightSectionProps {
  title: string;
  description?: string;
  icon?: ComponentType<{ className?: string }>;
  defaultOpen?: boolean;
  count?: number;
  children: ReactNode;
}

export function InsightSection({ title, description, icon: Icon, defaultOpen = true, count, children }: InsightSectionProps) {
  const [open, setOpen] = useState(defaultOpen);

  return (
    <div className="rounded-2xl border border-[var(--shell-border)] bg-[var(--shell-panel)]">
      <button
        type="button"
        onClick={() => setOpen(!open)}
        className="flex w-full items-center gap-3 px-5 py-4 text-left transition-colors hover:bg-[var(--shell-panel-soft)]"
      >
        {Icon && (
          <div className="rounded-lg bg-[var(--shell-panel-soft)] p-1.5">
            <Icon className="h-4 w-4 text-[var(--shell-text-muted)]" />
          </div>
        )}
        <div className="min-w-0 flex-1">
          <div className="flex items-center gap-2">
            <span className="text-sm font-semibold text-[var(--shell-text)]">{title}</span>
            {count != null && (
              <span className="rounded-md bg-[var(--shell-panel-soft)] px-1.5 py-0.5 text-[10px] font-medium text-[var(--shell-text-muted)]">{count}</span>
            )}
          </div>
          {description && <p className="mt-0.5 text-xs text-[var(--shell-text-muted)]">{description}</p>}
        </div>
        <ChevronDown className={`h-4 w-4 shrink-0 text-[var(--shell-text-muted)] transition-transform duration-200 ${open ? "rotate-0" : "-rotate-90"}`} />
      </button>
      {open && <div className="border-t border-[var(--shell-border)] px-5 py-4">{children}</div>}
    </div>
  );
}
