import { getDocs, query, limit as fbLimit } from "firebase/firestore";
import { paths } from "../../../db/paths";
import type { DiagnosticCheck, DiagnosticRunner } from "./types";

export const runTimelineDiagnostics: DiagnosticRunner = async (boardId) => {
  const results: DiagnosticCheck[] = [];

  try {
    const snap = await getDocs(query(paths.v3Actions(boardId), fbLimit(50)));
    const actions = snap.docs.map((d) => ({ id: d.id, ...d.data() })) as any[];
    results.push({
      id: "tl-actions",
      label: "V3 actions 문서 수",
      status: actions.length > 0 ? "pass" : "fail",
      detail: actions.length > 0 ? `${actions.length}개` : "액션이 없습니다. 개선 방향에서 액션을 먼저 생성해주세요.",
    });

    if (actions.length > 0) {
      const statusCounts: Record<string, number> = {};
      const priorityCounts: Record<string, number> = {};
      for (const a of actions) {
        const s = a.status || "unknown";
        statusCounts[s] = (statusCounts[s] || 0) + 1;
        const p = a.priority || "unknown";
        priorityCounts[p] = (priorityCounts[p] || 0) + 1;
      }

      results.push({
        id: "tl-status",
        label: "actions status 분포",
        status: "pass",
        detail: Object.entries(statusCounts).map(([k, v]) => `${k}: ${v}`).join(", "),
      });

      results.push({
        id: "tl-priority",
        label: "actions priority 분포",
        status: "pass",
        detail: Object.entries(priorityCounts).map(([k, v]) => `${k}: ${v}`).join(", "),
      });

      const withDueDate = actions.filter((a) => !!a.dueDate);
      results.push({
        id: "tl-due",
        label: "dueDate 필드 존재",
        status: withDueDate.length > 0 ? "pass" : "warn",
        detail: `${withDueDate.length}/${actions.length}개`,
      });
    }
  } catch (err: any) {
    results.push({ id: "tl-actions", label: "V3 actions 조회", status: "fail", detail: `에러: ${err.message}` });
  }

  return results;
};
