import { useEffect, useMemo, useState } from "react";
import { useParams } from "react-router-dom";
import { AlertTriangle, ClipboardList, GitCompare } from "lucide-react";
import { getDocument, getSummary, subscribeInsights } from "../../../db/boards";
import type { InsightDoc } from "../../../db/collections";
import { MetricCard } from "../../../components/shared/MetricCard";
import { EmptyState } from "../../../components/shared/EmptyState";

interface DiffDimension {
  dimension: string;
  gapSeverity: number;
  gapLevel: string;
  gapDescription?: string;
  customerValue?: string[];
  autoDetectedValue?: string[];
}

export function ActionPlan() {
  const { id } = useParams<{ id: string }>();
  const [diffDoc, setDiffDoc] = useState<Record<string, unknown> | null>(null);
  const [actionPlanDoc, setActionPlanDoc] = useState<Record<string, unknown> | null>(null);
  const [insightCards, setInsightCards] = useState<InsightDoc[]>([]);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    if (!id) return;
    setLoading(true);
    const unsubInsights = subscribeInsights(id, setInsightCards, {
      type: "brand_identity",
    });
    Promise.all([
      getSummary(id, "brand-gap").catch(() => null),
      getDocument(id, "action-plan").catch(() => null),
    ]).then(([diff, plan]) => {
      if (diff) setDiffDoc(diff as Record<string, unknown>);
      if (plan?.data) setActionPlanDoc(plan.data as Record<string, unknown>);
      setLoading(false);
    });
    return unsubInsights;
  }, [id]);

  const openInsightCards = useMemo(
    () => insightCards.filter((i) => i.status !== "resolved" && i.status !== "ignored"),
    [insightCards],
  );

  if (loading) return <Loading />;

  const overallGapScore = (diffDoc?.overallGapScore as number) ?? 0;
  const dimensions = (diffDoc?.dimensions as DiffDimension[]) ?? [];
  const nextActions = (diffDoc?.nextActions as string[]) ??
    (diffDoc?.recommendedActions as string[]) ??
    (diffDoc?.actionPlanSummary ? [diffDoc.actionPlanSummary as string] : []);
  const actionSummary = (actionPlanDoc?.summary as string) ?? "";
  const highGapCount = dimensions.filter((d) => d.gapLevel === "HIGH").length;

  if (!diffDoc && !actionPlanDoc && openInsightCards.length === 0) {
    return <EmptyState icon={ClipboardList} title="No action plan data" description="전체 분석을 실행하면 갭 분석 기반의 액션 권고가 생성됩니다" />;
  }

  return (
    <div className="space-y-6">
      {/* Metrics */}
      <div className="grid gap-4 sm:grid-cols-2 lg:grid-cols-4">
        <MetricCard icon={GitCompare} label="Gap Score" value={String(overallGapScore)} color={overallGapScore >= 70 ? "text-rose-500" : overallGapScore >= 35 ? "text-amber-500" : "text-emerald-600"} />
        <MetricCard icon={GitCompare} label="Dimensions" value={String(dimensions.length)} color="text-blue-600" />
        <MetricCard icon={GitCompare} label="High Gaps" value={String(highGapCount)} color="text-rose-500" />
        <MetricCard icon={ClipboardList} label="Planned Actions" value={String(nextActions.length)} color="text-teal-600" />
      </div>

      {/* Gap Score Hero */}
      {diffDoc && (
        <div className="rounded-2xl border border-[var(--shell-border)] bg-[var(--shell-panel)] p-6 text-center">
          <p className="text-xs text-[var(--shell-text-muted)]">Overall Gap Score</p>
          <p className={`mt-1 text-5xl font-bold ${overallGapScore >= 70 ? "text-rose-500" : overallGapScore >= 35 ? "text-amber-500" : "text-emerald-600"}`}>
            {overallGapScore}<span className="text-lg text-[var(--shell-text-muted)]">/100</span>
          </p>
          <p className="mt-2 text-sm text-[var(--shell-text-muted)]">
            {overallGapScore >= 70
              ? "Large gap between customer perception and web reality"
              : overallGapScore >= 35
                ? "Moderate gap -- some dimensions need attention"
                : "Healthy alignment between perception and reality"}
          </p>
        </div>
      )}

      {/* Open brand insights */}
      {openInsightCards.length > 0 && (
        <div className="rounded-2xl border border-[var(--shell-border)] bg-[var(--shell-panel)] p-5">
          <div className="flex items-center gap-2">
            <AlertTriangle className="h-4 w-4 text-amber-500" />
            <h3 className="text-sm font-semibold text-[var(--shell-text)]">Open Brand Gaps</h3>
            <span className="text-xs text-[var(--shell-text-muted)]">({openInsightCards.length})</span>
          </div>
          <div className="mt-3 space-y-2">
            {openInsightCards.slice(0, 10).map((ins) => (
              <div key={ins.id} className="rounded-xl border border-[var(--shell-border)] bg-[var(--shell-panel-soft)] px-4 py-3">
                <div className="flex items-center justify-between gap-2">
                  <p className="text-sm font-medium text-[var(--shell-text)]">{ins.title}</p>
                  <span className={`rounded-md px-1.5 py-0.5 text-[10px] font-medium ${
                    ins.severity === "critical" ? "bg-rose-500/10 text-rose-500"
                      : ins.severity === "warning" ? "bg-amber-500/10 text-amber-500"
                      : "bg-blue-400/10 text-blue-500"
                  }`}>
                    {ins.severity}
                  </span>
                </div>
                {ins.summary && <p className="mt-1 text-xs text-[var(--shell-text-muted)]">{ins.summary}</p>}
                {ins.suggestion && <p className="mt-1 text-xs text-[var(--shell-text)]">{ins.suggestion}</p>}
              </div>
            ))}
          </div>
        </div>
      )}

      {/* Action Plan Summary */}
      {actionSummary && (
        <div className="rounded-2xl border border-[var(--shell-border)] bg-[var(--shell-panel)] p-5">
          <h3 className="text-sm font-semibold text-[var(--shell-text)]">Action Plan Summary</h3>
          <p className="mt-2 whitespace-pre-wrap text-sm leading-relaxed text-[var(--shell-text-muted)]">{actionSummary}</p>
        </div>
      )}

      {/* Recommended Next Actions */}
      {nextActions.length > 0 && (
        <div className="rounded-2xl border border-[var(--shell-border)] bg-[var(--shell-panel)] p-5">
          <h3 className="text-sm font-semibold text-[var(--shell-text)]">Recommended Actions</h3>
          <div className="mt-3 space-y-2">
            {nextActions.map((action, i) => (
              <div key={i} className="flex items-start gap-3 rounded-xl border border-[var(--shell-border)] bg-[var(--shell-panel-soft)] px-4 py-3">
                <span className="mt-0.5 flex h-5 w-5 shrink-0 items-center justify-center rounded-full bg-blue-500/15 text-[10px] font-semibold text-blue-600">{i + 1}</span>
                <span className="text-sm text-[var(--shell-text-muted)]">{action}</span>
              </div>
            ))}
          </div>
        </div>
      )}

      {/* Dimension Cards */}
      {dimensions.length > 0 && (
        <div className="rounded-2xl border border-[var(--shell-border)] bg-[var(--shell-panel)] p-5">
          <h3 className="text-sm font-semibold text-[var(--shell-text)]">Gap Dimensions</h3>
          <div className="mt-3 grid gap-4 lg:grid-cols-2">
            {dimensions.map((dim, i) => {
              const barColor = dim.gapSeverity >= 70 ? "bg-rose-500" : dim.gapSeverity >= 35 ? "bg-amber-500" : "bg-emerald-500";
              const levelStyle = dim.gapLevel === "HIGH" ? "bg-rose-500/10 text-rose-500" : dim.gapLevel === "MEDIUM" ? "bg-amber-500/10 text-amber-500" : "bg-emerald-500/10 text-emerald-600";
              return (
                <div key={i} className="rounded-xl border border-[var(--shell-border)] bg-[var(--shell-panel-soft)] p-4">
                  <div className="flex items-center justify-between gap-3">
                    <span className="text-sm font-medium text-[var(--shell-text)]">{dim.dimension}</span>
                    <span className={`rounded-md px-2 py-0.5 text-[10px] font-medium ${levelStyle}`}>{dim.gapLevel}</span>
                  </div>
                  <div className="mt-3 h-1.5 overflow-hidden rounded-full bg-[var(--shell-panel)]">
                    <div className={`h-full rounded-full ${barColor}`} style={{ width: `${dim.gapSeverity}%` }} />
                  </div>
                  <div className="mt-3 grid grid-cols-2 gap-2">
                    <div className="rounded-lg border border-[var(--shell-border)] bg-[var(--shell-panel)] p-2.5">
                      <p className="text-[10px] text-[var(--shell-text-muted)]">Customer</p>
                      <p className="mt-0.5 text-xs text-[var(--shell-text)]">{dim.customerValue?.join(", ") || "--"}</p>
                    </div>
                    <div className="rounded-lg border border-[var(--shell-border)] bg-[var(--shell-panel)] p-2.5">
                      <p className="text-[10px] text-[var(--shell-text-muted)]">Web Reality</p>
                      <p className="mt-0.5 text-xs text-[var(--shell-text)]">{dim.autoDetectedValue?.join(", ") || "--"}</p>
                    </div>
                  </div>
                  {dim.gapDescription && (
                    <p className="mt-2 text-xs text-[var(--shell-text-muted)]">{dim.gapDescription}</p>
                  )}
                </div>
              );
            })}
          </div>
        </div>
      )}
    </div>
  );
}

function Loading() {
  return <div className="flex min-h-[30vh] items-center justify-center text-sm text-[var(--shell-text-muted)]">Loading...</div>;
}
