import { useEffect, useState } from "react";
import { Link, useParams } from "react-router-dom";
import {
  Activity, AlertTriangle, CheckCircle2, Clock, Eye,
  GitBranch, Search, Shield, TrendingUp, XCircle,
} from "lucide-react";
import {
  subscribeBoard,
  subscribeRuns,
  listSeoAudits,
  listGeoProbesV2,
  listErrorJournal,
  getDocument,
  listActionPreviews,
} from "../../db/boards";
import type { Board, RunDoc, StructuredAction } from "../../db/collections";
import { MetricCard } from "../../components/shared/MetricCard";
import { EmptyState } from "../../components/shared/EmptyState";

// ── Types ──────────────────────────────────────────────────

interface Violation {
  rule: string;
  severity: "error" | "warning";
  message: string;
}

interface SeoAuditSnapshot {
  seoScore: number;
  /** @deprecated legacy field; use seoScore. */
  score?: number;
  geoScore: number;
  violations: Violation[];
}

// ── Component ──────────────────────────────────────────────

export function Home() {
  const { id } = useParams<{ id: string }>();
  const [board, setBoard] = useState<Board | null>(null);
  const [runs, setRuns] = useState<RunDoc[]>([]);
  const [audit, setAudit] = useState<SeoAuditSnapshot | null>(null);
  const [geoProbeCount, setGeoProbeCount] = useState(0);
  const [mentionRate, setMentionRate] = useState<number | null>(null);
  const [errorCount, setErrorCount] = useState(0);
  const [actions, setActions] = useState<StructuredAction[]>([]);
  const [previewCount, setPreviewCount] = useState(0);

  useEffect(() => {
    if (!id) return;
    const unsubs = [
      subscribeBoard(id, setBoard),
      subscribeRuns(id, setRuns),
    ];

    listSeoAudits(id, 1).then((r) => {
      if (r[0]) setAudit(r[0] as unknown as SeoAuditSnapshot);
    });
    listGeoProbesV2(id).then((probes) => {
      setGeoProbeCount(probes.length);
      const mentioned = probes.filter((p) => p.ourSiteMentioned).length;
      setMentionRate(probes.length > 0 ? Math.round((mentioned / probes.length) * 100) : null);
    });
    listErrorJournal(id, 50).then((e) => {
      const today = new Date().toDateString();
      setErrorCount(e.filter((x) => x.createdAt?.toDateString() === today).length);
    });
    getDocument(id, "action-plan").then((doc) => {
      if (doc?.data && Array.isArray((doc.data as Record<string, unknown>).structuredActions)) {
        setActions((doc.data as Record<string, unknown>).structuredActions as StructuredAction[]);
      }
    });
    listActionPreviews(id).then((p) => setPreviewCount(p.length));

    return () => unsubs.forEach((u) => u());
  }, [id]);

  // ── Derived stats ──

  const todayRuns = runs.filter(
    (r) => r.startedAt.toDateString() === new Date().toDateString(),
  );
  const runSuccess = todayRuns.filter((r) => r.status === "complete").length;
  const runFailed = todayRuns.filter((r) => r.status === "failed" || r.status === "partial").length;
  const runActive = todayRuns.filter((r) => r.status === "running").length;

  const violations = audit?.violations ?? [];
  const criticalCount = violations.filter((v) => v.severity === "error").length;
  const warningCount = violations.length - criticalCount;

  const highActions = actions.filter((a) => a.priority === "high").length;

  return (
    <div className="mx-auto max-w-6xl space-y-8 p-6 lg:p-10">
      {/* Header */}
      <div>
        <h1 className="text-2xl font-semibold tracking-tight text-[var(--shell-text)]">Home</h1>
        <p className="mt-1 text-sm text-[var(--shell-text-muted)]">
          오늘의 상태, 우선순위, 최근 변경 내역을 확인합니다
        </p>
      </div>

      {/* Key Metric Cards */}
      <div className="grid gap-4 sm:grid-cols-2 lg:grid-cols-4">
        <MetricCard
          icon={Search}
          label="SEO Score"
          value={audit ? String(audit.seoScore ?? audit.score ?? 0) : "--"}
          color="text-blue-600"
        />
        <MetricCard
          icon={Eye}
          label="GEO Score"
          value={audit ? String(audit.geoScore) : "--"}
          color="text-teal-600"
        />
        <MetricCard
          icon={Shield}
          label="Questions Tracked"
          value={geoProbeCount > 0 ? String(geoProbeCount) : "--"}
          color="text-cyan-600"
        />
        <MetricCard
          icon={TrendingUp}
          label="Mention Rate"
          value={mentionRate !== null ? `${mentionRate}%` : "--"}
          color="text-emerald-600"
        />
      </div>

      {/* Three-column status grid */}
      <div className="grid gap-6 lg:grid-cols-3">
        {/* Today's Priorities */}
        <StatusSection
          icon={Clock}
          title="Today's Priorities"
          color="text-amber-600"
          boardId={id}
        >
          <PriorityRow
            label="Critical issues"
            count={criticalCount}
            tone={criticalCount > 0 ? "danger" : "neutral"}
            link={id ? `/board/${id}/workspace/insights/board` : undefined}
          />
          <PriorityRow
            label="Warnings"
            count={warningCount}
            tone={warningCount > 0 ? "warning" : "neutral"}
            link={id ? `/board/${id}/workspace/insights/board` : undefined}
          />
          <PriorityRow
            label="High-priority actions"
            count={highActions}
            tone={highActions > 0 ? "accent" : "neutral"}
            link={id ? `/board/${id}/workspace/actions/recommended` : undefined}
          />
          <PriorityRow
            label="Errors today"
            count={errorCount}
            tone={errorCount > 0 ? "danger" : "neutral"}
            link={id ? `/board/${id}/workspace/operations` : undefined}
          />
        </StatusSection>

        {/* Run Health */}
        <StatusSection
          icon={Activity}
          title="Run Health"
          color="text-blue-600"
          boardId={id}
        >
          <div className="grid grid-cols-3 gap-3">
            <MiniStat label="Runs" value={todayRuns.length} icon={GitBranch} />
            <MiniStat label="Success" value={runSuccess} icon={CheckCircle2} color="text-emerald-600" />
            <MiniStat label="Failed" value={runFailed} icon={XCircle} color="text-rose-500" />
          </div>
          {runActive > 0 && (
            <div className="mt-3 flex items-center gap-2 rounded-xl bg-blue-500/10 px-3 py-2 text-xs font-medium text-blue-600">
              <div className="h-1.5 w-1.5 animate-pulse rounded-full bg-blue-500" />
              {runActive} run{runActive > 1 ? "s" : ""} active
            </div>
          )}
          {todayRuns.length === 0 && (
            <p className="mt-2 text-xs text-[var(--shell-text-muted)]">No runs today</p>
          )}
        </StatusSection>

        {/* Pending Actions */}
        <StatusSection
          icon={AlertTriangle}
          title="Pending Actions"
          color="text-rose-500"
          boardId={id}
        >
          <PriorityRow
            label="Structured actions"
            count={actions.length}
            tone="neutral"
            link={id ? `/board/${id}/workspace/actions/recommended` : undefined}
          />
          <PriorityRow
            label="Previews generated"
            count={previewCount}
            tone="neutral"
            link={id ? `/board/${id}/workspace/actions/studio` : undefined}
          />
          {actions.length === 0 && previewCount === 0 && (
            <p className="mt-1 text-xs text-[var(--shell-text-muted)]">
              대기 중인 액션이 없습니다. 분석을 실행하면 권고 사항이 생성됩니다.
            </p>
          )}
        </StatusSection>
      </div>

      {/* Active Diagnoses + Recent Changes */}
      <div className="grid gap-6 lg:grid-cols-2">
        {/* Active Diagnoses */}
        <div className="rounded-2xl border border-[var(--shell-border)] bg-[var(--shell-panel)] p-6">
          <div className="flex items-center justify-between">
            <div className="flex items-center gap-2 text-[var(--shell-text)]">
              <AlertTriangle className="h-5 w-5 text-rose-500" />
              <h2 className="text-lg font-semibold">Active Diagnoses</h2>
            </div>
            {id && violations.length > 0 && (
              <Link
                to={`/board/${id}/workspace/insights/board`}
                className="text-xs font-medium text-[var(--shell-accent)] hover:underline"
              >
                View all
              </Link>
            )}
          </div>

          {violations.length > 0 ? (
            <div className="mt-4 space-y-2">
              {violations.slice(0, 6).map((v, i) => (
                <div
                  key={`${v.rule}-${i}`}
                  className="flex items-start gap-3 rounded-xl border border-[var(--shell-border)] bg-[var(--shell-panel-soft)] px-3 py-2.5"
                >
                  <span
                    className={`mt-0.5 inline-block h-2 w-2 flex-shrink-0 rounded-full ${
                      v.severity === "error" ? "bg-rose-500" : "bg-amber-500"
                    }`}
                  />
                  <div className="min-w-0">
                    <p className="text-sm font-medium text-[var(--shell-text)]">{v.message}</p>
                    <p className="mt-0.5 text-xs text-[var(--shell-text-muted)]">{v.rule}</p>
                  </div>
                </div>
              ))}
              {violations.length > 6 && (
                <p className="pt-1 text-center text-xs text-[var(--shell-text-muted)]">
                  +{violations.length - 6} more issues
                </p>
              )}
            </div>
          ) : (
            <EmptyState
              icon={CheckCircle2}
              title="No active issues"
              description="진단을 실행하면 문제를 점검합니다"
            />
          )}
        </div>

        {/* Recent Changes */}
        <div className="rounded-2xl border border-[var(--shell-border)] bg-[var(--shell-panel)] p-6">
          <div className="flex items-center gap-2 text-[var(--shell-text)]">
            <Activity className="h-5 w-5 text-blue-600" />
            <h2 className="text-lg font-semibold">Recent Changes</h2>
          </div>

          {board?.activity && board.activity.length > 0 ? (
            <div className="mt-4 space-y-2">
              {board.activity.slice(0, 8).map((a) => (
                <div
                  key={a.id}
                  className="flex items-start gap-3 rounded-xl border border-[var(--shell-border)] bg-[var(--shell-panel-soft)] px-3 py-2.5"
                >
                  <div className="mt-1 h-1.5 w-1.5 flex-shrink-0 rounded-full bg-[var(--shell-accent)]" />
                  <div className="min-w-0">
                    <p className="text-sm text-[var(--shell-text)]">{a.action}</p>
                    <p className="mt-0.5 text-xs text-[var(--shell-text-muted)]">
                      {formatRelativeTime(a.createdAt)}
                      {a.entityType && ` \u00B7 ${a.entityType}`}
                    </p>
                  </div>
                </div>
              ))}
            </div>
          ) : (
            <EmptyState
              icon={Activity}
              title="No recent activity"
              description="분석과 액션이 실행되면 활동 내역이 여기에 표시됩니다"
            />
          )}
        </div>
      </div>
    </div>
  );
}

// ── Sub-components ──────────────────────────────────────────

function StatusSection(props: {
  icon: typeof Activity;
  title: string;
  color: string;
  boardId?: string;
  children: React.ReactNode;
}) {
  const Icon = props.icon;
  return (
    <div className="rounded-2xl border border-[var(--shell-border)] bg-[var(--shell-panel)] p-5">
      <div className="flex items-center gap-2 mb-4">
        <div className={`rounded-xl bg-[var(--shell-panel-soft)] p-2 ${props.color}`}>
          <Icon className="h-4 w-4" />
        </div>
        <h3 className="text-sm font-semibold text-[var(--shell-text)]">{props.title}</h3>
      </div>
      {props.children}
    </div>
  );
}

function PriorityRow(props: {
  label: string;
  count: number;
  tone: "danger" | "warning" | "accent" | "neutral";
  link?: string;
}) {
  const colorMap = {
    danger: "text-rose-500",
    warning: "text-amber-500",
    accent: "text-[var(--shell-accent)]",
    neutral: "text-[var(--shell-text)]",
  };
  const inner = (
    <div className="flex items-center justify-between rounded-lg px-2 py-1.5 transition-colors hover:bg-[var(--shell-panel-soft)]">
      <span className="text-sm text-[var(--shell-text-muted)]">{props.label}</span>
      <span className={`text-sm font-semibold ${props.count > 0 ? colorMap[props.tone] : "text-[var(--shell-text-muted)]"}`}>
        {props.count}
      </span>
    </div>
  );
  return props.link ? <Link to={props.link}>{inner}</Link> : inner;
}

function MiniStat(props: {
  label: string;
  value: number;
  icon: typeof Activity;
  color?: string;
}) {
  const Icon = props.icon;
  return (
    <div className="flex flex-col items-center gap-1 rounded-xl bg-[var(--shell-panel-soft)] py-2.5">
      <Icon className={`h-3.5 w-3.5 ${props.color ?? "text-[var(--shell-text-muted)]"}`} />
      <span className="text-lg font-semibold text-[var(--shell-text)]">{props.value}</span>
      <span className="text-[10px] text-[var(--shell-text-muted)]">{props.label}</span>
    </div>
  );
}

// ── Helpers ─────────────────────────────────────────────────

function formatRelativeTime(dateStr: string): string {
  try {
    const date = new Date(dateStr);
    const diffMs = Date.now() - date.getTime();
    const mins = Math.floor(diffMs / 60000);
    if (mins < 1) return "just now";
    if (mins < 60) return `${mins}m ago`;
    const hours = Math.floor(mins / 60);
    if (hours < 24) return `${hours}h ago`;
    const days = Math.floor(hours / 24);
    return `${days}d ago`;
  } catch {
    return dateStr;
  }
}
