import { getDocs, query, limit as fbLimit } from "firebase/firestore";
import { paths } from "../../../db/paths";
import type { DiagnosticCheck, DiagnosticRunner } from "./types";

export const runImprovementPlanDiagnostics: DiagnosticRunner = async (boardId) => {
  const results: DiagnosticCheck[] = [];

  // V3 Recommendations
  try {
    const snap = await getDocs(query(paths.v3Recommendations(boardId), fbLimit(50)));
    const recs = snap.docs.map((d) => ({ id: d.id, ...d.data() })) as any[];
    results.push({
      id: "ip-recs",
      label: "V3 recommendations 문서 수",
      status: recs.length > 0 ? "pass" : "fail",
      detail: `${recs.length}개`,
    });

    if (recs.length > 0) {
      const statusCounts: Record<string, number> = {};
      for (const r of recs) {
        const s = r.status || "unknown";
        statusCounts[s] = (statusCounts[s] || 0) + 1;
      }
      results.push({
        id: "ip-recs-status",
        label: "recommendations status 분포",
        status: "pass",
        detail: Object.entries(statusCounts).map(([k, v]) => `${k}: ${v}`).join(", "),
      });

      const withCategory = recs.filter((r) => !!r.category);
      results.push({
        id: "ip-recs-category",
        label: "category 필드 존재",
        status: withCategory.length === recs.length ? "pass" : "warn",
        detail: `${withCategory.length}/${recs.length}개`,
      });
    }
  } catch (err: any) {
    results.push({ id: "ip-recs", label: "V3 recommendations 조회", status: "fail", detail: `에러: ${err.message}` });
  }

  // V3 Actions (converted from recommendations)
  try {
    const snap = await getDocs(query(paths.v3Actions(boardId), fbLimit(50)));
    const actions = snap.docs.map((d) => ({ id: d.id, ...d.data() })) as any[];
    results.push({
      id: "ip-actions",
      label: "V3 actions (전환된 액션) 수",
      status: actions.length > 0 ? "pass" : "warn",
      detail: `${actions.length}개`,
    });
  } catch (err: any) {
    results.push({ id: "ip-actions", label: "V3 actions 조회", status: "fail", detail: `에러: ${err.message}` });
  }

  return results;
};
