// @ts-nocheck — 고객 화면 4: V3 기획서 Sheet 1 인풋 정합성 적용.
//   brandKeywords / brandWeaknesses / targetPersona / queryCategories / competitorDomains 신규.
import { useEffect, useState } from "react";
import { useParams, useSearchParams } from "react-router-dom";
import { useMutation, useQuery, useQueryClient } from "@tanstack/react-query";
import { Save, Plus, X } from "lucide-react";
import { type BrandTruth, KR_REGIONS, SAMPLE_COUNT_PRESETS, V3_QUERY_CATEGORIES, normalizeQueryCategory } from "./dataHub/types";
import { trendApi } from "./dataHub";
import { V3MeasurementCard } from "./V3MeasurementCard";
import { HeaderDiagnosticButton } from "./V3DiagnosticPanel";
import { runInputDiagnostics } from "./diagnostics/inputDiagnostics";

const EMPTY: BrandTruth = {
  canonicalName: "",
  businessSummary: "",
  primaryCategory: "",
  coreOfferings: [],
  positiveKeywords: [],
  negativeKeywords: [],
  mustWinQueries: [],
  importantCompetitors: [],
  measurementCadence: { frequency: "weekly", runsPerCycle: 1, totalSamples: 30, runAt: "09:00", regionalMode: false, regions: [] },
  // ★ Phase 2 — V3 인풋 정합성 (Sheet 1)
  brandAliases: [],
  brandKeywords: [],
  brandWeaknesses: [],
  targetPersona: "",
  queryCategories: {},
  competitorDomains: {},
};

export function PortalV3Input() {
  const { id } = useParams<{ id: string }>();
  const [searchParams] = useSearchParams();
  const queryClient = useQueryClient();
  const [draft, setDraft] = useState<BrandTruth>(EMPTY);
  const [feedback, setFeedback] = useState<{ ok: boolean; message: string } | null>(null);

  const { data, isLoading } = useQuery({
    queryKey: ["portalV3", "brand-truth", id],
    queryFn: () => trendApi.getBrandTruth(id!),
    enabled: !!id,
    staleTime: 60_000,
  });

  useEffect(() => {
    if (data?.truth) {
      const t: any = data.truth;
      setDraft({
        ...EMPTY,
        ...t,
        coreOfferings: t.coreOfferings || [],
        positiveKeywords: t.positiveKeywords || [],
        negativeKeywords: t.negativeKeywords || [],
        mustWinQueries: t.mustWinQueries || [],
        importantCompetitors: t.importantCompetitors || [],
        measurementCadence: t.measurementCadence || EMPTY.measurementCadence,
        // ★ Phase 2 — V3 신규 필드 + 기존 필드로부터 fallback (마이그레이션 대비)
        brandAliases: t.brandAliases || (t.aliases || []),   // ★ legacy aliases 도 자동 흡수
        brandKeywords: t.brandKeywords?.length ? t.brandKeywords : (t.positiveKeywords || []).slice(0, 5),
        brandWeaknesses: t.brandWeaknesses?.length ? t.brandWeaknesses : (t.negativeKeywords || []).slice(0, 5),
        targetPersona: t.targetPersona || t.targetAudience || "",
        queryCategories: t.queryCategories || {},
        competitorDomains: t.competitorDomains || {},
      });
    }
  }, [data]);

  const save = useMutation({
    mutationFn: (truth: BrandTruth) => trendApi.saveBrandTruth(id!, truth),
    onSuccess: () => {
      setFeedback({ ok: true, message: "저장되었습니다." });
      queryClient.invalidateQueries({ queryKey: ["portalV3", "brand-truth", id] });
    },
    onError: (err: any) => {
      setFeedback({ ok: false, message: err instanceof Error ? err.message : "저장 실패" });
    },
  });

  return (
    <>
      {id && <HeaderDiagnosticButton boardId={id} title="Input Diagnostics" runner={runInputDiagnostics} />}
      <div className="mx-auto max-w-3xl space-y-5 px-4 py-6">
        <header>
          <div className="text-xs uppercase tracking-[0.28em] text-[var(--shell-text-soft)]">Client / 고객 인풋</div>
          <h1 className="mt-2 text-3xl font-semibold tracking-tight text-[var(--shell-text)]">브랜드 정보 입력</h1>
          <p className="mt-2 text-sm text-[var(--shell-text-muted)]">
            브랜드의 기본 정보, 핵심 서비스, 중요 키워드, 꼭 노출되어야 할 검색 쿼리를 입력합니다. 입력 내용은 분석 정확도를 높이고 LLM 컨텍스트로 활용됩니다.
          </p>
        </header>

        {isLoading && (
          <div className="rounded-2xl border border-[var(--shell-border)] bg-[var(--shell-panel)] px-6 py-12 text-center text-sm text-[var(--shell-text-muted)]">
            불러오는 중입니다...
          </div>
        )}

        {!isLoading && (
          <>
            {/* ★ 02 Input mockup — 회사 정보 섹션 (신규) */}
            <section className="rounded-2xl border border-[var(--shell-border)] bg-[var(--shell-panel)] p-5">
              <div className="mb-3 flex items-center gap-2 text-sm font-semibold text-[var(--shell-text)]">
                <span className="inline-block h-1.5 w-1.5 rounded-full bg-[var(--shell-accent)]" />
                회사 정보
              </div>
              <div className="space-y-4">
                <FieldText
                  label="회사명"
                  value={draft.companyName || ""}
                  onChange={(v) => setDraft((d) => ({ ...d, companyName: v }))}
                  placeholder="ex) (주)드시모네코리아"
                />
                <FieldText
                  label="담당자 성함"
                  value={draft.contactName || ""}
                  onChange={(v) => setDraft((d) => ({ ...d, contactName: v }))}
                  placeholder="ex) 홍길동"
                />
                <FieldText
                  label="이메일 주소"
                  value={draft.contactEmail || ""}
                  onChange={(v) => setDraft((d) => ({ ...d, contactEmail: v }))}
                  placeholder="ex) contact@desimone.co.kr"
                />
              </div>
            </section>

            {/* ★ 02 Input mockup — 브랜드 본질 */}
            <section className="rounded-2xl border border-[var(--shell-border)] bg-[var(--shell-panel)] p-5">
              <div className="mb-3 flex items-center gap-2 text-sm font-semibold text-[var(--shell-text)]">
                <span className="inline-block h-1.5 w-1.5 rounded-full bg-[var(--shell-accent)]" />
                브랜드 본질
              </div>
              <div className="space-y-4">
                <FieldText
                  label="브랜드명"
                  value={draft.canonicalName}
                  onChange={(v) => setDraft((d) => ({ ...d, canonicalName: v }))}
                  placeholder="ex) 드시모네"
                />
                <FieldList
                  label="브랜드 별칭 (최대 10개, 권장)"
                  hint="AI 답변에서 자사를 가리키는 다른 표기를 모두 추가하세요. 예: 브랜드명이 '드시모네몰' 이면 ['드시모네', 'De Simone', 'DeSimone'] 추가. 매칭률이 크게 올라갑니다."
                  items={draft.brandAliases || []}
                  onChange={(items) => setDraft((d) => ({ ...d, brandAliases: items }))}
                  max={10}
                  placeholder="ex) 드시모네, De Simone, DeSimone"
                />
                <FieldText
                  label="업종 / 카테고리"
                  value={draft.primaryCategory}
                  onChange={(v) => setDraft((d) => ({ ...d, primaryCategory: v }))}
                  placeholder="ex) 건강기능식품 - 유산균"
                />
                <FieldTextarea
                  label="비즈니스 한 줄 설명 (서비스 / 타겟 / 차별점)"
                  value={draft.businessSummary}
                  onChange={(v) => setDraft((d) => ({ ...d, businessSummary: v }))}
                  placeholder="ex) 30~50대 여성을 위한 프리미엄 프로바이오틱스 브랜드. 의사 처방 기반으로 개발."
                  rows={3}
                />
                <FieldList
                  label="핵심 서비스 / 제품 (최대 5개)"
                  hint="대표 제품/서비스를 한 줄에 하나씩"
                  items={draft.coreOfferings}
                  onChange={(items) => setDraft((d) => ({ ...d, coreOfferings: items }))}
                  max={5}
                  placeholder="제품/서비스명"
                />
              </div>
            </section>

            {/* ★ 02 Input mockup — 운영 채널 (신규: 공식/기타/SNS/비즈니스 프로필) */}
            <section className="rounded-2xl border border-[var(--shell-border)] bg-[var(--shell-panel)] p-5">
              <div className="mb-3 flex items-center gap-2 text-sm font-semibold text-[var(--shell-text)]">
                <span className="inline-block h-1.5 w-1.5 rounded-full bg-[var(--shell-accent)]" />
                운영 채널
              </div>
              <div className="space-y-4">
                <FieldText
                  label="공식 사이트"
                  hint="브랜드의 핵심 사이트, 본문을 위주로 분석"
                  value={draft.officialSite || ""}
                  onChange={(v) => setDraft((d) => ({ ...d, officialSite: v }))}
                  placeholder="https://www.desimone.co.kr"
                />
                <FieldList
                  label="기타 사이트 (최대 5개)"
                  hint="브랜드가 보유한 보조 사이트, 보조 사이트를 위주로 분석"
                  items={draft.subSites || []}
                  onChange={(items) => setDraft((d) => ({ ...d, subSites: items }))}
                  max={5}
                  placeholder="https://blog.desimone.co.kr"
                />
                <FieldList
                  label="SNS 채널"
                  hint="유튜브 · 페이스북 · 인스타그램 · X(트위터) · 블로그 · 카카오 · 네이버 블로그 · 네이버 카페"
                  items={draft.snsChannels || []}
                  onChange={(items) => setDraft((d) => ({ ...d, snsChannels: items }))}
                  max={10}
                  placeholder="ex) https://www.instagram.com/desimone_kr"
                />
                <FieldList
                  label="비즈니스 프로필"
                  hint="구글 비즈니스 프로필 · 옐프 · 트립어드바이저 · 네이버 스마트플레이스 등"
                  items={draft.businessProfiles || []}
                  onChange={(items) => setDraft((d) => ({ ...d, businessProfiles: items }))}
                  max={10}
                  placeholder="ex) https://maps.google.com/..."
                />
              </div>
            </section>

            {/* ★ Phase 2 (Sheet 1) — 키워드 · 약점 · 페르소나 */}
            <section className="rounded-2xl border border-[var(--shell-border)] bg-[var(--shell-panel)] p-5">
              <div className="mb-3 flex items-center gap-2 text-sm font-semibold text-[var(--shell-text)]">
                <span className="inline-block h-1.5 w-1.5 rounded-full bg-[var(--shell-accent)]" />
                키워드 · 약점 · 타겟
              </div>
              <div className="space-y-4">
                <FieldList
                  label="브랜드 키워드 — 강점, 경쟁사 차이점 (1~5개, 필수)"
                  hint="우리 브랜드의 강점과 경쟁사 대비 차별화 포인트를 키워드로 입력하세요. AI 쿼리 생성 시 컨텍스트로 활용됩니다."
                  items={draft.brandKeywords || []}
                  onChange={(items) => setDraft((d) => ({ ...d, brandKeywords: items, positiveKeywords: items /* legacy mirror */ }))}
                  max={5}
                  placeholder="ex) 장면역 개별인정, 4500억 CFU, SCI 365편"
                />
                <FieldList
                  label="브랜드 약점 / 보완점 (1~5개, 필수)"
                  hint="현재 인지하고 있는 브랜드 약점 — 개선 방향 분석 시 우선순위 반영. AI 답변에서 부정 톤이 나오면 추적됩니다."
                  items={draft.brandWeaknesses || []}
                  onChange={(items) => setDraft((d) => ({ ...d, brandWeaknesses: items, negativeKeywords: items /* legacy mirror */ }))}
                  max={5}
                  placeholder="ex) 가격이 비싸다, 냉장보관 불편, 브랜드 인지도 부족"
                />
                <FieldTextarea
                  label="타겟 페르소나 (선택)"
                  hint="핵심 고객층 정의 — 연령대 · 성별 · 라이프스타일 · 니즈. 쿼리 생성/분석 시 관점으로 반영. 최대 500자."
                  value={draft.targetPersona || ""}
                  onChange={(v) => setDraft((d) => ({ ...d, targetPersona: v.slice(0, 500) }))}
                  placeholder="ex) 40-50대 여성, 갱년기 면역력 저하 우려, 프리미엄 건강식품에 월 10만원 이상 투자 의향"
                  rows={3}
                />
                <div className="text-[10px] text-[var(--shell-text-soft)]">
                  {(draft.targetPersona || "").length} / 500자
                </div>
              </div>
            </section>

            {/* ★ Phase 2 — 머스트윈 쿼리 (10개) + 카테고리 태그 */}
            <section className="rounded-2xl border border-[var(--shell-border)] bg-[var(--shell-panel)] p-5">
              <div className="mb-3 flex items-center gap-2 text-sm font-semibold text-[var(--shell-text)]">
                <span className="inline-block h-1.5 w-1.5 rounded-full bg-[var(--shell-accent)]" />
                꼭 노출되어야 할 검색 쿼리 (최대 10개, 필수)
              </div>
              <div className="mb-3 text-[11px] leading-5 text-[var(--shell-text-muted)]">
                AI 답변에 우리 브랜드가 반드시 포함되어야 할 질문입니다.
                각 쿼리에 소비자 여정 4단계 카테고리를 부여하면 리포트에서 단계별 분석이 가능합니다:
              </div>
              <ul className="mb-3 space-y-0.5 text-[10px] text-[var(--shell-text-soft)]">
                <li>· <span className="font-semibold text-[var(--shell-text-muted)]">DISCOVER (탐색)</span> — 카테고리를 처음 탐색하는 소비자가 AI 에게 던지는 질문</li>
                <li>· <span className="font-semibold text-[var(--shell-text-muted)]">CONSIDER (비교)</span> — 제품/서비스를 비교하고 평가하는 단계의 질문</li>
                <li>· <span className="font-semibold text-[var(--shell-text-muted)]">DECIDE (결정)</span> — 구매 직전 최종 결정을 내리는 단계의 질문</li>
                <li>· <span className="font-semibold text-[var(--shell-text-muted)]">ADVOCATE (추천)</span> — 사용 경험자가 타인에게 추천하는 맥락의 질문</li>
              </ul>

              <QueryListWithCategories
                queries={draft.mustWinQueries || []}
                categories={draft.queryCategories || {}}
                onChange={(queries, categories) => setDraft((d) => ({
                  ...d,
                  mustWinQueries: queries,
                  queryCategories: categories,
                }))}
              />
            </section>

            {/* ★ Phase 2 — 주요 경쟁사 + 도메인 */}
            <section className="rounded-2xl border-2 border-[var(--shell-accent)]/30 bg-[var(--shell-accent)]/5 p-5">
              <div className="mb-3">
                <div className="flex items-center gap-2 text-sm font-semibold text-[var(--shell-text)]">
                  <span className="text-amber-300">⭐</span> 주요 경쟁사 + 도메인 (1~5개, 필수)
                </div>
                <div className="mt-1 text-[11px] leading-5 text-[var(--shell-text-muted)]">
                  AI 답변에서 함께 언급된 횟수와 톤(긍정/부정/중립)을 추적할 경쟁사입니다.
                  도메인을 함께 입력하면 AI 답변의 인용 URL이 자사/경쟁사 어느 쪽인지 자동 라벨링합니다.
                </div>
              </div>

              <CompetitorListWithDomains
                competitors={draft.importantCompetitors || []}
                domains={draft.competitorDomains || {}}
                onChange={(comps, doms) => setDraft((d) => ({
                  ...d,
                  importantCompetitors: comps,
                  competitorDomains: doms,
                }))}
              />
            </section>

            {/* ★ V3 측정 설정 — 실제 1000 calls (GPT + Gemini) + Claude 분석 */}
            <V3MeasurementCard />

            <div className="flex items-center justify-between gap-3">
              <div className="flex items-center gap-3">
                <button
                  type="button"
                  onClick={() => save.mutate(draft)}
                  disabled={save.isPending}
                  className="flex items-center gap-2 rounded-xl bg-[var(--shell-accent)] px-5 py-2.5 text-sm font-medium text-white hover:opacity-90 disabled:opacity-50"
                >
                  <Save className="h-4 w-4" />
                  {save.isPending ? "저장 중..." : "저장"}
                </button>
              </div>
              {data?.truth?.updatedAt && (
                <div className="text-[11px] text-[var(--shell-text-soft)]">
                  마지막 저장: {(data.truth.updatedAt?.toDate ? data.truth.updatedAt.toDate() : new Date(data.truth.updatedAt)).toLocaleString()}
                </div>
              )}
            </div>

            {feedback && (
              <div className={`rounded-xl border px-4 py-3 text-sm ${feedback.ok ? "border-emerald-500/30 bg-emerald-500/5 text-emerald-200" : "border-red-500/30 bg-red-500/5 text-red-200"}`}>
                {feedback.message}
              </div>
            )}
          </>
        )}
      </div>
    </>
  );
}

function FieldText({ label, hint, value, onChange, placeholder }: { label: string; hint?: string; value: string; onChange: (v: string) => void; placeholder?: string }) {
  return (
    <div>
      <label className="mb-1.5 block text-xs font-medium text-[var(--shell-text)]">{label}</label>
      {hint && <div className="mb-1.5 text-[11px] leading-5 text-[var(--shell-text-muted)]">{hint}</div>}
      <input
        type="text"
        value={value}
        onChange={(e) => onChange(e.target.value)}
        placeholder={placeholder}
        className="w-full rounded-lg border border-[var(--shell-border)] bg-[var(--shell-panel-soft)] px-3 py-2 text-sm text-[var(--shell-text)] placeholder-[var(--shell-text-soft)] outline-none focus:border-[var(--shell-accent)]"
      />
    </div>
  );
}

function FieldTextarea({ label, hint, value, onChange, placeholder, rows = 3 }: { label: string; hint?: string; value: string; onChange: (v: string) => void; placeholder?: string; rows?: number }) {
  return (
    <div>
      <label className="mb-1.5 block text-xs font-medium text-[var(--shell-text)]">{label}</label>
      {hint && <div className="mb-1.5 text-[11px] leading-5 text-[var(--shell-text-muted)]">{hint}</div>}
      <textarea
        value={value}
        onChange={(e) => onChange(e.target.value)}
        placeholder={placeholder}
        rows={rows}
        className="w-full rounded-lg border border-[var(--shell-border)] bg-[var(--shell-panel-soft)] px-3 py-2 text-sm text-[var(--shell-text)] placeholder-[var(--shell-text-soft)] outline-none focus:border-[var(--shell-accent)]"
      />
    </div>
  );
}

function FieldList({ label, hint, items, onChange, max, placeholder }: { label: string; hint?: string; items: string[]; onChange: (items: string[]) => void; max: number; placeholder?: string }) {
  const [input, setInput] = useState("");
  const add = () => {
    const v = input.trim();
    if (!v || items.includes(v) || items.length >= max) return;
    onChange([...items, v]);
    setInput("");
  };

  return (
    <div>
      <div className="mb-1.5 flex items-center justify-between">
        <label className="text-xs font-medium text-[var(--shell-text)]">{label}</label>
        <span className="text-[10px] text-[var(--shell-text-soft)]">{items.length} / {max}</span>
      </div>
      {hint && <div className="mb-1.5 text-[10px] text-[var(--shell-text-muted)]">{hint}</div>}
      <div className="mb-2 flex flex-wrap gap-1.5">
        {items.map((it, i) => (
          <span key={i} className="inline-flex items-center gap-1 rounded-full bg-[var(--shell-accent)]/15 px-3 py-1 text-xs text-[var(--shell-text)]">
            {it}
            <button
              type="button"
              onClick={() => onChange(items.filter((_, j) => j !== i))}
              className="text-[var(--shell-text-soft)] hover:text-red-300"
            >
              <X className="h-3 w-3" />
            </button>
          </span>
        ))}
      </div>
      <div className="flex items-center gap-2">
        <input
          type="text"
          value={input}
          onChange={(e) => setInput(e.target.value)}
          onKeyDown={(e) => {
            if (e.key === "Enter") {
              e.preventDefault();
              add();
            }
          }}
          placeholder={placeholder}
          disabled={items.length >= max}
          className="flex-1 rounded-lg border border-[var(--shell-border)] bg-[var(--shell-panel-soft)] px-3 py-1.5 text-xs text-[var(--shell-text)] placeholder-[var(--shell-text-soft)] outline-none focus:border-[var(--shell-accent)] disabled:opacity-50"
        />
        <button
          type="button"
          onClick={add}
          disabled={!input.trim() || items.length >= max}
          className="rounded-lg border border-[var(--shell-border)] px-3 py-1.5 text-xs text-[var(--shell-text)] hover:bg-[var(--shell-panel-soft)] disabled:opacity-50"
        >
          <Plus className="h-3 w-3" />
        </button>
      </div>
    </div>
  );
}

// ─── Phase 2 — 쿼리 + 카테고리 태그 입력 컴포넌트 ──────────────
function QueryListWithCategories({
  queries, categories, onChange,
}: {
  queries: string[];
  categories: { [q: string]: string };
  onChange: (queries: string[], categories: { [q: string]: string }) => void;
}) {
  const [input, setInput] = useState("");
  const max = 10;

  const add = () => {
    const v = input.trim();
    if (!v) return;
    if (queries.includes(v) || queries.length >= max) return;
    onChange([...queries, v], categories);
    setInput("");
  };

  const remove = (q: string) => {
    const next = queries.filter((x) => x !== q);
    const nextCats = { ...categories };
    delete nextCats[q];
    onChange(next, nextCats);
  };

  const setCategory = (q: string, code: string) => {
    const nextCats = { ...categories };
    if (code) nextCats[q] = code;
    else delete nextCats[q];
    onChange(queries, nextCats);
  };

  return (
    <div className="space-y-2">
      {queries.map((q, i) => (
        <div key={q} className="flex flex-col gap-2 rounded-xl border border-[var(--shell-border)] bg-[var(--shell-panel-soft)] p-3 sm:flex-row sm:items-center">
          <div className="flex flex-1 items-center gap-2 min-w-0">
            <span className="shrink-0 rounded-full bg-[var(--shell-panel)] px-2 py-0.5 text-[10px] font-medium text-[var(--shell-text-muted)]">
              Q{i + 1}
            </span>
            <span className="flex-1 truncate text-sm text-[var(--shell-text)]" title={q}>{q}</span>
          </div>
          <div className="flex items-center gap-2 shrink-0">
            <select
              value={normalizeQueryCategory(categories[q]) || ""}
              onChange={(e) => setCategory(q, e.target.value)}
              className="rounded-lg border border-[var(--shell-border)] bg-[var(--shell-panel)] px-2 py-1.5 text-[11px] text-[var(--shell-text)] outline-none focus:border-[var(--shell-accent)]"
              title={V3_QUERY_CATEGORIES.find((c) => c.code === normalizeQueryCategory(categories[q]))?.description}
            >
              <option value="">카테고리 선택...</option>
              {V3_QUERY_CATEGORIES.map((c) => (
                <option key={c.code} value={c.code} title={c.description}>
                  {c.code} — {c.name}
                </option>
              ))}
            </select>
            <button
              type="button"
              onClick={() => remove(q)}
              className="rounded p-1 text-[var(--shell-text-soft)] hover:bg-[var(--shell-panel)] hover:text-red-300"
            >
              <X className="h-3.5 w-3.5" />
            </button>
          </div>
        </div>
      ))}

      <div className="flex items-center gap-2">
        <input
          type="text"
          value={input}
          onChange={(e) => setInput(e.target.value)}
          onKeyDown={(e) => {
            if (e.key === "Enter") {
              e.preventDefault();
              add();
            }
          }}
          placeholder={queries.length >= max ? `최대 ${max}개 입력 완료` : `질문 입력 후 Enter (${queries.length}/${max})`}
          disabled={queries.length >= max}
          className="flex-1 rounded-lg border border-[var(--shell-border)] bg-[var(--shell-panel-soft)] px-3 py-2 text-sm text-[var(--shell-text)] placeholder-[var(--shell-text-soft)] outline-none focus:border-[var(--shell-accent)] disabled:opacity-50"
        />
        <button
          type="button"
          onClick={add}
          disabled={!input.trim() || queries.length >= max}
          className="rounded-lg border border-[var(--shell-border)] px-3 py-2 text-sm text-[var(--shell-text)] hover:bg-[var(--shell-panel-soft)] disabled:opacity-50"
        >
          <Plus className="h-3.5 w-3.5" />
        </button>
      </div>
    </div>
  );
}

// ─── Phase 2 — 경쟁사 + 도메인 입력 컴포넌트 ──────────────
function CompetitorListWithDomains({
  competitors, domains, onChange,
}: {
  competitors: string[];
  domains: { [name: string]: string };
  onChange: (competitors: string[], domains: { [name: string]: string }) => void;
}) {
  const [input, setInput] = useState("");
  const max = 5;

  const add = () => {
    const v = input.trim();
    if (!v) return;
    if (competitors.includes(v) || competitors.length >= max) return;
    onChange([...competitors, v], domains);
    setInput("");
  };

  const remove = (name: string) => {
    const next = competitors.filter((x) => x !== name);
    const nextDoms = { ...domains };
    delete nextDoms[name];
    onChange(next, nextDoms);
  };

  const setDomain = (name: string, dom: string) => {
    const nextDoms = { ...domains };
    const cleaned = dom.trim().replace(/^https?:\/\//, "").replace(/\/.*$/, "").toLowerCase();
    if (cleaned) nextDoms[name] = cleaned;
    else delete nextDoms[name];
    onChange(competitors, nextDoms);
  };

  return (
    <div className="space-y-2">
      {competitors.map((name, i) => (
        <div key={name} className="flex flex-col gap-2 rounded-xl border border-[var(--shell-border)] bg-[var(--shell-panel-soft)] p-3 sm:flex-row sm:items-center">
          <div className="flex flex-1 items-center gap-2 min-w-0">
            <span className="shrink-0 rounded-full bg-[var(--shell-panel)] px-2 py-0.5 text-[10px] font-medium text-[var(--shell-text-muted)]">
              #{i + 1}
            </span>
            <span className="shrink-0 text-sm font-medium text-[var(--shell-text)]">{name}</span>
          </div>
          <div className="flex items-center gap-2 shrink-0 flex-1 sm:flex-none sm:min-w-[260px]">
            <input
              type="text"
              value={domains[name] || ""}
              onChange={(e) => setDomain(name, e.target.value)}
              placeholder="ex) lactofit.co.kr"
              className="flex-1 rounded-lg border border-[var(--shell-border)] bg-[var(--shell-panel)] px-2 py-1 text-[11px] text-[var(--shell-text)] placeholder-[var(--shell-text-soft)] outline-none focus:border-[var(--shell-accent)]"
            />
            <button
              type="button"
              onClick={() => remove(name)}
              className="rounded p-1 text-[var(--shell-text-soft)] hover:bg-[var(--shell-panel)] hover:text-red-300"
            >
              <X className="h-3.5 w-3.5" />
            </button>
          </div>
        </div>
      ))}

      <div className="flex items-center gap-2">
        <input
          type="text"
          value={input}
          onChange={(e) => setInput(e.target.value)}
          onKeyDown={(e) => {
            if (e.key === "Enter") {
              e.preventDefault();
              add();
            }
          }}
          placeholder={competitors.length >= max ? `최대 ${max}개 입력 완료` : `경쟁사 이름 입력 후 Enter (${competitors.length}/${max})`}
          disabled={competitors.length >= max}
          className="flex-1 rounded-lg border border-[var(--shell-border)] bg-[var(--shell-panel-soft)] px-3 py-2 text-sm text-[var(--shell-text)] placeholder-[var(--shell-text-soft)] outline-none focus:border-[var(--shell-accent)] disabled:opacity-50"
        />
        <button
          type="button"
          onClick={add}
          disabled={!input.trim() || competitors.length >= max}
          className="rounded-lg border border-[var(--shell-border)] px-3 py-2 text-sm text-[var(--shell-text)] hover:bg-[var(--shell-panel-soft)] disabled:opacity-50"
        >
          <Plus className="h-3.5 w-3.5" />
        </button>
      </div>
    </div>
  );
}
