import { useEffect, useMemo, useState } from "react";
import { useParams } from "react-router-dom";
import {
  Check, ChevronDown, Eye, Lightbulb, MessageSquare,
  Play, Plus, Search, Star, Wrench, X, Zap,
} from "lucide-react";
import {
  listGeoProbesV2,
  getDocument,
  getBoard,
  getSummary,
  updateBrandKeywords,
  listSeoAudits,
  subscribeInsights,
} from "../../../db/boards";
import { flatKeywords, type Board, type BoardDocument, type InsightDoc } from "../../../db/collections";
import { OpenInsightsList } from "../../../components/shared/OpenInsightsList";
import { useCommand } from "../../../hooks/useCommand";
import { MetricCard } from "../../../components/shared/MetricCard";
import { EmptyState } from "../../../components/shared/EmptyState";
import { InsightSection } from "../../../components/shared/InsightSection";
import { DataQualityBadge } from "../../../components/shared/DataQualityBadge";

// ── Types ──────────────────────────────────────────────────

interface Probe {
  id: string;
  question: string;
  category: string;
  engine: string;
  status: string;
  answer: string;
  ourSiteInResults: boolean;
  ourSiteMentioned: boolean;
  ourMentionContext: string;
}

interface VisQuestion {
  question: string;
  category: string;
  engines: Array<{
    engine: string;
    inResults: boolean;
    mentioned: boolean;
    mentionContext?: string;
  }>;
}

interface EngineBreakdown {
  engine: string;
  totalQuestions: number;
  exposedCount: number;
  mentionedCount: number;
  exposureRate: number;
  mentionRate: number;
}

interface Violation {
  rule: string;
  file: string;
  severity: "error" | "warning";
  message: string;
  suggestion?: string;
}

interface SeoAuditData {
  seoScore: number;
  /** @deprecated legacy field; use seoScore. */
  score?: number;
  geoScore: number;
  errors: number;
  warnings: number;
  totalViolations: number;
  violations: Violation[];
  checks: Array<{ rule: string; label?: string; status: "pass" | "warn" | "fail"; message?: string }>;
  geoChecks: Array<{ rule: string; label?: string; status: "pass" | "warn" | "fail"; message?: string; score?: number }>;
  categories: Record<string, { errors: number; warnings: number }>;
}

interface ActionItem {
  title: string;
  type?: string;
  category?: string;
  priority?: string;
  expectedImpact?: string;
  effort?: string;
  description?: string;
}

const ENGINE_LABELS: Record<string, string> = {
  gpt: "ChatGPT", openai: "ChatGPT", gemini: "Gemini", claude: "Claude", perplexity: "Perplexity",
};

const CATEGORY_LABELS: Record<string, string> = {
  product: "Product", comparison: "Comparison", howto: "How-to", local: "Local", brand: "Brand",
};

type Category = "product" | "comparison" | "local" | "brand" | "howto";
const CATEGORY_OPTIONS: Category[] = ["product", "comparison", "local", "brand", "howto"];

const RULE_LABELS: Record<string, string> = {
  "geo-missing-source-citations": "Source Citations Missing",
  "geo-missing-expert-quotes": "No Expert Quotes",
  "geo-low-citation-density": "Low Citation Density",
  "geo-missing-author": "Author Info Missing",
  "geo-author-not-person": "Author Not a Person",
  "geo-passive-voice-excess": "Excessive Passive Voice",
  "geo-sentence-too-long": "Sentence Length Exceeded",
  "geo-weak-lead-sentences": "Weak Lead Sentences",
  "content-too-short": "Content Too Short",
  "geo-no-question-headings": "No Question Headings",
  "geo-missing-faq-section": "FAQ Section Missing",
  "schema-org-missing": "No Structured Data",
  "geo-missing-table": "No Data Tables",
  "geo-missing-lists": "No Lists",
  "geo-low-internal-links": "Low Internal Links",
  "geo-missing-tldr": "No TL;DR",
  "geo-missing-summary-section": "Summary Section Missing",
  "geo-llms-discovery": "AI Crawler Discoverability",
  "geo-answer-depth-coverage": "Answer Depth Coverage",
  "geo-question-answer-coverage": "Q&A Structure Coverage",
  "geo-evidence-citation-coverage": "Evidence & Trust Signals",
  "geo-entity-schema-coverage": "Entity Schema Coverage",
  "geo-authority-signal-coverage": "Authority Signals",
  "geo-freshness-coverage": "Freshness Signals",
};

const TIER1_RULES = [
  "geo-llms-discovery", "geo-answer-depth-coverage", "geo-question-answer-coverage",
  "geo-evidence-citation-coverage", "geo-missing-source-citations", "geo-missing-expert-quotes", "geo-low-citation-density",
];
const TIER2_RULES = [
  "geo-entity-schema-coverage", "geo-authority-signal-coverage", "geo-missing-author",
  "geo-author-not-person", "geo-passive-voice-excess", "geo-sentence-too-long", "geo-weak-lead-sentences", "content-too-short",
];
const TIER3_RULES = [
  "geo-freshness-coverage", "geo-no-question-headings", "geo-missing-faq-section",
  "schema-org-missing", "geo-missing-table", "geo-missing-lists", "geo-low-internal-links", "geo-missing-tldr", "geo-missing-summary-section",
];

const GEO_DIMENSIONS = [
  { key: "citations", label: "Citations & References" },
  { key: "expertQuotes", label: "Expert Quotes" },
  { key: "depth", label: "Content Depth" },
  { key: "balance", label: "Perspective Balance" },
  { key: "authority", label: "Authority Signals" },
  { key: "readability", label: "Readability" },
  { key: "faqQuality", label: "FAQ Quality" },
  { key: "answerCapsule", label: "Answer Capsule" },
];

// ── Component ──────────────────────────────────────────────

export function AiVisibilityInsight() {
  const { id } = useParams<{ id: string }>();
  const [board, setBoard] = useState<Board | null>(null);
  const [probes, setProbes] = useState<Probe[]>([]);
  const [visDoc, setVisDoc] = useState<BoardDocument | null>(null);
  const [audit, setAudit] = useState<SeoAuditData | null>(null);
  const [contentDoc, setContentDoc] = useState<Record<string, unknown> | null>(null);
  const [actionPlanDoc, setActionPlanDoc] = useState<BoardDocument | null>(null);
  const [insights, setInsights] = useState<InsightDoc[]>([]);
  const [loading, setLoading] = useState(true);
  const [newQuestion, setNewQuestion] = useState("");
  const [newCategory, setNewCategory] = useState<Category>("product");
  const [filterEngine, setFilterEngine] = useState("all");
  const [filterStatus, setFilterStatus] = useState<"all" | "mentioned" | "not_mentioned">("all");
  const cmd = useCommand(id);

  useEffect(() => {
    if (!id) return;
    setLoading(true);
    const unsub = subscribeInsights(id, setInsights, {
      type: ["ai_visibility", "geo_readiness"],
    });
    Promise.all([
      getBoard(id),
      listGeoProbesV2(id).catch(() => []),
      getDocument(id, "geo-visibility").catch(() => null),
      listSeoAudits(id, 1).then((a) => (a[0] ?? null) as unknown as SeoAuditData | null),
      getSummary(id, "content-quality").catch(() => null),
      getDocument(id, "action-plan").catch(() => null),
    ]).then(([b, p, v, a, c, ap]) => {
      setBoard(b);
      setProbes(p as unknown as Probe[]);
      setVisDoc(v);
      setAudit(a);
      setContentDoc(c);
      setActionPlanDoc(ap);
      setLoading(false);
    });
    return unsub;
  }, [id]);

  const handleRunProbe = async () => {
    await cmd.execute("run_geo_probe");
    if (id) {
      const [b, p, v] = await Promise.all([
        getBoard(id),
        listGeoProbesV2(id).catch(() => []),
        getDocument(id, "geo-visibility").catch(() => null),
      ]);
      setBoard(b);
      setProbes(p as unknown as Probe[]);
      setVisDoc(v);
    }
  };

  const handleAddQuestion = async () => {
    if (!id || !newQuestion.trim()) return;
    const formatted = `[${newCategory}] ${newQuestion.trim()}`;
    const existing = flatKeywords(board?.classifiedKeywords);
    if (existing.includes(formatted)) return;
    const updated = [...existing, formatted];
    await updateBrandKeywords(id, updated);
    setBoard((prev) => (prev ? { ...prev, classifiedKeywords: updated } : prev));
    setNewQuestion("");
  };

  // ── Derived: Visibility ──

  const visData = (visDoc?.data ?? {}) as Record<string, unknown>;
  const engineBreakdown = (visData.engineBreakdown ?? []) as EngineBreakdown[];
  const docMentionRate = (visData.mentionRate as number) ?? 0;
  const docExposureRate = (visData.exposureRate as number) ?? 0;
  const completedQuestions = (visData.completedQuestions as number) ?? 0;
  const visQuestions = (visData.questions ?? []) as VisQuestion[];

  const completed = probes.filter((p) => p.status === "completed");
  const totalAnswers = completed.length || completedQuestions;
  const recommendedCount = completed.length > 0
    ? completed.filter((p) => p.ourSiteMentioned).length
    : engineBreakdown.reduce((s, e) => s + e.mentionedCount, 0);
  const recommendedRate = totalAnswers > 0
    ? Math.round((recommendedCount / totalAnswers) * 100) : 0;

  const groupedFromProbes = useMemo(() => {
    const map = new Map<string, Probe[]>();
    for (const probe of probes) {
      map.set(probe.question, [...(map.get(probe.question) || []), probe]);
    }
    return [...map.entries()].map(([question, items]) => ({
      question,
      category: items[0]?.category || "",
      items,
      mentionCount: items.filter((i) => i.ourSiteMentioned).length,
      exposureCount: items.filter((i) => i.ourSiteInResults).length,
      engines: [...new Set(items.map((i) => i.engine))],
    }));
  }, [probes]);

  const allEngines = useMemo(() => {
    const set = new Set<string>();
    for (const p of probes) set.add(p.engine);
    return [...set];
  }, [probes]);

  const filteredGroups = useMemo(() => {
    let groups = groupedFromProbes;
    if (filterEngine !== "all") {
      groups = groups.map((g) => ({ ...g, items: g.items.filter((i) => i.engine === filterEngine) })).filter((g) => g.items.length > 0);
    }
    if (filterStatus === "mentioned") {
      groups = groups.filter((g) => g.items.some((i) => i.ourSiteMentioned));
    } else if (filterStatus === "not_mentioned") {
      groups = groups.filter((g) => !g.items.some((i) => i.ourSiteMentioned));
    }
    return groups;
  }, [groupedFromProbes, filterEngine, filterStatus]);

  const hasProbeDetails = groupedFromProbes.length > 0;

  // ── Derived: GEO Diagnosis ──

  const geoScore = audit?.geoScore ?? 0;
  const violations = audit?.violations ?? [];
  const firedRules = new Set(violations.map((v) => v.rule));

  const buildTierItems = (rules: string[]) =>
    rules.map((ruleId) => ({
      id: ruleId,
      present: !firedRules.has(ruleId),
      violation: violations.find((v) => v.rule === ruleId),
    }));

  const tier1Items = buildTierItems(TIER1_RULES);
  const tier2Items = buildTierItems(TIER2_RULES);
  const tier3Items = buildTierItems(TIER3_RULES);
  const hasTripleCombo = tier1Items.every((i) => i.present);

  const dimensions = ((contentDoc as Record<string, unknown> | null)?.dimensions ?? {}) as Record<string, number>;
  const hasDimensions = Object.keys(dimensions).length > 0;

  // ── Derived: Suggested Actions ──

  const suggestedActions = useMemo(() => {
    const planData = (actionPlanDoc?.data ?? {}) as Record<string, unknown>;
    const actions = (planData.actions ?? planData.items ?? []) as ActionItem[];
    return actions.filter((a) => {
      const cat = (a.category ?? a.type ?? "").toLowerCase();
      return cat.includes("geo") || cat.includes("ai") || cat.includes("visibility") || cat.includes("content");
    }).slice(0, 5);
  }, [actionPlanDoc]);

  // ── Derived: Data Quality ──

  const dataQuality = useMemo(() => {
    const hasProbes = probes.length > 0;
    const hasVis = !!visDoc;
    const hasAudit = !!audit;
    const sources = [hasProbes, hasVis, hasAudit].filter(Boolean).length;
    const score = Math.round((sources / 3) * 100);
    const status: "ok" | "warning" | "degraded" | "invalid" =
      score >= 80 ? "ok" : score >= 50 ? "warning" : score > 0 ? "degraded" : "invalid";
    const notes: string[] = [];
    if (!hasProbes) notes.push("No AI probe results available");
    if (!hasVis) notes.push("No visibility analysis document");
    if (!hasAudit) notes.push("No SEO/GEO audit data");
    return { score, status, notes };
  }, [probes, visDoc, audit]);

  if (loading) {
    return (
      <div className="flex min-h-[30vh] items-center justify-center text-sm text-[var(--shell-text-muted)]">
        불러오는 중...
      </div>
    );
  }

  return (
    <div className="space-y-6">
      {/* Action bar */}
      <div className="flex flex-wrap items-center justify-between gap-3">
        <div className="flex items-center gap-2 text-sm text-[var(--shell-text-muted)]">
          {cmd.isRunning && (
            <span className="flex items-center gap-2 rounded-xl bg-[var(--shell-accent)]/10 px-3 py-1.5 text-xs font-medium text-[var(--shell-accent)]">
              <span className="inline-flex h-2 w-2 animate-pulse rounded-full bg-[var(--shell-accent)]" />
              {cmd.message || "Running simulation..."} {cmd.progress > 0 && `(${cmd.progress}%)`}
            </span>
          )}
        </div>
        <button
          type="button"
          onClick={handleRunProbe}
          disabled={cmd.isRunning}
          className="flex items-center gap-2 rounded-xl border border-[var(--shell-border)] bg-[var(--shell-panel)] px-4 py-2 text-sm font-medium text-[var(--shell-text)] transition-colors hover:border-[var(--shell-accent)] hover:text-[var(--shell-accent)] disabled:opacity-50"
        >
          <Play className="h-3.5 w-3.5" />
          Run Simulation
        </button>
      </div>

      {/* Summary Metrics */}
      <div className="grid gap-4 sm:grid-cols-2 lg:grid-cols-4">
        <MetricCard icon={MessageSquare} label="Total Answers" value={`${totalAnswers}`} color="text-blue-600" />
        <MetricCard icon={Eye} label="Mention Rate" value={`${docMentionRate}%`} color="text-teal-600" />
        <MetricCard icon={Search} label="Exposure Rate" value={`${docExposureRate}%`} color="text-cyan-600" />
        <MetricCard icon={Eye} label="Recommended Rate" value={`${recommendedRate}%`} color="text-emerald-600" />
      </div>

      {/* Data Quality */}
      <DataQualityBadge score={dataQuality.score} status={dataQuality.status} notes={dataQuality.notes} />

      {/* Raw Data: Engine breakdown */}
      <InsightSection title="Engine Breakdown" icon={Eye} count={engineBreakdown.length} defaultOpen={engineBreakdown.length > 0}>
        {engineBreakdown.length > 0 ? (
          <div className="grid gap-4 sm:grid-cols-2 lg:grid-cols-3">
            {engineBreakdown.map((eng) => (
              <EngineCard key={eng.engine} data={eng} />
            ))}
          </div>
        ) : (
          <p className="text-sm text-[var(--shell-text-muted)]">Run a simulation to see engine breakdown data</p>
        )}
      </InsightSection>

      {/* Raw Data: Question Manager */}
      <InsightSection title="Question Manager" icon={Plus} defaultOpen>
        <div className="flex flex-col gap-3 sm:flex-row sm:items-end">
          <div className="min-w-0 flex-1">
            <label className="mb-1 block text-xs text-[var(--shell-text-muted)]">Question</label>
            <input
              type="text"
              value={newQuestion}
              onChange={(e) => setNewQuestion(e.target.value)}
              placeholder="e.g., What are the benefits of our product?"
              className="w-full rounded-xl border border-[var(--shell-border)] bg-[var(--shell-panel-soft)] px-3 py-2 text-sm text-[var(--shell-text)] outline-none transition-colors focus:border-[var(--shell-accent)]"
              onKeyDown={(e) => { if (e.key === "Enter") handleAddQuestion(); }}
            />
          </div>
          <div className="w-full sm:w-40">
            <label className="mb-1 block text-xs text-[var(--shell-text-muted)]">Category</label>
            <select
              value={newCategory}
              onChange={(e) => setNewCategory(e.target.value as Category)}
              className="w-full rounded-xl border border-[var(--shell-border)] bg-[var(--shell-panel-soft)] px-3 py-2 text-sm text-[var(--shell-text)] outline-none transition-colors focus:border-[var(--shell-accent)]"
            >
              {CATEGORY_OPTIONS.map((cat) => (
                <option key={cat} value={cat}>{CATEGORY_LABELS[cat]}</option>
              ))}
            </select>
          </div>
          <button
            type="button"
            onClick={handleAddQuestion}
            disabled={!newQuestion.trim()}
            className="flex items-center gap-1.5 rounded-xl border border-[var(--shell-border)] bg-[var(--shell-panel)] px-4 py-2 text-sm font-medium text-[var(--shell-text)] transition-colors hover:border-[var(--shell-accent)] hover:text-[var(--shell-accent)] disabled:opacity-50"
          >
            <Plus className="h-3.5 w-3.5" />
            Add
          </button>
        </div>
      </InsightSection>

      {/* Raw Data: Probe Results */}
      <InsightSection title="Probe Results" icon={MessageSquare} count={hasProbeDetails ? filteredGroups.length : visQuestions.length} defaultOpen>
        {/* Filters */}
        {hasProbeDetails && (
          <div className="mb-4 flex flex-wrap gap-2">
            <FilterChip label="All Engines" active={filterEngine === "all"} onClick={() => setFilterEngine("all")} />
            {allEngines.map((e) => (
              <FilterChip key={e} label={ENGINE_LABELS[e] || e} active={filterEngine === e} onClick={() => setFilterEngine(e)} />
            ))}
            <div className="w-px bg-[var(--shell-border)]" />
            <FilterChip label="All" active={filterStatus === "all"} onClick={() => setFilterStatus("all")} />
            <FilterChip label="Mentioned" active={filterStatus === "mentioned"} onClick={() => setFilterStatus("mentioned")} />
            <FilterChip label="Not Mentioned" active={filterStatus === "not_mentioned"} onClick={() => setFilterStatus("not_mentioned")} />
          </div>
        )}

        {/* Question groups */}
        <div className="space-y-3">
          {hasProbeDetails ? (
            filteredGroups.length > 0 ? (
              filteredGroups.map((group) => <QuestionGroup key={group.question} group={group} />)
            ) : (
              <div className="rounded-2xl border border-dashed border-[var(--shell-border)] bg-[var(--shell-panel)] p-8 text-center text-sm text-[var(--shell-text-muted)]">
                No results match the current filters
              </div>
            )
          ) : visQuestions.length > 0 ? (
            visQuestions.map((vq) => <VisQuestionRow key={vq.question} data={vq} />)
          ) : (
            <EmptyState
              icon={Eye}
              title="No AI visibility data yet"
              description="시뮬레이션을 실행하면 AI 엔진이 브랜드를 어떻게 언급하는지 측정합니다"
              action={{ label: "Run Simulation", onClick: handleRunProbe }}
            />
          )}
        </div>
      </InsightSection>

      {/* Diagnosis: GEO */}
      {audit && (
        <InsightSection title="GEO Diagnosis" icon={Star} defaultOpen>
          <div className="space-y-5">
            <div className="flex items-center gap-5">
              <ScoreCircle value={geoScore} />
              <div>
                <h4 className="text-lg font-semibold text-[var(--shell-text)]">GEO Score</h4>
                <p className="mt-0.5 text-xs text-[var(--shell-text-muted)]">LLM content quality for AI search engines</p>
              </div>
            </div>

            {/* Dimensions */}
            {hasDimensions && (
              <div>
                <h5 className="text-xs font-semibold uppercase tracking-wider text-[var(--shell-text-muted)]">Content Quality Dimensions</h5>
                <div className="mt-2 grid gap-2 sm:grid-cols-2">
                  {GEO_DIMENSIONS.map((dim) => {
                    const val = dimensions[dim.key];
                    if (val == null) return null;
                    return (
                      <div key={dim.key} className="flex items-center justify-between rounded-xl border border-[var(--shell-border)] bg-[var(--shell-panel-soft)] px-4 py-3">
                        <span className="text-sm text-[var(--shell-text)]">{dim.label}</span>
                        <div className="flex items-center gap-2">
                          <div className="h-1.5 w-16 overflow-hidden rounded-full bg-[var(--shell-panel-strong)]">
                            <div
                              className={`h-full rounded-full ${val >= 70 ? "bg-emerald-500" : val >= 40 ? "bg-amber-500" : "bg-rose-500"}`}
                              style={{ width: `${val}%` }}
                            />
                          </div>
                          <span className={`text-xs font-medium ${val >= 70 ? "text-emerald-600" : val >= 40 ? "text-amber-500" : "text-rose-500"}`}>{val}</span>
                        </div>
                      </div>
                    );
                  })}
                </div>
              </div>
            )}

            {/* Tier cards */}
            <TierCard title="Tier 1: Core Signals" subtitle="Discoverability, Depth, Evidence" maxPoints={45} items={tier1Items} icon={<Star className="h-4 w-4 text-amber-500" />} />
            {hasTripleCombo && (
              <div className="rounded-xl border border-amber-500/30 bg-amber-500/5 p-3 text-center text-xs font-medium text-amber-600">
                Triple Combo active: All Tier 1 signals present
              </div>
            )}
            <TierCard title="Tier 2: Authority & Structure" subtitle="Entity, Authorship, Readability" maxPoints={25} items={tier2Items} icon={<Wrench className="h-4 w-4 text-blue-500" />} />
            <TierCard title="Tier 3: Enhancement" subtitle="Freshness, Navigation, Supplements" maxPoints={20} items={tier3Items} icon={<Zap className="h-4 w-4 text-teal-500" />} />
          </div>
        </InsightSection>
      )}

      {/* Open Insights (from insights collection) */}
      <InsightSection
        title="Open Insights"
        icon={Lightbulb}
        count={insights.filter((i) => i.status !== "resolved" && i.status !== "ignored").length}
        defaultOpen
      >
        <OpenInsightsList insights={insights} />
      </InsightSection>

      {/* Generated (legacy client-side heuristics) */}
      <InsightSection title="Generated Insights" icon={Lightbulb} defaultOpen={false}>
        <GeneratedInsights probes={probes} engineBreakdown={engineBreakdown} mentionRate={docMentionRate} />
      </InsightSection>

      {/* Suggested Actions */}
      <InsightSection title="Suggested Actions" icon={Zap} count={suggestedActions.length} defaultOpen={false}>
        {suggestedActions.length > 0 ? (
          <div className="space-y-2">
            {suggestedActions.map((action, i) => (
              <div key={i} className="flex items-start gap-3 rounded-xl border border-[var(--shell-border)] bg-[var(--shell-panel-soft)] px-4 py-3">
                <Zap className="mt-0.5 h-3.5 w-3.5 shrink-0 text-[var(--shell-accent)]" />
                <div className="min-w-0 flex-1">
                  <p className="text-sm font-medium text-[var(--shell-text)]">{action.title}</p>
                  {action.description && <p className="mt-0.5 text-xs text-[var(--shell-text-muted)]">{action.description}</p>}
                  <div className="mt-1.5 flex flex-wrap gap-2">
                    {action.priority && (
                      <span className={`rounded-md px-1.5 py-0.5 text-[10px] font-medium ${
                        action.priority === "high" ? "bg-rose-500/10 text-rose-500"
                          : action.priority === "medium" ? "bg-amber-500/10 text-amber-500"
                            : "bg-emerald-500/10 text-emerald-600"
                      }`}>{action.priority}</span>
                    )}
                    {action.expectedImpact && (
                      <span className="rounded-md bg-[var(--shell-panel-soft)] px-1.5 py-0.5 text-[10px] text-[var(--shell-text-muted)]">
                        Impact: {action.expectedImpact}
                      </span>
                    )}
                  </div>
                </div>
              </div>
            ))}
          </div>
        ) : (
          <p className="text-sm text-[var(--shell-text-muted)]">Run an analysis to generate action recommendations</p>
        )}
      </InsightSection>
    </div>
  );
}

// ── Generated Insights (computed from data) ──────────────────

function GeneratedInsights({ probes, engineBreakdown, mentionRate }: {
  probes: Probe[];
  engineBreakdown: EngineBreakdown[];
  mentionRate: number;
}) {
  const insights = useMemo(() => {
    const result: Array<{ severity: "high" | "medium" | "low"; title: string; explanation: string }> = [];

    if (mentionRate < 30 && probes.length > 0) {
      result.push({
        severity: "high",
        title: "Low AI mention rate across engines",
        explanation: `Your brand is mentioned in only ${mentionRate}% of AI responses. Content optimization for AI discoverability is recommended.`,
      });
    }

    for (const eng of engineBreakdown) {
      if (eng.mentionRate === 0 && eng.totalQuestions > 0) {
        result.push({
          severity: "high",
          title: `Zero mentions on ${ENGINE_LABELS[eng.engine] || eng.engine}`,
          explanation: `${ENGINE_LABELS[eng.engine] || eng.engine} does not mention your brand in any of ${eng.totalQuestions} tested questions.`,
        });
      }
    }

    const comparisonProbes = probes.filter((p) => p.category === "comparison");
    if (comparisonProbes.length > 0) {
      const compMentioned = comparisonProbes.filter((p) => p.ourSiteMentioned).length;
      if (compMentioned === 0) {
        result.push({
          severity: "medium",
          title: "Not mentioned in comparison queries",
          explanation: "Your brand is absent from AI responses to comparison-type questions. Consider creating comparison content.",
        });
      }
    }

    if (probes.length === 0 && engineBreakdown.length === 0) {
      result.push({
        severity: "low",
        title: "No simulation data available",
        explanation: "Run an AI visibility simulation to discover how AI engines reference your brand.",
      });
    }

    return result;
  }, [probes, engineBreakdown, mentionRate]);

  if (insights.length === 0) {
    return <p className="text-sm text-[var(--shell-text-muted)]">No insights generated yet. Data from probes and audits will produce insights here.</p>;
  }

  return (
    <div className="space-y-2">
      {insights.map((insight, i) => (
        <div key={i} className="flex items-start gap-3 rounded-xl border border-[var(--shell-border)] bg-[var(--shell-panel-soft)] px-4 py-3">
          <SeverityDot severity={insight.severity} />
          <div className="min-w-0 flex-1">
            <p className="text-sm font-medium text-[var(--shell-text)]">{insight.title}</p>
            <p className="mt-0.5 text-xs text-[var(--shell-text-muted)]">{insight.explanation}</p>
          </div>
        </div>
      ))}
    </div>
  );
}

function SeverityDot({ severity }: { severity: "high" | "medium" | "low" }) {
  const color = severity === "high" ? "bg-rose-500" : severity === "medium" ? "bg-amber-500" : "bg-blue-500";
  return <span className={`mt-1.5 inline-block h-2 w-2 shrink-0 rounded-full ${color}`} />;
}

