function ProbeStatusBadge({ probe }: { probe: Probe }) {
  if (probe.status === "failed") return <span className="rounded-full bg-rose-500/15 px-2.5 py-1 text-[11px] font-medium text-rose-500">Failed</span>;
  if (probe.ourSiteMentioned) return <span className="rounded-full bg-emerald-500/15 px-2.5 py-1 text-[11px] font-medium text-emerald-600">Mentioned</span>;
  if (probe.ourSiteInResults) return <span className="rounded-full bg-amber-500/15 px-2.5 py-1 text-[11px] font-medium text-amber-600">Source only</span>;
  return <span className="rounded-full bg-rose-500/15 px-2.5 py-1 text-[11px] font-medium text-rose-500">Not mentioned</span>;
}

function MentionBadge({ mentioned }: { mentioned: boolean }) {
  return mentioned
    ? <span className="shrink-0 rounded-md bg-emerald-500/15 px-2 py-0.5 text-[11px] font-medium text-emerald-600">Mentioned</span>
    : <span className="shrink-0 rounded-md bg-rose-500/15 px-2 py-0.5 text-[11px] font-medium text-rose-500">Not mentioned</span>;
}

function FilterChip({ label, active, onClick }: { label: string; active: boolean; onClick: () => void }) {
  return (
    <button
      type="button"
      onClick={onClick}
      className={`rounded-lg px-3 py-1.5 text-xs font-medium transition-colors ${
        active
          ? "bg-[var(--shell-accent)]/15 text-[var(--shell-accent)]"
          : "bg-[var(--shell-panel-soft)] text-[var(--shell-text-muted)] hover:text-[var(--shell-text)]"
      }`}
    >
      {label}
    </button>
  );
}

