const RUN_TYPE_OPTIONS: { value: string; label: string }[] = [
  { value: "all", label: "All Types" },
  ...Object.entries(COMMAND_LABELS).map(([value, label]) => ({ value, label })),
];

const RUN_STATUS_OPTIONS: { value: string; label: string }[] = [
  { value: "all", label: "All Status" },
  { value: "running", label: "Running" },
  { value: "complete", label: "Complete" },
  { value: "partial", label: "Partial" },
  { value: "failed", label: "Failed" },
];

const ERROR_CATEGORY_OPTIONS = ["all", "firestore", "parse", "llm"] as const;

// ── Component ───────────────────────────────────────────────

export function Operations() {
  const { id } = useParams<{ id: string }>();
  const [runs, setRuns] = useState<RunDoc[]>([]);
  const [logLines, setLogLines] = useState<LogLine[]>([]);
  const [errors, setErrors] = useState<ErrorJournalEntry[]>([]);
  const [expandedRun, setExpandedRun] = useState<string | null>(null);
  const hasUserToggled = useRef(false);
  const [logFilter, setLogFilter] = useState<string>("all");
  const [errorSeverityFilter, setErrorSeverityFilter] = useState<string>("all");
  const [errorCategoryFilter, setErrorCategoryFilter] = useState<string>("all");
  const [runTypeFilter, setRunTypeFilter] = useState<string>("all");
  const [runStatusFilter, setRunStatusFilter] = useState<string>("all");
  const consoleRef = useRef<HTMLDivElement>(null);
  const [autoScroll, setAutoScroll] = useState(true);
  const cmd = useCommand(id);

  useEffect(() => {
    if (!id) return;
    const unsubs: Array<() => void> = [];

    unsubs.push(subscribeRuns(id, setRuns));
    unsubs.push(
      subscribeLiveEvents(id, (data) => {
        if (!data) return;
        setLogLines((data.logLines ?? []) as LogLine[]);
      }),
    );

    listErrorJournal(id, 100).then(setErrors);

    return () => unsubs.forEach((u) => u());
  }, [id]);

  useEffect(() => {
    if (!hasUserToggled.current && runs.length > 0 && expandedRun === null) {
      setExpandedRun(runs[0].id);
    }
  }, [runs, expandedRun]);

  useEffect(() => {
    if (autoScroll && consoleRef.current) {
      consoleRef.current.scrollTop = consoleRef.current.scrollHeight;
    }
  }, [logLines, autoScroll]);

  const refreshErrors = () => {
    if (id) listErrorJournal(id, 100).then(setErrors);
  };

  const handleRetry = (run: RunDoc) => {
    if (!id) return;
    const failedSteps = Object.entries(run.steps)
      .filter(([, e]) => (e as { status: string }).status === "failed")
      .map(([step]) => step);

    if (run.commandType === "onboard" && failedSteps.length > 0) {
      cmd.execute("retry_step", { steps: failedSteps });
    } else {
      cmd.execute(run.commandType);
    }
  };

  // ── Derived stats ──
  const todayRuns = runs.filter(
    (r) => r.startedAt.toDateString() === new Date().toDateString(),
  );
  const successCount = todayRuns.filter((r) => r.status === "complete").length;
  const failedCount = todayRuns.filter(
    (r) => r.status === "failed" || r.status === "partial",
  ).length;
  const runningCount = todayRuns.filter((r) => r.status === "running").length;
  const totalErrors = todayRuns.reduce((sum, r) => sum + r.errorCount, 0);

  const filteredRuns = useMemo(() => {
    let result = runs;
    if (runTypeFilter !== "all") {
      result = result.filter((r) => r.commandType === runTypeFilter);
    }
    if (runStatusFilter !== "all") {
      result = result.filter((r) => r.status === runStatusFilter);
    }
    return result;
  }, [runs, runTypeFilter, runStatusFilter]);

  const filteredLogs =
    logFilter === "all"
      ? logLines
      : logLines.filter((l) => l.type === logFilter);

  const filteredErrors = useMemo(() => {
    let result = errors;
    if (errorSeverityFilter !== "all") {
      result = result.filter((e) => e.severity === errorSeverityFilter);
    }
    if (errorCategoryFilter !== "all") {
      result = result.filter((e) => e.category === errorCategoryFilter);
    }
    return result;
  }, [errors, errorSeverityFilter, errorCategoryFilter]);

  return (
    <div className="mx-auto max-w-6xl space-y-6 p-6 lg:p-10">
      {/* Header */}
      <div>
        <h1 className="text-2xl font-semibold tracking-tight text-[var(--shell-text)]">
          Operations
        </h1>
        <p className="mt-1 text-sm text-[var(--shell-text-muted)]">
          실행 기록, 실시간 로그, 오류 추적을 확인합니다
        </p>
      </div>

      {/* Status Bar */}
      <div className="grid gap-3 sm:grid-cols-2 lg:grid-cols-4">
        <MetricCard
          icon={Play}
          label="Today's Runs"
          value={String(todayRuns.length)}
          sub={runningCount > 0 ? `${runningCount} active` : undefined}
          color="text-blue-600"
        />
        <MetricCard
          icon={CheckCircle2}
          label="Successful"
          value={String(successCount)}
          color="text-emerald-600"
        />
        <MetricCard
          icon={XCircle}
          label="Failed / Partial"
          value={String(failedCount)}
          color="text-rose-500"
        />
        <MetricCard
          icon={AlertTriangle}
          label="Errors Today"
          value={String(totalErrors)}
          color="text-amber-600"
        />
      </div>

      {/* Run History */}
      <section className="rounded-2xl border border-[var(--shell-border)] bg-[var(--shell-panel)] shadow-[var(--shell-shadow)]">
        <div className="flex items-center justify-between border-b border-[var(--shell-border)] px-5 py-4">
          <div className="flex items-center gap-2">
            <Activity className="h-4 w-4 text-[var(--shell-text-soft)]" />
            <h2 className="text-sm font-semibold text-[var(--shell-text)]">
              Run History
            </h2>
            <span className="ml-1 text-xs text-[var(--shell-text-muted)]">
              ({filteredRuns.length}{filteredRuns.length !== runs.length ? ` / ${runs.length}` : ""})
            </span>
          </div>
          <div className="flex items-center gap-2">
            <FilterSelect
              value={runTypeFilter}
              onChange={setRunTypeFilter}
              options={RUN_TYPE_OPTIONS}
            />
            <FilterSelect
              value={runStatusFilter}
              onChange={setRunStatusFilter}
              options={RUN_STATUS_OPTIONS}
            />
          </div>
        </div>

        {filteredRuns.length === 0 ? (
          <div className="flex items-center justify-center py-16 text-sm text-[var(--shell-text-muted)]">
            {runs.length === 0 ? "No runs recorded yet" : "No runs match the current filters"}
          </div>
        ) : (
          <div className="divide-y divide-[var(--shell-border)]">
            {filteredRuns.map((run) => (
              <RunRow
                key={run.id}
                boardId={id!}
                run={run}
                expanded={expandedRun === run.id}
                onToggle={() => {
                  hasUserToggled.current = true;
                  setExpandedRun(expandedRun === run.id ? null : run.id);
                }}
                onRetry={() => handleRetry(run)}
                retrying={cmd.isRunning}
              />
            ))}
          </div>
        )}
      </section>

      {/* Live Console + Error Journal */}
      <div className="grid gap-5 lg:grid-cols-2">
        {/* Live Console */}
        <section className="rounded-2xl border border-[var(--shell-border)] bg-[var(--shell-panel)] shadow-[var(--shell-shadow)]">
          <div className="flex items-center justify-between border-b border-[var(--shell-border)] px-5 py-3">
            <div className="flex items-center gap-2">
              <Terminal className="h-4 w-4 text-[var(--shell-text-soft)]" />
              <h2 className="text-sm font-semibold text-[var(--shell-text)]">
                Live Console
              </h2>
              {logLines.length > 0 && (
                <span className="h-2 w-2 animate-pulse rounded-full bg-emerald-500" />
              )}
            </div>
            <div className="flex items-center gap-1">
              {["all", "step", "info", "warning", "error"].map((f) => (
                <button
                  key={f}
                  onClick={() => setLogFilter(f)}
                  className={`rounded-lg px-2 py-1 text-[10px] font-medium transition-colors ${
                    logFilter === f
                      ? "bg-[var(--shell-accent-soft)] text-[var(--shell-accent)]"
                      : "text-[var(--shell-text-muted)] hover:text-[var(--shell-text)]"
                  }`}
                >
                  {f === "all" ? "All" : f.charAt(0).toUpperCase() + f.slice(1)}
                </button>
              ))}
            </div>
          </div>
          <div
            ref={consoleRef}
            onScroll={() => {
              if (!consoleRef.current) return;
              const el = consoleRef.current;
              const atBottom =
                el.scrollHeight - el.scrollTop - el.clientHeight < 40;
              setAutoScroll(atBottom);
            }}
            className="h-[320px] overflow-y-auto bg-[var(--shell-bg)] p-4 font-mono text-xs leading-5"
          >
            {filteredLogs.length === 0 ? (
              <div className="flex h-full items-center justify-center text-[var(--shell-text-muted)]">
                Waiting for log events...
              </div>
            ) : (
              filteredLogs.map((line, i) => (
                <div key={i} className="flex gap-3">
                  <span className="shrink-0 text-[var(--shell-text-soft)]">
                    {new Date(line.ts).toLocaleTimeString("en-US", {
                      hour: "2-digit",
                      minute: "2-digit",
                      second: "2-digit",
                      hour12: false,
                    })}
                  </span>
                  <span className={LOG_COLORS[line.type] ?? LOG_COLORS.info}>
                    {line.message}
                  </span>
                </div>
              ))
            )}
          </div>
        </section>

        {/* Error Journal */}
        <section className="rounded-2xl border border-[var(--shell-border)] bg-[var(--shell-panel)] shadow-[var(--shell-shadow)]">
          <div className="flex items-center justify-between border-b border-[var(--shell-border)] px-5 py-3">
            <div className="flex items-center gap-2">
              <AlertTriangle className="h-4 w-4 text-[var(--shell-text-soft)]" />
              <h2 className="text-sm font-semibold text-[var(--shell-text)]">
                Error Journal
              </h2>
              <span className="text-xs text-[var(--shell-text-muted)]">
                ({errors.length})
              </span>
            </div>
            <div className="flex items-center gap-1">
              <button
                onClick={refreshErrors}
                className="rounded-lg p-1.5 text-[var(--shell-text-muted)] hover:bg-[var(--shell-panel-soft)] hover:text-[var(--shell-text)]"
              >
                <RefreshCw className="h-3.5 w-3.5" />
              </button>
              {["all", "error", "warning"].map((f) => (
                <button
                  key={f}
                  onClick={() => setErrorSeverityFilter(f)}
                  className={`rounded-lg px-2 py-1 text-[10px] font-medium transition-colors ${
                    errorSeverityFilter === f
                      ? "bg-[var(--shell-accent-soft)] text-[var(--shell-accent)]"
                      : "text-[var(--shell-text-muted)] hover:text-[var(--shell-text)]"
                  }`}
                >
                  {f === "all" ? "All" : f.charAt(0).toUpperCase() + f.slice(1)}
                </button>
              ))}
              <span className="mx-0.5 text-[var(--shell-border)]">|</span>
              {ERROR_CATEGORY_OPTIONS.map((f) => (
                <button
                  key={f}
                  onClick={() => setErrorCategoryFilter(f)}
                  className={`rounded-lg px-2 py-1 text-[10px] font-medium transition-colors ${
                    errorCategoryFilter === f
                      ? "bg-[var(--shell-accent-soft)] text-[var(--shell-accent)]"
                      : "text-[var(--shell-text-muted)] hover:text-[var(--shell-text)]"
                  }`}
                >
                  {f === "all" ? "All" : f.toUpperCase()}
                </button>
              ))}
            </div>
          </div>
          <div className="h-[320px] divide-y divide-[var(--shell-border)] overflow-y-auto">
            {filteredErrors.length === 0 ? (
              <div className="flex h-full items-center justify-center text-sm text-[var(--shell-text-muted)]">
                No errors recorded
              </div>
            ) : (
              filteredErrors.map((err) => (
                <ErrorRow key={err.id} entry={err} />
              ))
            )}
          </div>
        </section>
      </div>
    </div>
  );
}

// ── Sub-components ──────────────────────────────────────────

function FilterSelect(props: {
  value: string;
  onChange: (v: string) => void;
  options: { value: string; label: string }[];
}) {
  return (
    <div className="relative">
      <select
        value={props.value}
        onChange={(e) => props.onChange(e.target.value)}
        className="appearance-none rounded-lg border border-[var(--shell-border)] bg-[var(--shell-panel)] py-1.5 pl-2.5 pr-7 text-[10px] font-medium text-[var(--shell-text)] outline-none transition-colors hover:border-[var(--shell-accent)] focus:border-[var(--shell-accent)]"
      >
        {props.options.map((o) => (
          <option key={o.value} value={o.value}>
            {o.label}
          </option>
        ))}
      </select>
      <ChevronDown className="pointer-events-none absolute right-1.5 top-1/2 h-3 w-3 -translate-y-1/2 text-[var(--shell-text-muted)]" />
    </div>
  );
}

function RunRow(props: {
  boardId: string;
  run: RunDoc;
  expanded: boolean;
  onToggle: () => void;
  onRetry: () => void;
  retrying: boolean;
}) {
  const { boardId, run, expanded, onToggle } = props;
  const cfg = STATUS_CONFIG[run.status];
  const stuck = isRunStuck(run);
  const stepEntries = Object.entries(run.steps) as Array<
    [StepName, { status: StepStatus; error?: string | null }]
  >;

  const isPipelineRun = run.commandType === "onboard" || run.commandType === "retry_step";
  const totalPipelineSteps = isPipelineRun
    ? PIPELINE_WAVES.reduce((s, w) => s + w.steps.length, 0)
    : stepEntries.length || 1;
  const completedSteps = stepEntries.filter(([, e]) => e.status === "complete").length;
  const pipelineProgress = totalPipelineSteps > 0
    ? Math.round((completedSteps / totalPipelineSteps) * 100)
    : 0;

  return (
    <div>
      <button
        onClick={onToggle}
        className="flex w-full items-center gap-4 px-5 py-3.5 text-left transition-colors hover:bg-[var(--shell-panel-soft)]"
      >
        {/* Status dot */}
        <div
          className={`h-2.5 w-2.5 shrink-0 rounded-full ${
            run.status === "running" ? "animate-pulse bg-blue-500" :
            run.status === "analyzing" ? "animate-pulse bg-teal-500" : ""
          } ${cfg.bg.replace("/10", "")}`}
          style={
            run.status !== "running" && run.status !== "analyzing"
              ? {
                  backgroundColor:
                    run.status === "complete"
                      ? "rgb(16 185 129)"
                      : run.status === "partial"
                        ? "rgb(245 158 11)"
                        : "rgb(244 63 94)",
                }
              : undefined
          }
        />

        {/* Type */}
        <div className="min-w-0 flex-1">
          <div className="truncate text-sm font-medium text-[var(--shell-text)]">
            {getRunLabel(run)}
          </div>
        </div>

        {/* Status badge */}
        <span
          className={`shrink-0 rounded-lg px-2 py-0.5 text-[10px] font-medium ${cfg.bg} ${cfg.color}`}
        >
          {cfg.label}
        </span>
        {stuck && (
          <span className="shrink-0 rounded-lg bg-amber-500/15 px-2 py-0.5 text-[10px] font-medium text-amber-500">
            Stuck
          </span>
        )}

        {/* Duration */}
        <span className="w-16 shrink-0 text-right text-xs text-[var(--shell-text-muted)]">
          {formatDuration(run.durationMs)}
        </span>

        {/* Time */}
        <span className="w-20 shrink-0 text-right text-xs text-[var(--shell-text-muted)]">
          {formatDate(run.startedAt)} {formatTime(run.startedAt)}
        </span>

        {/* Error/Warning counts */}
        <div className="flex w-14 shrink-0 justify-end gap-1.5">
          {run.errorCount > 0 && (
            <span className="rounded bg-rose-500/10 px-1.5 py-0.5 text-[10px] font-medium text-rose-500">
              {run.errorCount}
            </span>
          )}
          {run.warningCount > 0 && (
            <span className="rounded bg-amber-500/10 px-1.5 py-0.5 text-[10px] font-medium text-amber-600">
              {run.warningCount}
            </span>
          )}
        </div>
      </button>

      {/* Progress bar for running/analyzing */}
      {(run.status === "running" || run.status === "analyzing") && (isPipelineRun ? pipelineProgress : run.progress) > 0 && (
        <div className="px-5 pb-2">
          <div className="h-1 overflow-hidden rounded-full bg-[var(--shell-panel-soft)]">
            <div
              className={`h-full rounded-full transition-all duration-500 ${
                run.status === "analyzing" ? "bg-teal-500" : "bg-blue-500"
              }`}
              style={{ width: `${Math.min(isPipelineRun ? pipelineProgress : run.progress, 100)}%` }}
            />
          </div>
        </div>
      )}

      {/* Expanded detail */}
      {expanded && (
        <RunDetailPanel boardId={boardId} run={run} stepEntries={stepEntries} onRetry={props.onRetry} retrying={props.retrying} stuck={stuck} />
      )}
    </div>
  );
}

function RunDetailPanel(props: {
  boardId: string;
  run: RunDoc;
  stepEntries: Array<[StepName, { status: StepStatus; error?: string | null }]>;
  onRetry: () => void;
  retrying: boolean;
  stuck: boolean;
}) {
  const { boardId, run, stepEntries } = props;
  const [killing, setKilling] = useState(false);

  const isPipelineRun = run.commandType === "onboard" || run.commandType === "retry_step";

  const runStepStatus: Record<string, StepStatus> = {};
  for (const [step, entry] of stepEntries) {
    runStepStatus[step] = entry.status;
  }

  const failedSteps = stepEntries.filter(([, e]) => e.error);

  return (
    <div className="border-t border-[var(--shell-border)] bg-[var(--shell-panel-soft)] px-5 py-4 space-y-4">
      {/* Pipeline tracker -- only for full pipeline runs */}
      {isPipelineRun && stepEntries.length > 0 && (
        <div>
          <div className="flex items-start gap-0">
            {PIPELINE_WAVES.map((wave, wi) => {
              const statuses = wave.steps.map((s) => runStepStatus[s.key] ?? "idle");
              const ws: StepStatus =
                statuses.some((s) => s === "running") ? "running" :
                statuses.every((s) => s === "complete") ? "complete" :
                statuses.some((s) => s === "failed")
                  ? (statuses.every((s) => s === "complete" || s === "failed") ? "failed" : "running")
                  : statuses.some((s) => s === "pending") ? "pending" : "idle";
              const isLast = wi === PIPELINE_WAVES.length - 1;

              return (
                <div key={wave.label} className="flex items-start" style={{ flex: 1 }}>
                  <div className="flex flex-col items-center" style={{ minWidth: 0, flex: 1 }}>
                    {/* Wave label */}
                    <span className={`mb-1.5 text-[9px] font-semibold uppercase tracking-wider ${
                      ws === "running" ? "text-blue-500" :
                      ws === "complete" ? "text-emerald-600" :
                      ws === "failed" ? "text-rose-500" :
                      "text-[var(--shell-text-soft)]"
                    }`}>
                      {wave.label}
                    </span>

                    {/* Circle */}
                    <div className={`relative flex h-7 w-7 items-center justify-center rounded-full border-2 transition-all duration-500 ${
                      ws === "running" ? "border-blue-500 bg-blue-500/10" :
                      ws === "complete" ? "border-emerald-500 bg-emerald-500/10" :
                      ws === "failed" ? "border-rose-500 bg-rose-500/10" :
                      ws === "pending" ? "border-amber-400 bg-amber-400/10" :
                      "border-[var(--shell-border)] bg-[var(--shell-panel)]"
                    }`}>
                      {ws === "complete" && <CheckCircle2 className="h-3.5 w-3.5 text-emerald-500" />}
                      {ws === "failed" && <XCircle className="h-3.5 w-3.5 text-rose-500" />}
                      {ws === "running" && <div className="h-2.5 w-2.5 animate-spin rounded-full border-2 border-blue-500 border-t-transparent" />}
                      {ws === "pending" && <div className="h-2 w-2 rounded-full bg-amber-400/50" />}
                      {ws === "idle" && <div className="h-2 w-2 rounded-full bg-[var(--shell-text-soft)]/20" />}
                    </div>

                    {/* Step pills */}
                    <div className="mt-1.5 flex flex-wrap justify-center gap-0.5">
                      {wave.steps.map((step) => {
                        const ss = runStepStatus[step.key] ?? "idle";
                        return (
                          <span
                            key={step.key}
                            className={`rounded px-1.5 py-px text-[8px] font-medium transition-all duration-300 ${
                              ss === "running" ? "bg-blue-500/10 text-blue-600" :
                              ss === "complete" ? "bg-emerald-500/10 text-emerald-600" :
                              ss === "failed" ? "bg-rose-500/10 text-rose-500" :
                              ss === "pending" ? "bg-amber-400/10 text-amber-600" :
                              "bg-[var(--shell-panel)] text-[var(--shell-text-muted)]"
                            }`}
                          >
                            {step.label}
                          </span>
                        );
                      })}
                    </div>
                  </div>

                  {/* Connector */}
                  {!isLast && (
                    <div className="mt-[30px] flex items-center" style={{ width: 24, flexShrink: 0 }}>
                      <div className={`h-px w-full transition-colors duration-500 ${
                        ws === "complete" || ws === "failed" ? "bg-emerald-500/40" :
                        ws === "running" ? "bg-blue-500/30" :
                        "bg-[var(--shell-border)]"
                      }`} />
                    </div>
                  )}
                </div>
              );
            })}
          </div>
        </div>
      )}

      {/* Progress indicator for non-pipeline runs */}
      {!isPipelineRun && (run.status === "running" || run.status === "analyzing") && (
        <div className="flex items-center gap-3">
          <div className={`h-2.5 w-2.5 animate-spin rounded-full border-2 border-t-transparent ${
            run.status === "analyzing" ? "border-teal-500" : "border-blue-500"
          }`} />
          <div className="flex-1">
            <div className="flex items-center justify-between text-xs">
              <span className="font-medium text-[var(--shell-text)]">{run.message || "Processing..."}</span>
              <span className="text-[var(--shell-text-muted)]">
                {run.totalItems != null && run.totalItems > 0
                  ? `${(run.completedItems ?? 0) + (run.failedItems ?? 0)} / ${run.totalItems}`
                  : run.progress > 0 ? `${run.progress}%` : null}
              </span>
            </div>
            {run.progress > 0 && (
              <div className="mt-1.5 h-1.5 overflow-hidden rounded-full bg-[var(--shell-panel)]">
                <div
                  className={`h-full rounded-full transition-all duration-500 ${
                    run.status === "analyzing" ? "bg-teal-500" : "bg-blue-500"
                  }`}
                  style={{ width: `${Math.min(run.progress, 100)}%` }}
                />
              </div>
            )}
            {run.failedItems != null && run.failedItems > 0 && (
              <div className="mt-1 text-[10px] text-rose-400">
                Failed: {run.failedItems}
              </div>
            )}
          </div>
        </div>
      )}

      {/* Failed step errors */}
      {failedSteps.length > 0 && (
        <div className="flex flex-wrap gap-2">
          {failedSteps.map(([step, entry]) => (
            <div key={step} className="flex items-center gap-1.5 rounded-lg bg-rose-500/5 px-2.5 py-1.5">
              <XCircle className="h-3 w-3 text-rose-500" />
              <span className="text-[10px] font-medium text-rose-500">
                {getStepLabel(step)}
              </span>
              {entry.error && (
                <span className="max-w-[200px] truncate text-[10px] text-rose-400">
                  {entry.error}
                </span>
              )}
            </div>
          ))}
        </div>
      )}

      {/* Meta row */}
      <div className="flex items-center justify-between">
        <div className="flex flex-wrap gap-x-6 gap-y-1 text-xs text-[var(--shell-text-muted)]">
          <span>Started: {run.startedAt.toLocaleString()}</span>
          {run.completedAt && (
            <span>Completed: {run.completedAt.toLocaleString()}</span>
          )}
          <span>Duration: {formatDuration(run.durationMs)}</span>
          <span>Run ID: {run.id.slice(0, 8)}...</span>
        </div>

        <div className="flex items-center gap-2">
          {/* Force Kill — running/analyzing runs only */}
          {(run.status === "running" || run.status === "analyzing") && (
            <button
              onClick={async (e) => {
                e.stopPropagation();
                if (!confirm(
                  `이 실행을 강제 종료합니다.\n\nRun: ${run.id.slice(0, 8)}...\nType: ${getRunLabel(run)}\n\n진행할까요?`
                )) return;
                setKilling(true);
                try {
                  await forceFailCommand(boardId, run.id);
                } catch (err) {
                  alert(`강제 종료 실패: ${err instanceof Error ? err.message : err}`);
                } finally {
                  setKilling(false);
                }
              }}
              disabled={killing}
              className={`flex items-center gap-1.5 rounded-lg border px-3 py-1.5 text-xs font-medium transition-colors disabled:opacity-50 ${
                props.stuck
                  ? "border-rose-500/40 bg-rose-500/10 text-rose-500 hover:bg-rose-500/20"
                  : "border-amber-500/40 bg-amber-500/10 text-amber-600 hover:bg-amber-500/20"
              }`}
            >
              <Skull className={`h-3 w-3 ${killing ? "animate-pulse" : ""}`} />
              {killing ? "Killing..." : "Force Kill"}
            </button>
          )}

          {/* Retry — failed/partial runs */}
          {(run.status === "failed" || run.status === "partial") && (
            <button
              onClick={(e) => {
                e.stopPropagation();
                props.onRetry();
              }}
              disabled={props.retrying}
              className="flex items-center gap-1.5 rounded-lg border border-[var(--shell-border)] bg-[var(--shell-panel)] px-3 py-1.5 text-xs font-medium text-[var(--shell-text)] transition-colors hover:border-[var(--shell-accent)] hover:text-[var(--shell-accent)] disabled:opacity-50"
            >
              <RotateCcw className={`h-3 w-3 ${props.retrying ? "animate-spin" : ""}`} />
              {props.retrying ? "Retrying..." : "Retry"}
            </button>
          )}
        </div>
      </div>
    </div>
  );
}

function ErrorRow(props: { entry: ErrorJournalEntry }) {
  const { entry } = props;
  const badge = SEVERITY_BADGE[entry.severity] ?? SEVERITY_BADGE.warning;
  const [expanded, setExpanded] = useState(false);
  const friendlyMsg = getUserMessage(entry.worker, entry.category, entry.message);

  return (
    <div>
      <button
        onClick={() => setExpanded(!expanded)}
        className="flex w-full items-center gap-3 px-5 py-3 text-left transition-colors hover:bg-[var(--shell-panel-soft)]"
      >
        <span
          className={`shrink-0 rounded px-1.5 py-0.5 text-[9px] font-bold ${badge.cls}`}
        >
          {badge.label}
        </span>
        <span className="shrink-0 rounded bg-[var(--shell-panel-soft)] px-1.5 py-0.5 text-[10px] text-[var(--shell-text-muted)]">
          {entry.category}
        </span>
        <span className="shrink-0 text-[10px] text-[var(--shell-text-soft)]">
          {entry.worker}
        </span>
        <span className="min-w-0 flex-1 truncate text-xs text-[var(--shell-text)]">
          {friendlyMsg}
        </span>
        <span className="shrink-0 text-[10px] text-[var(--shell-text-muted)]">
          {entry.createdAt
            ? `${formatDate(entry.createdAt)} ${formatTime(entry.createdAt)}`
            : ""}
        </span>
      </button>
      {expanded && (
        <div className="border-t border-[var(--shell-border)] bg-[var(--shell-panel-soft)] px-5 py-3">
          <div className="space-y-2 text-xs">
            {friendlyMsg !== entry.message && (
              <div>
                <span className="font-medium text-[var(--shell-text-muted)]">
                  Original:{" "}
                </span>
                <span className="text-[var(--shell-text)]">
                  {entry.message}
                </span>
              </div>
            )}
            <div>
              <span className="font-medium text-[var(--shell-text-muted)]">
                Function:{" "}
              </span>
              <span className="text-[var(--shell-text)]">
                {entry.functionName}
              </span>
            </div>
            {entry.detail && (
              <div>
                <span className="font-medium text-[var(--shell-text-muted)]">
                  Detail:{" "}
                </span>
                <span className="text-[var(--shell-text)]">
                  {entry.detail}
                </span>
              </div>
            )}
            {Object.keys(entry.context).length > 0 && (
              <pre className="mt-2 overflow-x-auto rounded-lg bg-[var(--shell-bg)] p-3 text-[10px] text-[var(--shell-text-muted)]">
                {JSON.stringify(entry.context, null, 2)}
              </pre>
            )}
          </div>
        </div>
      )}
    </div>
  );
}
