// @ts-nocheck — 고객 화면: V3 실데이터 (mock 보조 정보 제거 완료)
import { useParams } from "react-router-dom";
import { useQuery } from "@tanstack/react-query";
import { Download, FileText, Globe } from "lucide-react";
import { v3MeasurementApi } from "./dataHub";
import { V3RealWeeklyReportCard } from "./V3RealWeeklyReportCard";
import { V3MonthlyReportCard } from "./V3MonthlyReportCard";
import { V3HistoryDownloadCard } from "./V3HistoryDownloadCard";
import { HeaderDiagnosticButton } from "./V3DiagnosticPanel";
import { runReportDiagnostics } from "./diagnostics/reportDiagnostics";

export function PortalV3WeeklyReport() {
  const { id } = useParams<{ id: string }>();

  const latestQ = useQuery({
    queryKey: ["portalV3", "v3-latest", id],
    queryFn: () => v3MeasurementApi.getLatest(id!),
    enabled: !!id,
  });
  const latestAnalysis = latestQ.data?.analysis;
  const hasReport = !!latestQ.data?.run?.id && !!latestAnalysis;

  const handleDownloadCsv = () => {
    if (!latestAnalysis) return;
    const rows = (latestAnalysis.queryBreakdown ?? []).map((q: any) => [
      q.query, q.category, q.gptMentioned ? "Y" : "N", q.geminiMentioned ? "Y" : "N",
      `${q.totalMentionRate ?? 0}%`,
    ]);
    const header = ["Query", "Category", "GPT Mentioned", "Gemini Mentioned", "Mention Rate"];
    const csv = [header, ...rows].map((r) => r.map((c: string) => `"${String(c).replace(/"/g, '""')}"`).join(",")).join("\n");
    const blob = new Blob(["\uFEFF" + csv], { type: "text/csv;charset=utf-8;" });
    const url = URL.createObjectURL(blob);
    const a = document.createElement("a");
    a.href = url;
    a.download = `v3-report-${latestQ.data?.run?.id ?? "latest"}.csv`;
    a.click();
    URL.revokeObjectURL(url);
  };

  const handlePdfDownload = (format: "kor" | "eng") => {
    const label = format === "kor" ? "한글 보고서 (.pdf)" : "영문 보고서 (.pdf)";
    alert(`${label} 다운로드는 아래 '월간 리포트' 카드의 'PDF 저장 / 인쇄' 버튼을 사용해주세요.`);
  };

  return (
    <>
      {id && <HeaderDiagnosticButton boardId={id} title="Report Diagnostics" runner={runReportDiagnostics} />}
      <div className="mx-auto max-w-6xl space-y-6 px-4 py-6">
        <header className="flex flex-wrap items-start justify-between gap-4">
          <div className="flex-1 min-w-0">
            <div className="text-xs uppercase tracking-[0.28em] text-[var(--shell-text-soft)]">Client / 분석 보고서</div>
            <h1 className="mt-2 text-3xl font-semibold tracking-tight text-[var(--shell-text)]">측정 결과 분석 보고서</h1>
            <p className="mt-2 text-sm text-[var(--shell-text-muted)]">
              실제 측정 결과 통합 분석 + 월간 리포트 (Claude 인사이트) + 엑셀 raw data 다운로드.
            </p>
          </div>
          <div className="flex flex-wrap gap-2">
            {hasReport ? (
              <button
                type="button"
                onClick={handleDownloadCsv}
                className="flex items-center gap-1.5 rounded-full border border-[var(--shell-accent)] bg-[var(--shell-accent)]/10 px-3 py-2 text-[11px] font-medium text-[var(--shell-accent)] hover:bg-[var(--shell-accent)]/20"
                title="최신 측정 결과 CSV 다운로드"
              >
                <Download className="h-3.5 w-3.5" /> 보고서
              </button>
            ) : (
              <button
                type="button"
                disabled
                className="flex items-center gap-1.5 rounded-full border border-[var(--shell-border)] bg-[var(--shell-panel)]/40 px-3 py-2 text-[11px] text-[var(--shell-text-muted)] opacity-50"
                title="측정 데이터가 없어 다운로드 불가"
              >
                <Download className="h-3.5 w-3.5" /> 보고서
              </button>
            )}
            <button type="button" onClick={() => handlePdfDownload("kor")} className="flex items-center gap-1.5 rounded-full border border-[var(--shell-border)] bg-[var(--shell-panel)] px-3 py-2 text-[11px] text-[var(--shell-text)] hover:bg-[var(--shell-panel-soft)]">
              <FileText className="h-3.5 w-3.5" /> 한글 PDF
            </button>
            <button type="button" onClick={() => handlePdfDownload("eng")} className="flex items-center gap-1.5 rounded-full border border-[var(--shell-border)] bg-[var(--shell-panel)] px-3 py-2 text-[11px] text-[var(--shell-text)] hover:bg-[var(--shell-panel-soft)]">
              <Globe className="h-3.5 w-3.5" /> 영문 PDF
            </button>
          </div>
        </header>

        {/* ★ Phase 3 — V4 실측정 결과 (가장 최신 dk_v3_analysis) */}
        <V3RealWeeklyReportCard />

        {/* ★ Phase 3-C4 — 월간 리포트 + PDF 저장 */}
        <V3MonthlyReportCard />

        {/* ★ 측정 보고서 다운로드 관리 (개별/일괄 + 저장 한도 200개) */}
        <V3HistoryDownloadCard />
      </div>
    </>
  );
}
