import { useCallback, useMemo, useState } from "react";
import { useParams, useNavigate } from "react-router-dom";
import {
  Activity, ChevronDown, ChevronRight, CheckCircle2,
  Database, ExternalLink, Eye, Loader2, Play, RefreshCw,
  XCircle,
} from "lucide-react";
import { getDoc, getDocs, query, limit, orderBy } from "firebase/firestore";
import { paths } from "../../../db/paths";
import { useCommand } from "../../../hooks/useCommand";
import { WORKER_MAP, WORKER_GROUPS, type WorkerEntry, type FirestoreTarget } from "./workerMap";

type DocStatus = "loading" | "exists" | "missing" | "error";

interface DocCheck {
  path: string;
  label: string;
  status: DocStatus;
  updatedAt?: string;
  docCount?: number;
  sampleFields?: string[];
}

// ── Firestore checker ────────────────────────────────────

function resolveRef(target: FirestoreTarget) {
  const p = target.path;

  if (p.includes("{id}") || p.includes("{slug}") || p.includes("{key}") ||
      p.includes("{date}") || p.includes("{runId}") || p.includes("{yearWeek}") ||
      p.includes("{recId}")) {
    return { type: "collection" as const, target };
  }
  return { type: "doc" as const, target };
}

async function checkDoc(boardId: string, target: FirestoreTarget): Promise<DocCheck> {
  const { type } = resolveRef(target);
  const p = target.path;
  const base: DocCheck = { path: p, label: target.label, status: "loading" };

  try {
    if (type === "collection") {
      const colRef = getCollectionRef(boardId, p);
      if (!colRef) return { ...base, status: "error" };
      const snap = await getDocs(query(colRef, orderBy("__name__"), limit(3)));
      if (snap.empty) return { ...base, status: "missing", docCount: 0 };
      const fields = snap.docs[0].data();
      return {
        ...base,
        status: "exists",
        docCount: snap.size >= 3 ? 3 : snap.size,
        sampleFields: Object.keys(fields).slice(0, 8),
        updatedAt: extractTimestamp(fields),
      };
    }

    const docRef = getDocRef(boardId, p);
    if (!docRef) return { ...base, status: "error" };
    const snap = await getDoc(docRef);
    if (!snap.exists()) return { ...base, status: "missing" };
    const data = snap.data()!;
    return {
      ...base,
      status: "exists",
      sampleFields: Object.keys(data).slice(0, 8),
      updatedAt: extractTimestamp(data),
    };
  } catch {
    return { ...base, status: "error" };
  }
}

function extractTimestamp(data: Record<string, unknown>): string | undefined {
  const ts = data.updatedAt ?? data.writtenAt ?? data.createdAt ?? data.analyzedAt;
  if (!ts) return undefined;
  if (typeof ts === "string") return ts;
  if (ts && typeof ts === "object" && "toDate" in ts) {
    return (ts as { toDate: () => Date }).toDate().toLocaleString();
  }
  return undefined;
}

function getDocRef(boardId: string, path: string) {
  if (path.startsWith("analyses/")) {
    const key = path.replace("analyses/", "");
    return paths.analysis(boardId, key);
  }
  if (path.startsWith("summaries/")) {
    const key = path.replace("summaries/", "");
    return paths.summary(boardId, key);
  }
  if (path === "raw/v1/brand_truth/default") return paths.rawBrandTruth(boardId);
  return null;
}

function getCollectionRef(boardId: string, path: string) {
  if (path.startsWith("raw/v1/crawl_pages")) return paths.rawCrawlPages(boardId);
  if (path.startsWith("raw/v1/competitors")) return paths.rawCompetitors(boardId);
  if (path.startsWith("raw/v1/geo_probes")) return paths.rawGeoProbes(boardId);
  if (path.startsWith("raw/v1/external_sources")) return paths.rawExternalSources(boardId);
  if (path.startsWith("raw/v1/benchmark_daily")) return paths.rawBenchmarkDaily(boardId);
  if (path.startsWith("analyses/v3/measurements")) return paths.v3MeasurementAnalyses(boardId);
  if (path.startsWith("reports/v3/weekly")) return paths.v3WeeklyReports(boardId);
  if (path.startsWith("actions/v3/recommendations")) return paths.v3Recommendations(boardId);
  if (path.startsWith("insights")) return paths.insights(boardId);
  return null;
}

// ── Component ────────────────────────────────────────────

export function DataInspector() {
  const { id } = useParams<{ id: string }>();
  const navigate = useNavigate();
  const cmd = useCommand(id);
  const [expandedWorker, setExpandedWorker] = useState<string | null>(null);
  const [docChecks, setDocChecks] = useState<Record<string, DocCheck[]>>({});
  const [checkingWorker, setCheckingWorker] = useState<string | null>(null);
  const [groupFilter, setGroupFilter] = useState<string>("all");

  const filteredWorkers = useMemo(
    () => groupFilter === "all" ? WORKER_MAP : WORKER_MAP.filter((w) => w.group === groupFilter),
    [groupFilter],
  );

  const checkWorkerDocs = useCallback(async (worker: WorkerEntry) => {
    if (!id) return;
    setCheckingWorker(worker.id);
    const results = await Promise.all(
      worker.firestoreWrites.map((t) => checkDoc(id, t)),
    );
    setDocChecks((prev) => ({ ...prev, [worker.id]: results }));
    setCheckingWorker(null);
  }, [id]);

  const checkAllDocs = useCallback(async () => {
    if (!id) return;
    setCheckingWorker("__all__");
    const allResults: Record<string, DocCheck[]> = {};
    for (const worker of WORKER_MAP) {
      const results = await Promise.all(
        worker.firestoreWrites.map((t) => checkDoc(id, t)),
      );
      allResults[worker.id] = results;
    }
    setDocChecks(allResults);
    setCheckingWorker(null);
  }, [id]);

  const handleToggle = useCallback((workerId: string) => {
    setExpandedWorker((prev) => prev === workerId ? null : workerId);
  }, []);

  const handleRunWorker = useCallback((worker: WorkerEntry) => {
    if (!id || cmd.isRunning) return;
    cmd.execute("run_single_worker", { worker: worker.id });
  }, [id, cmd]);

  const base = `/board/${id}`;

  const summary = useMemo(() => {
    let total = 0;
    let existing = 0;
    let missing = 0;
    for (const checks of Object.values(docChecks)) {
      for (const c of checks) {
        total++;
        if (c.status === "exists") existing++;
        if (c.status === "missing") missing++;
      }
    }
    return { total, existing, missing, unchecked: WORKER_MAP.reduce((s, w) => s + w.firestoreWrites.length, 0) - total };
  }, [docChecks]);

  return (
    <div className="mx-auto max-w-6xl space-y-6 p-6 lg:p-10">
      {/* Header */}
      <div className="flex items-start justify-between">
        <div>
          <h1 className="text-2xl font-semibold tracking-tight text-[var(--shell-text)]">
            Data Inspector
          </h1>
          <p className="mt-1 text-sm text-[var(--shell-text-muted)]">
            Worker별 Firestore 기록 확인 + 연결된 UI 화면 추적
          </p>
        </div>
        <button
          onClick={checkAllDocs}
          disabled={checkingWorker === "__all__"}
          className="flex items-center gap-2 rounded-xl border border-[var(--shell-border)] bg-[var(--shell-panel)] px-4 py-2 text-sm font-medium text-[var(--shell-text)] transition-colors hover:border-[var(--shell-accent)] hover:text-[var(--shell-accent)] disabled:opacity-50"
        >
          {checkingWorker === "__all__" ? (
            <Loader2 className="h-4 w-4 animate-spin" />
          ) : (
            <RefreshCw className="h-4 w-4" />
          )}
          Check All
        </button>
      </div>

      {/* Summary bar */}
      {summary.total > 0 && (
        <div className="flex gap-3">
          <SummaryPill label="Checked" value={summary.total} color="text-blue-600" bg="bg-blue-500/10" />
          <SummaryPill label="Exists" value={summary.existing} color="text-emerald-600" bg="bg-emerald-500/10" />
          <SummaryPill label="Missing" value={summary.missing} color="text-rose-500" bg="bg-rose-500/10" />
          <SummaryPill label="Unchecked" value={summary.unchecked} color="text-[var(--shell-text-muted)]" bg="bg-[var(--shell-panel-soft)]" />
        </div>
      )}

      {/* Command progress / result */}
      {cmd.isRunning && (
        <div className="rounded-xl border border-blue-500/20 bg-blue-500/5 px-4 py-3">
          <div className="flex items-center gap-3">
            <Loader2 className="h-4 w-4 animate-spin text-blue-500" />
            <span className="text-sm font-medium text-blue-600">{cmd.message || "Running..."}</span>
            <span className="ml-auto text-sm font-semibold text-blue-600">{cmd.progress}%</span>
          </div>
          <div className="mt-2 h-1.5 overflow-hidden rounded-full bg-blue-500/10">
            <div
              className="h-full rounded-full bg-blue-500 transition-all duration-500"
              style={{ width: `${Math.min(cmd.progress, 100)}%` }}
            />
          </div>
        </div>
      )}
      {cmd.isComplete && (
        <div className="flex items-center justify-between rounded-xl border border-emerald-500/20 bg-emerald-500/5 px-4 py-3">
          <div className="flex items-center gap-2">
            <CheckCircle2 className="h-4 w-4 text-emerald-500" />
            <span className="text-sm font-medium text-emerald-600">{cmd.message || "Complete"}</span>
          </div>
          <button onClick={cmd.reset} className="text-xs text-[var(--shell-text-muted)] hover:text-[var(--shell-text)]">Dismiss</button>
        </div>
      )}
      {cmd.isFailed && (
        <div className="flex items-center justify-between rounded-xl border border-rose-500/20 bg-rose-500/5 px-4 py-3">
          <div className="flex items-center gap-2">
            <XCircle className="h-4 w-4 text-rose-500" />
            <span className="text-sm font-medium text-rose-500">{cmd.error || "Failed"}</span>
          </div>
          <button onClick={cmd.reset} className="text-xs text-[var(--shell-text-muted)] hover:text-[var(--shell-text)]">Dismiss</button>
        </div>
      )}

      {/* Group filter */}
      <div className="flex items-center gap-2">
        <button
          onClick={() => setGroupFilter("all")}
          className={`rounded-lg px-3 py-1.5 text-xs font-medium transition-colors ${
            groupFilter === "all"
              ? "bg-[var(--shell-accent-soft)] text-[var(--shell-accent)]"
              : "text-[var(--shell-text-muted)] hover:text-[var(--shell-text)]"
          }`}
        >
          All ({WORKER_MAP.length})
        </button>
        {WORKER_GROUPS.map((g) => {
          const count = WORKER_MAP.filter((w) => w.group === g.key).length;
          return (
            <button
              key={g.key}
              onClick={() => setGroupFilter(g.key)}
              className={`rounded-lg px-3 py-1.5 text-xs font-medium transition-colors ${
                groupFilter === g.key
                  ? "bg-[var(--shell-accent-soft)] text-[var(--shell-accent)]"
                  : "text-[var(--shell-text-muted)] hover:text-[var(--shell-text)]"
              }`}
            >
              {g.label} ({count})
            </button>
          );
        })}
      </div>

      {/* Worker list */}
      <div className="space-y-2">
        {filteredWorkers.map((worker) => {
          const checks = docChecks[worker.id];
          const isExpanded = expandedWorker === worker.id;
          const allExist = checks?.length === worker.firestoreWrites.length &&
            checks.every((c) => c.status === "exists");
          const someMissing = checks?.some((c) => c.status === "missing");
          const isChecking = checkingWorker === worker.id;

          return (
            <div
              key={worker.id}
              className="rounded-2xl border border-[var(--shell-border)] bg-[var(--shell-panel)] shadow-[var(--shell-shadow)] transition-all"
            >
              {/* Row header */}
              <button
                onClick={() => handleToggle(worker.id)}
                className="flex w-full items-center gap-3 px-5 py-3.5 text-left transition-colors hover:bg-[var(--shell-panel-soft)]"
              >
                {isExpanded ? (
                  <ChevronDown className="h-4 w-4 shrink-0 text-[var(--shell-text-soft)]" />
                ) : (
                  <ChevronRight className="h-4 w-4 shrink-0 text-[var(--shell-text-soft)]" />
                )}

                {/* Status indicator */}
                <div className="shrink-0">
                  {!checks ? (
                    <div className="h-2.5 w-2.5 rounded-full bg-[var(--shell-text-soft)]/20" />
                  ) : allExist ? (
                    <CheckCircle2 className="h-4 w-4 text-emerald-500" />
                  ) : someMissing ? (
                    <XCircle className="h-4 w-4 text-rose-500" />
                  ) : (
                    <div className="h-2.5 w-2.5 rounded-full bg-amber-400" />
                  )}
                </div>

                {/* Label */}
                <div className="min-w-0 flex-1">
                  <span className="text-sm font-medium text-[var(--shell-text)]">
                    {worker.label}
                  </span>
                  {worker.wave != null && (
                    <span className="ml-2 rounded bg-[var(--shell-panel-soft)] px-1.5 py-0.5 text-[10px] text-[var(--shell-text-muted)]">
                      Wave {worker.wave}
                    </span>
                  )}
                </div>

                {/* Doc counts */}
                <div className="flex items-center gap-3">
                  <span className="flex items-center gap-1 text-xs text-[var(--shell-text-muted)]">
                    <Database className="h-3 w-3" />
                    {worker.firestoreWrites.length}
                  </span>
                  <span className="flex items-center gap-1 text-xs text-[var(--shell-text-muted)]">
                    <Eye className="h-3 w-3" />
                    {worker.uiReaders.length}
                  </span>
                </div>

                {/* Group badge */}
                <span className={`shrink-0 rounded-lg px-2 py-0.5 text-[10px] font-medium ${
                  worker.group === "onboard" ? "bg-blue-500/10 text-blue-600" :
                  worker.group === "v3" ? "bg-teal-500/10 text-teal-600" :
                  "bg-[var(--shell-panel-soft)] text-[var(--shell-text-muted)]"
                }`}>
                  {worker.group}
                </span>
              </button>

              {/* Expanded detail */}
              {isExpanded && (
                <div className="border-t border-[var(--shell-border)] bg-[var(--shell-panel-soft)] px-5 py-4 space-y-4">
                  {/* Action buttons */}
                  <div className="flex gap-2">
                    <button
                      onClick={() => handleRunWorker(worker)}
                      disabled={cmd.isRunning}
                      className="flex items-center gap-1.5 rounded-lg border border-[var(--shell-border)] bg-[var(--shell-panel)] px-3 py-1.5 text-xs font-medium text-[var(--shell-text)] transition-colors hover:border-blue-500 hover:text-blue-600 disabled:opacity-50"
                    >
                      <Play className="h-3 w-3" />
                      Run {worker.label}
                    </button>
                    <button
                      onClick={() => checkWorkerDocs(worker)}
                      disabled={!!checkingWorker}
                      className="flex items-center gap-1.5 rounded-lg border border-[var(--shell-border)] bg-[var(--shell-panel)] px-3 py-1.5 text-xs font-medium text-[var(--shell-text)] transition-colors hover:border-[var(--shell-accent)] hover:text-[var(--shell-accent)] disabled:opacity-50"
                    >
                      {isChecking ? (
                        <Loader2 className="h-3 w-3 animate-spin" />
                      ) : (
                        <RefreshCw className="h-3 w-3" />
                      )}
                      Check Firestore
                    </button>
                  </div>

                  {/* Firestore writes */}
                  <div>
                    <h3 className="mb-2 flex items-center gap-1.5 text-xs font-semibold text-[var(--shell-text-muted)]">
                      <Database className="h-3.5 w-3.5" />
                      Firestore Writes
                    </h3>
                    <div className="space-y-1">
                      {worker.firestoreWrites.map((target) => {
                        const check = checks?.find((c) => c.path === target.path);
                        return (
                          <DocCheckRow key={target.path} target={target} check={check} />
                        );
                      })}
                    </div>
                  </div>

                  {/* UI readers */}
                  {worker.uiReaders.length > 0 && (
                    <div>
                      <h3 className="mb-2 flex items-center gap-1.5 text-xs font-semibold text-[var(--shell-text-muted)]">
                        <Eye className="h-3.5 w-3.5" />
                        UI Pages
                      </h3>
                      <div className="flex flex-wrap gap-2">
                        {worker.uiReaders.map((ui) => (
                          <button
                            key={`${ui.route}-${ui.card ?? ""}`}
                            onClick={() => navigate(`${base}${ui.route}`)}
                            className="flex items-center gap-1.5 rounded-lg border border-[var(--shell-border)] bg-[var(--shell-panel)] px-3 py-2 text-xs font-medium text-[var(--shell-text)] transition-all hover:border-[var(--shell-accent)] hover:text-[var(--shell-accent)]"
                          >
                            <ExternalLink className="h-3 w-3" />
                            <span>{ui.page}</span>
                            {ui.card && (
                              <span className="text-[var(--shell-text-muted)]">/ {ui.card}</span>
                            )}
                          </button>
                        ))}
                      </div>
                    </div>
                  )}
                </div>
              )}
            </div>
          );
        })}
      </div>
    </div>
  );
}

// ── Sub-components ───────────────────────────────────────

function SummaryPill(props: { label: string; value: number; color: string; bg: string }) {
  return (
    <div className={`flex items-center gap-2 rounded-lg px-3 py-1.5 ${props.bg}`}>
      <span className={`text-sm font-semibold ${props.color}`}>{props.value}</span>
      <span className="text-xs text-[var(--shell-text-muted)]">{props.label}</span>
    </div>
  );
}

function DocCheckRow(props: { target: FirestoreTarget; check?: DocCheck }) {
  const { target, check } = props;
  const [showFields, setShowFields] = useState(false);

  return (
    <div className="rounded-lg border border-[var(--shell-border)] bg-[var(--shell-panel)]">
      <button
        onClick={() => check?.sampleFields && setShowFields(!showFields)}
        className="flex w-full items-center gap-3 px-3 py-2 text-left"
      >
        {/* Status */}
        <div className="shrink-0">
          {!check ? (
            <div className="h-2 w-2 rounded-full bg-[var(--shell-text-soft)]/20" />
          ) : check.status === "exists" ? (
            <CheckCircle2 className="h-3.5 w-3.5 text-emerald-500" />
          ) : check.status === "missing" ? (
            <XCircle className="h-3.5 w-3.5 text-rose-500" />
          ) : check.status === "loading" ? (
            <Loader2 className="h-3.5 w-3.5 animate-spin text-[var(--shell-text-muted)]" />
          ) : (
            <Activity className="h-3.5 w-3.5 text-amber-500" />
          )}
        </div>

        {/* Label + path */}
        <div className="min-w-0 flex-1">
          <span className="text-xs font-medium text-[var(--shell-text)]">{target.label}</span>
          <span className="ml-2 text-[10px] text-[var(--shell-text-muted)]">{target.path}</span>
        </div>

        {/* Metadata */}
        {check?.docCount != null && (
          <span className="text-[10px] text-[var(--shell-text-muted)]">{check.docCount}+ docs</span>
        )}
        {check?.updatedAt && (
          <span className="text-[10px] text-[var(--shell-text-muted)]">{check.updatedAt}</span>
        )}

        {/* Status text */}
        {check && (
          <span className={`shrink-0 rounded px-1.5 py-0.5 text-[9px] font-bold ${
            check.status === "exists" ? "bg-emerald-500/10 text-emerald-600" :
            check.status === "missing" ? "bg-rose-500/10 text-rose-500" :
            "bg-amber-500/10 text-amber-600"
          }`}>
            {check.status === "exists" ? "EXISTS" : check.status === "missing" ? "MISSING" : check.status.toUpperCase()}
          </span>
        )}
      </button>

      {/* Sample fields */}
      {showFields && check?.sampleFields && (
        <div className="border-t border-[var(--shell-border)] px-3 py-2">
          <div className="flex flex-wrap gap-1">
            {check.sampleFields.map((f) => (
              <span key={f} className="rounded bg-[var(--shell-panel-soft)] px-1.5 py-0.5 text-[10px] text-[var(--shell-text-muted)]">
                {f}
              </span>
            ))}
          </div>
        </div>
      )}
    </div>
  );
}
