// @ts-nocheck — V3 실데이터 Dashboard 카드 (Step D — 카테고라이즈 + 데이터 일관성 강화)
// 측정 / 쿼리별 결과 / 경쟁사 / 강점·약점 / 액션 / 추천 / 적중률 / 시계열 — 섹션별 구분.
import { useMemo } from "react";
import { useParams, Link } from "react-router-dom";
import { useQuery } from "@tanstack/react-query";
import {
  Activity, TrendingUp, TrendingDown, CheckCircle2, Clock,
  PlayCircle, Sparkles, Target, Cpu, ArrowRight, Loader2,
  BarChart3, Search, FileText, MessageSquare, Award, Calendar, Swords,
} from "lucide-react";
import { MentionRateTrendChart } from "../../components/shared/MentionRateTrendChart";
import { trendApi } from "./dataHub";
import { v3MeasurementApi } from "./dataHub";
import { v3ActionsApi } from "./dataHub";
import { v3RecommendationsApi } from "./dataHub";

const DAY_LABELS = ["일", "월", "화", "수", "목", "금", "토"];

export function V3RealDashboardCard() {
  const { id: onboardingId } = useParams<{ id: string }>();

  const truthQ = useQuery({
    queryKey: ["portalV3", "brand-truth", onboardingId],
    queryFn: () => trendApi.getBrandTruth(onboardingId!),
    enabled: !!onboardingId,
  });
  const latestQ = useQuery({
    queryKey: ["portalV3", "v3-latest", onboardingId],
    queryFn: () => v3MeasurementApi.getLatest(onboardingId!),
    enabled: !!onboardingId,
  });
  const runsQ = useQuery({
    queryKey: ["portalV3", "v3-runs-20", onboardingId],
    queryFn: () => v3MeasurementApi.listRuns(onboardingId!, 20),
    enabled: !!onboardingId,
  });
  const scheduleQ = useQuery({
    queryKey: ["portalV3", "v3-schedule", onboardingId],
    queryFn: () => v3MeasurementApi.getSchedule(onboardingId!),
    enabled: !!onboardingId,
  });
  const actionsQ = useQuery({
    queryKey: ["portalV3", "v3-actions", onboardingId],
    queryFn: () => v3ActionsApi.list(onboardingId!),
    enabled: !!onboardingId,
  });
  const recsQ = useQuery({
    queryKey: ["portalV3", "v3-recs", onboardingId],
    queryFn: () => v3RecommendationsApi.list(onboardingId!),
    enabled: !!onboardingId,
  });
  const hitQ = useQuery({
    queryKey: ["portalV3", "v3-recs-hit", onboardingId],
    queryFn: () => v3RecommendationsApi.getHitRate(onboardingId!),
    enabled: !!onboardingId,
  });
  const trendQ = useQuery({
    queryKey: ["portalV3", "v3-trend", onboardingId],
    queryFn: () => v3MeasurementApi.getTrend(onboardingId!, 12),
    enabled: !!onboardingId,
  });

  const doneRuns = useMemo(() => {
    const runs = runsQ.data?.runs || [];
    return runs
      .filter((r: any) => (r.status === "complete" || r.status === "done") && r.completedAt)
      .sort((a: any, b: any) => new Date(a.completedAt!).getTime() - new Date(b.completedAt!).getTime());
  }, [runsQ.data]);

  const trendSnapshots = useMemo(() => {
    const rawPoints: any[] = trendQ.data?.points || [];
    if (rawPoints.length === 0) return [];

    const dayMap = new Map<string, any[]>();
    for (const p of rawPoints) {
      const d = new Date(p.date || Date.now());
      const key = `${d.getFullYear()}-${d.getMonth() + 1}-${d.getDate()}`;
      const arr = dayMap.get(key) || [];
      arr.push(p);
      dayMap.set(key, arr);
    }

    return Array.from(dayMap.entries())
      .sort(([a], [b]) => a.localeCompare(b))
      .map(([, pts]) => {
        const n = pts.length;
        const avgBrand = pts.reduce((s, p) => s + (p.brandRate || 0), 0) / n;
        const avgGpt = pts.reduce((s, p) => s + (p.gptRate ?? 0), 0) / n;
        const avgGemini = pts.reduce((s, p) => s + (p.geminiRate ?? 0), 0) / n;
        const sumCalls = pts.reduce((s, p) => s + (p.totalCalls || 0), 0);
        const latestDate = pts.reduce((latest, p) => {
          const t = new Date(p.date || 0).getTime();
          return t > new Date(latest).getTime() ? p.date : latest;
        }, pts[0].date);

        return {
          capturedAt: latestDate || new Date().toISOString(),
          metrics: {
            totalQuestions: sumCalls,
            exposureRate: 0,
            mentionRate: avgBrand,
            visibilityScore: avgBrand,
            weightedMentionRate: avgBrand,
            mentionCount: 0,
          },
          engineBreakdown: [
            { engine: "gpt", totalQuestions: sumCalls, exposedCount: 0, mentionedCount: 0, exposureRate: 0, mentionRate: avgGpt },
            { engine: "gemini", totalQuestions: sumCalls, exposedCount: 0, mentionedCount: 0, exposureRate: 0, mentionRate: avgGemini },
          ],
          topQueries: [],
          actions: [],
        };
      });
  }, [trendQ.data]);

  const truth: any = truthQ.data?.truth || {};
  const brandName = truth.canonicalName || "";
  const latest = latestQ.data;
  const analysis = latest?.analysis;
  const wrd = analysis?.weeklyReportData as any;

  const isLoading = truthQ.isLoading || latestQ.isLoading;

  const counts = actionsQ.data?.counts;
  const recsPending = recsQ.data?.counts?.pending ?? 0;
  const recsConverted = recsQ.data?.counts?.converted ?? 0;
  const hit = hitQ.data;
  const schedule = scheduleQ.data?.schedule;

  if (isLoading) {
    return (
      <div className="rounded-2xl border border-[var(--shell-border)] bg-[var(--shell-panel)] p-6 text-center text-sm text-[var(--shell-text-muted)]">
        <Loader2 className="mx-auto h-5 w-5 animate-spin" />
        <div className="mt-2">V3 데이터를 불러오는 중...</div>
      </div>
    );
  }

  if (!analysis) {
    return (
      <div className="rounded-2xl border-2 border-dashed border-[var(--shell-border)] bg-[var(--shell-panel)] p-8 text-center">
        <Sparkles className="mx-auto h-6 w-6 text-[var(--shell-text-soft)]" />
        <div className="mt-2 text-sm text-[var(--shell-text)]">V3 측정 데이터가 없습니다</div>
        <div className="mt-1 text-[11px] text-[var(--shell-text-muted)]">
          <Link to={`/board/${onboardingId}/portal-v3/input`} className="text-[var(--shell-accent)] hover:underline">
            "고객 인풋" 메뉴
          </Link>
          {" "}에서 측정을 먼저 실행해주세요.
        </div>
      </div>
    );
  }

  const brandRate = parseFloat(analysis.brandMentionRate as any) || 0;
  const rateLevel = brandRate >= 80 ? { label: "매우 우수", color: "text-emerald-300", bg: "bg-emerald-500/10", arc: "stroke-emerald-400" }
    : brandRate >= 60 ? { label: "우수", color: "text-emerald-300", bg: "bg-emerald-500/8", arc: "stroke-emerald-400" }
    : brandRate >= 40 ? { label: "보통", color: "text-amber-300", bg: "bg-amber-500/10", arc: "stroke-amber-400" }
    : { label: "미흡", color: "text-red-300", bg: "bg-red-500/10", arc: "stroke-red-400" };

  const top1Count = wrd?.mentionPositionHistogram?.["1"] ?? 0;
  const totalCalls = wrd?.globalEngine?.totalQuestions ?? latest.run?.totalCalls ?? 0;
  const top1Rate = totalCalls > 0 ? (top1Count / totalCalls) * 100 : 0;
  const queryBreakdown: any[] = wrd?.queryBreakdown || [];

  const competitorBreakdown: any[] = analysis.competitorBreakdown || [];
  const sortedCompetitors = [...competitorBreakdown].sort((a, b) => (b.count || 0) - (a.count || 0));
  const ourMentionCount = analysis.brandMentionCount || 0;
  const sovTop3 = sortedCompetitors.slice(0, 3);
  const sovCompetitorTotal = sovTop3.reduce((s, c) => s + (c.count || 0), 0);
  const sovTotalUnits = ourMentionCount + sovCompetitorTotal;
  const ourShare = sovTotalUnits > 0 ? Math.round((ourMentionCount / sovTotalUnits) * 100) : 0;

  return (
    <div className="space-y-6">
      {/* ═══════════════════════════════════════════════════════════
          1) 📊 GEO 통합 점수 — 큰 게이지 + 핵심 KPI
         ═══════════════════════════════════════════════════════════ */}
      <section className="rounded-2xl border-2 border-[var(--shell-accent)]/30 bg-gradient-to-br from-[var(--shell-accent)]/8 to-[var(--shell-panel)] p-5">
        <SectionHeader icon={<BarChart3 className="h-4 w-4" />} title="GEO 통합 점수" hint="자사 언급률 기준 — Sheet 7 평가 기준" />
        <div className="mt-4 grid gap-4 md:grid-cols-3">
          {/* 큰 게이지 */}
          <div className="flex items-center justify-center md:col-span-1">
            <ScoreGauge value={brandRate} color={rateLevel.arc} level={rateLevel.label} />
          </div>
          {/* 우측 메타 + KPI 칩 */}
          <div className="md:col-span-2 space-y-3">
            <div className={`rounded-xl px-4 py-3 ${rateLevel.bg}`}>
              <div className="flex items-baseline gap-2">
                <span className={`text-3xl font-semibold ${rateLevel.color}`}>{brandRate.toFixed(1)}%</span>
                <span className={`text-sm font-medium ${rateLevel.color}`}>{rateLevel.label}</span>
              </div>
              <div className="mt-1 text-xs text-[var(--shell-text-muted)]">
                {brandName ? `${brandName} 자사 언급률` : "자사 언급률"} · {analysis.brandMentionCount}/{totalCalls} 답변
                {latest.run?.completedAt && ` · ${new Date(latest.run.completedAt).toLocaleDateString()}`}
              </div>
            </div>
            <div className="grid grid-cols-3 gap-2">
              <Kpi label="GPT" value={`${(analysis.engineBreakdown?.gpt?.rate || 0).toFixed(1)}%`}
                   sub={`${analysis.engineBreakdown?.gpt?.count || 0}/${analysis.engineBreakdown?.gpt?.total || 0}`} tone="info" />
              <Kpi label="Gemini" value={`${(analysis.engineBreakdown?.gemini?.rate || 0).toFixed(1)}%`}
                   sub={`${analysis.engineBreakdown?.gemini?.count || 0}/${analysis.engineBreakdown?.gemini?.total || 0}`} tone="info" />
              <Kpi label="1순위 추천률" value={`${top1Rate.toFixed(1)}%`}
                   sub={`${top1Count}건`}
                   tone={top1Rate >= 30 ? "good" : top1Rate >= 10 ? "warn" : "bad"} />
            </div>
            <div className="grid grid-cols-3 gap-2">
              <SmallKpi label="긍정" value={`${getSentimentRate(analysis.sentimentBreakdown, "positive").toFixed(0)}%`} tone="text-emerald-300" />
              <SmallKpi label="중립" value={`${getSentimentRate(analysis.sentimentBreakdown, "neutral").toFixed(0)}%`} tone="text-neutral-300" />
              <SmallKpi label="부정" value={`${getSentimentRate(analysis.sentimentBreakdown, "negative").toFixed(0)}%`} tone="text-red-300" />
            </div>
          </div>
        </div>
      </section>

      {/* ═══════════════════════════════════════════════════════════
          1.5) 기간별 추세 + 경쟁사 — 실측정 데이터
         ═══════════════════════════════════════════════════════════ */}
      <MentionRateTrendChart snapshots={trendSnapshots} />

      {sovTotalUnits > 0 && (
        <section className="rounded-2xl border border-[var(--shell-border)] bg-[var(--shell-panel)] p-5">
          <div className="flex items-center justify-between">
            <SectionHeader icon={<BarChart3 className="h-4 w-4" />} title="경쟁사 대비 점유율 (Share of Voice)"
              hint="자사 답변 내 자사 vs 경쟁사 언급 비중 — 실측정" />
            <div className="text-xs text-[var(--shell-text-muted)]">우리 {ourShare}%</div>
          </div>
          <div className="mt-3 flex h-3 overflow-hidden rounded-full bg-[var(--shell-panel-soft)]">
            <div className="bg-[var(--shell-accent)]" style={{ width: `${(ourMentionCount / sovTotalUnits) * 100}%` }} title={`우리: ${ourMentionCount}`} />
            {sovTop3.map((c, i) => (
              <div
                key={c.name}
                className={i === 0 ? "bg-red-400" : i === 1 ? "bg-amber-400" : "bg-neutral-400"}
                style={{ width: `${((c.count || 0) / sovTotalUnits) * 100}%` }}
                title={`${c.name}: ${c.count}`}
              />
            ))}
          </div>
          <div className="mt-2 flex flex-wrap gap-3 text-[11px]">
            <span className="text-[var(--shell-accent)]">■ {brandName || "우리"} ({ourMentionCount})</span>
            {sovTop3.map((c, i) => (
              <span key={c.name} className={i === 0 ? "text-red-300" : i === 1 ? "text-amber-300" : "text-neutral-300"}>
                ■ {c.name} ({c.count})
              </span>
            ))}
          </div>
        </section>
      )}

      {sortedCompetitors.length > 0 && (
        <section className="rounded-2xl border border-[var(--shell-border)] bg-[var(--shell-panel)] p-5">
          <div className="flex items-center justify-between">
            <SectionHeader icon={<Swords className="h-4 w-4" />} title="경쟁사 언급"
              hint="자사 답변에서 함께 언급된 경쟁사 — 측정 횟수 순" />
            <Link to={`/board/${onboardingId}/portal-v3/ai-search-analysis`}
                  className="flex items-center gap-1 text-xs text-[var(--shell-accent)] hover:underline">
              경쟁사 비교 자세히 <ArrowRight className="h-3 w-3" />
            </Link>
          </div>
          <div className="mt-3 space-y-1.5">
            {sortedCompetitors.slice(0, 5).map((c, i) => (
              <div key={c.name} className="flex items-center gap-3 rounded-lg bg-[var(--shell-panel-soft)] px-3 py-2 text-sm">
                <span className="w-5 shrink-0 text-[11px] text-[var(--shell-text-soft)]">{i + 1}.</span>
                <span className="flex-1 truncate text-[var(--shell-text)]">{c.name}</span>
                {typeof c.rate === "number" && c.rate > 0 && (
                  <span className="shrink-0 text-[11px] text-[var(--shell-text-soft)]">{c.rate.toFixed(1)}%</span>
                )}
                <span className="shrink-0 text-xs font-mono text-[var(--shell-text-muted)]">{c.count} 회</span>
              </div>
            ))}
          </div>
        </section>
      )}

      {/* ═══════════════════════════════════════════════════════════
          2) 🔍 쿼리별 측정 결과 — 다른 메뉴와 동일 데이터 (NEW)
         ═══════════════════════════════════════════════════════════ */}
      {queryBreakdown.length > 0 && (
        <section className="rounded-2xl border border-[var(--shell-border)] bg-[var(--shell-panel)] p-5">
          <div className="flex items-center justify-between">
            <SectionHeader icon={<Search className="h-4 w-4" />} title="쿼리별 측정 결과"
              hint={`머스트윈 ${queryBreakdown.length}개 쿼리 · 카테고리 + 자사/GPT/Gemini 언급률`} />
            <Link to={`/board/${onboardingId}/portal-v3/ai-search-analysis`}
                  className="flex items-center gap-1 text-xs text-[var(--shell-accent)] hover:underline">
              자세히 <ArrowRight className="h-3 w-3" />
            </Link>
          </div>
          <div className="mt-3 overflow-x-auto">
            <table className="w-full min-w-[680px] text-xs">
              <thead>
                <tr className="border-b border-[var(--shell-border)] text-left text-[10px] uppercase tracking-wider text-[var(--shell-text-soft)]">
                  <th className="py-2 pr-2 font-medium">#</th>
                  <th className="py-2 pr-2 font-medium">쿼리</th>
                  <th className="py-2 pr-2 font-medium">카테고리</th>
                  <th className="py-2 pr-2 font-medium text-right">자사 %</th>
                  <th className="py-2 pr-2 font-medium text-right">GPT %</th>
                  <th className="py-2 pr-2 font-medium text-right">Gemini %</th>
                  <th className="py-2 font-medium text-right">평균 순위</th>
                </tr>
              </thead>
              <tbody>
                {queryBreakdown.map((q: any) => (
                  <tr key={q.queryIndex} className="border-b border-[var(--shell-border)]/40 hover:bg-[var(--shell-panel-soft)]">
                    <td className="py-2.5 pr-2 text-[var(--shell-text-soft)] font-mono">Q{q.queryIndex + 1}</td>
                    <td className="py-2.5 pr-2 max-w-[260px] truncate text-[var(--shell-text)]" title={q.queryText}>{q.queryText}</td>
                    <td className="py-2.5 pr-2">
                      {q.category ? (
                        <span className="rounded-full bg-blue-500/15 px-1.5 py-0.5 text-[9px] text-blue-300">{q.category}</span>
                      ) : <span className="text-[var(--shell-text-soft)]">-</span>}
                    </td>
                    <td className={`py-2.5 pr-2 text-right font-mono font-semibold ${
                      q.brandRate >= 60 ? "text-emerald-300" : q.brandRate >= 40 ? "text-amber-300" : "text-red-300"
                    }`}>{q.brandRate.toFixed(1)}%</td>
                    <td className="py-2.5 pr-2 text-right font-mono text-blue-300">{q.gptRate.toFixed(1)}%</td>
                    <td className="py-2.5 pr-2 text-right font-mono text-emerald-300">{q.geminiRate.toFixed(1)}%</td>
                    <td className="py-2.5 text-right font-mono text-[var(--shell-text-muted)]">
                      {q.avgMentionPosition != null ? q.avgMentionPosition.toFixed(1) : "-"}
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        </section>
      )}

      {/* ═══════════════════════════════════════════════════════════
          3) 🏆 경쟁사 비교 + 강점·약점
         ═══════════════════════════════════════════════════════════ */}
      <section className="grid gap-4 md:grid-cols-2">
        {/* 경쟁사 */}
        <div className="rounded-2xl border border-[var(--shell-border)] bg-[var(--shell-panel)] p-5">
          <SectionHeader icon={<Award className="h-4 w-4" />} title="경쟁사 비교"
            hint="자사 답변 내 함께 언급된 경쟁사" />
          {analysis.competitorBreakdown?.length > 0 ? (
            <div className="mt-3 space-y-2">
              <CompetitorBar name={`${brandName || "자사"} (기준)`} count={analysis.brandMentionCount} rate={brandRate} isSelf />
              {(analysis.competitorBreakdown || []).slice(0, 5).map((c: any) => (
                <CompetitorBar key={c.name} name={c.name} count={c.count} rate={c.rate || 0} isSelf={false} />
              ))}
            </div>
          ) : (
            <div className="mt-3 text-[10px] text-[var(--shell-text-muted)]">
              경쟁사 언급 데이터가 없습니다. 고객 인풋에서 경쟁사를 브랜드명으로 입력해주세요.
            </div>
          )}
        </div>

        {/* 강점/약점 통합 */}
        <div className="rounded-2xl border border-[var(--shell-border)] bg-[var(--shell-panel)] p-5">
          <SectionHeader icon={<MessageSquare className="h-4 w-4" />} title="자사 강점 / 약점"
            hint="Claude 가 추출한 핵심 포인트" />
          <div className="mt-3 space-y-3">
            <div>
              <div className="flex items-center gap-1.5 text-[11px] font-semibold text-emerald-300">
                <TrendingUp className="h-3 w-3" /> 강점 Top 3
              </div>
              {(analysis.strengths || []).slice(0, 3).map((s: any, i: number) => (
                <div key={i} className="mt-1 flex items-center justify-between text-[11px]">
                  <span className="text-[var(--shell-text)] truncate">• {s.point}</span>
                  <span className="ml-2 shrink-0 text-[var(--shell-text-muted)]">{s.count}회</span>
                </div>
              ))}
              {(analysis.strengths || []).length === 0 && <div className="mt-1 text-[10px] text-[var(--shell-text-muted)]">데이터 없음</div>}
            </div>
            <div>
              <div className="flex items-center gap-1.5 text-[11px] font-semibold text-red-300">
                <TrendingDown className="h-3 w-3" /> 약점 Top 3
              </div>
              {(analysis.weaknesses || []).slice(0, 3).map((w: any, i: number) => (
                <div key={i} className="mt-1 flex items-center justify-between text-[11px]">
                  <span className="text-[var(--shell-text)] truncate">• {w.point}</span>
                  <span className="ml-2 shrink-0 text-[var(--shell-text-muted)]">{w.count}회</span>
                </div>
              ))}
              {(analysis.weaknesses || []).length === 0 && <div className="mt-1 text-[10px] text-[var(--shell-text-muted)]">데이터 없음</div>}
            </div>
          </div>
        </div>
      </section>

      {/* ═══════════════════════════════════════════════════════════
          4) 🎯 액션 + 🤖 AI 추천 + 📈 적중률 — 통합 패널
         ═══════════════════════════════════════════════════════════ */}
      <section className="grid gap-3 md:grid-cols-3">
        {/* 액션 */}
        <PanelCard
          icon={<Target className="h-3.5 w-3.5" />}
          title="액션 진행 현황"
          link={{ to: `/board/${onboardingId}/portal-v3/timeline`, text: "관리" }}
        >
          {counts ? (
            <>
              <div className="mt-3 grid grid-cols-2 gap-2">
                <Stat label="진행 중" value={counts.inProgress} tone="text-blue-300" />
                <Stat label="예정" value={counts.planned} tone="text-amber-300" />
                <Stat label="완료" value={counts.completed} tone="text-emerald-300" />
                <Stat label="전체" value={counts.total} tone="text-[var(--shell-text)]" />
              </div>
            </>
          ) : (
            <div className="mt-3 text-[11px] text-[var(--shell-text-muted)]">데이터 없음</div>
          )}
        </PanelCard>

        {/* AI 추천 */}
        <PanelCard
          icon={<Sparkles className="h-3.5 w-3.5" />}
          title="AI 추천"
          link={{ to: `/board/${onboardingId}/portal-v3/improvement-plan`, text: "보기" }}
        >
          <div className="mt-3 grid grid-cols-2 gap-2">
            <Stat label="검토 대기" value={recsPending} tone={recsPending > 0 ? "text-amber-300" : "text-[var(--shell-text-muted)]"} />
            <Stat label="액션 전환" value={recsConverted} tone="text-emerald-300" />
            <Stat label="기각" value={recsQ.data?.counts?.dismissed ?? 0} tone="text-[var(--shell-text-soft)]" />
            <Stat label="전체" value={recsQ.data?.counts?.total ?? 0} tone="text-[var(--shell-text)]" />
          </div>
          {recsPending > 0 && (
            <Link to={`/board/${onboardingId}/portal-v3/improvement-plan`}
                  className="mt-2 block rounded-lg border border-amber-500/30 bg-amber-500/5 px-2 py-1 text-center text-[10px] text-amber-300 hover:bg-amber-500/10">
              {recsPending}건 검토 필요 →
            </Link>
          )}
        </PanelCard>

        {/* 적중률 */}
        <PanelCard
          icon={<TrendingUp className="h-3.5 w-3.5" />}
          title="추천 적중률"
          link={{ to: `/board/${onboardingId}/portal-v3/improvement-plan`, text: "자세히" }}
        >
          {hit ? (
            <div className="mt-3 text-center">
              <div className={`text-4xl font-semibold ${
                hit.hitRate >= 60 ? "text-emerald-300" :
                hit.hitRate >= 30 ? "text-amber-300" :
                "text-[var(--shell-text-muted)]"
              }`}>
                {hit.totalConverted === 0 ? "—" : `${hit.hitRate.toFixed(0)}%`}
              </div>
              <div className="mt-1 text-[10px] text-[var(--shell-text-soft)]">
                {hit.effective} / {hit.totalConverted} 액션 적중
              </div>
              <div className="text-[10px] text-[var(--shell-text-muted)]">+1%p 이상 효과</div>
            </div>
          ) : (
            <div className="mt-3 text-[11px] text-[var(--shell-text-muted)]">데이터 없음</div>
          )}
        </PanelCard>
      </section>

      {/* ═══════════════════════════════════════════════════════════
          5) 📅 측정 스케줄 + 시계열
         ═══════════════════════════════════════════════════════════ */}
      <section className="rounded-2xl border border-[var(--shell-border)] bg-[var(--shell-panel)] p-5">
        <div className="flex items-center justify-between">
          <SectionHeader icon={<Calendar className="h-4 w-4" />} title="측정 스케줄 + 시계열"
            hint="자동 측정 주기 + 최근 측정 마커" />
          <Link
            to={`/board/${onboardingId}/portal-v3/input`}
            className="flex items-center gap-1 rounded-lg border border-[var(--shell-accent)] bg-[var(--shell-accent)]/10 px-3 py-1.5 text-[11px] font-medium text-[var(--shell-accent)] hover:bg-[var(--shell-accent)]/20"
          >
            <PlayCircle className="h-3.5 w-3.5" /> 즉시 측정
          </Link>
        </div>

        {schedule && (
          <div className="mt-3 flex flex-wrap items-center gap-3 text-[11px] text-[var(--shell-text-muted)]">
            <span className="flex items-center gap-1">
              <Clock className="h-3 w-3" />
              <span>자동 주기:</span>
              <span className="font-medium text-[var(--shell-text)]">매주 {DAY_LABELS[schedule.dayOfWeek] || "월"}요일 {String(schedule.hourOfDay).padStart(2, "0")}:00</span>
            </span>
            {schedule.nextRunAt && (
              <span>다음 자동: <span className="text-[var(--shell-text)]">{new Date(schedule.nextRunAt).toLocaleString()}</span></span>
            )}
            <span className="ml-auto">
              총 {runsQ.data?.runs?.length ?? 0}회 · 완료 {doneRuns.length} · 자동 {runsQ.data?.runs?.filter((r: any) => r.triggerType === "scheduled").length ?? 0} · 즉시 {runsQ.data?.runs?.filter((r: any) => r.triggerType === "manual").length ?? 0}
            </span>
          </div>
        )}

        {doneRuns.length >= 2 && (
          <div className="mt-3">
            <RunTimelineMini runs={doneRuns} />
          </div>
        )}
      </section>

      {/* ═══════════════════════════════════════════════════════════
          6) ⚡ 빠른 메뉴
         ═══════════════════════════════════════════════════════════ */}
      <section className="grid grid-cols-2 gap-2 md:grid-cols-5">
        <QuickLink to={`/board/${onboardingId}/portal-v3/input`} icon={<PlayCircle className="h-4 w-4" />} label="고객 인풋" sub="측정 시작" />
        <QuickLink to={`/board/${onboardingId}/portal-v3/ai-search-analysis`} icon={<Cpu className="h-4 w-4" />} label="AI 검색결과" sub="원문 + 통계" />
        <QuickLink to={`/board/${onboardingId}/portal-v3/improvement-plan`} icon={<Sparkles className="h-4 w-4" />} label="개선 방향" sub={`${recsPending} 대기`} />
        <QuickLink to={`/board/${onboardingId}/portal-v3/timeline`} icon={<Target className="h-4 w-4" />} label="액션 진행" sub={`${counts?.inProgress ?? 0} 진행`} />
        <QuickLink to={`/board/${onboardingId}/portal-v3/analysis-report`} icon={<FileText className="h-4 w-4" />} label="분석 보고서" sub="월간 + 엑셀" />
      </section>
    </div>
  );
}

