function SectionHeader({ icon, title, hint }: { icon: React.ReactNode; title: string; hint?: string }) {
  return (
    <div>
      <div className="flex items-center gap-1.5 text-sm font-semibold text-[var(--shell-text)]">
        {icon} {title}
      </div>
      {hint && <div className="mt-0.5 text-[10px] text-[var(--shell-text-soft)]">{hint}</div>}
    </div>
  );
}

function PanelCard({ icon, title, link, children }: {
  icon: React.ReactNode;
  title: string;
  link: { to: string; text: string };
  children: React.ReactNode;
}) {
  return (
    <div className="rounded-2xl border border-[var(--shell-border)] bg-[var(--shell-panel)] p-4">
      <div className="flex items-center justify-between">
        <div className="flex items-center gap-1.5 text-xs font-semibold text-[var(--shell-text)]">
          {icon} {title}
        </div>
        <Link to={link.to} className="text-[10px] text-[var(--shell-accent)] hover:underline">
          {link.text} →
        </Link>
      </div>
      {children}
    </div>
  );
}

function ScoreGauge({ value, color, level }: { value: number; color: string; level: string }) {
  const size = 160;
  const cx = size / 2;
  const cy = size / 2;
  const r = 60;
  const circumference = 2 * Math.PI * r;
  // 0-100 percent → arc length (3/4 of circle visible)
  const visibleFraction = 0.75;
  const arcLen = circumference * visibleFraction;
  const filled = arcLen * (Math.min(100, Math.max(0, value)) / 100);
  const rotation = -135;   // 시작 각도

  return (
    <div className="relative" style={{ width: size, height: size }}>
      <svg viewBox={`0 0 ${size} ${size}`} className="absolute inset-0">
        {/* Background arc */}
        <circle
          cx={cx} cy={cy} r={r}
          fill="none"
          stroke="currentColor"
          strokeOpacity={0.1}
          strokeWidth="12"
          strokeDasharray={`${arcLen} ${circumference}`}
          strokeLinecap="round"
          transform={`rotate(${rotation} ${cx} ${cy})`}
        />
        {/* Filled arc */}
        <circle
          cx={cx} cy={cy} r={r}
          fill="none"
          className={color}
          strokeWidth="12"
          strokeDasharray={`${filled} ${circumference}`}
          strokeLinecap="round"
          transform={`rotate(${rotation} ${cx} ${cy})`}
        />
      </svg>
      <div className="absolute inset-0 flex flex-col items-center justify-center">
        <span className="text-4xl font-semibold text-[var(--shell-text)]">{value.toFixed(0)}</span>
        <span className="text-[10px] uppercase tracking-wider text-[var(--shell-text-soft)]">/ 100</span>
        <span className="mt-1 text-[10px] font-medium text-[var(--shell-text-muted)]">{level}</span>
      </div>
    </div>
  );
}

function getSentimentRate(breakdown: any, key: "positive" | "neutral" | "negative"): number {
  if (!breakdown) return 0;
  const total = (breakdown.positive || 0) + (breakdown.neutral || 0) + (breakdown.negative || 0);
  if (total === 0) return 0;
  return ((breakdown[key] || 0) / total) * 100;
}

function Kpi({ label, value, sub, tone }: { label: string; value: string; sub?: string; tone: "good" | "warn" | "bad" | "info" }) {
  const t = {
    good: "border-emerald-500/30 bg-emerald-500/5 text-emerald-300",
    warn: "border-amber-500/30 bg-amber-500/5 text-amber-300",
    bad: "border-red-500/30 bg-red-500/5 text-red-300",
    info: "border-[var(--shell-border)] bg-[var(--shell-panel)] text-[var(--shell-text)]",
  }[tone];
  return (
    <div className={`rounded-xl border p-2.5 ${t}`}>
      <div className="text-[10px] uppercase tracking-wider opacity-70">{label}</div>
      <div className="mt-1 text-lg font-semibold">{value}</div>
      {sub && <div className="text-[9px] opacity-70">{sub}</div>}
    </div>
  );
}

function SmallKpi({ label, value, tone }: { label: string; value: string; tone: string }) {
  return (
    <div className="rounded-lg border border-[var(--shell-border)] bg-[var(--shell-panel-soft)] px-2 py-1.5 text-center">
      <div className="text-[9px] text-[var(--shell-text-soft)]">{label}</div>
      <div className={`text-sm font-semibold ${tone}`}>{value}</div>
    </div>
  );
}

function Stat({ label, value, tone }: { label: string; value: number; tone: string }) {
  return (
    <div className="rounded-lg border border-[var(--shell-border)] bg-[var(--shell-panel-soft)] px-2 py-1.5">
      <div className="text-[9px] uppercase tracking-wider text-[var(--shell-text-soft)]">{label}</div>
      <div className={`mt-0.5 text-xl font-semibold ${tone}`}>{value}</div>
    </div>
  );
}

function CompetitorBar({ name, count, rate, isSelf }: { name: string; count: number; rate: number; isSelf: boolean }) {
  return (
    <div>
      <div className="flex items-center justify-between text-[11px]">
        <span className={isSelf ? "font-semibold text-emerald-300" : "text-[var(--shell-text)]"}>{name}</span>
        <span className="text-[var(--shell-text-muted)]">{count}회 ({rate.toFixed(1)}%)</span>
      </div>
      <div className="mt-1 h-2 overflow-hidden rounded-full bg-[var(--shell-panel-soft)]">
        <div className={isSelf ? "h-full bg-emerald-400" : "h-full bg-blue-400"} style={{ width: `${Math.min(100, rate)}%` }} />
      </div>
    </div>
  );
}

function RunTimelineMini({ runs }: { runs: any[] }) {
  const width = 720;
  const height = 70;
  const padding = { top: 6, right: 20, bottom: 18, left: 20 };
  const innerW = width - padding.left - padding.right;
  const innerH = height - padding.top - padding.bottom;
  const xFor = (i: number) => runs.length === 1 ? padding.left + innerW / 2 : padding.left + (i / (runs.length - 1)) * innerW;
  return (
    <div className="w-full overflow-x-auto">
      <svg viewBox={`0 0 ${width} ${height}`} className="w-full" preserveAspectRatio="xMidYMid meet">
        <line x1={padding.left} x2={width - padding.right} y1={padding.top + innerH / 2} y2={padding.top + innerH / 2} stroke="currentColor" strokeOpacity={0.08} />
        {runs.map((r, i) => (
          <g key={i}>
            <circle cx={xFor(i)} cy={padding.top + innerH / 2} r="4" fill={r.triggerType === "scheduled" ? "#34d399" : "#60a5fa"} />
            <text x={xFor(i)} y={height - 4} textAnchor="middle" className="fill-[var(--shell-text-soft)] text-[8px]">
              {new Date(r.completedAt!).toLocaleDateString().slice(5)}
            </text>
          </g>
        ))}
      </svg>
    </div>
  );
}

function QuickLink({ to, icon, label, sub }: { to: string; icon: React.ReactNode; label: string; sub: string }) {
  return (
    <Link
      to={to}
      className="flex flex-col items-center gap-1 rounded-xl border border-[var(--shell-border)] bg-[var(--shell-panel)] p-3 text-center hover:border-[var(--shell-accent)] hover:bg-[var(--shell-panel-soft)]"
    >
      <div className="text-[var(--shell-text)]">{icon}</div>
      <div className="text-xs font-medium text-[var(--shell-text)]">{label}</div>
      <div className="text-[9px] text-[var(--shell-text-muted)]">{sub}</div>
    </Link>
  );
}
