import type { ComponentType } from "react";

interface MetricCardProps {
  icon: ComponentType<{ className?: string }>;
  label: string;
  value: string;
  sub?: string;
  color?: string;
}

export function MetricCard({ icon: Icon, label, value, sub, color = "text-[var(--shell-text)]" }: MetricCardProps) {
  return (
    <div className="rounded-2xl border border-[var(--shell-border)] bg-[var(--shell-panel)] p-4">
      <div className="flex items-center gap-2.5">
        <div className={`rounded-xl bg-[var(--shell-panel-soft)] p-2 ${color}`}>
          <Icon className="h-4 w-4" />
        </div>
        <span className="text-xs font-medium text-[var(--shell-text-muted)]">
          {label}
        </span>
      </div>
      <div className="mt-3 flex items-baseline gap-2">
        <span className="text-2xl font-semibold text-[var(--shell-text)]">
          {value}
        </span>
        {sub && (
          <span className="text-xs text-[var(--shell-text-muted)]">
            {sub}
          </span>
        )}
      </div>
    </div>
  );
}
