import { getDoc } from "firebase/firestore";
import { paths } from "../../../db/paths";
import type { DiagnosticCheck, DiagnosticRunner } from "./types";

export const runInputDiagnostics: DiagnosticRunner = async (boardId) => {
  const results: DiagnosticCheck[] = [];

  try {
    const snap = await getDoc(paths.rawBrandTruth(boardId));
    if (!snap.exists()) {
      results.push({ id: "input-truth", label: "raw/v1/brand_truth/default 문서 존재", status: "fail", detail: "브랜드 진실 문서가 없습니다. '고객 인풋' 페이지에서 데이터를 먼저 입력해주세요." });
      return results;
    }

    const data = snap.data() as any;
    results.push({ id: "input-truth", label: "raw/v1/brand_truth/default 문서 존재", status: "pass", detail: `canonicalName: ${data.canonicalName || "N/A"}` });

    const checks: { field: string; label: string; required: boolean }[] = [
      { field: "canonicalName", label: "브랜드명 (canonicalName)", required: true },
      { field: "businessSummary", label: "비즈니스 요약 (businessSummary)", required: true },
      { field: "websiteUrl", label: "웹사이트 URL (websiteUrl)", required: true },
      { field: "primaryCategory", label: "주요 카테고리 (primaryCategory)", required: false },
      { field: "brandKeywords", label: "브랜드 키워드 (brandKeywords)", required: false },
      { field: "targetPersona", label: "타겟 페르소나 (targetPersona)", required: false },
      { field: "queryCategories", label: "질문 카테고리 (queryCategories)", required: false },
      { field: "competitorDomains", label: "경쟁사 도메인 (competitorDomains)", required: false },
    ];

    const rawUpdated = data.updatedAt;
    if (!rawUpdated) {
      results.push({ id: "input-updatedAt", label: "updatedAt 필드", status: "warn", detail: "updatedAt 값이 없습니다 (저장 기록 없음)" });
    } else {
      const ts = rawUpdated?.toDate ? rawUpdated.toDate() : new Date(rawUpdated);
      const valid = !isNaN(ts.getTime());
      results.push({
        id: "input-updatedAt",
        label: "updatedAt 필드 (마지막 저장 시각)",
        status: valid ? "pass" : "fail",
        detail: valid
          ? `${ts.toLocaleString()} (type: ${rawUpdated?.toDate ? "Timestamp" : typeof rawUpdated})`
          : `Invalid Date — 원본 값: ${JSON.stringify(rawUpdated)} (type: ${typeof rawUpdated}). Firestore Timestamp.toDate() 변환 필요`,
      });
    }

    for (const c of checks) {
      const val = data[c.field];
      const hasValue = Array.isArray(val) ? val.length > 0 : !!val;
      const preview = Array.isArray(val) ? `${val.length}개` : (typeof val === "string" ? (val.length > 60 ? val.slice(0, 60) + "..." : val) : String(val ?? "없음"));
      results.push({
        id: `input-${c.field}`,
        label: c.label,
        status: hasValue ? "pass" : (c.required ? "fail" : "warn"),
        detail: preview,
      });
    }
  } catch (err: any) {
    results.push({ id: "input-truth", label: "brand_truth 문서 조회", status: "fail", detail: `에러: ${err.message}` });
  }

  return results;
};
