import { useEffect, useMemo, useState } from "react";
import { useParams, Link } from "react-router-dom";
import {
  AlertTriangle, BarChart3, Eye, Flame, Lightbulb, Monitor, Shield, Swords, XCircle,
} from "lucide-react";
import {
  subscribeBoard,
  subscribeInsights,
  getDocument,
  listSeoAudits,
  listErrorJournal,
  listCompetitorsV2,
  listManualCompetitors,
} from "../../../db/boards";
import type { Board, InsightDoc, InsightType } from "../../../db/collections";
import type { ErrorJournalEntry } from "../../../db/boards";
import { DataQualityBadge } from "../../../components/shared/DataQualityBadge";
import { InsightBoard } from "./InsightBoard";

// ── Types ──────────────────────────────────────────────────

interface ScoreWidget {
  label: string;
  slug: string;
  icon: React.ComponentType<{ className?: string }>;
  value: number | null;
  color: string;
}

// ── Component ──────────────────────────────────────────────

export function InsightsOverview() {
  const { id } = useParams<{ id: string }>();
  const [board, setBoard] = useState<Board | null>(null);
  const [seoAudit, setSeoAudit] = useState<Record<string, unknown> | null>(null);
  const [trustData, setTrustData] = useState<Record<string, unknown> | null>(null);
  const [errors, setErrors] = useState<ErrorJournalEntry[]>([]);
  const [competitorCount, setCompetitorCount] = useState(0);
  const [insights, setInsights] = useState<InsightDoc[]>([]);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    if (!id) return;
    setLoading(true);
    const unsubBoard = subscribeBoard(id, setBoard);
    const unsubIns = subscribeInsights(id, setInsights);
    Promise.all([
      listSeoAudits(id, 1),
      getDocument(id, "external-sources-analysis").catch(() => null),
      getDocument(id, "external-analysis").catch(() => null),
      listErrorJournal(id, 50),
      listCompetitorsV2(id).catch(() => []),
      listManualCompetitors(id).catch(() => []),
    ]).then(([audits, ext1, ext2, errs, autoComps, manualComps]) => {
      if (audits[0]) setSeoAudit(audits[0] as Record<string, unknown>);
      setTrustData((ext1?.data ?? ext2?.data ?? null) as Record<string, unknown> | null);
      setErrors(errs);
      setCompetitorCount(autoComps.length + manualComps.length);
      setLoading(false);
    });
    return () => {
      unsubBoard();
      unsubIns();
    };
  }, [id]);

  // ── Derived: Insights aggregation ──

  const openInsights = useMemo(
    () => insights.filter((i) => i.status !== "resolved" && i.status !== "ignored"),
    [insights],
  );
  const criticalOpen = useMemo(
    () => openInsights.filter((i) => i.severity === "critical"),
    [openInsights],
  );
  const warningOpen = useMemo(
    () => openInsights.filter((i) => i.severity === "warning"),
    [openInsights],
  );

  const countsByType = useMemo(() => {
    const map = new Map<InsightType, number>();
    for (const ins of openInsights) {
      if (!ins.type) continue;
      map.set(ins.type, (map.get(ins.type) ?? 0) + 1);
    }
    return Array.from(map.entries()).sort((a, b) => b[1] - a[1]);
  }, [openInsights]);

  const topPriority = useMemo(() => {
    return [...openInsights]
      .sort((a, b) => (b.priorityScore ?? 0) - (a.priorityScore ?? 0))
      .slice(0, 5);
  }, [openInsights]);

  // ── Derived: Score widgets ──

  const seoScore = (seoAudit?.seoScore as number) ?? (seoAudit?.score as number) ?? null;
  const geoScore = (seoAudit?.geoScore as number) ?? null;

  const trustScore = useMemo(() => {
    if (!trustData) return null;
    const ts = (trustData as { trustScore?: number; analysis?: { trustScore?: number }; sources?: Array<{ exists: boolean }> });
    if (ts.trustScore != null) return ts.trustScore;
    if (ts.analysis?.trustScore != null) return ts.analysis.trustScore;
    const sources = ts.sources ?? [];
    return Math.min(100, sources.filter((s) => s.exists).length * 15);
  }, [trustData]);

  const scoreWidgets: ScoreWidget[] = [
    { label: "SEO Score", slug: "website-health", icon: Monitor, value: seoScore, color: scoreColor(seoScore) },
    { label: "GEO Score", slug: "ai-visibility", icon: Eye, value: geoScore, color: scoreColor(geoScore) },
    { label: "Trust Score", slug: "trust-signals", icon: Shield, value: trustScore, color: scoreColor(trustScore) },
    { label: "Competitors", slug: "competitors", icon: Swords, value: competitorCount, color: "text-blue-600" },
  ];

  // ── Derived: Data Quality ──

  const dataQuality = useMemo(() => {
    const signals = [
      { name: "SEO/GEO Audit", ok: !!seoAudit },
      { name: "Board Data", ok: !!board },
      { name: "Trust Signals", ok: !!trustData },
      { name: "Competitor Data", ok: competitorCount > 0 },
      { name: "Keywords", ok: (board?.rawKeywords?.length ?? 0) > 0 },
    ];
    const okCount = signals.filter((s) => s.ok).length;
    const score = Math.round((okCount / signals.length) * 100);
    const status: "ok" | "warning" | "degraded" | "invalid" =
      score >= 80 ? "ok" : score >= 50 ? "warning" : score > 0 ? "degraded" : "invalid";
    const notes = signals.filter((s) => !s.ok).map((s) => `${s.name} not available`);
    return { score, status, notes, signals };
  }, [seoAudit, board, trustData, competitorCount]);

  // ── Derived: Issue stats ──

  const criticalCount = useMemo(() => {
    let count = 0;
    const violations = (seoAudit?.violations ?? []) as Array<{ severity: string }>;
    count += violations.filter((v) => v.severity === "error").length;
    const checks = (seoAudit?.checks ?? []) as Array<{ status: string }>;
    count += checks.filter((c) => c.status === "fail").length;
    return count;
  }, [seoAudit]);

  const warningCount = useMemo(() => {
    let count = 0;
    const violations = (seoAudit?.violations ?? []) as Array<{ severity: string }>;
    count += violations.filter((v) => v.severity === "warning").length;
    const checks = (seoAudit?.checks ?? []) as Array<{ status: string }>;
    count += checks.filter((c) => c.status === "warn").length;
    return count;
  }, [seoAudit]);

  if (loading) {
    return (
      <div className="flex min-h-[30vh] items-center justify-center text-sm text-[var(--shell-text-muted)]">
        불러오는 중...
      </div>
    );
  }

  const basePath = `/board/${id}/workspace/insights`;

  return (
    <div className="space-y-6">
      {/* Score Cards */}
      <div className="grid gap-4 sm:grid-cols-2 lg:grid-cols-4">
        {scoreWidgets.map((w) => (
          <Link
            key={w.slug}
            to={`${basePath}/${w.slug}`}
            className="group rounded-2xl border border-[var(--shell-border)] bg-[var(--shell-panel)] p-5 transition-all hover:border-[var(--shell-accent)] hover:shadow-sm"
          >
            <div className="flex items-center justify-between">
              <w.icon className="h-5 w-5 text-[var(--shell-text-soft)] group-hover:text-[var(--shell-accent)]" />
              <span className={`text-3xl font-bold ${w.color}`}>
                {w.value != null ? w.value : "--"}
              </span>
            </div>
            <p className="mt-3 text-sm font-medium text-[var(--shell-text)]">{w.label}</p>
          </Link>
        ))}
      </div>

      {/* Issue summary bar */}
      <div className="flex flex-wrap items-center gap-4 rounded-2xl border border-[var(--shell-border)] bg-[var(--shell-panel)] px-5 py-4">
        <div className="flex items-center gap-2 text-sm font-medium text-[var(--shell-text)]">
          <BarChart3 className="h-4 w-4" />
          Issue Summary
        </div>
        <div className="h-4 w-px bg-[var(--shell-border)]" />
        <div className="flex items-center gap-1.5">
          <XCircle className="h-3.5 w-3.5 text-rose-500" />
          <span className="text-sm font-medium text-rose-500">{criticalCount}</span>
          <span className="text-xs text-[var(--shell-text-muted)]">critical</span>
        </div>
        <div className="flex items-center gap-1.5">
          <AlertTriangle className="h-3.5 w-3.5 text-amber-500" />
          <span className="text-sm font-medium text-amber-500">{warningCount}</span>
          <span className="text-xs text-[var(--shell-text-muted)]">warnings</span>
        </div>
        <div className="flex items-center gap-1.5">
          <span className="text-xs text-[var(--shell-text-muted)]">{errors.length} runtime events today</span>
        </div>
      </div>

      {/* Data Quality */}
      <DataQualityBadge score={dataQuality.score} status={dataQuality.status} notes={dataQuality.notes} />

      {/* Data sources detail */}
      <div className="rounded-2xl border border-[var(--shell-border)] bg-[var(--shell-panel)] p-5">
        <h3 className="text-sm font-semibold text-[var(--shell-text)]">Data Sources</h3>
        <div className="mt-3 grid gap-2 sm:grid-cols-2 lg:grid-cols-3">
          {dataQuality.signals.map((s) => (
            <div key={s.name} className="flex items-center gap-2.5 rounded-xl border border-[var(--shell-border)] bg-[var(--shell-panel-soft)] px-4 py-3">
              <span className={`inline-flex h-2.5 w-2.5 rounded-full ${s.ok ? "bg-emerald-500" : "bg-rose-500"}`} />
              <span className="text-sm text-[var(--shell-text)]">{s.name}</span>
            </div>
          ))}
        </div>
      </div>

      {/* Insights aggregate */}
      <div className="grid gap-4 lg:grid-cols-3">
        <div className="rounded-2xl border border-[var(--shell-border)] bg-[var(--shell-panel)] p-5">
          <div className="flex items-center gap-2">
            <Lightbulb className="h-4 w-4 text-[var(--shell-text-soft)]" />
            <h3 className="text-sm font-semibold text-[var(--shell-text)]">Open Insights</h3>
          </div>
          <div className="mt-4 flex items-baseline gap-3">
            <span className="text-3xl font-bold text-[var(--shell-text)]">{openInsights.length}</span>
            <span className="text-xs text-[var(--shell-text-muted)]">total open</span>
          </div>
          <div className="mt-3 flex items-center gap-3 text-xs">
            <span className="rounded-md bg-rose-500/10 px-2 py-0.5 font-medium text-rose-500">{criticalOpen.length} critical</span>
            <span className="rounded-md bg-amber-500/10 px-2 py-0.5 font-medium text-amber-500">{warningOpen.length} warning</span>
          </div>
        </div>

        <div className="rounded-2xl border border-[var(--shell-border)] bg-[var(--shell-panel)] p-5 lg:col-span-2">
          <div className="flex items-center gap-2">
            <BarChart3 className="h-4 w-4 text-[var(--shell-text-soft)]" />
            <h3 className="text-sm font-semibold text-[var(--shell-text)]">By Category</h3>
          </div>
          {countsByType.length > 0 ? (
            <div className="mt-3 grid gap-2 sm:grid-cols-2">
              {countsByType.map(([type, count]) => (
                <div key={type} className="flex items-center justify-between rounded-xl border border-[var(--shell-border)] bg-[var(--shell-panel-soft)] px-3 py-2">
                  <span className="text-sm capitalize text-[var(--shell-text)]">{type.replace(/_/g, " ")}</span>
                  <span className="text-sm font-semibold text-[var(--shell-text)]">{count}</span>
                </div>
              ))}
            </div>
          ) : (
            <p className="mt-3 text-sm text-[var(--shell-text-muted)]">어떤 카테고리에도 미해결 인사이트가 없습니다.</p>
          )}
        </div>
      </div>

      {topPriority.length > 0 && (
        <div className="rounded-2xl border border-[var(--shell-border)] bg-[var(--shell-panel)] p-5">
          <div className="mb-3 flex items-center gap-2">
            <Flame className="h-4 w-4 text-rose-500" />
            <h3 className="text-sm font-semibold text-[var(--shell-text)]">Top Priority</h3>
          </div>
          <div className="space-y-2">
            {topPriority.map((ins) => (
              <div key={ins.id} className="rounded-xl border border-[var(--shell-border)] bg-[var(--shell-panel-soft)] px-4 py-3">
                <div className="flex items-center justify-between gap-2">
                  <p className="text-sm font-medium text-[var(--shell-text)]">{ins.title}</p>
                  <div className="flex shrink-0 items-center gap-1.5">
                    {ins.priorityScore != null && (
                      <span className="rounded-md bg-[var(--shell-panel)] px-1.5 py-0.5 text-[10px] font-medium text-[var(--shell-text-muted)]">
                        P{Math.round(ins.priorityScore)}
                      </span>
                    )}
                    <span className={`rounded-md px-1.5 py-0.5 text-[10px] font-medium ${
                      ins.severity === "critical" ? "bg-rose-500/10 text-rose-500"
                        : ins.severity === "warning" ? "bg-amber-500/10 text-amber-500"
                          : "bg-blue-400/10 text-blue-500"
                    }`}>
                      {ins.severity}
                    </span>
                  </div>
                </div>
                {ins.summary && <p className="mt-1 text-xs text-[var(--shell-text-muted)]">{ins.summary}</p>}
              </div>
            ))}
          </div>
        </div>
      )}

      {/* Integrated issue board (formerly Insight Board tab) */}
      <div className="rounded-2xl border border-[var(--shell-border)] bg-[var(--shell-panel)] p-5">
        <div className="mb-4 flex items-center justify-between gap-3">
          <div>
            <h3 className="text-sm font-semibold text-[var(--shell-text)]">All Insights</h3>
            <p className="mt-0.5 text-xs text-[var(--shell-text-muted)]">
              심각도, 소스, 상태별로 필터링하고 각 이슈에서 바로 액션을 만들 수 있습니다.
            </p>
          </div>
        </div>
        <InsightBoard />
      </div>
    </div>
  );
}

// ── Helpers ────────────────────────────────────────────────

function scoreColor(value: number | null): string {
  if (value == null) return "text-[var(--shell-text-muted)]";
  if (value >= 70) return "text-emerald-600";
  if (value >= 40) return "text-amber-500";
  return "text-rose-500";
}
