// ── Derived Pipeline ──────────────────────────────────────

export interface PipelineStep {
  key: string;
  label: string;
}

export interface PipelineWave {
  key: string;
  label: string;
  steps: PipelineStep[];
}

function buildPipelineWaves(): PipelineWave[] {
  const onboardWorkers = WORKER_MAP.filter(
    (w) => w.group === "onboard" && w.wave != null && w.waveLabel,
  );

  const grouped = new Map<string, { minWave: number; steps: PipelineStep[] }>();

  for (const w of onboardWorkers) {
    const wl = w.waveLabel!;
    if (!grouped.has(wl)) {
      grouped.set(wl, { minWave: w.wave!, steps: [] });
    }
    const group = grouped.get(wl)!;
    group.minWave = Math.min(group.minWave, w.wave!);
    group.steps.push({
      key: w.stepName ?? w.id,
      label: w.shortLabel ?? w.label,
    });
  }

  return [...grouped.entries()]
    .sort(([, a], [, b]) => a.minWave - b.minWave)
    .map(([label, { steps }]) => ({
      key: label.toLowerCase().replace(/\s+/g, "-"),
      label,
      steps,
    }));
}

export const PIPELINE_WAVES: PipelineWave[] = buildPipelineWaves();

const stepLabelMap = new Map<string, string>();
for (const w of WORKER_MAP) {
  const key = w.stepName ?? w.id;
  if (!stepLabelMap.has(key)) {
    stepLabelMap.set(key, w.shortLabel ?? w.label);
  }
}

export function getStepLabel(stepName: string): string {
  return stepLabelMap.get(stepName) ?? stepName;
}
