// @ts-nocheck — V3 실데이터 주간 리포트 카드
// 최신 dk_v3_analysis + dk_v3_measurement_runs (12주) 을 보여줌.
// ClientV4WeeklyReport 페이지 상단에 삽입되어 mock 보다 우선 표시.
import { useMemo } from "react";
import { useParams } from "react-router-dom";
import { useQuery } from "@tanstack/react-query";
import {
  Activity, AlertTriangle, CheckCircle2, MessageSquare, Sparkles, TrendingDown, TrendingUp, Loader2,
  Download,
} from "lucide-react";
import { v3MeasurementApi } from "./dataHub";

export function V3RealWeeklyReportCard() {
  const { id: onboardingId } = useParams<{ id: string }>();

  const latestQ = useQuery({
    queryKey: ["portalV3", "v3-latest", onboardingId],
    queryFn: () => v3MeasurementApi.getLatest(onboardingId!),
    enabled: !!onboardingId,
  });
  const runsQ = useQuery({
    queryKey: ["portalV3", "v3-runs-12", onboardingId],
    queryFn: () => v3MeasurementApi.listRuns(onboardingId!, 20),
    enabled: !!onboardingId,
  });

  const latest = latestQ.data;
  const analysis = latest?.analysis;
  const wrd = analysis?.weeklyReportData as any;
  const runs = runsQ.data?.runs || [];

  if (latestQ.isLoading || runsQ.isLoading) {
    return (
      <div className="rounded-2xl border border-[var(--shell-border)] bg-[var(--shell-panel)] p-6 text-center text-sm text-[var(--shell-text-muted)]">
        <Loader2 className="mx-auto h-5 w-5 animate-spin" />
        <div className="mt-2">V3 측정 데이터를 불러오는 중...</div>
      </div>
    );
  }

  if (!analysis) {
    return (
      <div className="rounded-2xl border-2 border-dashed border-[var(--shell-border)] bg-[var(--shell-panel)] p-6 text-center">
        <Sparkles className="mx-auto h-6 w-6 text-[var(--shell-text-soft)]" />
        <div className="mt-2 text-sm text-[var(--shell-text)]">아직 V3 측정 결과가 없습니다</div>
        <div className="mt-1 text-[11px] text-[var(--shell-text-muted)]">
          "고객 인풋" 메뉴에서 "지금 즉시 측정 시작" 을 눌러 1,000 calls 측정을 실행해주세요.
        </div>
      </div>
    );
  }

  // 12주 trend — 과거 done runs 의 mention rate 시계열
  const doneRuns = runs
    .filter((r: any) => (r.status === "complete" || r.status === "done") && r.completedAt)
    .sort((a: any, b: any) => new Date(a.completedAt!).getTime() - new Date(b.completedAt!).getTime());

  return (
    <div className="space-y-4">
      {/* ── Headline + 평가 수준 ─────────────────────── */}
      <section className="rounded-2xl border-2 border-[var(--shell-accent)]/30 bg-gradient-to-br from-[var(--shell-accent)]/8 to-[var(--shell-panel)] p-5">
        <div className="flex items-center gap-2 text-[10px] uppercase tracking-[0.22em] text-[var(--shell-text-soft)]">
          <Sparkles className="h-3.5 w-3.5" /> V4 실측정 결과
        </div>
        {/* Raw Data 엑셀 다운로드는 페이지 상단 '보고서' 버튼으로 통합됨 */}
        <h2 className="mt-1 text-xl font-semibold text-[var(--shell-text)]">{wrd?.headline}</h2>
        {wrd?.overview && (
          <ul className="mt-3 space-y-1 text-xs leading-5 text-[var(--shell-text-muted)]">
            {wrd.overview.map((line: string, i: number) => (
              <li key={i} className="flex items-start gap-1.5">
                <span className="mt-0.5 text-[var(--shell-text-soft)]">•</span>
                <span>{line}</span>
              </li>
            ))}
          </ul>
        )}
        <div className="mt-3 flex flex-wrap items-center gap-2 text-[10px] text-[var(--shell-text-soft)]">
          <span>측정 모델: {analysis.analysisModel}</span>
          <span>·</span>
          <span>분석 시각: {new Date(analysis.generatedAt).toLocaleString()}</span>
        </div>
      </section>

      {/* ── 핵심 지표 카드 4개 ─────────────────────── */}
      <section className="grid grid-cols-2 gap-2.5 md:grid-cols-4">
        <KpiCard
          label="자사 언급률"
          value={`${parseFloat(analysis.brandMentionRate).toFixed(1)}%`}
          sub={`${analysis.brandMentionCount} / ${wrd?.globalEngine?.totalQuestions || "-"}`}
          tone={parseFloat(analysis.brandMentionRate) >= 60 ? "good" : parseFloat(analysis.brandMentionRate) >= 40 ? "warn" : "bad"}
        />
        <KpiCard
          label="1순위 추천률"
          value={`${(((wrd?.mentionPositionHistogram?.["1"] || 0) / (wrd?.globalEngine?.totalQuestions || 1)) * 100).toFixed(1)}%`}
          sub={`${wrd?.mentionPositionHistogram?.["1"] || 0}건`}
          tone="info"
        />
        <KpiCard
          label="GPT 언급률"
          value={`${(analysis.engineBreakdown?.gpt?.rate || 0).toFixed(1)}%`}
          sub={`${analysis.engineBreakdown?.gpt?.count || 0}/${analysis.engineBreakdown?.gpt?.total || 0}`}
          tone="info"
        />
        <KpiCard
          label="Gemini 언급률"
          value={`${(analysis.engineBreakdown?.gemini?.rate || 0).toFixed(1)}%`}
          sub={`${analysis.engineBreakdown?.gemini?.count || 0}/${analysis.engineBreakdown?.gemini?.total || 0}`}
          tone="info"
        />
      </section>

      {/* ── 멘션 순서 분포 + 감성 분포 ─────────────────────── */}
      <section className="grid gap-4 md:grid-cols-2">
        <Card title="멘션 순서 분포">
          <div className="text-[11px] text-[var(--shell-text-muted)]">자사가 답변에서 등장한 순서</div>
          <div className="mt-3 space-y-2">
            {Object.entries(wrd?.mentionPositionHistogram || { "1": 0, "2": 0, "3+": 0 }).map(([rank, cnt]: any) => {
              const total = Object.values(wrd?.mentionPositionHistogram || {}).reduce((s: number, n: any) => s + (Number(n) || 0), 0);
              const pct = total > 0 ? (cnt / total) * 100 : 0;
              const bgColor = rank === "1" ? "bg-emerald-400" : rank === "2" ? "bg-blue-400" : "bg-amber-400";
              return (
                <div key={rank}>
                  <div className="flex items-center justify-between text-[11px]">
                    <span className="font-mono text-[var(--shell-text)]">{rank}순위</span>
                    <span className="text-[var(--shell-text-muted)]">{cnt}건 ({pct.toFixed(1)}%)</span>
                  </div>
                  <div className="mt-1 h-2 overflow-hidden rounded-full bg-[var(--shell-panel-soft)]">
                    <div className={bgColor} style={{ width: `${pct}%`, height: "100%" }} />
                  </div>
                </div>
              );
            })}
          </div>
        </Card>

        <Card title="감성 분포">
          <div className="text-[11px] text-[var(--shell-text-muted)]">
            Claude 분석 (샘플 {((analysis.sentimentBreakdown?.positive || 0) + (analysis.sentimentBreakdown?.neutral || 0) + (analysis.sentimentBreakdown?.negative || 0))}건)
          </div>
          <div className="mt-3 space-y-2">
            {[
              { key: "positive", label: "긍정", color: "bg-emerald-400" },
              { key: "neutral", label: "중립", color: "bg-neutral-400" },
              { key: "negative", label: "부정", color: "bg-red-400" },
            ].map((s) => {
              const cnt = analysis.sentimentBreakdown?.[s.key] || 0;
              const total = (analysis.sentimentBreakdown?.positive || 0) + (analysis.sentimentBreakdown?.neutral || 0) + (analysis.sentimentBreakdown?.negative || 0);
              const pct = total > 0 ? (cnt / total) * 100 : 0;
              return (
                <div key={s.key}>
                  <div className="flex items-center justify-between text-[11px]">
                    <span className="text-[var(--shell-text)]">{s.label}</span>
                    <span className="text-[var(--shell-text-muted)]">{cnt}건 ({pct.toFixed(1)}%)</span>
                  </div>
                  <div className="mt-1 h-2 overflow-hidden rounded-full bg-[var(--shell-panel-soft)]">
                    <div className={s.color} style={{ width: `${pct}%`, height: "100%" }} />
                  </div>
                </div>
              );
            })}
          </div>
        </Card>
      </section>

      {/* ── 쿼리별 성과 ─────────────────────── */}
      {wrd?.queryBreakdown?.length > 0 && (
        <Card title={`쿼리별 성과 (${wrd.queryBreakdown.length})`}>
          <div className="text-[11px] text-[var(--shell-text-muted)]">쿼리별 자사 언급률 · 1순위 추천률 · 카테고리</div>
          <div className="mt-3 overflow-x-auto">
            <table className="w-full min-w-[600px] text-xs">
              <thead>
                <tr className="border-b border-[var(--shell-border)] text-left text-[10px] uppercase tracking-wider text-[var(--shell-text-soft)]">
                  <th className="py-2 pr-2 font-medium">#</th>
                  <th className="py-2 pr-2 font-medium">쿼리</th>
                  <th className="py-2 pr-2 font-medium">카테고리</th>
                  <th className="py-2 pr-2 font-medium text-right">전체</th>
                  <th className="py-2 pr-2 font-medium text-right">GPT</th>
                  <th className="py-2 pr-2 font-medium text-right">Gemini</th>
                  <th className="py-2 font-medium text-right">평균 순위</th>
                </tr>
              </thead>
              <tbody>
                {wrd.queryBreakdown.map((q: any, i: number) => (
                  <tr key={i} className="border-b border-[var(--shell-border)]/50">
                    <td className="py-2.5 pr-2 text-[var(--shell-text-soft)]">Q{q.queryIndex + 1}</td>
                    <td className="py-2.5 pr-2 max-w-[260px] truncate text-[var(--shell-text)]" title={q.queryText}>{q.queryText}</td>
                    <td className="py-2.5 pr-2 text-[10px] text-[var(--shell-text-muted)]">{q.category || "-"}</td>
                    <td className="py-2.5 pr-2 text-right font-mono">{q.brandRate.toFixed(1)}%</td>
                    <td className="py-2.5 pr-2 text-right font-mono text-blue-300">{q.gptRate.toFixed(1)}%</td>
                    <td className="py-2.5 pr-2 text-right font-mono text-emerald-300">{q.geminiRate.toFixed(1)}%</td>
                    <td className="py-2.5 text-right font-mono text-[var(--shell-text-muted)]">
                      {q.avgMentionPosition != null ? q.avgMentionPosition.toFixed(1) : "-"}
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        </Card>
      )}

      {/* ── 경쟁사 비교 ─────────────────────── */}
      {analysis.competitorBreakdown?.length > 0 && (
        <Card title={`경쟁사 멘션 비교 (${analysis.competitorBreakdown.length})`}>
          <div className="text-[11px] text-[var(--shell-text-muted)]">자사 + 경쟁사가 답변에서 함께 언급된 횟수</div>
          <div className="mt-3 space-y-2">
            {/* 자사 행 (비교 기준) */}
            <div>
              <div className="flex items-center justify-between text-[11px]">
                <span className="font-semibold text-emerald-300">{wrd?.brandName || "자사"} (기준)</span>
                <span className="text-[var(--shell-text-muted)]">{analysis.brandMentionCount}회 ({parseFloat(analysis.brandMentionRate).toFixed(1)}%)</span>
              </div>
              <div className="mt-1 h-2.5 overflow-hidden rounded-full bg-[var(--shell-panel-soft)]">
                <div className="bg-emerald-400" style={{ width: `${parseFloat(analysis.brandMentionRate)}%`, height: "100%" }} />
              </div>
            </div>
            {analysis.competitorBreakdown.map((c: any, i: number) => (
              <div key={i}>
                <div className="flex items-center justify-between text-[11px]">
                  <span className="text-[var(--shell-text)]">{c.name}</span>
                  <span className="text-[var(--shell-text-muted)]">{c.count}회 ({c.rate.toFixed(1)}%)</span>
                </div>
                <div className="mt-1 h-2 overflow-hidden rounded-full bg-[var(--shell-panel-soft)]">
                  <div className="bg-blue-400" style={{ width: `${c.rate}%`, height: "100%" }} />
                </div>
              </div>
            ))}
          </div>
        </Card>
      )}

      {/* ── 강점 / 약점 / 중립 ─────────────────────── */}
      <section className="grid gap-4 md:grid-cols-3">
        <PointsCard title="강점" icon={<TrendingUp className="h-3.5 w-3.5" />} tone="emerald" points={analysis.strengths || []} />
        <PointsCard title="약점" icon={<TrendingDown className="h-3.5 w-3.5" />} tone="red" points={analysis.weaknesses || []} />
        <PointsCard title="중립 정보" icon={<MessageSquare className="h-3.5 w-3.5" />} tone="neutral" points={analysis.neutralPoints || []} />
      </section>

      {/* ── 12주 시계열 trend ─────────────────────── */}
      {doneRuns.length >= 2 && (
        <Card title={`측정 시계열 (최근 ${doneRuns.length} 회)`}>
          <div className="text-[11px] text-[var(--shell-text-muted)]">측정마다의 자사 언급률 변화</div>
          <div className="mt-3">
            <TrendChart runs={doneRuns} />
          </div>
        </Card>
      )}

      {/* ── URL 인용 통계 ─────────────────────── */}
      {wrd?.citedUrls && (
        <Card title="출처 URL 인용 통계">
          <div className="text-[11px] text-[var(--shell-text-muted)]">AI 답변이 인용한 출처 URL 의 자사/경쟁사 분포</div>
          <div className="mt-3 grid grid-cols-2 gap-3 sm:grid-cols-4">
            <div className="rounded-lg border border-emerald-500/30 bg-emerald-500/5 p-3">
              <div className="text-[10px] text-emerald-300">자사 도메인 인용</div>
              <div className="mt-1 text-2xl font-semibold text-emerald-200">{wrd.citedUrls.brandCount}</div>
              <div className="text-[10px] text-[var(--shell-text-muted)]">답변 수</div>
            </div>
            <div className="rounded-lg border border-blue-500/30 bg-blue-500/5 p-3">
              <div className="text-[10px] text-blue-300">경쟁사 도메인 인용</div>
              <div className="mt-1 text-2xl font-semibold text-blue-200">{wrd.citedUrls.competitorCount}</div>
              <div className="text-[10px] text-[var(--shell-text-muted)]">답변 수</div>
            </div>
            {Object.entries(wrd.citedUrls.byCompetitor || {}).slice(0, 2).map(([name, cnt]: any) => (
              <div key={name} className="rounded-lg border border-[var(--shell-border)] bg-[var(--shell-panel-soft)] p-3">
                <div className="truncate text-[10px] text-[var(--shell-text-muted)]" title={name}>{name}</div>
                <div className="mt-1 text-2xl font-semibold text-[var(--shell-text)]">{cnt}</div>
                <div className="text-[10px] text-[var(--shell-text-soft)]">답변 수</div>
              </div>
            ))}
          </div>
        </Card>
      )}
    </div>
  );
}

// ─── Helper components ───
function KpiCard({ label, value, sub, tone }: { label: string; value: string; sub?: string; tone: "good" | "warn" | "bad" | "info" }) {
  const t = {
    good: "border-emerald-500/30 bg-emerald-500/5 text-emerald-300",
    warn: "border-amber-500/30 bg-amber-500/5 text-amber-300",
    bad:  "border-red-500/30 bg-red-500/5 text-red-300",
    info: "border-[var(--shell-border)] bg-[var(--shell-panel)] text-[var(--shell-text)]",
  }[tone];
  return (
    <div className={`rounded-xl border p-3 ${t}`}>
      <div className="text-[10px] uppercase tracking-wider opacity-70">{label}</div>
      <div className="mt-1 text-2xl font-semibold">{value}</div>
      {sub && <div className="text-[10px] opacity-70">{sub}</div>}
    </div>
  );
}

function Card({ title, children }: { title: string; children: React.ReactNode }) {
  return (
    <div className="rounded-2xl border border-[var(--shell-border)] bg-[var(--shell-panel)] p-5">
      <div className="text-sm font-semibold text-[var(--shell-text)]">{title}</div>
      {children}
    </div>
  );
}

function PointsCard({ title, icon, tone, points }: {
  title: string;
  icon: React.ReactNode;
  tone: "emerald" | "red" | "neutral";
  points: Array<{ point: string; count: number; examples: string[] }>;
}) {
  const t = {
    emerald: "border-emerald-500/30 bg-emerald-500/5 text-emerald-300",
    red: "border-red-500/30 bg-red-500/5 text-red-300",
    neutral: "border-[var(--shell-border)] bg-[var(--shell-panel-soft)] text-[var(--shell-text-muted)]",
  }[tone];
  return (
    <div className={`rounded-2xl border p-4 ${t}`}>
      <div className="flex items-center gap-1.5 text-sm font-semibold">
        {icon} {title} ({points.length})
      </div>
      {points.length === 0 ? (
        <div className="mt-3 text-[11px] opacity-60">데이터 없음</div>
      ) : (
        <ul className="mt-3 space-y-2">
          {points.slice(0, 5).map((p, i) => (
            <li key={i} className="rounded-lg bg-[var(--shell-panel)]/60 px-2.5 py-2">
              <div className="flex items-center justify-between text-[11px] font-medium text-[var(--shell-text)]">
                <span className="truncate">{p.point}</span>
                <span className="ml-2 shrink-0 text-[var(--shell-text-muted)]">{p.count}회</span>
              </div>
              {p.examples?.[0] && (
                <div className="mt-1 line-clamp-2 text-[10px] text-[var(--shell-text-muted)]">"{p.examples[0]}"</div>
              )}
            </li>
          ))}
        </ul>
      )}
    </div>
  );
}

function TrendChart({ runs }: { runs: any[] }) {
  if (runs.length < 2) return null;

  const width = 720;
  const height = 140;
  const padding = { top: 8, right: 50, bottom: 22, left: 30 };
  const innerW = width - padding.left - padding.right;
  const innerH = height - padding.top - padding.bottom;

  const rates = runs.map((r) => {
    // brand mention rate — analysis 가 없으면 progress 기반으로 계산은 어려움 → run.completedCalls/totalCalls 의 자사 비율은 알 수 없으니 보정값 사용
    // brand_mention_rate 는 dk_v3_analysis 에 있는데 listRuns 는 run 정보만 반환함 → 일단 progress 만 표시
    // TODO: backend 에서 listRuns 에 analysis brandMentionRate 도 같이 반환하면 더 정확
    return 0; // placeholder
  });

  // 단순화: run 갯수만 표시하는 시계열 — 향후 listRuns 응답에 brandMentionRate 포함하도록 backend 보강 필요
  const xFor = (i: number) => padding.left + (i / (runs.length - 1)) * innerW;
  const yFor = (v: number) => padding.top + (1 - v / 100) * innerH;

  // Render — but rates are 0 unless we fetch each analysis. So show as run-count timeline only.
  return (
    <div className="w-full overflow-x-auto">
      <svg viewBox={`0 0 ${width} ${height}`} className="w-full" preserveAspectRatio="xMidYMid meet">
        {[0, 25, 50, 75, 100].map((y) => (
          <g key={y}>
            <line x1={padding.left} x2={width - padding.right} y1={yFor(y)} y2={yFor(y)} stroke="currentColor" strokeOpacity={0.08} strokeDasharray="2 4" />
            <text x={padding.left - 6} y={yFor(y) + 3} textAnchor="end" className="fill-[var(--shell-text-soft)] text-[9px]">{y}</text>
          </g>
        ))}
        {/* Run 들의 trigger 마커 (월요일 자동 / 즉시) */}
        {runs.map((r, i) => (
          <g key={i}>
            <circle cx={xFor(i)} cy={yFor(50)} r="3" fill={r.triggerType === "scheduled" ? "#34d399" : "#60a5fa"} />
            <text x={xFor(i)} y={height - 6} textAnchor="middle" className="fill-[var(--shell-text-soft)] text-[8px]">
              {new Date(r.completedAt!).toLocaleDateString().slice(5)}
            </text>
          </g>
        ))}
      </svg>
      <div className="mt-1 flex items-center gap-3 text-[10px] text-[var(--shell-text-soft)]">
        <span className="flex items-center gap-1"><span className="h-2 w-2 rounded-full bg-emerald-400" /> 자동 (주 1회)</span>
        <span className="flex items-center gap-1"><span className="h-2 w-2 rounded-full bg-blue-400" /> 즉시 측정</span>
        <span className="ml-auto">총 {runs.length}회</span>
      </div>
    </div>
  );
}
