import { createContext, useContext, useState, useCallback, type ReactNode } from "react";
import { ko, type LocaleKey } from "./locales/ko";
import { en } from "./locales/en";

type Locale = "ko" | "en";

const locales: Record<Locale, Record<LocaleKey, string>> = { ko, en };

interface I18nContextValue {
  locale: Locale;
  setLocale: (l: Locale) => void;
  t: (key: LocaleKey, vars?: Record<string, string | number>) => string;
}

const I18nContext = createContext<I18nContextValue>({
  locale: "ko",
  setLocale: () => {},
  t: (key) => key,
});

export function I18nProvider({ children }: { children: ReactNode }) {
  const [locale, setLocale] = useState<Locale>(
    () => (localStorage.getItem("dk-locale") as Locale) || "ko",
  );

  const changeLocale = useCallback((l: Locale) => {
    setLocale(l);
    localStorage.setItem("dk-locale", l);
  }, []);

  const t = useCallback(
    (key: LocaleKey, vars?: Record<string, string | number>) => {
      let str = locales[locale][key] ?? key;
      if (vars) {
        for (const [k, v] of Object.entries(vars)) {
          str = str.replace(new RegExp(`\\{${k}\\}`, "g"), String(v));
        }
      }
      return str;
    },
    [locale],
  );

  return (
    <I18nContext.Provider value={{ locale, setLocale: changeLocale, t }}>
      {children}
    </I18nContext.Provider>
  );
}

export function useI18n() {
  return useContext(I18nContext);
}

export type { Locale, LocaleKey };
