export const CACHE_KEYS = {
  USER_AUTHENTICATED: 'userAuthenticated',
  APP_LANG: 'app.lang',
  GLOBAL_CONFIG_CACHE: 'global_config_cache',
  SELECTED_BOARD_ID: 'selected_board_id',
  SELECTED_MENU_PATH: 'selected_menu_path',
  SIDEBAR_COLLAPSED_GROUPS: 'sidebar_collapsed_groups',
} as const;

export type CacheKey = typeof CACHE_KEYS[keyof typeof CACHE_KEYS];

export const TTL = {
  HOUR: 60 * 60 * 1000,
  DAY: 24 * 60 * 60 * 1000,
  WEEK: 7 * 24 * 60 * 60 * 1000,
  MONTH: 30 * 24 * 60 * 60 * 1000,
  TWO_MONTHS: 60 * 24 * 60 * 60 * 1000,
  YEAR: 365 * 24 * 60 * 60 * 1000,
} as const;

export const TTL_CONFIGS: Record<CacheKey, number | null> = {
  [CACHE_KEYS.USER_AUTHENTICATED]: null,
  [CACHE_KEYS.APP_LANG]: null,
  [CACHE_KEYS.GLOBAL_CONFIG_CACHE]: TTL.HOUR,
  [CACHE_KEYS.SELECTED_BOARD_ID]: null,
  [CACHE_KEYS.SELECTED_MENU_PATH]: null,
  [CACHE_KEYS.SIDEBAR_COLLAPSED_GROUPS]: null,
};
