import { useEffect, useMemo, useState } from "react";
import { useParams } from "react-router-dom";
import {
  AlertTriangle,
  Lightbulb,
  Shield,
  ShieldAlert,
  ShieldCheck,
  Swords,
  Target,
} from "lucide-react";
import { listGeoProbesV2, listCompetitorsV2, subscribeBoard, subscribeInsights } from "../../../db/boards";
import type { Board, CompetitorV2Doc, GeoProbeV2Doc, InsightDoc } from "../../../db/collections";
import { MetricCard } from "../../../components/shared/MetricCard";
import { EmptyState } from "../../../components/shared/EmptyState";
import { InsightSection } from "../../../components/shared/InsightSection";
import { DataQualityBadge } from "../../../components/shared/DataQualityBadge";
import { OpenInsightsList } from "../../../components/shared/OpenInsightsList";

type Probe = GeoProbeV2Doc & { id: string };

interface RedAttack {
  probe: Probe;
  competitor: string;
}

interface BlueWin {
  probe: Probe;
  context?: string;
}

export function RedBlueTeamInsight() {
  const { id } = useParams<{ id: string }>();
  const [probes, setProbes] = useState<Probe[]>([]);
  const [competitors, setCompetitors] = useState<CompetitorV2Doc[]>([]);
  const [board, setBoard] = useState<Board | null>(null);
  const [liveInsights, setLiveInsights] = useState<InsightDoc[]>([]);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    if (!id) return;
    setLoading(true);
    const unsubBoard = subscribeBoard(id, setBoard);
    const unsubIns = subscribeInsights(id, setLiveInsights, { type: "red_team" });
    Promise.all([
      listGeoProbesV2(id).catch(() => []),
      listCompetitorsV2(id).catch(() => []),
    ]).then(([p, c]) => {
      setProbes(p);
      setCompetitors(c);
      setLoading(false);
    });
    return () => {
      unsubBoard();
      unsubIns();
    };
  }, [id]);

  const competitorNames = useMemo(
    () =>
      competitors
        .map((c) => (c as unknown as { name?: string; domain?: string }).name || (c as unknown as { domain?: string }).domain || "")
        .filter(Boolean)
        .map((n) => n.toLowerCase()),
    [competitors],
  );

  const { redAttacks, blueWins, neutralGaps } = useMemo(() => {
    const red: RedAttack[] = [];
    const blue: BlueWin[] = [];
    const gaps: Probe[] = [];

    for (const probe of probes) {
      if (probe.status !== "completed") continue;
      const mentionedUs = probe.ourSiteMentioned;
      const answer = (probe.answer ?? "").toLowerCase();
      const matchedCompetitor = competitorNames.find((c) => c && answer.includes(c));

      if (mentionedUs) {
        blue.push({ probe, context: probe.ourMentionContext });
      } else if (matchedCompetitor) {
        red.push({ probe, competitor: matchedCompetitor });
      } else {
        gaps.push(probe);
      }
    }

    return { redAttacks: red, blueWins: blue, neutralGaps: gaps };
  }, [probes, competitorNames]);

  const totalProbes = probes.filter((p) => p.status === "completed").length;
  const attackRate = totalProbes > 0 ? Math.round((redAttacks.length / totalProbes) * 100) : 0;
  const winRate = totalProbes > 0 ? Math.round((blueWins.length / totalProbes) * 100) : 0;

  const topAttackCategories = useMemo(() => {
    const map = new Map<string, number>();
    for (const a of redAttacks) {
      const cat = a.probe.category || "other";
      map.set(cat, (map.get(cat) ?? 0) + 1);
    }
    return Array.from(map.entries())
      .map(([category, count]) => ({ category, count }))
      .sort((a, b) => b.count - a.count);
  }, [redAttacks]);

  const diagnosis = useMemo(() => {
    const items: Array<{ severity: "high" | "medium" | "low"; title: string; detail: string }> = [];
    if (totalProbes === 0) {
      items.push({ severity: "medium", title: "No completed probes", detail: "Run GEO Probe to surface competitor attacks and defensive wins." });
      return items;
    }
    if (attackRate >= 50) {
      items.push({ severity: "high", title: `High attack rate (${attackRate}%)`, detail: "Competitors dominate AI answers for your topics. Strengthen authority and citations." });
    } else if (attackRate >= 25) {
      items.push({ severity: "medium", title: `Moderate competitor attack rate (${attackRate}%)`, detail: "Address queries where competitors are surfacing in AI answers." });
    }
    if (winRate < 20 && totalProbes >= 5) {
      items.push({ severity: "medium", title: `Low defensive win rate (${winRate}%)`, detail: "Your brand appears in few AI answers. Improve visibility and E-E-A-T signals." });
    }
    if (neutralGaps.length > totalProbes * 0.3) {
      items.push({
        severity: "medium",
        title: `${neutralGaps.length} unclaimed queries`,
        detail: "Many queries mention neither you nor known competitors. These are opportunities to own the narrative.",
      });
    }
    return items;
  }, [totalProbes, attackRate, winRate, neutralGaps.length]);

  const dataQuality = useMemo(() => {
    const signals = [
      { name: "GEO probes", ok: probes.length > 0 },
      { name: "Completed probes", ok: totalProbes > 0 },
      { name: "Competitor list", ok: competitors.length > 0 },
      { name: "Attack/defense classification", ok: redAttacks.length + blueWins.length > 0 },
    ];
    const okCount = signals.filter((s) => s.ok).length;
    const score = Math.round((okCount / signals.length) * 100);
    const status: "ok" | "warning" | "degraded" | "invalid" =
      score >= 80 ? "ok" : score >= 50 ? "warning" : score > 0 ? "degraded" : "invalid";
    const notes = signals.filter((s) => !s.ok).map((s) => `${s.name} not available`);
    return { score, status, notes };
  }, [probes.length, totalProbes, competitors.length, redAttacks.length, blueWins.length]);

  if (loading) {
    return (
      <div className="flex min-h-[30vh] items-center justify-center text-sm text-[var(--shell-text-muted)]">
        불러오는 중...
      </div>
    );
  }

  if (probes.length === 0 && competitors.length === 0) {
    return (
      <EmptyState
        icon={ShieldAlert}
        title="No adversarial data yet"
        description="GEO Probe를 실행하고 경쟁사를 추가하면 Red(공격) 및 Blue(방어) 인텔리전스를 생성합니다."
      />
    );
  }

  const _unusedBoard = board; // keep subscribeBoard warm for future fields
  void _unusedBoard;

  return (
    <div className="space-y-6">
      <div className="grid gap-4 sm:grid-cols-2 lg:grid-cols-4">
        <MetricCard icon={Swords} label="Red · Attacks" value={String(redAttacks.length)} color="text-rose-500" />
        <MetricCard icon={Shield} label="Blue · Wins" value={String(blueWins.length)} color="text-emerald-600" />
        <MetricCard icon={Target} label="Unclaimed" value={String(neutralGaps.length)} color="text-amber-500" />
        <MetricCard icon={ShieldCheck} label="Win Rate" value={`${winRate}%`} color="text-blue-600" />
      </div>

      <DataQualityBadge score={dataQuality.score} status={dataQuality.status} notes={dataQuality.notes} />

      <InsightSection title="Red Team · Competitor Attacks" icon={Swords} count={redAttacks.length} defaultOpen>
        {redAttacks.length > 0 ? (
          <div className="space-y-2">
            {redAttacks.slice(0, 10).map((a) => (
              <div key={a.probe.id} className="rounded-xl border border-rose-500/20 bg-rose-500/5 px-4 py-3">
                <div className="flex items-start justify-between gap-3">
                  <div className="min-w-0 flex-1">
                    <p className="text-sm font-medium text-[var(--shell-text)]">{a.probe.question}</p>
                    <div className="mt-1 flex flex-wrap items-center gap-2 text-[11px]">
                      <span className="rounded-full bg-rose-500/10 px-2 py-0.5 font-medium text-rose-500">
                        {a.competitor}
                      </span>
                      <span className="text-[var(--shell-text-muted)]">
                        {a.probe.engine} · {a.probe.category}
                      </span>
                    </div>
                  </div>
                </div>
                {a.probe.answer && (
                  <p className="mt-2 line-clamp-2 text-xs text-[var(--shell-text-muted)]">
                    {a.probe.answer}
                  </p>
                )}
              </div>
            ))}
          </div>
        ) : (
          <p className="text-sm text-emerald-600">No competitor attacks detected in probe data.</p>
        )}
      </InsightSection>

      <InsightSection title="Blue Team · Defensive Wins" icon={Shield} count={blueWins.length} defaultOpen>
        {blueWins.length > 0 ? (
          <div className="space-y-2">
            {blueWins.slice(0, 10).map((w) => (
              <div key={w.probe.id} className="rounded-xl border border-emerald-500/20 bg-emerald-500/5 px-4 py-3">
                <p className="text-sm font-medium text-[var(--shell-text)]">{w.probe.question}</p>
                <div className="mt-1 flex flex-wrap items-center gap-2 text-[11px] text-[var(--shell-text-muted)]">
                  <span>{w.probe.engine}</span>
                  <span>·</span>
                  <span>{w.probe.category}</span>
                </div>
                {w.context && (
                  <p className="mt-2 line-clamp-2 text-xs text-[var(--shell-text-muted)]">{w.context}</p>
                )}
              </div>
            ))}
          </div>
        ) : (
          <p className="text-sm text-[var(--shell-text-muted)]">No brand mentions found yet. Improve authority and entity signals.</p>
        )}
      </InsightSection>

      {topAttackCategories.length > 0 && (
        <InsightSection title="Attack Surface by Category" icon={Target} count={topAttackCategories.length} defaultOpen={false}>
          <div className="grid gap-2 sm:grid-cols-2 lg:grid-cols-3">
            {topAttackCategories.map((c) => (
              <div key={c.category} className="flex items-center justify-between rounded-xl border border-[var(--shell-border)] bg-[var(--shell-panel-soft)] px-4 py-3">
                <span className="text-sm font-medium capitalize text-[var(--shell-text)]">{c.category}</span>
                <span className="text-sm font-semibold text-rose-500">{c.count}</span>
              </div>
            ))}
          </div>
        </InsightSection>
      )}

      {neutralGaps.length > 0 && (
        <InsightSection title="Unclaimed Queries" icon={Target} count={neutralGaps.length} defaultOpen={false}>
          <div className="space-y-2">
            {neutralGaps.slice(0, 10).map((p) => (
              <div key={p.id} className="rounded-xl border border-[var(--shell-border)] bg-[var(--shell-panel-soft)] px-4 py-3">
                <p className="text-sm text-[var(--shell-text)]">{p.question}</p>
                <p className="mt-1 text-[11px] text-[var(--shell-text-muted)]">
                  {p.engine} · {p.category}
                </p>
              </div>
            ))}
          </div>
        </InsightSection>
      )}

      <InsightSection
        title="Open Insights"
        icon={Lightbulb}
        count={liveInsights.filter((i) => i.status !== "resolved" && i.status !== "ignored").length}
        defaultOpen
      >
        <OpenInsightsList insights={liveInsights} />
      </InsightSection>

      <InsightSection title="Diagnosis" icon={AlertTriangle} count={diagnosis.length} defaultOpen={diagnosis.length > 0}>
        {diagnosis.length > 0 ? (
          <div className="space-y-2">
            {diagnosis.map((item, i) => (
              <div key={i} className="flex items-start gap-3 rounded-xl border border-[var(--shell-border)] bg-[var(--shell-panel-soft)] px-4 py-3">
                <SeverityDot severity={item.severity} />
                <div className="min-w-0 flex-1">
                  <p className="text-sm font-medium text-[var(--shell-text)]">{item.title}</p>
                  <p className="mt-0.5 text-xs text-[var(--shell-text-muted)]">{item.detail}</p>
                </div>
              </div>
            ))}
          </div>
        ) : (
          <p className="text-sm text-emerald-600">Red/Blue posture looks balanced.</p>
        )}
      </InsightSection>
    </div>
  );
}

function SeverityDot({ severity }: { severity: "high" | "medium" | "low" }) {
  const color = severity === "high" ? "bg-rose-500" : severity === "medium" ? "bg-amber-500" : "bg-blue-500";
  return <span className={`mt-1.5 inline-block h-2 w-2 shrink-0 rounded-full ${color}`} />;
}
