/** 작은 KPI 카드 — 라벨 + 큰 숫자 + 보조 텍스트. */
function KpiCard({ label, value, suffix, hint, tone }: { label: string; value: number | string; suffix?: string; hint?: string; tone?: "blue" | "green" | "amber" | "red" }) {
  const toneColor =
    tone === "blue" ? "text-blue-300" :
    tone === "green" ? "text-emerald-300" :
    tone === "amber" ? "text-amber-300" :
    tone === "red" ? "text-red-300" :
    "text-[var(--shell-text)]";
  return (
    <div className="rounded-2xl border border-[var(--shell-border)] bg-[var(--shell-panel)] px-5 py-4">
      <div className="text-[11px] uppercase tracking-[0.18em] text-[var(--shell-text-soft)]">{label}</div>
      <div className="mt-2 flex items-baseline gap-1">
        <div className={`text-3xl font-semibold ${toneColor}`}>{value}</div>
        {suffix && <div className="text-sm text-[var(--shell-text-muted)]">{suffix}</div>}
      </div>
      {hint && <div className="mt-1 text-[11px] text-[var(--shell-text-muted)]">{hint}</div>}
    </div>
  );
}

/** priority 문자열 → P0/P1/P2 매핑. */
function priorityToTier(priority: string): "P0" | "P1" | "P2" {
  const p = (priority || "").toLowerCase();
  if (p === "urgent" || p === "critical" || p === "high") return "P0";
  if (p === "medium" || p === "p1") return "P1";
  return "P2";
}

function tierLabel(tier: "P0" | "P1" | "P2"): string {
  if (tier === "P0") return "P0 · 즉시 (1-2주)";
  if (tier === "P1") return "P1 · 단기 (1개월)";
  return "P2 · 중기 (분기)";
}

function deltaIcon(delta: number) {
  if (delta > 0) return <ArrowUpRight className="h-4 w-4 text-emerald-400" />;
  if (delta < 0) return <ArrowDownRight className="h-4 w-4 text-red-400" />;
  return <Minus className="h-4 w-4 text-neutral-400" />;
}

function getGenericSampleCount(generic: any): number {
  if (!generic) return 0;
  const explicit = Number(generic.sampleCount ?? generic.totalQuestions ?? 0);
  const engineTotal = (generic.engineBreakdown || []).reduce((sum: number, row: any) => sum + Number(row.totalQuestions || 0), 0);
  return Math.max(explicit, engineTotal);
}

function hasGenericMentionData(generic: any): boolean {
  return !!generic?.hasMentionData || getGenericSampleCount(generic) > 0;
}

function formatMeasurementFrequency(frequency?: string | null): string {
  if (frequency === "daily") return "매일";
  if (frequency === "weekly") return "매주";
  if (frequency === "biweekly") return "격주";
  if (frequency === "monthly") return "매월";
  return "미설정";
}

function formatMeasurementDate(value?: string | null): string | null {
  if (!value) return null;
  const date = new Date(value);
  if (Number.isNaN(date.getTime())) return null;
  return date.toLocaleString("ko-KR", {
    month: "2-digit",
    day: "2-digit",
    hour: "2-digit",
    minute: "2-digit",
  });
}

export function PortalV3Dashboard() {
  const { id } = useParams<{ id: string }>();
  const { data, isLoading } = useQuery({
    queryKey: ["portalV3", "dashboard", id],
    queryFn: () => dashboardApi.get(id!),
    enabled: !!id,
    staleTime: 30_000,
  });

  const { data: snapshotsData } = useQuery({
    queryKey: ["portalV3", "trend-snapshots", id],
    queryFn: () => trendApi.listSnapshots(id!),
    enabled: !!id,
    staleTime: 60_000,
  });

  const snapshots = snapshotsData?.snapshots || [];
  const weekDelta = computeWeekDelta(snapshots);

  // 점수 계산 — AiAnswers compositeScore 의 핵심 4개 카테고리를 단순화 (100점 만점).
  const scores = useMemo(() => {
    const exec = data?.executiveSummary;
    if (!exec) return null;

    // 1. 웹사이트 (30점) — siteHealth.score (0~100) 의 30%.
    const siteScore = exec.siteHealth?.score ?? 0;
    const websiteScore = Math.round((siteScore / 100) * 30);

    // 2. GEO 가시성 (30점) — mentionRate(0~100) 의 30%.
    const hasGeoData = hasGenericMentionData(exec.genericEngine);
    const hasExposureData = !!exec.genericEngine?.hasExposureData;
    const mentionRate = exec.genericEngine?.mentionRate ?? 0;
    const exposureRate = exec.genericEngine?.exposureRate ?? 0;
    const geoScore = hasGeoData ? Math.round((mentionRate / 100) * 30) : 0;

    // 3. 키워드 (20점) — google + naver 키워드 합산 (max 20).
    const googleKw = (exec.keywordClouds?.google || []).length;
    const naverKw = (exec.keywordClouds?.naver || []).length;
    const keywordScore = Math.min(googleKw + naverKw, 20);

    // 4. 외부 신뢰성 (20점) — externalSignals.trustScore(0~100) 의 20%.
    const trustScore = exec.externalSignals?.trustScore ?? 0;
    const externalScore = Math.round((trustScore / 100) * 20);

    const total = websiteScore + geoScore + keywordScore + externalScore;

    return {
      total,
      websiteScore,
      websiteMax: 30,
      geoScore,
      geoMax: 30,
      keywordScore,
      keywordMax: 20,
      externalScore,
      externalMax: 20,
      hasGeoData,
      hasExposureData,
      genericSampleCount: getGenericSampleCount(exec.genericEngine),
      genericSource: exec.genericEngine?.source,
      mentionRate,
      exposureRate,
      googleKw,
      naverKw,
      trustScore,
      siteScore,
    };
  }, [data]);

  // 이번 주 주요 변화 — activity 피드에서 최근 항목 추려옴 (간단화).
  const weeklyHighlights = useMemo(() => {
    if (!data?.activity) return [];
    return data.activity.slice(0, 3).map((a) => {
      const detail = a.details as any;
      return {
        text: detail?.summary || a.action || a.entityType,
        when: a.createdAt,
      };
    });
  }, [data]);

  const recommendedActions = data?.executiveSummary?.nextActions?.recommended || [];

  return (
    <>
      {id && <HeaderDiagnosticButton boardId={id} title="Dashboard Diagnostics" runner={runDashboardDiagnostics} />}
      <div className="mx-auto max-w-6xl space-y-6 px-4 py-6">
        <header>
          <div className="text-xs uppercase tracking-[0.28em] text-[var(--shell-text-soft)]">Client / Dashboard</div>
          <h1 className="mt-2 text-3xl font-semibold tracking-tight text-[var(--shell-text)]">종합 현황</h1>
          <p className="mt-2 text-sm text-[var(--shell-text-muted)]">
            ChatGPT·Gemini 가 우리 브랜드를 답변에서 얼마나 자주 언급하는지 + 액션 진행 + 추천 + 적중률을 한눈에 확인합니다.
          </p>
        </header>

        {/* ★ V3 실데이터 통합 카드 — 측정 / 액션 / 추천 / 적중률 한방 표시 */}
        <V3RealDashboardCard />
      </div>
    </>
  );
}
