import { type ComponentType, useEffect, useState } from "react";
import {
  BarChart3, Building2, CalendarCheck, ChevronDown, ChevronRight, FolderInput, Gauge,
  Home, Lightbulb, LineChart, Search, SearchCode, Settings, Sparkles,
  Terminal, TrendingUp, Users, Zap,
} from "lucide-react";
import { NavLink, useLocation, useNavigate, useParams } from "react-router-dom";
import { useShellPreferences } from "./ShellPreferences";
import { listBoards, subscribeBoard } from "../db/boards";
import type { Board } from "../db/collections";
import { useRunSteps, type StepStatusMap } from "../hooks/useRunSteps";
import { CACHE_KEYS, LocalCache } from "../contexts/LocalCacheContext";
import { useAuth } from "../contexts/AuthContext";

type NavItem = {
  label: string;
  path: string;
  icon: ComponentType<{ className?: string }>;
  badgeKey?: string;
};

type NavGroup = {
  section: string;
  items: NavItem[];
};

const navGroups: NavGroup[] = [
  {
    section: "Portal v3",
    items: [
      { label: "Dashboard", icon: BarChart3, path: "/portal-v3" },
      { label: "고객 인풋", icon: FolderInput, path: "/portal-v3/input" },
      { label: "웹사이트 분석", icon: Gauge, path: "/portal-v3/website" },
      { label: "AI 검색 결과 분석", icon: Search, path: "/portal-v3/ai-search" },
      { label: "AI 검색 결과 개선 방향", icon: Sparkles, path: "/portal-v3/improvement-plan" },
      { label: "액션 진행일정", icon: CalendarCheck, path: "/portal-v3/timeline" },
      { label: "분석 보고서", icon: LineChart, path: "/portal-v3/report" },
    ],
  },
  {
    section: "Workspace",
    items: [
      { label: "Home", icon: Home, path: "/workspace" },
      { label: "Insights", icon: Lightbulb, path: "/workspace/insights" },
      { label: "Actions", icon: Zap, path: "/workspace/actions" },
      { label: "Performance", icon: TrendingUp, path: "/workspace/performance" },
      { label: "Operations", icon: Terminal, path: "/workspace/operations" },
      { label: "Assets", icon: Building2, path: "/workspace/assets" },
      { label: "Data Inspector", icon: SearchCode, path: "/workspace/data-inspector" },
      { label: "Settings", icon: Settings, path: "/workspace/settings" },
    ],
  },
];

function computeBadges(
  board: Board | null,
  steps: StepStatusMap,
): Record<string, { label: string; tone: "live" | "count" }> {
  const result: Record<string, { label: string; tone: "live" | "count" }> = {};
  if (!board) return result;

  const kwCount = board.rawKeywords?.length || (board.naverKeywords as any)?.topKeywords?.length || 0;
  if (kwCount > 0) result.queries = { label: `+${Math.min(kwCount, 99)}`, tone: "count" };

  const pendingSteps = Object.values(steps).filter((s) => s === "pending" || s === "running").length;
  if (pendingSteps > 0) result.jobs = { label: String(pendingSteps), tone: "count" };

  return result;
}

export function Sidebar() {
  const { id } = useParams<{ id: string }>();
  const location = useLocation();
  const navigate = useNavigate();
  const { sidebarCollapsed } = useShellPreferences();
  const { user } = useAuth();
  const base = `/board/${id}`;
  const [board, setBoard] = useState<Board | null>(null);
  const [projectSwitcherOpen, setProjectSwitcherOpen] = useState(false);
  const [allBoards, setAllBoards] = useState<Board[]>([]);

  useEffect(() => {
    if (!id) return;
    void LocalCache.setString(CACHE_KEYS.SELECTED_BOARD_ID, id);
    return subscribeBoard(id, setBoard);
  }, [id]);

  useEffect(() => {
    if (!user?.uid) return;
    listBoards(user.uid).then(setAllBoards).catch(() => {});
  }, [user?.uid]);

  const { steps } = useRunSteps(id);
  const badges = computeBadges(board, steps);

  const [collapsedGroups, setCollapsedGroups] = useState<Record<string, boolean>>({});

  useEffect(() => {
    let cancelled = false;
    (async () => {
      const saved = await LocalCache.getObject<Record<string, boolean>>(CACHE_KEYS.SIDEBAR_COLLAPSED_GROUPS);
      if (!cancelled && saved) setCollapsedGroups(saved);
    })();
    return () => { cancelled = true; };
  }, []);

  const toggleGroup = (section: string) => {
    setCollapsedGroups((prev) => {
      const next = { ...prev, [section]: !prev[section] };
      void LocalCache.setObject(CACHE_KEYS.SIDEBAR_COLLAPSED_GROUPS, next);
      return next;
    });
  };

  return (
    <aside
      className={`shell-transition sticky top-0 flex h-screen shrink-0 flex-col border-r border-[var(--shell-border)] bg-[var(--shell-sidebar)] ${
        sidebarCollapsed ? "w-[92px]" : "w-[300px]"
      }`}
    >
      <div className={`shell-transition border-b border-[var(--shell-border)] ${sidebarCollapsed ? "px-3 py-4" : "px-5 py-5"}`}>
        <div className={`flex items-center ${sidebarCollapsed ? "justify-center" : "gap-4"}`}>
          <div className="grid h-14 w-14 shrink-0 place-items-center rounded-2xl bg-[linear-gradient(135deg,#5B7CFF_0%,#7D5CFF_100%)] text-2xl font-semibold text-white shadow-[0_16px_32px_rgba(91,124,255,0.28)]">
            G
          </div>
          {!sidebarCollapsed && (
            <div className="min-w-0">
              <div className="truncate text-[18px] font-semibold tracking-[-0.04em] text-[var(--shell-text)]">GEO Insight</div>
              <div className="mt-1 text-sm text-[var(--shell-accent)]">v2.0</div>
            </div>
          )}
        </div>

        {!sidebarCollapsed && (
          <div className="mt-5 rounded-3xl border border-[var(--shell-border)] bg-[var(--shell-panel-soft)] px-4 py-4">
            <div className="flex items-start justify-between gap-3">
              <div className="min-w-0">
                <div className="truncate text-lg font-semibold text-[var(--shell-text)]">{board?.siteName || "Project"}</div>
                <div className="mt-1 truncate text-sm text-[var(--shell-text-muted)]">
                  {(() => {
                    const industry = board?.siteInfo?.industry;
                    const domain = board?.domain || "도메인 연결 대기";
                    return industry ? `${industry} · ${domain}` : domain;
                  })()}
                </div>
              </div>
              {allBoards.length > 1 && (
                <button
                  type="button"
                  onClick={() => setProjectSwitcherOpen((prev) => !prev)}
                  className="mt-1 shrink-0 rounded-lg p-1 text-[var(--shell-text-muted)] transition hover:bg-[var(--shell-panel-strong)] hover:text-[var(--shell-text)]"
                >
                  {projectSwitcherOpen ? <ChevronDown className="h-4 w-4" /> : <ChevronRight className="h-4 w-4" />}
                </button>
              )}
            </div>
            {projectSwitcherOpen && allBoards.length > 1 && (
              <div className="mt-3 space-y-1 border-t border-[var(--shell-border)] pt-3">
                {allBoards
                  .filter((b) => b.id !== id)
                  .map((b) => (
                    <button
                      key={b.id}
                      type="button"
                      onClick={() => {
                        setProjectSwitcherOpen(false);
                        void LocalCache.setString(CACHE_KEYS.SELECTED_BOARD_ID, b.id);
                        navigate(`/board/${b.id}/portal-v3`);
                      }}
                      className="flex w-full items-center gap-2 rounded-xl px-3 py-2 text-left text-sm text-[var(--shell-text-muted)] transition hover:bg-[var(--shell-panel-strong)] hover:text-[var(--shell-text)]"
                    >
                      <div className="min-w-0 flex-1">
                        <div className="truncate font-medium">{b.siteName || b.domain}</div>
                        <div className="truncate text-xs text-[var(--shell-text-soft)]">{b.domain}</div>
                      </div>
                    </button>
                  ))}
              </div>
            )}
          </div>
        )}
      </div>

      <nav className={`flex-1 space-y-6 overflow-y-auto ${sidebarCollapsed ? "px-2 py-4" : "px-4 py-5"}`}>
        {navGroups.map((group) => {
          const isGroupCollapsed = !sidebarCollapsed && !!collapsedGroups[group.section];
          return (
            <div key={group.section}>
              {!sidebarCollapsed && (
                <button
                  type="button"
                  onClick={() => toggleGroup(group.section)}
                  className="flex w-full items-center justify-between gap-2 rounded-lg px-3 pb-2 pt-1 text-[11px] font-semibold uppercase tracking-[0.24em] text-[var(--shell-text-soft)] transition hover:text-[var(--shell-text)]"
                >
                  <span>{group.section}</span>
                  <ChevronDown
                    className={`h-3.5 w-3.5 shrink-0 transition-transform ${isGroupCollapsed ? "-rotate-90" : ""}`}
                  />
                </button>
              )}
              {!isGroupCollapsed && (
              <div className="space-y-1.5">
                  {group.items.map((item) => {
                    const href = `${base}${item.path}`;
                    const isExact = item.path === "" || item.path === "/workspace" || item.path === "/portal-v3";
                    const isActive = isExact
                      ? location.pathname === href
                      : location.pathname === href || location.pathname.startsWith(href + "/");
                    const Icon = item.icon;
                    const badge = item.badgeKey ? badges[item.badgeKey] : undefined;

                    return (
                      <NavLink
                        key={`${group.section}-${item.label}`}
                        to={href}
                        end={item.path === ""}
                        onClick={() => { void LocalCache.setString(CACHE_KEYS.SELECTED_MENU_PATH, item.path); }}
                        title={sidebarCollapsed ? item.label : undefined}
                        className={`shell-transition relative flex items-center rounded-2xl border px-3 py-3 ${
                          sidebarCollapsed ? "justify-center" : "gap-3"
                        } ${
                          isActive
                            ? "border-[var(--shell-accent)] bg-[var(--shell-accent-soft)] text-[var(--shell-accent)]"
                            : "border-transparent text-[var(--shell-text-muted)] hover:border-[var(--shell-border)] hover:bg-[var(--shell-panel-soft)] hover:text-[var(--shell-text)]"
                        }`}
                      >
                        <Icon className={`h-4 w-4 shrink-0 ${isActive ? "text-[var(--shell-accent)]" : "text-[var(--shell-text-soft)]"}`} />
                        {!sidebarCollapsed && <span className="min-w-0 flex-1 truncate text-base font-medium">{item.label}</span>}
                        {badge && (
                          sidebarCollapsed ? (
                            <span className={`absolute -right-1 -top-1 grid h-4 min-w-[16px] place-items-center rounded-full px-0.5 text-[8px] font-bold ${
                              badge.tone === "live"
                                ? "bg-[var(--shell-accent)] text-white"
                                : "bg-[var(--shell-panel-strong)] text-[var(--shell-text-muted)]"
                            }`}>{badge.label}</span>
                          ) : (
                            <span className={`ml-auto shrink-0 rounded-full px-2 py-0.5 text-[10px] font-medium ${
                              badge.tone === "live"
                                ? "bg-[color-mix(in_srgb,var(--shell-accent)_14%,transparent)] text-[var(--shell-accent)]"
                                : "bg-[var(--shell-panel-strong)] text-[var(--shell-text-muted)]"
                            }`}>{badge.label}</span>
                          )
                        )}
                      </NavLink>
                    );
                  })}
                </div>
              )}
            </div>
          );
        })}
      </nav>

      <div className={`mt-auto border-t border-[var(--shell-border)] ${sidebarCollapsed ? "px-2 py-4" : "px-4 py-4"}`}>
        <NavLink
          to="/"
          title="Projects"
          onClick={() => {
            void LocalCache.remove(CACHE_KEYS.SELECTED_BOARD_ID);
            void LocalCache.remove(CACHE_KEYS.SELECTED_MENU_PATH);
          }}
          className={`shell-transition flex items-center rounded-2xl border border-transparent px-3 py-3 text-sm text-[var(--shell-text-muted)] hover:border-[var(--shell-border)] hover:bg-[var(--shell-panel-soft)] hover:text-[var(--shell-text)] ${
            sidebarCollapsed ? "justify-center" : "gap-3"
          }`}
        >
          <Users className="h-4 w-4 shrink-0" />
          {!sidebarCollapsed && <span>Projects</span>}
        </NavLink>
      </div>
    </aside>
  );
}
