import type { InsightDoc } from "../../db/collections";

interface Props {
  insights: InsightDoc[];
  limit?: number;
}

export function OpenInsightsList({ insights, limit = 12 }: Props) {
  const open = insights.filter(
    (i) => i.status !== "resolved" && i.status !== "ignored",
  );

  if (open.length === 0) {
    return (
      <p className="text-sm text-[var(--shell-text-muted)]">
        No open insights for this category. Run a fresh analysis to generate new signals.
      </p>
    );
  }

  return (
    <div className="space-y-2">
      {open.slice(0, limit).map((ins) => (
        <InsightRow key={ins.id} ins={ins} />
      ))}
      {open.length > limit && (
        <p className="pt-1 text-xs text-[var(--shell-text-muted)]">
          +{open.length - limit} more open insight{open.length - limit === 1 ? "" : "s"}
        </p>
      )}
    </div>
  );
}

function InsightRow({ ins }: { ins: InsightDoc }) {
  return (
    <div className="rounded-xl border border-[var(--shell-border)] bg-[var(--shell-panel-soft)] px-4 py-3">
      <div className="flex items-center justify-between gap-2">
        <p className="text-sm font-medium text-[var(--shell-text)]">{ins.title}</p>
        <div className="flex shrink-0 items-center gap-1.5">
          {ins.priorityScore != null && (
            <span className="rounded-md bg-[var(--shell-panel)] px-1.5 py-0.5 text-[10px] font-medium text-[var(--shell-text-muted)]">
              P{Math.round(ins.priorityScore)}
            </span>
          )}
          <span
            className={`rounded-md px-1.5 py-0.5 text-[10px] font-medium ${
              ins.severity === "critical"
                ? "bg-rose-500/10 text-rose-500"
                : ins.severity === "warning"
                  ? "bg-amber-500/10 text-amber-500"
                  : "bg-blue-400/10 text-blue-500"
            }`}
          >
            {ins.severity}
          </span>
        </div>
      </div>
      {ins.summary && (
        <p className="mt-1 text-xs text-[var(--shell-text-muted)]">{ins.summary}</p>
      )}
      {ins.suggestion && (
        <p className="mt-1 text-xs text-[var(--shell-text)]">{ins.suggestion}</p>
      )}
      {ins.linkedActionTitle && (
        <div className="mt-2 inline-flex items-center gap-1.5 rounded-md bg-emerald-500/10 px-2 py-0.5 text-[10px] font-medium text-emerald-600">
          Action: {ins.linkedActionTitle}
        </div>
      )}
    </div>
  );
}
