function hydrateBoard(id: string, data: Record<string, unknown>): Board {
  return {
    id,
    ...data,
    status: normalizeBoardStatus((data as { status?: unknown }).status),
    createdAt: (data as { createdAt?: { toDate?: () => Date } }).createdAt?.toDate?.() ?? new Date(),
    completedAt: (data as { completedAt?: { toDate?: () => Date } }).completedAt?.toDate?.() ?? undefined,
  } as Board;
}

function extractDomain(url: string): string {
  try {
    return new URL(url).hostname.replace(/^www\./, "");
  } catch {
    return url;
  }
}

// ── Board CRUD ─────────────────────────────────────────────

export async function listBoards(userId: string): Promise<Board[]> {
  const q = query(paths.boards(), where("userId", "==", userId));
  const snap = await getDocs(q);
  const boards = snap.docs.map((d) => hydrateBoard(d.id, d.data()));
  boards.sort((a, b) => b.createdAt.getTime() - a.createdAt.getTime());
  return boards;
}

export async function listAllBoards(): Promise<Board[]> {
  const q = query(paths.boards(), orderBy("createdAt", "desc"));
  const snap = await getDocs(q);
  return snap.docs.map((d) => hydrateBoard(d.id, d.data()));
}

export async function getBoard(boardId: string): Promise<Board | null> {
  const snap = await getDoc(paths.board(boardId));
  if (!snap.exists()) return null;
  return hydrateBoard(snap.id, snap.data());
}

export async function createBoard(userId: string, url: string): Promise<string> {
  const domain = extractDomain(url);
  const ref = await addDoc(paths.boards(), {
    url,
    domain,
    siteName: domain,
    userId,
    status: "pending",
    createdAt: serverTimestamp(),
  });
  return ref.id;
}

export async function deleteBoard(boardId: string): Promise<void> {
  await deleteDoc(paths.board(boardId));
}

export async function retryBoard(boardId: string): Promise<void> {
  await updateDoc(paths.board(boardId), {
    status: "pending",
    failReason: null,
    activeRunId: null,
  });
}

export async function updateBoard(
  boardId: string,
  data: Partial<Omit<Board, "id" | "createdAt">>,
): Promise<void> {
  await updateDoc(paths.board(boardId), data);
}

export async function updateBrandKeywords(
  boardId: string,
  keywords: string[],
): Promise<void> {
  await setDoc(
    paths.summary(boardId, SUMMARY_KEYS.brand),
    {
      key: SUMMARY_KEYS.brand,
      data: { rawKeywords: keywords },
      updatedAt: serverTimestamp(),
    },
    { merge: true },
  );
}

// ── Board subscription ─────────────────────────────────────

export function subscribeBoard(
  boardId: string,
  callback: (board: Board | null) => void,
): Unsubscribe {
  return onSnapshot(paths.board(boardId), (snap) => {
    if (!snap.exists()) {
      callback(null);
      return;
    }
    callback(hydrateBoard(snap.id, snap.data()));
  });
}

