// ── Summaries subscription ────────────────────────────────

export function subscribeSummaries(
  boardId: string,
  callback: (summaries: Record<string, Record<string, unknown>>) => void,
): Unsubscribe {
  return onSnapshot(paths.summaries(boardId), (snap) => {
    const next: Record<string, Record<string, unknown>> = {};
    snap.forEach((d) => {
      const payload = d.data() as { data?: Record<string, unknown> };
      const data = (payload?.data ?? {}) as Record<string, unknown>;
      next[d.id] = data;
    });
    callback(next);
  });
}

// ── Raw list subscriptions ─────────────────────────────────

export function subscribeCompetitors(
  boardId: string,
  callback: (rows: CompetitorV2Doc[]) => void,
): Unsubscribe {
  return onSnapshot(paths.rawCompetitors(boardId), (snap) => {
    const rows: CompetitorV2Doc[] = [];
    snap.forEach((d) => {
      const data = d.data() as Partial<CompetitorV2Doc>;
      rows.push({
        name: String(data.name ?? ""),
        domain: String(data.domain ?? ""),
        strengths: Array.isArray(data.strengths) ? data.strengths : [],
        weaknesses: Array.isArray(data.weaknesses) ? data.weaknesses : [],
        positioning: String(data.positioning ?? ""),
        seoScore: Number(data.seoScore ?? 0),
        geoScore: Number(data.geoScore ?? 0),
        overallScore: Number(data.overallScore ?? 0),
      });
    });
    rows.sort((a, b) => b.overallScore - a.overallScore);
    callback(rows);
  });
}

