import { useEffect, useState } from "react";
import { useParams } from "react-router-dom";
import { GitBranch, Palette, Play } from "lucide-react";
import {
  getDocument,
  listActionPreviews,
  listActionRuns,
} from "../../../db/boards";
import { useCommand } from "../../../hooks/useCommand";
import { MetricCard } from "../../../components/shared/MetricCard";
import { EmptyState } from "../../../components/shared/EmptyState";

interface ActionPreview {
  id: string;
  title?: string;
  platform?: string;
  status?: string;
  body?: string;
  previewType?: string;
  sourceActionTitle?: string;
  beforeSnapshot?: string;
  afterPreview?: string;
  createdAt?: string;
}

interface ActionRun {
  id: string;
  title?: string;
  platform?: string;
  status?: string;
  createdAt?: string;
}

// ── Content Studio ─────────────────────────────────────────

export function ContentStudio() {
  const { id } = useParams<{ id: string }>();
  const [previews, setPreviews] = useState<ActionPreview[]>([]);
  const [actionPlanBody, setActionPlanBody] = useState<string>("");
  const [loading, setLoading] = useState(true);
  const cmd = useCommand(id);

  useEffect(() => {
    if (!id) return;
    setLoading(true);
    Promise.all([
      listActionPreviews(id).catch(() => []),
      getDocument(id, "action-plan").catch(() => null),
    ]).then(([pv, plan]) => {
      setPreviews(pv as ActionPreview[]);
      setActionPlanBody(plan?.body ?? "");
      setLoading(false);
    });
  }, [id]);

  const handleGenerate = async () => {
    await cmd.execute("generate_sns_drafts");
    if (id) {
      const pv = await listActionPreviews(id).catch(() => []);
      setPreviews(pv as ActionPreview[]);
    }
  };

  if (loading) return <Loading />;

  const readyCount = previews.filter((p) => p.status === "ready").length;
  const draftCount = previews.filter((p) => p.status !== "ready" && p.status !== "done").length;

  return (
    <div className="space-y-6">
      {/* Metrics */}
      <div className="grid gap-4 sm:grid-cols-2 lg:grid-cols-4">
        <MetricCard icon={Palette} label="Total Content" value={String(previews.length)} color="text-blue-600" />
        <MetricCard icon={Palette} label="Ready" value={String(readyCount)} color="text-emerald-600" />
        <MetricCard icon={Palette} label="Drafts" value={String(draftCount)} color="text-amber-500" />
        <MetricCard icon={Play} label="Generate" value={cmd.isRunning ? "Running..." : "Available"} color="text-teal-600" />
      </div>

      {/* Generate button */}
      <div className="flex items-center justify-between rounded-2xl border border-[var(--shell-border)] bg-[var(--shell-panel)] p-5">
        <div>
          <h3 className="text-sm font-semibold text-[var(--shell-text)]">Content Generation</h3>
          <p className="mt-0.5 text-xs text-[var(--shell-text-muted)]">AI-generated content drafts based on your action plan</p>
        </div>
        <button
          type="button"
          onClick={handleGenerate}
          disabled={cmd.isRunning}
          className="flex items-center gap-1.5 rounded-xl border border-[var(--shell-border)] bg-[var(--shell-panel)] px-4 py-2 text-sm font-medium text-[var(--shell-text)] transition-colors hover:border-[var(--shell-accent)] hover:text-[var(--shell-accent)] disabled:opacity-50"
        >
          <Play className="h-3.5 w-3.5" />
          {cmd.isRunning ? "Generating..." : "Generate Content"}
        </button>
      </div>

      {/* Running indicator */}
      {cmd.isRunning && (
        <div className="rounded-2xl border border-[var(--shell-accent)]/30 bg-[var(--shell-accent)]/5 px-5 py-4">
          <div className="flex items-center gap-2 text-sm font-medium text-[var(--shell-accent)]">
            <span className="inline-flex h-2 w-2 animate-pulse rounded-full bg-[var(--shell-accent)]" />
            {cmd.message || "Generating content..."}
          </div>
          <div className="mt-3 h-1.5 overflow-hidden rounded-full bg-[var(--shell-border)]">
            <div className="h-full rounded-full bg-[var(--shell-accent)] transition-all duration-500" style={{ width: `${Math.max(cmd.progress, 2)}%` }} />
          </div>
        </div>
      )}

      {/* Action plan summary */}
      {actionPlanBody && (
        <div className="rounded-2xl border border-[var(--shell-border)] bg-[var(--shell-panel)] p-5">
          <h3 className="text-xs font-semibold uppercase tracking-wider text-[var(--shell-text-muted)]">Action Plan</h3>
          <p className="mt-2 whitespace-pre-wrap text-sm leading-relaxed text-[var(--shell-text-muted)]">{actionPlanBody}</p>
        </div>
      )}

      {/* Content cards */}
      {previews.length > 0 ? (
        <div className="grid gap-4 md:grid-cols-2">
          {previews.map((preview) => (
            <div key={preview.id} className="rounded-2xl border border-[var(--shell-border)] bg-[var(--shell-panel)] p-5">
              <div className="flex items-start justify-between gap-3">
                <div className="min-w-0">
                  <p className="text-sm font-medium text-[var(--shell-text)]">{preview.title || preview.sourceActionTitle || "Untitled"}</p>
                  <div className="mt-1 flex items-center gap-2">
                    {preview.platform && (
                      <span className="rounded-md bg-[var(--shell-panel-soft)] px-2 py-0.5 text-[10px] text-[var(--shell-text-muted)]">{preview.platform}</span>
                    )}
                    {preview.previewType && (
                      <span className="rounded-md bg-[var(--shell-panel-soft)] px-2 py-0.5 text-[10px] text-[var(--shell-text-muted)]">{preview.previewType}</span>
                    )}
                  </div>
                </div>
                {preview.status && (
                  <span className={`shrink-0 rounded-md px-2 py-0.5 text-[10px] font-medium ${
                    preview.status === "ready" ? "bg-emerald-500/10 text-emerald-600" : "bg-amber-500/10 text-amber-500"
                  }`}>{preview.status}</span>
                )}
              </div>

              {/* Before/After */}
              {(preview.beforeSnapshot || preview.afterPreview) && (
                <div className="mt-3 grid gap-2 sm:grid-cols-2">
                  <div className="rounded-xl border border-[var(--shell-border)] bg-[var(--shell-panel-soft)] p-3">
                    <p className="text-[10px] uppercase tracking-wider text-[var(--shell-text-muted)]">Before</p>
                    <p className="mt-1 text-xs text-[var(--shell-text-muted)]">{preview.beforeSnapshot || "--"}</p>
                  </div>
                  <div className="rounded-xl border border-emerald-500/20 bg-emerald-500/5 p-3">
                    <p className="text-[10px] uppercase tracking-wider text-emerald-600">After</p>
                    <p className="mt-1 text-xs text-[var(--shell-text)]">{preview.afterPreview || "--"}</p>
                  </div>
                </div>
              )}

              {preview.body && (
                <p className="mt-3 line-clamp-4 text-sm leading-relaxed text-[var(--shell-text-muted)]">{preview.body}</p>
              )}
            </div>
          ))}
        </div>
      ) : (
        <EmptyState icon={Palette} title="No content yet" description="Generate Content를 누르면 AI 기반 초안이 생성됩니다" />
      )}
    </div>
  );
}

// ── Pipeline ───────────────────────────────────────────────

export function Pipeline() {
  const { id } = useParams<{ id: string }>();
  const [previews, setPreviews] = useState<ActionPreview[]>([]);
  const [runs, setRuns] = useState<ActionRun[]>([]);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    if (!id) return;
    setLoading(true);
    Promise.all([
      listActionPreviews(id).catch(() => []),
      listActionRuns(id).catch(() => []),
    ]).then(([pv, rn]) => {
      setPreviews(pv as ActionPreview[]);
      setRuns(rn as ActionRun[]);
      setLoading(false);
    });
  }, [id]);

  if (loading) return <Loading />;

  const openPreviews = previews.filter((p) => p.status !== "done" && p.status !== "completed");
  const activeRuns = runs.filter((r) => r.status === "running" || r.status === "pending" || r.status === "queued");
  const completedRuns = runs.filter((r) => r.status === "done" || r.status === "complete" || r.status === "completed");

  return (
    <div className="space-y-6">
      {/* Metrics */}
      <div className="grid gap-4 sm:grid-cols-2 lg:grid-cols-4">
        <MetricCard icon={GitBranch} label="Open Actions" value={String(openPreviews.length)} color="text-blue-600" />
        <MetricCard icon={GitBranch} label="Active Runs" value={String(activeRuns.length)} color="text-amber-500" />
        <MetricCard icon={GitBranch} label="Completed" value={String(completedRuns.length)} color="text-emerald-600" />
        <MetricCard icon={GitBranch} label="Total" value={String(previews.length + runs.length)} color="text-cyan-600" />
      </div>

      {/* Open actions */}
      <div className="rounded-2xl border border-[var(--shell-border)] bg-[var(--shell-panel)] p-5">
        <h3 className="text-sm font-semibold text-[var(--shell-text)]">Open Actions ({openPreviews.length})</h3>
        {openPreviews.length > 0 ? (
          <div className="mt-3 space-y-2">
            {openPreviews.slice(0, 12).map((p) => (
              <div key={p.id} className="flex items-center justify-between rounded-xl border border-[var(--shell-border)] bg-[var(--shell-panel-soft)] px-4 py-3">
                <div className="min-w-0">
                  <p className="truncate text-sm text-[var(--shell-text)]">{p.title || p.sourceActionTitle || "Action"}</p>
                  <div className="mt-0.5 flex gap-2 text-[10px] text-[var(--shell-text-muted)]">
                    {p.platform && <span>{p.platform}</span>}
                    {p.previewType && <span>{p.previewType}</span>}
                  </div>
                </div>
                <StatusPill status={p.status || "todo"} />
              </div>
            ))}
          </div>
        ) : (
          <p className="mt-3 text-sm text-[var(--shell-text-muted)]">No open actions in the pipeline</p>
        )}
      </div>

      {/* Active runs */}
      {activeRuns.length > 0 && (
        <div className="rounded-2xl border border-[var(--shell-border)] bg-[var(--shell-panel)] p-5">
          <h3 className="text-sm font-semibold text-[var(--shell-text)]">Active Runs ({activeRuns.length})</h3>
          <div className="mt-3 space-y-2">
            {activeRuns.map((r) => (
              <div key={r.id} className="flex items-center justify-between rounded-xl border border-[var(--shell-border)] bg-[var(--shell-panel-soft)] px-4 py-3">
                <p className="truncate text-sm text-[var(--shell-text)]">{r.title || r.id}</p>
                <StatusPill status={r.status || "running"} />
              </div>
            ))}
          </div>
        </div>
      )}
    </div>
  );
}

// ── Shared ──────────────────────────────────────────────────

function StatusPill({ status }: { status: string }) {
  const style = status === "done" || status === "complete" || status === "completed"
    ? "bg-emerald-500/10 text-emerald-600"
    : status === "running" || status === "pending" || status === "queued"
      ? "bg-amber-500/10 text-amber-500"
      : status === "failed"
        ? "bg-rose-500/10 text-rose-500"
        : "bg-[var(--shell-panel-soft)] text-[var(--shell-text-muted)]";
  return <span className={`rounded-md px-2 py-0.5 text-[10px] font-medium ${style}`}>{status}</span>;
}

function Loading() {
  return <div className="flex min-h-[30vh] items-center justify-center text-sm text-[var(--shell-text-muted)]">Loading...</div>;
}
