import { useMemo, useState } from "react";

const ENGINE_COLORS = {
  overall: "var(--shell-accent)",
  gpt: "rgb(52, 211, 153)",
  openai: "rgb(52, 211, 153)",
  claude: "rgb(96, 165, 250)",
  gemini: "rgb(167, 139, 250)",
} as const;

type Period = 4 | 8 | 12;

type DataPoint = {
  date: Date;
  dateLabel: string;
  overall: number;
  gpt: number | null;
  claude: number | null;
  gemini: number | null;
};

interface TrendSnapshot {
  capturedAt: string;
  metrics?: { mentionRate?: number; totalQuestions?: number };
  engineBreakdown?: Array<{ engine: string; mentionRate: number; totalQuestions?: number }>;
}

interface Props {
  snapshots: TrendSnapshot[];
  className?: string;
}

function hasMeasuredSnapshot(snapshot: TrendSnapshot): boolean {
  const metricQuestions = snapshot.metrics?.totalQuestions ?? 0;
  const engineQuestions = (snapshot.engineBreakdown || []).reduce((sum, row) => sum + (row.totalQuestions || 0), 0);
  return metricQuestions > 0 || engineQuestions > 0;
}

export function MentionRateTrendChart({ snapshots, className = "" }: Props) {
  const [period, setPeriod] = useState<Period>(8);
  const [hoverIndex, setHoverIndex] = useState<number | null>(null);
  const measuredSnapshots = useMemo(() => (snapshots || []).filter(hasMeasuredSnapshot), [snapshots]);

  const points: DataPoint[] = useMemo(() => {
    if (!measuredSnapshots || measuredSnapshots.length === 0) return [];
    const sorted = [...measuredSnapshots].sort((a, b) =>
      new Date(a.capturedAt).getTime() - new Date(b.capturedAt).getTime(),
    );
    const cutoffMs = Date.now() - period * 7 * 24 * 60 * 60 * 1000;
    const filtered = sorted.filter((s) => new Date(s.capturedAt).getTime() >= cutoffMs);
    const source = filtered.length >= 2 ? filtered : sorted;

    return source.map((s) => {
      const eng = (s.engineBreakdown || []).reduce<Record<string, number>>((acc, e) => {
        const key = e.engine === "openai" ? "gpt" : e.engine;
        acc[key] = e.mentionRate;
        return acc;
      }, {});
      const date = new Date(s.capturedAt);
      return {
        date,
        dateLabel: `${date.getMonth() + 1}/${date.getDate()}`,
        overall: s.metrics?.mentionRate ?? 0,
        gpt: eng.gpt ?? null,
        claude: eng.claude ?? null,
        gemini: eng.gemini ?? null,
      };
    });
  }, [measuredSnapshots, period]);

  if (measuredSnapshots.length === 0) {
    return (
      <section className={`rounded-2xl border border-[var(--shell-border)] bg-[var(--shell-panel)] p-5 ${className}`}>
        <div className="flex items-center justify-between">
          <div className="text-sm font-semibold text-[var(--shell-text)]">AI 언급률 추세</div>
          <div className="text-[10px] text-[var(--shell-text-soft)]">측정 대기</div>
        </div>
        <div className="mt-4 rounded-xl border border-dashed border-[var(--shell-border)] bg-[var(--shell-panel-soft)] px-4 py-8 text-center">
          <div className="text-xs text-[var(--shell-text-muted)]">
            아직 AI 측정 표본이 없습니다.
            <br />
            <span className="text-[10px] text-[var(--shell-text-soft)]">첫 측정은 고객 인풋 저장 후 자동으로 시작됩니다.</span>
          </div>
        </div>
      </section>
    );
  }

  if (measuredSnapshots.length === 1) {
    const s = measuredSnapshots[0];
    const rate = s.metrics?.mentionRate ?? 0;
    const engines = (s.engineBreakdown || []).reduce<Record<string, number>>((acc, e) => {
      const key = e.engine === "openai" ? "gpt" : e.engine;
      acc[key] = e.mentionRate;
      return acc;
    }, {});
    const d = new Date(s.capturedAt);
    const dateStr = `${d.getFullYear()}.${d.getMonth() + 1}.${d.getDate()}`;
    return (
      <section className={`rounded-2xl border border-[var(--shell-border)] bg-[var(--shell-panel)] p-5 ${className}`}>
        <div className="flex items-center justify-between">
          <div className="text-sm font-semibold text-[var(--shell-text)]">AI 언급률 추세</div>
          <div className="text-[10px] text-[var(--shell-text-soft)]">첫 번째 측정 완료 · 데이터 누적 중</div>
        </div>
        <div className="mt-4 flex items-center justify-center gap-6 rounded-xl border border-[var(--shell-border)] bg-[var(--shell-panel-soft)] px-4 py-6">
          <div className="text-center">
            <div className="text-2xl font-bold text-[var(--shell-text)]">{rate.toFixed(1)}%</div>
            <div className="mt-1 text-[10px] text-[var(--shell-text-muted)]">종합 언급률</div>
          </div>
          {engines.gpt != null && (
            <div className="text-center">
              <div className="text-lg font-semibold" style={{ color: ENGINE_COLORS.gpt }}>{engines.gpt.toFixed(1)}%</div>
              <div className="mt-1 text-[10px] text-[var(--shell-text-muted)]">ChatGPT</div>
            </div>
          )}
          {engines.claude != null && (
            <div className="text-center">
              <div className="text-lg font-semibold" style={{ color: ENGINE_COLORS.claude }}>{engines.claude.toFixed(1)}%</div>
              <div className="mt-1 text-[10px] text-[var(--shell-text-muted)]">Claude</div>
            </div>
          )}
          {engines.gemini != null && (
            <div className="text-center">
              <div className="text-lg font-semibold" style={{ color: ENGINE_COLORS.gemini }}>{engines.gemini.toFixed(1)}%</div>
              <div className="mt-1 text-[10px] text-[var(--shell-text-muted)]">Gemini</div>
            </div>
          )}
        </div>
        <div className="mt-2 text-center text-[10px] text-[var(--shell-text-soft)]">
          {dateStr} 측정 · 두 번째 측정이 쌓이면 추세 그래프가 나타납니다
        </div>
      </section>
    );
  }

  const W = 800;
  const H = 240;
  const PAD_LEFT = 40;
  const PAD_RIGHT = 12;
  const PAD_TOP = 16;
  const PAD_BOTTOM = 28;
  const innerW = W - PAD_LEFT - PAD_RIGHT;
  const innerH = H - PAD_TOP - PAD_BOTTOM;

  const allValues = points.flatMap((p) => [p.overall, p.gpt, p.claude, p.gemini].filter((v): v is number => v !== null));
  const maxY = Math.max(20, Math.ceil((Math.max(...allValues) + 5) / 10) * 10);

  const xFor = (i: number) => PAD_LEFT + (points.length === 1 ? innerW / 2 : (i / (points.length - 1)) * innerW);
  const yFor = (v: number) => PAD_TOP + innerH - (v / maxY) * innerH;

  const buildPath = (key: keyof DataPoint) => {
    let d = "";
    let prevValid = false;
    for (let i = 0; i < points.length; i++) {
      const v = points[i][key] as number | null;
      if (v === null || !Number.isFinite(v)) {
        prevValid = false;
        continue;
      }
      const cmd = prevValid ? "L" : "M";
      d += `${cmd}${xFor(i).toFixed(1)},${yFor(v).toFixed(1)} `;
      prevValid = true;
    }
    return d.trim();
  };

  const yTicks = [0, Math.round(maxY * 0.25), Math.round(maxY * 0.5), Math.round(maxY * 0.75), maxY];
  const xLabelStep = Math.max(1, Math.ceil(points.length / 8));
  const last = points[points.length - 1];

  return (
    <section className={`rounded-2xl border border-[var(--shell-border)] bg-[var(--shell-panel)] p-5 ${className}`}>
      <div className="flex items-start justify-between gap-3">
        <div>
          <div className="text-sm font-semibold text-[var(--shell-text)]">AI 언급률 추세</div>
          <div className="mt-1 text-[11px] text-[var(--shell-text-muted)]">
            ChatGPT · Claude · Gemini 가 답변에 우리 브랜드를 직접 언급한 비율 추이
          </div>
        </div>
        <div className="flex shrink-0 items-center gap-1 rounded-lg border border-[var(--shell-border)] bg-[var(--shell-panel-soft)] p-0.5 text-[11px]">
          {([4, 8, 12] as const).map((p) => (
            <button
              key={p}
              type="button"
              onClick={() => setPeriod(p)}
              className={`rounded px-2.5 py-1 transition-colors ${
                period === p
                  ? "bg-[var(--shell-accent)]/20 text-[var(--shell-text)]"
                  : "text-[var(--shell-text-muted)] hover:text-[var(--shell-text)]"
              }`}
            >
              {p}주
            </button>
          ))}
        </div>
      </div>

      <div className="relative mt-4">
        <svg
          viewBox={`0 0 ${W} ${H}`}
          className="w-full"
          style={{ height: "240px" }}
          onMouseLeave={() => setHoverIndex(null)}
        >
          {yTicks.map((v, i) => (
            <g key={i}>
              <line x1={PAD_LEFT} x2={W - PAD_RIGHT} y1={yFor(v)} y2={yFor(v)} stroke="var(--shell-border)" strokeOpacity={i === 0 ? 0.6 : 0.3} strokeDasharray={i === 0 ? "0" : "3,3"} />
              <text x={PAD_LEFT - 6} y={yFor(v) + 3} fontSize="10" fill="var(--shell-text-soft)" textAnchor="end">{v}%</text>
            </g>
          ))}

          {points.map((p, i) =>
            i % xLabelStep === 0 || i === points.length - 1 ? (
              <text key={i} x={xFor(i)} y={H - 8} fontSize="10" fill="var(--shell-text-soft)" textAnchor="middle">{p.dateLabel}</text>
            ) : null,
          )}

          <path d={buildPath("gemini")} fill="none" stroke={ENGINE_COLORS.gemini} strokeWidth="1.5" strokeOpacity="0.7" />
          <path d={buildPath("claude")} fill="none" stroke={ENGINE_COLORS.claude} strokeWidth="1.5" strokeOpacity="0.7" />
          <path d={buildPath("gpt")} fill="none" stroke={ENGINE_COLORS.gpt} strokeWidth="1.5" strokeOpacity="0.7" />
          <path d={buildPath("overall")} fill="none" stroke={ENGINE_COLORS.overall} strokeWidth="2.5" />

          {points.map((p, i) => (
            <circle key={i} cx={xFor(i)} cy={yFor(p.overall)} r={i === points.length - 1 ? 4 : 2.5} fill="var(--shell-accent)" stroke="var(--shell-panel)" strokeWidth="1.5" />
          ))}

          {points.map((_, i) => {
            const x = xFor(i);
            const halfW = points.length > 1 ? innerW / (points.length - 1) / 2 : innerW;
            return (
              <rect key={`hover-${i}`} x={x - halfW} y={PAD_TOP} width={halfW * 2} height={innerH} fill="transparent" onMouseEnter={() => setHoverIndex(i)} style={{ cursor: "crosshair" }} />
            );
          })}

          {hoverIndex !== null && points[hoverIndex] && (
            <>
              <line x1={xFor(hoverIndex)} x2={xFor(hoverIndex)} y1={PAD_TOP} y2={PAD_TOP + innerH} stroke="var(--shell-text-soft)" strokeOpacity="0.5" strokeDasharray="3,3" />
              {(() => {
                const p = points[hoverIndex];
                const lines = [
                  { label: "종합", value: p.overall, color: ENGINE_COLORS.overall },
                  { label: "ChatGPT", value: p.gpt, color: ENGINE_COLORS.gpt },
                  { label: "Claude", value: p.claude, color: ENGINE_COLORS.claude },
                  { label: "Gemini", value: p.gemini, color: ENGINE_COLORS.gemini },
                ].filter((l) => l.value !== null);
                const tipW = 130;
                const tipH = 20 + lines.length * 14;
                let tipX = xFor(hoverIndex) + 8;
                if (tipX + tipW > W - PAD_RIGHT) tipX = xFor(hoverIndex) - tipW - 8;
                return (
                  <g pointerEvents="none">
                    <rect x={tipX} y={PAD_TOP + 4} width={tipW} height={tipH} rx={6} fill="var(--shell-panel-strong)" stroke="var(--shell-border)" />
                    <text x={tipX + 8} y={PAD_TOP + 18} fontSize="11" fontWeight="600" fill="var(--shell-text)">{p.dateLabel}</text>
                    {lines.map((l, i) => (
                      <g key={l.label}>
                        <circle cx={tipX + 12} cy={PAD_TOP + 32 + i * 14} r="3" fill={l.color} />
                        <text x={tipX + 20} y={PAD_TOP + 35 + i * 14} fontSize="10" fill="var(--shell-text-muted)">
                          {l.label}: <tspan fill="var(--shell-text)" fontWeight="600">{(l.value ?? 0).toFixed(0)}%</tspan>
                        </text>
                      </g>
                    ))}
                  </g>
                );
              })()}
            </>
          )}
        </svg>
      </div>

      <div className="mt-3 flex flex-wrap items-center justify-between gap-3 border-t border-[var(--shell-border)] pt-3 text-[11px]">
        <div className="flex flex-wrap items-center gap-3">
          <LegendItem color={ENGINE_COLORS.overall} label="종합" weight="bold" />
          <LegendItem color={ENGINE_COLORS.gpt} label="ChatGPT" />
          <LegendItem color={ENGINE_COLORS.claude} label="Claude" />
          <LegendItem color={ENGINE_COLORS.gemini} label="Gemini" />
        </div>
        <div className="text-[10px] text-[var(--shell-text-soft)]">
          최신 ({last.dateLabel}): 종합 <span className="font-semibold text-[var(--shell-text)]">{last.overall.toFixed(0)}%</span>
          {last.gpt !== null && <> · GPT {last.gpt.toFixed(0)}%</>}
          {last.claude !== null && <> · Claude {last.claude.toFixed(0)}%</>}
          {last.gemini !== null && <> · Gemini {last.gemini.toFixed(0)}%</>}
        </div>
      </div>
    </section>
  );
}

function LegendItem({ color, label, weight }: { color: string; label: string; weight?: "bold" }) {
  return (
    <span className="flex items-center gap-1.5">
      <span className="inline-block h-2 w-3 rounded-sm" style={{ background: color }} />
      <span className={weight === "bold" ? "font-semibold text-[var(--shell-text)]" : "text-[var(--shell-text-muted)]"}>{label}</span>
    </span>
  );
}

export function computeWeekDelta(snapshots: TrendSnapshot[]): { current: number; previous: number; delta: number } | null {
  const measuredSnapshots = (snapshots || []).filter(hasMeasuredSnapshot);
  if (measuredSnapshots.length < 2) return null;
  const sorted = [...measuredSnapshots].sort((a, b) =>
    new Date(b.capturedAt).getTime() - new Date(a.capturedAt).getTime(),
  );
  const current = sorted[0].metrics?.mentionRate ?? 0;
  const previous = sorted[1].metrics?.mentionRate ?? 0;
  return { current, previous, delta: current - previous };
}
