import { useEffect, useMemo, useState } from "react";
import { useParams } from "react-router-dom";
import { AlertTriangle, Lightbulb, Plus, Swords, Trash2, Users, Zap } from "lucide-react";
import {
  listCompetitorsV2,
  listManualCompetitors,
  addManualCompetitor,
  deleteManualCompetitor,
  getDocument,
  listGeoProbesV2,
  listSeoAudits,
  subscribeBoard,
  subscribeInsights,
} from "../../../db/boards";
import type { Board, Competitor, BoardDocument, CompetitorV2Doc, InsightDoc } from "../../../db/collections";
import { OpenInsightsList } from "../../../components/shared/OpenInsightsList";
import { MetricCard } from "../../../components/shared/MetricCard";
import { InsightSection } from "../../../components/shared/InsightSection";
import { DataQualityBadge } from "../../../components/shared/DataQualityBadge";

// ── Types ──────────────────────────────────────────────────

interface CompAnalysis {
  competitors?: Array<Record<string, unknown>>;
  summary?: string;
}

interface ActionItem {
  title: string;
  type?: string;
  category?: string;
  priority?: string;
  description?: string;
}

// ── Component ──────────────────────────────────────────────

export function CompetitorsInsight() {
  const { id } = useParams<{ id: string }>();
  const [board, setBoard] = useState<Board | null>(null);
  const [manual, setManual] = useState<Competitor[]>([]);
  const [auto, setAuto] = useState<CompetitorV2Doc[]>([]);
  const [analysis, setAnalysis] = useState<CompAnalysis | null>(null);
  const [probes, setProbes] = useState<Array<Record<string, unknown>>>([]);
  const [actionPlanDoc, setActionPlanDoc] = useState<BoardDocument | null>(null);
  const [audit, setAudit] = useState<Record<string, unknown> | null>(null);
  const [liveInsights, setLiveInsights] = useState<InsightDoc[]>([]);
  const [loading, setLoading] = useState(true);
  const [name, setName] = useState("");
  const [domain, setDomain] = useState("");
  const [adding, setAdding] = useState(false);

  useEffect(() => {
    if (!id) return;
    setLoading(true);
    const unsubBoard = subscribeBoard(id, setBoard);
    const unsubIns = subscribeInsights(id, setLiveInsights, { type: "competitor_gap" });
    Promise.all([
      listCompetitorsV2(id).catch(() => [] as CompetitorV2Doc[]),
      listManualCompetitors(id).catch(() => [] as Competitor[]),
      getDocument(id, "competitor-analysis"),
      listGeoProbesV2(id).catch(() => []),
      getDocument(id, "action-plan").catch(() => null),
      listSeoAudits(id, 1).catch(() => []),
    ]).then(([autoComps, manualComps, doc, gp, ap, audits]) => {
      setAuto(autoComps);
      setManual(manualComps);
      setAnalysis((doc?.data ?? null) as CompAnalysis | null);
      setProbes(gp as unknown as Array<Record<string, unknown>>);
      setActionPlanDoc(ap);
      setAudit(((audits as Array<Record<string, unknown>>)[0] as Record<string, unknown>) ?? null);
      setLoading(false);
    });
    return () => {
      unsubBoard();
      unsubIns();
    };
  }, [id]);

  const autoCompetitors = useMemo(() => {
    if (auto.length > 0) return auto as unknown as Array<Record<string, unknown>>;
    return (analysis?.competitors ?? []) as Array<Record<string, unknown>>;
  }, [auto, analysis]);

  const allCompetitors = autoCompetitors.length > 0 ? autoCompetitors : manual;

  const shareOfVoice = useMemo(() => {
    const map = new Map<string, number>();
    for (const p of probes) {
      const engines = (p.competitors ?? p.mentionedCompetitors ?? []) as string[];
      for (const c of engines) {
        map.set(c, (map.get(c) ?? 0) + 1);
      }
    }
    return [...map.entries()]
      .sort((a, b) => b[1] - a[1])
      .slice(0, 10)
      .map(([name, count]) => ({ name, count }));
  }, [probes]);

  const handleAdd = async () => {
    if (!id || !name.trim() || !domain.trim()) return;
    setAdding(true);
    await addManualCompetitor(id, { name: name.trim(), domain: domain.trim() });
    setName("");
    setDomain("");
    const comps = await listManualCompetitors(id).catch(() => [] as Competitor[]);
    setManual(comps);
    setAdding(false);
  };

  const handleDelete = async (compId: string) => {
    if (!id) return;
    await deleteManualCompetitor(id, compId);
    setManual((prev) => prev.filter((c) => c.id !== compId));
  };

  const seoScore = (audit?.seoScore as number) ?? (audit?.score as number) ?? board?.seoScore ?? 0;
  const geoScore = (audit?.geoScore as number) ?? board?.geoScore ?? 0;

  // ── Derived: Diagnosis ──

  const diagnosis = useMemo(() => {
    const items: Array<{ severity: "high" | "medium" | "low"; title: string; detail: string }> = [];

    if (shareOfVoice.length > 0) {
      const topComp = shareOfVoice[0];
      const ourDomain = board?.domain ?? "";
      const ourCount = shareOfVoice.find((s) => s.name.includes(ourDomain))?.count ?? 0;
      if (topComp.count > ourCount && ourDomain) {
        items.push({
          severity: "high",
          title: `${topComp.name} leads in AI mentions`,
          detail: `${topComp.name} appears ${topComp.count} times vs your ${ourCount} mentions in AI probe results.`,
        });
      }
    }

    if (autoCompetitors.length > 0) {
      const highScoreComps = autoCompetitors.filter((c) => {
        const compGeo = Number(c.geoScore ?? 0);
        return compGeo > geoScore;
      });
      if (highScoreComps.length > 0) {
        items.push({
          severity: "medium",
          title: `${highScoreComps.length} competitor${highScoreComps.length !== 1 ? "s" : ""} with higher GEO score`,
          detail: highScoreComps.slice(0, 3).map((c) => `${String(c.name ?? c.domain)} (GEO ${String(c.geoScore)})`).join(", "),
        });
      }
    }

    if (allCompetitors.length === 0 && manual.length === 0) {
      items.push({
        severity: "medium",
        title: "No competitors tracked",
        detail: "Add competitors manually or run an analysis to auto-detect them.",
      });
    }

    return items;
  }, [shareOfVoice, autoCompetitors, allCompetitors, manual, board, geoScore]);

  // ── Derived: Generated Insights ──

  const insights = useMemo(() => {
    const result: Array<{ severity: "high" | "medium" | "low"; title: string; explanation: string }> = [];

    if (shareOfVoice.length >= 2) {
      const total = shareOfVoice.reduce((s, e) => s + e.count, 0);
      const topShare = Math.round((shareOfVoice[0].count / total) * 100);
      result.push({
        severity: topShare > 40 ? "high" : "medium",
        title: `${shareOfVoice[0].name} holds ${topShare}% share of AI voice`,
        explanation: `Across ${total} total AI mentions, the top competitor dominates. Consider creating targeted comparison content.`,
      });
    }

    if (autoCompetitors.length > 5) {
      result.push({
        severity: "low",
        title: `${autoCompetitors.length} competitors detected in your market`,
        explanation: "A crowded competitive landscape. Focus on differentiation through expert content, structured data, and trust signals.",
      });
    }

    if (probes.length > 0 && shareOfVoice.length === 0) {
      result.push({
        severity: "low",
        title: "No competitor mentions found in AI probes",
        explanation: "AI engines did not reference competitors for your queries. This could indicate a niche market or limited AI training data.",
      });
    }

    return result;
  }, [shareOfVoice, autoCompetitors, probes]);

  // ── Derived: Suggested Actions ──

  const suggestedActions = useMemo(() => {
    const planData = (actionPlanDoc?.data ?? {}) as Record<string, unknown>;
    const actions = (planData.actions ?? planData.items ?? []) as ActionItem[];
    return actions.filter((a) => {
      const cat = (a.category ?? a.type ?? "").toLowerCase();
      return cat.includes("competitor") || cat.includes("comparison") || cat.includes("positioning");
    }).slice(0, 5);
  }, [actionPlanDoc]);

  // ── Derived: Data Quality ──

  const dataQuality = useMemo(() => {
    const hasCompetitors = allCompetitors.length > 0 || manual.length > 0;
    const hasProbes = probes.length > 0;
    const hasAnalysis = !!analysis;
    const sources = [hasCompetitors, hasProbes, hasAnalysis].filter(Boolean).length;
    const score = Math.round((sources / 3) * 100);
    const status: "ok" | "warning" | "degraded" | "invalid" =
      score >= 80 ? "ok" : score >= 50 ? "warning" : score > 0 ? "degraded" : "invalid";
    const notes: string[] = [];
    if (!hasCompetitors) notes.push("No competitors registered or detected");
    if (!hasProbes) notes.push("No AI probe data for share of voice");
    if (!hasAnalysis) notes.push("No competitor analysis document");
    return { score, status, notes };
  }, [allCompetitors, manual, probes, analysis]);

  if (loading) {
    return (
      <div className="flex min-h-[30vh] items-center justify-center text-sm text-[var(--shell-text-muted)]">
        불러오는 중...
      </div>
    );
  }

  return (
    <div className="space-y-6">
      {/* Summary Metrics */}
      <div className="grid gap-4 sm:grid-cols-2 lg:grid-cols-4">
        <MetricCard icon={Swords} label="Our SEO" value={String(seoScore)} color="text-blue-600" />
        <MetricCard icon={Swords} label="Our GEO" value={String(geoScore)} color="text-teal-600" />
        <MetricCard icon={Users} label="Competitors" value={String(allCompetitors.length)} color="text-amber-600" />
        <MetricCard icon={Users} label="Share of Voice" value={shareOfVoice.length > 0 ? `${shareOfVoice.length} tracked` : "--"} color="text-cyan-600" />
      </div>

      {/* Data Quality */}
      <DataQualityBadge score={dataQuality.score} status={dataQuality.status} notes={dataQuality.notes} />

      {/* Raw Data: Add Competitor */}
      <InsightSection title="Add Competitor" icon={Plus} defaultOpen>
        <div className="flex flex-col gap-3 sm:flex-row sm:items-end">
          <div className="min-w-0 flex-1">
            <label className="mb-1 block text-xs text-[var(--shell-text-muted)]">Name</label>
            <input
              type="text"
              value={name}
              onChange={(e) => setName(e.target.value)}
              placeholder="Competitor name"
              className="w-full rounded-xl border border-[var(--shell-border)] bg-[var(--shell-panel-soft)] px-3 py-2 text-sm text-[var(--shell-text)] outline-none transition-colors focus:border-[var(--shell-accent)]"
            />
          </div>
          <div className="min-w-0 flex-1">
            <label className="mb-1 block text-xs text-[var(--shell-text-muted)]">Domain</label>
            <input
              type="text"
              value={domain}
              onChange={(e) => setDomain(e.target.value)}
              placeholder="example.com"
              className="w-full rounded-xl border border-[var(--shell-border)] bg-[var(--shell-panel-soft)] px-3 py-2 text-sm text-[var(--shell-text)] outline-none transition-colors focus:border-[var(--shell-accent)]"
              onKeyDown={(e) => { if (e.key === "Enter") handleAdd(); }}
            />
          </div>
          <button
            type="button"
            onClick={handleAdd}
            disabled={adding || !name.trim() || !domain.trim()}
            className="flex items-center gap-1.5 rounded-xl border border-[var(--shell-border)] bg-[var(--shell-panel)] px-4 py-2 text-sm font-medium text-[var(--shell-text)] transition-colors hover:border-[var(--shell-accent)] hover:text-[var(--shell-accent)] disabled:opacity-50"
          >
            <Plus className="h-3.5 w-3.5" />
            {adding ? "Adding..." : "Add"}
          </button>
        </div>
      </InsightSection>

      {/* Raw Data: Share of Voice */}
      <InsightSection title="Share of Voice (AI Mentions)" icon={Swords} count={shareOfVoice.length} defaultOpen={shareOfVoice.length > 0}>
        {shareOfVoice.length > 0 ? (
          <div className="space-y-2">
            {shareOfVoice.map((entry) => {
              const maxCount = shareOfVoice[0]?.count ?? 1;
              const pct = Math.round((entry.count / maxCount) * 100);
              return (
                <div key={entry.name} className="flex items-center gap-3">
                  <span className="w-28 shrink-0 truncate text-sm text-[var(--shell-text)]">{entry.name}</span>
                  <div className="flex-1">
                    <div className="h-2 overflow-hidden rounded-full bg-[var(--shell-panel-soft)]">
                      <div className="h-full rounded-full bg-[var(--shell-accent)]" style={{ width: `${pct}%` }} />
                    </div>
                  </div>
                  <span className="w-8 shrink-0 text-right text-xs tabular-nums text-[var(--shell-text-muted)]">{entry.count}</span>
                </div>
              );
            })}
          </div>
        ) : (
          <p className="text-sm text-[var(--shell-text-muted)]">Run AI probes to see share of voice data</p>
        )}
      </InsightSection>

      {/* Raw Data: Auto-detected */}
      {autoCompetitors.length > 0 && (
        <InsightSection title="Auto-detected Competitors" icon={Users} count={autoCompetitors.length} defaultOpen>
          <div className="grid gap-3 sm:grid-cols-2 lg:grid-cols-3">
            {autoCompetitors.slice(0, 9).map((c, i) => (
              <div key={String(c.name ?? i)} className="rounded-xl border border-[var(--shell-border)] bg-[var(--shell-panel-soft)] p-4">
                <div className="flex items-center justify-between">
                  <span className="text-sm font-medium text-[var(--shell-text)]">{String(c.name ?? c.domain ?? "Competitor")}</span>
                  {c.overallScore != null && (
                    <span className="text-xs font-medium text-[var(--shell-text-muted)]">Score: {String(c.overallScore)}</span>
                  )}
                </div>
                {c.domain != null && <p className="mt-1 text-xs text-[var(--shell-text-muted)]">{String(c.domain)}</p>}
                <div className="mt-2 flex items-center gap-2 text-xs text-[var(--shell-text-muted)]">
                  {c.seoScore != null && <span>SEO {String(c.seoScore)}</span>}
                  {c.geoScore != null && <span>GEO {String(c.geoScore)}</span>}
                </div>
                {c.positioning != null && (
                  <p className="mt-2 line-clamp-2 text-xs text-[var(--shell-text-muted)]">{String(c.positioning)}</p>
                )}
              </div>
            ))}
          </div>
        </InsightSection>
      )}

      {/* Raw Data: Registered Competitors */}
      <InsightSection title="Registered Competitors" icon={Users} count={manual.length} defaultOpen>
        {manual.length > 0 ? (
          <div className="grid gap-3 sm:grid-cols-2 lg:grid-cols-3">
            {manual.map((comp) => (
              <div key={comp.id} className="flex items-start justify-between rounded-xl border border-[var(--shell-border)] bg-[var(--shell-panel-soft)] p-4">
                <div className="min-w-0">
                  <p className="text-sm font-medium text-[var(--shell-text)]">{comp.name}</p>
                  <p className="mt-0.5 truncate text-xs text-[var(--shell-text-muted)]">{comp.domain ?? comp.url ?? ""}</p>
                  {comp.description && (
                    <p className="mt-1 line-clamp-2 text-xs text-[var(--shell-text-muted)]">{comp.description}</p>
                  )}
                </div>
                <button
                  type="button"
                  onClick={() => handleDelete(comp.id)}
                  className="ml-2 shrink-0 rounded-lg p-1.5 text-[var(--shell-text-muted)] transition-colors hover:bg-rose-500/10 hover:text-rose-500"
                >
                  <Trash2 className="h-3.5 w-3.5" />
                </button>
              </div>
            ))}
          </div>
        ) : (
          <div className="rounded-xl border border-dashed border-[var(--shell-border)] p-6 text-center text-sm text-[var(--shell-text-muted)]">
            No competitors registered yet. Add one above.
          </div>
        )}
      </InsightSection>

      {/* Diagnosis */}
      <InsightSection title="Diagnosis" icon={AlertTriangle} count={diagnosis.length} defaultOpen={diagnosis.length > 0}>
        {diagnosis.length > 0 ? (
          <div className="space-y-2">
            {diagnosis.map((item, i) => (
              <div key={i} className="flex items-start gap-3 rounded-xl border border-[var(--shell-border)] bg-[var(--shell-panel-soft)] px-4 py-3">
                <SeverityDot severity={item.severity} />
                <div className="min-w-0 flex-1">
                  <p className="text-sm font-medium text-[var(--shell-text)]">{item.title}</p>
                  <p className="mt-0.5 text-xs text-[var(--shell-text-muted)]">{item.detail}</p>
                </div>
              </div>
            ))}
          </div>
        ) : (
          <p className="text-sm text-[var(--shell-text-muted)]">No diagnostic issues found</p>
        )}
      </InsightSection>

      {/* Open Insights (from insights collection) */}
      <InsightSection
        title="Open Insights"
        icon={Lightbulb}
        count={liveInsights.filter((i) => i.status !== "resolved" && i.status !== "ignored").length}
        defaultOpen
      >
        <OpenInsightsList insights={liveInsights} />
      </InsightSection>

      {/* Generated Insights (legacy) */}
      <InsightSection title="Generated Insights (legacy)" icon={Lightbulb} count={insights.length} defaultOpen={false}>
        {insights.length > 0 ? (
          <div className="space-y-2">
            {insights.map((insight, i) => (
              <div key={i} className="flex items-start gap-3 rounded-xl border border-[var(--shell-border)] bg-[var(--shell-panel-soft)] px-4 py-3">
                <SeverityDot severity={insight.severity} />
                <div className="min-w-0 flex-1">
                  <p className="text-sm font-medium text-[var(--shell-text)]">{insight.title}</p>
                  <p className="mt-0.5 text-xs text-[var(--shell-text-muted)]">{insight.explanation}</p>
                </div>
              </div>
            ))}
          </div>
        ) : (
          <p className="text-sm text-[var(--shell-text-muted)]">No insights generated yet. Competitor and probe data will produce insights here.</p>
        )}
      </InsightSection>

      {/* Suggested Actions */}
      <InsightSection title="Suggested Actions" icon={Zap} count={suggestedActions.length} defaultOpen={false}>
        {suggestedActions.length > 0 ? (
          <div className="space-y-2">
            {suggestedActions.map((action, i) => (
              <div key={i} className="flex items-start gap-3 rounded-xl border border-[var(--shell-border)] bg-[var(--shell-panel-soft)] px-4 py-3">
                <Zap className="mt-0.5 h-3.5 w-3.5 shrink-0 text-[var(--shell-accent)]" />
                <div className="min-w-0 flex-1">
                  <p className="text-sm font-medium text-[var(--shell-text)]">{action.title}</p>
                  {action.description && <p className="mt-0.5 text-xs text-[var(--shell-text-muted)]">{action.description}</p>}
                  {action.priority && (
                    <span className={`mt-1 inline-block rounded-md px-1.5 py-0.5 text-[10px] font-medium ${
                      action.priority === "high" ? "bg-rose-500/10 text-rose-500"
                        : action.priority === "medium" ? "bg-amber-500/10 text-amber-500"
                          : "bg-emerald-500/10 text-emerald-600"
                    }`}>{action.priority}</span>
                  )}
                </div>
              </div>
            ))}
          </div>
        ) : (
          <p className="text-sm text-[var(--shell-text-muted)]">Run an analysis to generate competitor action recommendations</p>
        )}
      </InsightSection>
    </div>
  );
}

// ── Sub-components ──────────────────────────────────────────

function SeverityDot({ severity }: { severity: "high" | "medium" | "low" }) {
  const color = severity === "high" ? "bg-rose-500" : severity === "medium" ? "bg-amber-500" : "bg-blue-500";
  return <span className={`mt-1.5 inline-block h-2 w-2 shrink-0 rounded-full ${color}`} />;
}
