import { useCallback, useEffect, useRef, useState } from "react";
import { useAuth } from "../contexts/AuthContext";
import { issueCommand, subscribeCommand } from "../db/commands";
import { subscribeLiveEvents } from "../db/boards";
import type { CommandDoc, CommandType } from "../db/collections";

export interface LogLine {
  type: "info" | "error" | "warning" | "step";
  message: string;
  ts: number;
}

interface CommandState {
  status: CommandDoc["status"] | "idle";
  progress: number;
  message: string;
  result: Record<string, unknown> | null;
  error: string | null;
  logLines: LogLine[];
  liveProgress: number;
  liveMessage: string;
}

const IDLE_STATE: CommandState = {
  status: "idle",
  progress: 0,
  message: "",
  result: null,
  error: null,
  logLines: [],
  liveProgress: 0,
  liveMessage: "",
};

const PROBE_RE = /프로브 진행[:\s]*(\d+)\/(\d+)/;
const QUESTION_RE = /(\d+)개 질문 생성 완료/;
const DONE_RE = /프로브 완료/;

function deriveProgressFromLogs(lines: LogLine[]): {
  progress: number;
  message: string;
} {
  let progress = 0;
  let message = "";

  for (let i = lines.length - 1; i >= 0; i--) {
    const line = lines[i];

    if (DONE_RE.test(line.message)) {
      return { progress: 95, message: line.message };
    }

    const probeMatch = line.message.match(PROBE_RE);
    if (probeMatch) {
      const done = parseInt(probeMatch[1], 10);
      const total = parseInt(probeMatch[2], 10);
      progress = Math.round(18 + (done / total) * 67);
      message = `AI 엔진 프로브: ${done}/${total}`;
      return { progress, message };
    }

    const qMatch = line.message.match(QUESTION_RE);
    if (qMatch) {
      return { progress: 15, message: `${qMatch[1]}개 질문 생성 완료` };
    }
  }

  if (lines.length > 0) {
    const last = lines[lines.length - 1];
    if (last.message.includes("질문 생성 중")) {
      return { progress: 10, message: "질문 생성 중" };
    }
    if (last.message.includes("시작")) {
      return { progress: 5, message: last.message };
    }
    return { progress: Math.max(progress, 3), message: last.message };
  }

  return { progress, message };
}

export function useCommand(boardId: string | undefined) {
  const { user } = useAuth();
  const [state, setState] = useState<CommandState>(IDLE_STATE);
  const unsubCmdRef = useRef<(() => void) | null>(null);
  const unsubLiveRef = useRef<(() => void) | null>(null);
  const inFlightRef = useRef(false);

  useEffect(() => {
    if (!boardId) return;
    unsubLiveRef.current?.();
    unsubLiveRef.current = subscribeLiveEvents(boardId, (data) => {
      if (!data) return;
      const lines = (data.logLines ?? []) as LogLine[];
      const derived = deriveProgressFromLogs(lines);
      setState((prev) => ({
        ...prev,
        logLines: lines,
        liveProgress: derived.progress,
        liveMessage: derived.message,
      }));
    });
    return () => {
      unsubCmdRef.current?.();
      unsubLiveRef.current?.();
    };
  }, [boardId]);

  const execute = useCallback(
    async (type: CommandType, params: Record<string, unknown> = {}) => {
      if (!boardId || !user) return;
      // 같은 hook 인스턴스에서 in-flight 요청이 있으면 두 번째 클릭 차단.
      // issueCommand 의 활성 커맨드 재사용 로직과 합쳐 중복 문서 방지.
      if (inFlightRef.current) return;
      inFlightRef.current = true;

      unsubCmdRef.current?.();
      setState((prev) => ({
        ...IDLE_STATE,
        status: "pending",
        logLines: prev.logLines,
      }));

      try {
        const ref = await issueCommand(boardId, user.uid, type, params);

        unsubCmdRef.current = subscribeCommand(boardId, ref.id, (cmd) => {
          setState((prev) => ({
            ...prev,
            status: cmd.status,
            progress: cmd.progress,
            message: cmd.message,
            result: cmd.result,
            error: cmd.error,
          }));
        });

        return ref.id;
      } finally {
        inFlightRef.current = false;
      }
    },
    [boardId, user],
  );

  const reset = useCallback(() => {
    unsubCmdRef.current?.();
    unsubCmdRef.current = null;
    setState((prev) => ({
      ...IDLE_STATE,
      logLines: prev.logLines,
      liveProgress: prev.liveProgress,
      liveMessage: prev.liveMessage,
    }));
  }, []);

  const effectiveProgress = Math.max(state.progress, state.liveProgress);
  const effectiveMessage =
    state.message || state.liveMessage || "";

  return {
    ...state,
    progress: effectiveProgress,
    message: effectiveMessage,
    isIdle: state.status === "idle",
    isRunning: state.status === "pending" || state.status === "running",
    isComplete: state.status === "complete",
    isFailed: state.status === "failed",
    execute,
    reset,
  };
}
