import { Moon, RotateCcw, Search, ShieldCheck, Sparkles, Sun, Trash2 } from "lucide-react";
import { useEffect, useRef, useState } from "react";
import { useNavigate, Link } from "react-router-dom";
import { useQuery, useQueryClient } from "@tanstack/react-query";
import { useShellPreferences } from "../components/ShellPreferences";
import { useAuth } from "../contexts/AuthContext";
import { CACHE_KEYS, LocalCache } from "../contexts/LocalCacheContext";
import { listAllBoards, createBoard, deleteBoard, retryBoard } from "../db/boards";
import { issueCommand } from "../db/commands";

export function Landing() {
  const [url, setUrl] = useState("");
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const navigate = useNavigate();
  const { theme, toggleTheme } = useShellPreferences();
  const { user, isAdmin, signOut } = useAuth();
  const queryClient = useQueryClient();

  const { data: boards, error: boardsError } = useQuery({
    queryKey: ["boards"],
    queryFn: () => listAllBoards(),
    enabled: !!user,
  });

  const retryInFlightRef = useRef<Set<string>>(new Set());
  const autoRestoreAttempted = useRef(false);
  useEffect(() => {
    if (autoRestoreAttempted.current) return;
    if (!user || !boards) return;
    autoRestoreAttempted.current = true;
    let cancelled = false;
    (async () => {
      const savedId = await LocalCache.getString(CACHE_KEYS.SELECTED_BOARD_ID);
      if (!savedId || cancelled) return;
      const match = boards.find((b) => b.id === savedId);
      if (!match || match.status === "failed") {
        await LocalCache.remove(CACHE_KEYS.SELECTED_BOARD_ID);
        return;
      }
      if (cancelled) return;
      await LocalCache.remove(CACHE_KEYS.SELECTED_BOARD_ID);
      if (match.status === "pending" || match.status === "processing") {
        navigate(`/onboarding/${match.id}`, { replace: true });
      } else {
        const savedMenu = (await LocalCache.getString(CACHE_KEYS.SELECTED_MENU_PATH)) ?? "/portal-v3";
        navigate(`/board/${match.id}${savedMenu}`, { replace: true });
      }
    })();
    return () => { cancelled = true; };
  }, [user, boards, navigate]);

  const selectBoard = (boardId: string) => {
    void LocalCache.setString(CACHE_KEYS.SELECTED_BOARD_ID, boardId);
  };

  const openBoard = (boardId: string) => {
    void LocalCache.setString(CACHE_KEYS.SELECTED_BOARD_ID, boardId);
    navigate(`/board/${boardId}/portal-v3`);
  };

  async function handleSubmit(e: React.FormEvent) {
    e.preventDefault();
    let raw = url.trim();
    if (!raw) return;
    if (!/^https?:\/\//i.test(raw)) raw = `https://${raw}`;

    setLoading(true);
    setError(null);

    try {
      const boardId = await createBoard(user!.uid, raw);
      await issueCommand(boardId, user!.uid, "onboard", { url: raw });
      await LocalCache.setString(CACHE_KEYS.SELECTED_BOARD_ID, boardId);
      navigate(`/onboarding/${boardId}`);
    } catch (err) {
      setError(err instanceof Error ? err.message : "보드 생성에 실패했습니다.");
    } finally {
      setLoading(false);
    }
  }

  async function handleRetry(board: { id: string; url: string; domain: string }) {
    if (!user) return;
    if (retryInFlightRef.current.has(board.id)) return;
    retryInFlightRef.current.add(board.id);
    try {
      await retryBoard(board.id);
      await issueCommand(board.id, user.uid, "onboard", { url: board.url });
      await LocalCache.setString(CACHE_KEYS.SELECTED_BOARD_ID, board.id);
      queryClient.invalidateQueries({ queryKey: ["boards"] });
      navigate(`/onboarding/${board.id}`);
    } catch (err) {
      setError(err instanceof Error ? err.message : "재시도에 실패했습니다.");
    } finally {
      retryInFlightRef.current.delete(board.id);
    }
  }

  async function handleDelete(boardId: string, domain: string) {
    if (!confirm(`${domain}의 모든 데이터를 삭제합니다. 계속하시겠습니까?`)) return;
    try {
      await deleteBoard(boardId);
      const saved = await LocalCache.getString(CACHE_KEYS.SELECTED_BOARD_ID);
      if (saved === boardId) {
        await LocalCache.remove(CACHE_KEYS.SELECTED_BOARD_ID);
      }
      queryClient.invalidateQueries({ queryKey: ["boards"] });
    } catch (err) {
      setError(err instanceof Error ? err.message : "삭제에 실패했습니다.");
    }
  }

  const allBoards = boards ?? [];
  const inProgressBoards = allBoards.filter((b) => b.status === "pending" || b.status === "processing");
  const readyBoards = allBoards.filter((b) => b.status !== "pending" && b.status !== "processing");

  return (
    <div className="min-h-screen bg-[radial-gradient(circle_at_top_left,color-mix(in_srgb,var(--shell-accent)_16%,transparent),transparent_35%),linear-gradient(180deg,var(--shell-main),var(--shell-bg))] text-[var(--shell-text)]">
      <div className="mx-auto max-w-[1480px] px-4 py-6 sm:px-6">
        <header className="mb-10 flex items-center justify-between gap-4">
          <div className="flex items-center gap-4">
            <div className="grid h-14 w-14 place-items-center rounded-2xl bg-[linear-gradient(135deg,#5B7CFF_0%,#7D5CFF_100%)] text-2xl font-semibold text-white shadow-[0_16px_32px_rgba(91,124,255,0.28)]">
              G
            </div>
            <div>
              <div className="text-[30px] font-semibold tracking-[-0.04em]">GEO Insight</div>
              <div className="mt-1 text-sm text-[var(--shell-accent)]">AI CMO workspace</div>
            </div>
          </div>

          <div className="flex items-center gap-2">
            {isAdmin && (
              <Link
                to="/admin/users"
                className="shell-transition flex items-center gap-2 rounded-2xl border border-[var(--shell-border)] bg-[var(--shell-panel-soft)] px-4 py-2 text-sm text-[var(--shell-text-muted)] hover:text-[var(--shell-text)]"
              >
                <ShieldCheck className="h-4 w-4" />
                <span>사용자 승인</span>
              </Link>
            )}
            {user && (
              <button
                onClick={() => signOut()}
                className="shell-transition rounded-2xl border border-[var(--shell-border)] bg-[var(--shell-panel-soft)] px-4 py-2 text-sm text-[var(--shell-text-muted)] hover:text-[var(--shell-text)]"
              >
                로그아웃
              </button>
            )}
            <button
              type="button"
              onClick={toggleTheme}
              className="shell-toggle shell-transition flex h-11 items-center gap-2 px-4"
            >
              {theme === "dark" ? <Sun className="h-4 w-4" /> : <Moon className="h-4 w-4" />}
              <span className="text-sm">{theme === "dark" ? "Light UI" : "Dark UI"}</span>
            </button>
          </div>
        </header>

        <div className="grid gap-6 xl:grid-cols-[1.1fr,0.9fr]">
          <section className="shell-panel shell-transition overflow-hidden rounded-[28px] p-6 sm:p-8">
            <div className="text-[11px] uppercase tracking-[0.24em] text-[var(--shell-text-soft)]">AI Chief Marketing Officer</div>
            <div className="mt-5 max-w-2xl">
              <h1 className="text-4xl font-semibold tracking-tight sm:text-4xl">
                고객 사이트를 넣으면 GEO 보드가 바로 열립니다.
              </h1>
              <p className="mt-4 text-base leading-7 text-[var(--shell-text-muted)]">
                웹사이트, 언론/커뮤니티, 키워드, 경쟁사, GEO 노출 구조를 한 번에 분석하고,
                이후 Plan, Action, Reporting까지 같은 보드 안에서 이어집니다.
              </p>
            </div>

            <form onSubmit={handleSubmit} className="mt-8 space-y-4">
              <div className="shell-panel-soft shell-transition flex flex-col gap-3 rounded-[22px] p-3 sm:flex-row sm:items-center">
                <div className="flex flex-1 items-center gap-3 rounded-2xl border border-[var(--shell-border)] bg-[var(--shell-panel-strong)] px-4 py-4">
                  <Search className="h-5 w-5 text-[var(--shell-accent)]" />
                  <input
                    type="text"
                    value={url}
                    onChange={(e) => setUrl(e.target.value)}
                    placeholder="https://example.com"
                    className="shell-transition w-full bg-transparent text-base outline-none placeholder:text-[var(--shell-text-soft)]"
                    disabled={loading}
                    autoFocus
                  />
                </div>
                <button
                  type="submit"
                  disabled={loading || !url.trim()}
                  className="shell-transition rounded-2xl bg-[var(--shell-accent)] px-6 py-4 text-sm font-semibold text-white disabled:cursor-not-allowed disabled:opacity-50"
                >
                  {loading ? "분석 시작 중..." : "Analyze"}
                </button>
              </div>

              {error && <p className="text-sm text-[var(--shell-danger)]">{error}</p>}
            </form>

            <div className="mt-8 grid gap-4 sm:grid-cols-3">
              {[
                ["Analysis", "웹사이트, 언론/커뮤니티, 키워드, 경쟁사"],
                ["Plan", "Forecast, 문제 우선순위, 실행 방향"],
                ["Action", "콘텐츠 생성, 고객 승인, 배포 관리"],
              ].map(([title, body]) => (
                <div key={title} className="shell-panel-soft shell-transition rounded-[22px] p-4">
                  <div className="text-[11px] uppercase tracking-[0.18em] text-[var(--shell-text-soft)]">{title}</div>
                  <div className="mt-3 text-sm leading-6 text-[var(--shell-text-muted)]">{body}</div>
                </div>
              ))}
            </div>
          </section>

          <section className="space-y-6">
            <div className="shell-panel shell-transition rounded-[28px] p-6">
              <div className="flex items-center justify-between gap-3">
                <div>
                  <div className="text-[11px] uppercase tracking-[0.22em] text-[var(--shell-text-soft)]">Workspace</div>
                  <div className="mt-2 text-2xl font-semibold">프로젝트 보드</div>
                </div>
                <Sparkles className="h-5 w-5 text-[var(--shell-accent)]" />
              </div>
              <div className="mt-4 text-sm leading-6 text-[var(--shell-text-muted)]">
                최근 완료된 고객 보드에 바로 진입해서 Dashboard, Analysis, Plan &amp; Predict, Create &amp; Deploy를 이어서 볼 수 있습니다.
              </div>
            </div>

            {inProgressBoards.length > 0 && (
              <div className="shell-panel shell-transition rounded-[28px] p-4 sm:p-5">
                <div className="mb-3 text-[11px] uppercase tracking-[0.22em] text-[var(--shell-text-soft)]">In Progress</div>
                <div className="space-y-3">
                  {inProgressBoards.map((b) => (
                    <Link
                      key={b.id}
                      to={`/onboarding/${b.id}`}
                      onClick={() => selectBoard(b.id)}
                      className="shell-transition flex items-center gap-3 rounded-[20px] border border-[var(--shell-border)] bg-[var(--shell-panel-soft)] px-4 py-4"
                    >
                      <span className="inline-flex h-2.5 w-2.5 shrink-0 animate-pulse rounded-full bg-[var(--shell-secondary)]" />
                      <div className="min-w-0">
                        <div className="truncate text-base font-medium">{b.domain}</div>
                        <div className="mt-1 text-xs text-[var(--shell-text-soft)]">
                          {b.status === "pending" ? "대기 중" : "작업 중"}
                        </div>
                      </div>
                    </Link>
                  ))}
                </div>
              </div>
            )}

            <div className="shell-panel shell-transition rounded-[28px] p-4 sm:p-5">
              <div className="mb-3 text-[11px] uppercase tracking-[0.22em] text-[var(--shell-text-soft)]">Your Boards</div>
              <div className="space-y-3">
                {boardsError ? (
                  <div className="rounded-[22px] border border-dashed border-[var(--shell-danger)]/40 bg-[var(--shell-danger)]/5 px-4 py-8 text-center text-sm text-[var(--shell-danger)]">
                    보드 목록을 불러오지 못했습니다. Firestore 보안 규칙에 boards 컬렉션 읽기 권한이 필요합니다.
                    <div className="mt-2 text-xs text-[var(--shell-text-soft)]">
                      {boardsError instanceof Error ? boardsError.message : String(boardsError)}
                    </div>
                  </div>
                ) : readyBoards.length > 0 ? (
                  readyBoards.map((b) => (
                    <div
                      key={b.id}
                      className="group/board shell-transition flex items-center justify-between gap-3 rounded-[20px] border border-[var(--shell-border)] bg-[var(--shell-panel-soft)] px-4 py-4"
                    >
                      <button
                        type="button"
                        onClick={() => void openBoard(b.id)}
                        className="flex min-w-0 flex-1 items-center gap-3 text-left"
                      >
                        <span className={`inline-flex h-2.5 w-2.5 shrink-0 rounded-full ${
                          b.status === "complete" ? "bg-[var(--shell-positive)]"
                            : b.status === "failed" ? "bg-[var(--shell-danger)]"
                            : "bg-[var(--shell-warning)]"
                        }`} />
                        <div className="min-w-0">
                          <div className="truncate text-base font-medium">{b.siteName || b.domain}</div>
                          <div className="mt-1 flex items-center gap-2 text-xs text-[var(--shell-text-soft)]">
                            <span>{b.createdAt.toLocaleDateString()}</span>
                            {b.status !== "complete" && (
                              <span className={`rounded-md px-1.5 py-0.5 text-[10px] ${
                                b.status === "failed"
                                  ? "bg-[var(--shell-danger)]/15 text-[var(--shell-danger)]"
                                  : "bg-[var(--shell-warning)]/15 text-[var(--shell-warning)]"
                              }`}>
                                {b.status === "failed" ? "실패" : b.status === "processing" ? "작업 중" : "대기 중"}
                              </span>
                            )}
                          </div>
                        </div>
                      </button>
                      <div className="flex items-center gap-1">
                        {b.status === "failed" && (
                          <button
                            onClick={() => void handleRetry({ id: b.id, url: b.url, domain: b.domain })}
                            className="shell-transition flex items-center gap-1.5 rounded-xl border border-[var(--shell-border)] bg-[var(--shell-panel-strong)] px-3 py-1.5 text-xs font-medium text-[var(--shell-text-muted)] hover:text-[var(--shell-text)]"
                            title="다시 분석"
                          >
                            <RotateCcw className="h-3.5 w-3.5" />
                            <span>재시도</span>
                          </button>
                        )}
                        <button
                          onClick={() => handleDelete(b.id, b.domain)}
                          className="shell-transition rounded-xl border border-transparent p-2 text-[var(--shell-text-soft)] opacity-0 hover:border-[var(--shell-border)] hover:bg-[var(--shell-panel-strong)] hover:text-[var(--shell-danger)] group-hover/board:opacity-100"
                          title="전체 삭제"
                        >
                          <Trash2 className="h-4 w-4" />
                        </button>
                      </div>
                    </div>
                  ))
                ) : (
                  <div className="rounded-[22px] border border-dashed border-[var(--shell-border)] px-4 py-8 text-center text-sm text-[var(--shell-text-soft)]">
                    아직 보드가 없습니다. 첫 고객 사이트를 분석하면 여기에 쌓입니다.
                  </div>
                )}
              </div>
            </div>
          </section>
        </div>
      </div>
    </div>
  );
}
