// @ts-nocheck — V3 월간 리포트 카드 + PDF 인쇄.
import { useState } from "react";
import { useParams } from "react-router-dom";
import { useQuery, useQueryClient } from "@tanstack/react-query";
import {
  Sparkles, Calendar, Printer, TrendingUp, TrendingDown, Loader2, AlertTriangle,
  CheckCircle2, BarChart3, Lightbulb, Target, RefreshCw,
} from "lucide-react";
import { v3MeasurementApi } from "./dataHub";

export function V3MonthlyReportCard() {
  const { id: onboardingId } = useParams<{ id: string }>();
  const queryClient = useQueryClient();
  const [yearMonth, setYearMonth] = useState(() => {
    const now = new Date();
    return `${now.getFullYear()}-${String(now.getMonth() + 1).padStart(2, "0")}`;
  });
  const [generating, setGenerating] = useState(false);

  const reportQ = useQuery({
    queryKey: ["portalV3", "v3-monthly", onboardingId, yearMonth],
    queryFn: () => v3MeasurementApi.getMonthlyReport(onboardingId!, yearMonth),
    enabled: !!onboardingId && !!yearMonth,
    staleTime: 5 * 60_000,
  });

  const report = reportQ.data?.report;

  const handleGenerate = async () => {
    if (!onboardingId || generating) return;
    setGenerating(true);
    try {
      await v3MeasurementApi.generateMonthlyReport(onboardingId, yearMonth);
      await new Promise((r) => setTimeout(r, 3000));
      await queryClient.invalidateQueries({
        queryKey: ["portalV3", "v3-monthly", onboardingId, yearMonth],
      });
    } catch {
      // error handled by react-query refetch
    } finally {
      setGenerating(false);
    }
  };

  const handlePrint = () => {
    // 인쇄 전용 스타일 적용을 위해 print 클래스 토글
    document.body.classList.add("printing-monthly-report");
    setTimeout(() => {
      window.print();
      setTimeout(() => document.body.classList.remove("printing-monthly-report"), 500);
    }, 100);
  };

  return (
    <section className="v3-monthly-report rounded-2xl border border-[var(--shell-border)] bg-[var(--shell-panel)] p-5 print:border-none print:bg-white print:text-black">
      <style>{`
        @media print {
          @page { size: A4; margin: 12mm; }
          body.printing-monthly-report > *:not(.v3-monthly-report-print-root),
          body.printing-monthly-report .v3-monthly-print-hide { display: none !important; }
          body.printing-monthly-report .v3-monthly-report { background: white !important; color: #111 !important; border: none !important; padding: 0 !important; max-width: none !important; }
          body.printing-monthly-report * { color: #111 !important; background: transparent !important; }
          body.printing-monthly-report .v3-monthly-print-keep { background: #f5f5f5 !important; }
        }
      `}</style>

      {/* Header — print 에서도 보임 */}
      <div className="flex flex-wrap items-center justify-between gap-3">
        <div>
          <div className="flex items-center gap-1.5 text-[10px] uppercase tracking-[0.22em] text-[var(--shell-text-soft)] print:text-[#666]">
            <Calendar className="h-3.5 w-3.5" /> 월간 리포트 (Monthly Report)
          </div>
          <h2 className="mt-1 text-xl font-semibold text-[var(--shell-text)] print:text-black">
            {yearMonth} {report?.brandName ? `· ${report.brandName}` : ""}
          </h2>
        </div>

        {/* 컨트롤 — print 에서는 숨김 */}
        <div className="v3-monthly-print-hide flex items-center gap-2">
          <input
            type="month"
            value={yearMonth}
            onChange={(e) => setYearMonth(e.target.value)}
            className="rounded-lg border border-[var(--shell-border)] bg-[var(--shell-panel-soft)] px-3 py-1.5 text-sm text-[var(--shell-text)]"
          />
          <button
            onClick={handleGenerate}
            disabled={generating}
            className="flex items-center gap-1.5 rounded-lg border border-[var(--shell-border)] bg-[var(--shell-panel-soft)] px-3 py-1.5 text-sm font-medium text-[var(--shell-text-soft)] hover:bg-[var(--shell-panel)] disabled:opacity-50"
            title="리포트 갱신"
          >
            {generating ? <Loader2 className="h-3.5 w-3.5 animate-spin" /> : <RefreshCw className="h-3.5 w-3.5" />}
          </button>
          <button
            onClick={handlePrint}
            disabled={!report || report.runsCount === 0}
            className="flex items-center gap-1.5 rounded-lg border border-[var(--shell-accent)] bg-[var(--shell-accent)]/10 px-3 py-1.5 text-sm font-medium text-[var(--shell-accent)] hover:bg-[var(--shell-accent)]/20 disabled:opacity-50"
          >
            <Printer className="h-3.5 w-3.5" /> PDF 저장 / 인쇄
          </button>
        </div>
      </div>

      {/* 로딩 / Empty */}
      {reportQ.isLoading && (
        <div className="mt-4 flex items-center gap-2 text-sm text-[var(--shell-text-muted)]">
          <Loader2 className="h-4 w-4 animate-spin" /> Claude 가 월간 인사이트 생성 중... (10-30초)
        </div>
      )}
      {reportQ.isError && (
        <div className="mt-4 rounded-lg border border-red-500/30 bg-red-500/5 p-3 text-xs text-red-300">
          <AlertTriangle className="mr-1 inline h-3.5 w-3.5" />
          월간 리포트 생성 실패: {String((reportQ.error as any)?.message || reportQ.error)}
        </div>
      )}

      {!reportQ.isLoading && !reportQ.isError && !report && (
        <div className="mt-4 rounded-xl border border-dashed border-[var(--shell-border)] bg-[var(--shell-panel-soft)] p-6 text-center text-sm text-[var(--shell-text-muted)]">
          <Calendar className="mx-auto h-5 w-5" />
          <div className="mt-2">{yearMonth} 월간 리포트가 없습니다.</div>
          <button
            onClick={handleGenerate}
            disabled={generating}
            className="mt-3 inline-flex items-center gap-1.5 rounded-lg border border-[var(--shell-accent)] bg-[var(--shell-accent)]/10 px-4 py-2 text-sm font-medium text-[var(--shell-accent)] hover:bg-[var(--shell-accent)]/20 disabled:opacity-50"
          >
            {generating ? <Loader2 className="h-3.5 w-3.5 animate-spin" /> : <RefreshCw className="h-3.5 w-3.5" />}
            {generating ? "생성 중..." : "리포트 생성"}
          </button>
        </div>
      )}

      {report && (
        <div className="mt-5 space-y-5">
          {report.runsCount === 0 ? (
            <div className="rounded-xl border border-dashed border-[var(--shell-border)] bg-[var(--shell-panel-soft)] p-6 text-center text-sm text-[var(--shell-text-muted)]">
              <Calendar className="mx-auto h-5 w-5" />
              <div className="mt-2">{yearMonth} 에는 측정 데이터가 없습니다.</div>
            </div>
          ) : (
            <>
              {/* 헤드라인 */}
              <div className="rounded-xl border border-[var(--shell-accent)]/40 bg-[var(--shell-accent)]/8 p-4 v3-monthly-print-keep">
                <div className="flex items-center gap-2 text-[10px] uppercase tracking-wider text-[var(--shell-accent)]">
                  <Sparkles className="h-3.5 w-3.5" /> Claude 인사이트
                </div>
                <h3 className="mt-1 text-lg font-semibold text-[var(--shell-text)] print:text-black">
                  {report.insightHeadline}
                </h3>
              </div>

              {/* 핵심 지표 4종 */}
              <div className="grid grid-cols-2 gap-2 md:grid-cols-4">
                <MetricBox label="측정 횟수" value={`${report.runsCount}회`} sub={`총 ${report.totalCalls.toLocaleString()} calls`} />
                <MetricBox label="평균 자사 언급률" value={`${report.avgBrandMentionRate.toFixed(1)}%`} sub={evaluateRate(report.avgBrandMentionRate)} />
                <MetricBox label="GPT 평균" value={`${report.avgGptRate.toFixed(1)}%`} />
                <MetricBox label="Gemini 평균" value={`${report.avgGeminiRate.toFixed(1)}%`} />
              </div>

              {/* 트렌드 + Best/Worst */}
              <div className="grid gap-3 md:grid-cols-2">
                <div className="rounded-xl border border-[var(--shell-border)] bg-[var(--shell-panel-soft)] p-4 print:bg-white print:border-gray-300">
                  <div className="text-xs font-semibold text-[var(--shell-text)] print:text-black">월간 추이</div>
                  {report.trend.firstRun != null && report.trend.lastRun != null ? (
                    <div className="mt-2 flex items-center gap-3 text-sm">
                      <span className="text-[var(--shell-text)] print:text-black">{report.trend.firstRun.toFixed(1)}%</span>
                      <span className="text-[var(--shell-text-soft)]">→</span>
                      <span className="text-[var(--shell-text)] print:text-black">{report.trend.lastRun.toFixed(1)}%</span>
                      {report.trend.delta != null && (
                        <span className={`flex items-center gap-1 rounded-full px-2 py-0.5 text-xs font-semibold ${
                          report.trend.delta > 0.5 ? "bg-emerald-500/20 text-emerald-300" :
                          report.trend.delta < -0.5 ? "bg-red-500/20 text-red-300" :
                          "bg-neutral-500/20 text-neutral-300"
                        }`}>
                          {report.trend.delta > 0 ? <TrendingUp className="h-3 w-3" /> : <TrendingDown className="h-3 w-3" />}
                          {report.trend.delta > 0 ? "+" : ""}{report.trend.delta.toFixed(1)}%p
                        </span>
                      )}
                    </div>
                  ) : (
                    <div className="mt-2 text-xs text-[var(--shell-text-muted)]">측정 1회만 — 추이 불가</div>
                  )}
                </div>

                <div className="rounded-xl border border-[var(--shell-border)] bg-[var(--shell-panel-soft)] p-4 print:bg-white print:border-gray-300">
                  <div className="text-xs font-semibold text-[var(--shell-text)] print:text-black">Best / Worst</div>
                  <div className="mt-2 space-y-1 text-xs">
                    {report.bestRun && (
                      <div className="flex items-center gap-2">
                        <span className="rounded-full bg-emerald-500/20 px-1.5 py-0.5 text-[9px] text-emerald-300">BEST</span>
                        <span className="text-[var(--shell-text)] print:text-black font-mono">{report.bestRun.brandRate.toFixed(1)}%</span>
                        <span className="text-[var(--shell-text-soft)]">{report.bestRun.date}</span>
                      </div>
                    )}
                    {report.worstRun && report.worstRun.runId !== report.bestRun?.runId && (
                      <div className="flex items-center gap-2">
                        <span className="rounded-full bg-red-500/20 px-1.5 py-0.5 text-[9px] text-red-300">WORST</span>
                        <span className="text-[var(--shell-text)] print:text-black font-mono">{report.worstRun.brandRate.toFixed(1)}%</span>
                        <span className="text-[var(--shell-text-soft)]">{report.worstRun.date}</span>
                      </div>
                    )}
                  </div>
                </div>
              </div>

              {/* 인사이트 narrative */}
              {report.insightNarrative.length > 0 && (
                <div className="rounded-xl border border-[var(--shell-border)] bg-[var(--shell-panel)] p-4 print:bg-white print:border-gray-300">
                  <div className="flex items-center gap-1.5 text-xs font-semibold text-[var(--shell-text)] print:text-black">
                    <Lightbulb className="h-3.5 w-3.5" /> 월간 분석
                  </div>
                  <ul className="mt-2 space-y-1.5 text-xs leading-6 text-[var(--shell-text-muted)] print:text-gray-700">
                    {report.insightNarrative.map((line, i) => (
                      <li key={i} className="flex items-start gap-1.5">
                        <span className="mt-0.5 text-[var(--shell-text-soft)]">•</span>
                        <span>{line}</span>
                      </li>
                    ))}
                  </ul>
                </div>
              )}

              {/* 강점/약점 TOP */}
              {(report.insightStrengthTop || report.insightWeaknessTop) && (
                <div className="grid gap-3 md:grid-cols-2">
                  {report.insightStrengthTop && (
                    <div className="rounded-xl border border-emerald-500/30 bg-emerald-500/5 p-4 v3-monthly-print-keep">
                      <div className="flex items-center gap-1.5 text-xs font-semibold text-emerald-300 print:text-black">
                        <TrendingUp className="h-3.5 w-3.5" /> 최대 강점
                      </div>
                      <p className="mt-1.5 text-xs leading-5 text-emerald-200 print:text-black">{report.insightStrengthTop}</p>
                    </div>
                  )}
                  {report.insightWeaknessTop && (
                    <div className="rounded-xl border border-red-500/30 bg-red-500/5 p-4 v3-monthly-print-keep">
                      <div className="flex items-center gap-1.5 text-xs font-semibold text-red-300 print:text-black">
                        <TrendingDown className="h-3.5 w-3.5" /> 최대 약점
                      </div>
                      <p className="mt-1.5 text-xs leading-5 text-red-200 print:text-black">{report.insightWeaknessTop}</p>
                    </div>
                  )}
                </div>
              )}

              {/* 다음 달 추천 */}
              {report.insightRecommendations.length > 0 && (
                <div className="rounded-xl border border-blue-500/30 bg-blue-500/5 p-4 v3-monthly-print-keep">
                  <div className="flex items-center gap-1.5 text-xs font-semibold text-blue-300 print:text-black">
                    <Target className="h-3.5 w-3.5" /> 다음 달 추천 액션
                  </div>
                  <ol className="mt-2 space-y-1.5 text-xs leading-5 text-blue-200 print:text-black">
                    {report.insightRecommendations.map((r, i) => (
                      <li key={i} className="flex gap-2">
                        <span className="shrink-0 font-semibold">{i + 1}.</span>
                        <span>{r}</span>
                      </li>
                    ))}
                  </ol>
                </div>
              )}

              {/* 액션 효과 */}
              <div className="grid grid-cols-3 gap-2">
                <MetricBox label="완료 액션" value={`${report.actionsCompleted}건`} />
                <MetricBox label="효과 측정 완료" value={`${report.actionsWithEffect}건`} sub={`/${report.actionsCompleted}`} />
                <MetricBox label="양 효과 (+1%p+)" value={`${report.actionsPositiveEffect}건`} sub={
                  report.actionsWithEffect > 0
                    ? `${((report.actionsPositiveEffect / report.actionsWithEffect) * 100).toFixed(0)}% 적중`
                    : "—"
                } tone={report.actionsPositiveEffect > 0 ? "good" : "info"} />
              </div>

              {/* 경쟁사 */}
              {report.competitorAverages.length > 0 && (
                <div className="rounded-xl border border-[var(--shell-border)] bg-[var(--shell-panel)] p-4 print:bg-white print:border-gray-300">
                  <div className="flex items-center gap-1.5 text-xs font-semibold text-[var(--shell-text)] print:text-black">
                    <BarChart3 className="h-3.5 w-3.5" /> 경쟁사 평균 언급률 (자사 답변 내)
                  </div>
                  <ul className="mt-2 space-y-1.5">
                    {/* 자사 vs 경쟁사 비교 */}
                    <li className="flex items-center justify-between text-xs">
                      <span className="font-semibold text-emerald-300 print:text-black">{report.brandName || "자사"} (기준)</span>
                      <span className="font-mono text-[var(--shell-text)] print:text-black">{report.avgBrandMentionRate.toFixed(1)}%</span>
                    </li>
                    {report.competitorAverages.slice(0, 8).map((c) => (
                      <li key={c.name} className="flex items-center justify-between text-xs">
                        <span className="text-[var(--shell-text)] print:text-black">{c.name}</span>
                        <span className="font-mono text-[var(--shell-text-muted)] print:text-black">{c.avgRate.toFixed(1)}%</span>
                      </li>
                    ))}
                  </ul>
                </div>
              )}

              {/* 메타 */}
              <div className="text-[10px] text-[var(--shell-text-soft)] print:text-gray-500">
                생성: {new Date(report.generatedAt).toLocaleString()} · 모델: {report.generatorModel}
              </div>
            </>
          )}
        </div>
      )}
    </section>
  );
}

function MetricBox({ label, value, sub, tone }: { label: string; value: string; sub?: string; tone?: "good" | "info" }) {
  const t = tone === "good"
    ? "border-emerald-500/30 bg-emerald-500/5 text-emerald-300"
    : "border-[var(--shell-border)] bg-[var(--shell-panel-soft)] text-[var(--shell-text)]";
  return (
    <div className={`rounded-lg border p-3 print:bg-white print:border-gray-300 print:text-black ${t}`}>
      <div className="text-[10px] uppercase tracking-wider opacity-70">{label}</div>
      <div className="mt-1 text-xl font-semibold">{value}</div>
      {sub && <div className="text-[10px] opacity-70">{sub}</div>}
    </div>
  );
}

function evaluateRate(rate: number): string {
  if (rate >= 80) return "매우 우수";
  if (rate >= 60) return "우수";
  if (rate >= 40) return "보통";
  return "미흡";
}
