// @ts-nocheck — V3 측정 삭제 전 미리보기 모달 (Danger Zone 스타일)
import { useEffect, useMemo, useState } from "react";
import {
  AlertTriangle, Loader2, Trash2, X, Clock, ChevronDown, ChevronUp, ShieldAlert,
} from "lucide-react";
import { v3MeasurementApi } from "./dataHub";
import type { V3PreviewDeleteResponse } from "./dataHub/types";

const COLLAPSE_THRESHOLD = 5;

interface Props {
  onboardingId: string;
  runIds: string[];
  isOpen: boolean;
  onClose: () => void;
  onConfirm: (eligibleIds: string[]) => Promise<void> | void;
  mode: "single" | "bulk";
}

export function V3DeletePreviewModal({ onboardingId, runIds, isOpen, onClose, onConfirm, mode }: Props) {
  const [loading, setLoading] = useState(false);
  const [preview, setPreview] = useState<V3PreviewDeleteResponse | null>(null);
  const [err, setErr] = useState<string | null>(null);
  const [confirming, setConfirming] = useState(false);
  const [showAllEligible, setShowAllEligible] = useState(false);
  const [showAllBlocked, setShowAllBlocked] = useState(false);
  const [holdProgress, setHoldProgress] = useState(0);
  const [holdTimer, setHoldTimer] = useState<ReturnType<typeof setInterval> | null>(null);

  useEffect(() => {
    if (!isOpen) return;
    setLoading(true);
    setErr(null);
    setPreview(null);
    setShowAllEligible(false);
    setShowAllBlocked(false);
    v3MeasurementApi.previewDelete(onboardingId, runIds)
      .then((res) => setPreview(res))
      .catch((e: any) => setErr(e?.message || "미리보기 실패"))
      .finally(() => setLoading(false));
  }, [isOpen, onboardingId, runIds.join(",")]);

  const eligibleItems = preview?.eligible || [];
  const blockedItems = preview?.blocked || [];
  const eligibleIds = useMemo(() => eligibleItems.map((i) => i.runId), [eligibleItems]);

  if (!isOpen) return null;

  const handleConfirm = async () => {
    if (eligibleIds.length === 0) return;
    setConfirming(true);
    try {
      await onConfirm(eligibleIds);
      onClose();
    } catch (e: any) {
      setErr(e?.message || "삭제 실패");
    } finally {
      setConfirming(false);
    }
  };

  const startHold = () => {
    if (confirming || loading || eligibleIds.length === 0) return;
    setHoldProgress(0);
    const interval = setInterval(() => {
      setHoldProgress((prev) => {
        const next = prev + (100 / 15);
        if (next >= 100) {
          clearInterval(interval);
          setHoldTimer(null);
          handleConfirm();
          return 100;
        }
        return next;
      });
    }, 100);
    setHoldTimer(interval);
  };

  const cancelHold = () => {
    if (holdTimer) {
      clearInterval(holdTimer);
      setHoldTimer(null);
    }
    setHoldProgress(0);
  };

  const visibleEligible = showAllEligible ? eligibleItems : eligibleItems.slice(0, COLLAPSE_THRESHOLD);
  const visibleBlocked = showAllBlocked ? blockedItems : blockedItems.slice(0, COLLAPSE_THRESHOLD);
  const hiddenEligibleCount = eligibleItems.length - visibleEligible.length;
  const hiddenBlockedCount = blockedItems.length - visibleBlocked.length;

  return (
    <div
      className="fixed inset-0 z-50 flex items-center justify-center bg-black/70 p-4"
      onClick={(e) => { if (e.target === e.currentTarget) onClose(); }}
    >
      <div className="w-full max-w-2xl rounded-2xl border-2 border-red-500/40 bg-[var(--shell-panel)] shadow-2xl shadow-red-500/20 ring-1 ring-red-500/20">
        {/* Header */}
        <div className="rounded-t-2xl border-b-2 border-red-500/40 bg-gradient-to-r from-red-500/15 via-red-500/10 to-red-500/15 px-5 py-4">
          <div className="flex items-start justify-between gap-3">
            <div className="flex items-start gap-3">
              <div className="rounded-full bg-red-500/25 p-2.5 ring-2 ring-red-500/30">
                <ShieldAlert className="h-4 w-4 text-red-300" />
              </div>
              <div>
                <div className="flex items-center gap-2">
                  <span className="rounded bg-red-500/30 px-1.5 py-0.5 text-[9px] font-bold uppercase tracking-wider text-red-100">
                    Danger Zone
                  </span>
                  <h3 className="text-sm font-semibold text-[var(--shell-text)]">
                    {mode === "single" ? "측정 1건 영구 삭제" : `측정 ${runIds.length}건 일괄 영구 삭제`}
                  </h3>
                </div>
                <p className="mt-1 text-[11px] text-red-200/80">
                  raw data + Claude 분석 결과가 모두 삭제됩니다. <strong>복구 불가</strong>.
                </p>
              </div>
            </div>
            <button
              type="button"
              onClick={onClose}
              disabled={confirming}
              className="rounded p-1 text-[var(--shell-text-soft)] hover:bg-[var(--shell-panel-soft)] hover:text-[var(--shell-text)] disabled:opacity-40"
              aria-label="닫기"
            >
              <X className="h-4 w-4" />
            </button>
          </div>
        </div>

        {/* Body */}
        <div className="max-h-[60vh] overflow-y-auto p-5">
          {loading && (
            <div className="flex items-center gap-2 rounded-lg border border-[var(--shell-border)] bg-[var(--shell-panel-soft)] px-3 py-4 text-[12px] text-[var(--shell-text-muted)]">
              <Loader2 className="h-4 w-4 animate-spin" />
              삭제 대상 정보 불러오는 중...
            </div>
          )}

          {err && (
            <div className="flex items-start gap-2 rounded-lg border border-red-500/40 bg-red-500/10 px-3 py-2.5 text-[11px] text-red-200">
              <AlertTriangle className="mt-0.5 h-3.5 w-3.5 shrink-0" />
              <span>{err}</span>
            </div>
          )}

          {preview && !loading && (
            <>
              {/* 요약 카드 */}
              <div className="mb-4 grid gap-2 sm:grid-cols-3">
                <div className="rounded-lg border border-[var(--shell-border)] bg-[var(--shell-panel-soft)] px-3 py-2">
                  <div className="text-[9px] uppercase tracking-wider text-[var(--shell-text-soft)]">요청</div>
                  <div className="text-base font-semibold text-[var(--shell-text)] tabular-nums">{runIds.length}</div>
                </div>
                <div className="rounded-lg border-2 border-red-500/50 bg-red-500/15 px-3 py-2">
                  <div className="text-[9px] uppercase tracking-wider text-red-300">삭제 예정</div>
                  <div className="text-base font-bold text-red-200 tabular-nums">{preview.totalEligible}</div>
                </div>
                <div className={`rounded-lg border px-3 py-2 ${
                  preview.totalBlocked > 0
                    ? "border-amber-500/40 bg-amber-500/10"
                    : "border-[var(--shell-border)] bg-[var(--shell-panel-soft)]"
                }`}>
                  <div className={`text-[9px] uppercase tracking-wider ${
                    preview.totalBlocked > 0 ? "text-amber-300" : "text-[var(--shell-text-soft)]"
                  }`}>건너뜀</div>
                  <div className={`text-base font-semibold tabular-nums ${
                    preview.totalBlocked > 0 ? "text-amber-200" : "text-[var(--shell-text)]"
                  }`}>{preview.totalBlocked}</div>
                </div>
              </div>

              {/* 삭제 예정 리스트 */}
              {eligibleItems.length > 0 && (
                <div className="mb-3">
                  <div className="mb-1.5 text-[10px] font-semibold uppercase tracking-wider text-red-300">
                    삭제 예정 ({eligibleItems.length}건)
                  </div>
                  <ItemTable items={visibleEligible} tone="delete" />
                  {hiddenEligibleCount > 0 && (
                    <button
                      type="button"
                      onClick={() => setShowAllEligible(true)}
                      className="mt-1.5 flex w-full items-center justify-center gap-1 rounded-lg border border-dashed border-red-500/40 bg-red-500/5 px-3 py-1.5 text-[10px] text-red-300 hover:bg-red-500/10"
                    >
                      <ChevronDown className="h-3 w-3" />
                      +{hiddenEligibleCount}건 더보기
                    </button>
                  )}
                  {showAllEligible && eligibleItems.length > COLLAPSE_THRESHOLD && (
                    <button
                      type="button"
                      onClick={() => setShowAllEligible(false)}
                      className="mt-1.5 flex w-full items-center justify-center gap-1 rounded-lg border border-dashed border-[var(--shell-border)] bg-[var(--shell-panel-soft)] px-3 py-1.5 text-[10px] text-[var(--shell-text-soft)] hover:bg-[var(--shell-panel)]"
                    >
                      <ChevronUp className="h-3 w-3" />
                      접기
                    </button>
                  )}
                </div>
              )}

              {/* Blocked 리스트 */}
              {blockedItems.length > 0 && (
                <div className="mb-3 rounded-lg border border-amber-500/40 bg-amber-500/5 p-2.5">
                  <div className="mb-1.5 flex items-start gap-2">
                    <AlertTriangle className="mt-0.5 h-3.5 w-3.5 shrink-0 text-amber-300" />
                    <div className="text-[11px] text-amber-200">
                      <strong>{blockedItems.length}건 건너뜀</strong> — 진행 중이거나 분석 중인 측정은 완료 후 다시 시도해주세요.
                    </div>
                  </div>
                  <ItemTable items={visibleBlocked} tone="blocked" />
                  {hiddenBlockedCount > 0 && (
                    <button
                      type="button"
                      onClick={() => setShowAllBlocked(true)}
                      className="mt-1.5 flex w-full items-center justify-center gap-1 rounded-lg border border-dashed border-amber-500/40 bg-amber-500/5 px-3 py-1.5 text-[10px] text-amber-300 hover:bg-amber-500/10"
                    >
                      <ChevronDown className="h-3 w-3" />
                      +{hiddenBlockedCount}건 더보기
                    </button>
                  )}
                </div>
              )}

              {eligibleItems.length === 0 && blockedItems.length === 0 && (
                <div className="rounded-lg border border-[var(--shell-border)] bg-[var(--shell-panel-soft)] px-3 py-4 text-center text-[11px] text-[var(--shell-text-muted)]">
                  삭제 대상이 없습니다.
                </div>
              )}
            </>
          )}
        </div>

        {/* Footer — Hold-to-confirm */}
        <div className="rounded-b-2xl border-t-2 border-red-500/40 bg-gradient-to-r from-red-500/10 via-red-500/15 to-red-500/10 px-5 py-3.5">
          <div className="flex flex-wrap items-center justify-between gap-2">
            <div className="text-[10px] text-red-200/90">
              {preview && eligibleIds.length > 0 ? (
                <div className="flex items-center gap-1">
                  <AlertTriangle className="h-3 w-3 text-red-300" />
                  <span>
                    이 작업은 <strong className="text-red-100">취소할 수 없습니다</strong>.
                    버튼을 <strong className="text-red-100">1.5초간 누르고 있어야</strong> 실행됩니다.
                  </span>
                </div>
              ) : (
                <span className="text-[var(--shell-text-soft)]">삭제 가능한 항목 없음</span>
              )}
            </div>
            <div className="flex items-center gap-2">
              <button
                type="button"
                onClick={onClose}
                disabled={confirming}
                className="rounded-lg border border-[var(--shell-border)] bg-[var(--shell-panel-soft)] px-3 py-2 text-[11px] font-medium text-[var(--shell-text)] hover:bg-[var(--shell-panel)] disabled:opacity-40"
              >
                취소
              </button>
              <button
                type="button"
                onMouseDown={startHold}
                onMouseUp={cancelHold}
                onMouseLeave={cancelHold}
                onTouchStart={startHold}
                onTouchEnd={cancelHold}
                disabled={confirming || loading || eligibleIds.length === 0}
                title="삭제 버튼을 1.5초간 누르고 있어야 실행됩니다 (실수 방지)"
                className="relative flex items-center gap-1.5 overflow-hidden rounded-lg border-2 border-red-500/60 bg-red-600/40 px-4 py-2 text-[12px] font-semibold text-white shadow-lg shadow-red-500/20 hover:bg-red-600/60 disabled:opacity-40 disabled:shadow-none"
              >
                <div
                  className="absolute inset-0 bg-red-500/50 transition-none"
                  style={{ width: `${holdProgress}%` }}
                />
                <span className="relative z-10 flex items-center gap-1.5">
                  {confirming ? <Loader2 className="h-3.5 w-3.5 animate-spin" /> : <Trash2 className="h-3.5 w-3.5" />}
                  {confirming
                    ? "삭제 중..."
                    : eligibleIds.length === 0
                      ? "삭제할 항목 없음"
                      : `${eligibleIds.length}건 영구 삭제 (1.5초 누르기)`}
                </span>
              </button>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
}

function ItemTable({ items, tone }: {
  items: Array<{ runId: string; completedAt?: string; totalCalls?: number; reason?: string }>;
  tone: "delete" | "blocked";
}) {
  return (
    <div className="overflow-x-auto rounded-lg border border-[var(--shell-border)]">
      <table className="w-full min-w-[360px] text-[11px]">
        <thead className="bg-[var(--shell-panel-soft)]">
          <tr className="text-left text-[9px] uppercase tracking-wider text-[var(--shell-text-soft)]">
            <th className="px-2 py-1.5">측정 일시</th>
            <th className="px-2 py-1.5 text-right">Calls</th>
            <th className="px-2 py-1.5">runId</th>
          </tr>
        </thead>
        <tbody>
          {items.map((item) => (
            <tr
              key={item.runId}
              className={`border-t border-[var(--shell-border)] ${
                tone === "blocked" ? "bg-amber-500/5" : "bg-red-500/5"
              }`}
            >
              <td className="px-2 py-1.5 text-[var(--shell-text)]">
                <div className="flex items-center gap-1.5">
                  <Clock className="h-3 w-3 text-[var(--shell-text-soft)]" />
                  {item.completedAt
                    ? new Date(item.completedAt).toLocaleString()
                    : "—"}
                </div>
              </td>
              <td className="px-2 py-1.5 text-right font-mono text-[var(--shell-text-muted)]">
                {item.totalCalls ?? "—"}
              </td>
              <td className="px-2 py-1.5 font-mono text-[10px] text-[var(--shell-text-soft)]">
                {item.runId.slice(0, 8)}...
              </td>
            </tr>
          ))}
        </tbody>
      </table>
    </div>
  );
}
