import { useCallback, useEffect, useState } from "react";
import { useParams } from "react-router-dom";
import {
  Camera, FileText, Target, TrendingUp, Zap,
} from "lucide-react";
import {
  getDocument,
  getSummary,
  listActionRuns,
  listReports,
  listTrendSnapshots,
} from "../../db/boards";
import { useCommand } from "../../hooks/useCommand";
import { TabLayout, useActiveTab, type TabDef } from "../../components/shared/TabLayout";
import { MetricCard } from "../../components/shared/MetricCard";
import { EmptyState } from "../../components/shared/EmptyState";

// ── Types ──────────────────────────────────────────────────

interface SnapshotMetrics {
  mentionRate: number;
  exposureRate: number;
  weightedMentionRate: number;
  mentionCount: number;
}

interface EngineBreakdown {
  engine: string;
  mentionRate: number;
  mentioned: boolean;
  change?: number;
}

interface Snapshot {
  id: string;
  capturedAt: string;
  metrics: SnapshotMetrics;
  engineBreakdown?: EngineBreakdown[];
  actions?: Array<{ id: string; title: string; status: string }>;
}

interface Report {
  id: string;
  title?: string;
  headline?: string;
  body?: string;
  summary?: string;
  content?: string;
  overview?: string[];
  weekLabel?: string;
  period?: string;
  snapshotCount?: number;
  actionsExecuted?: number;
  highlights?: string[];
  engineBreakdown?: EngineBreakdown[];
  weeklyChanges?: { mentionRate?: number; exposureRate?: number; newKeywords?: number };
  createdAt?: { toDate?: () => Date } | Date | string;
}

interface ActionRun {
  id: string;
  title?: string;
  status?: string;
  platform?: string;
  createdAt?: string;
  completedAt?: string;
  beforeMetrics?: SnapshotMetrics;
  afterMetrics?: SnapshotMetrics;
}

// ── Tabs ────────────────────────────────────────────────────

export const PERFORMANCE_TABS: TabDef[] = [
  { label: "Trends", slug: "trends", icon: TrendingUp },
  { label: "Reports", slug: "reports", icon: FileText },
  { label: "Snapshots", slug: "snapshots", icon: Camera },
  { label: "Forecast", slug: "forecast", icon: Target },
  { label: "Action Impact", slug: "impact", icon: Zap },
];

export function Performance() {
  const activeTab = useActiveTab(PERFORMANCE_TABS, "workspace/performance");
  const { id } = useParams<{ id: string }>();
  const cmd = useCommand(id);

  const [snapshots, setSnapshots] = useState<Snapshot[]>([]);
  const [reports, setReports] = useState<Report[]>([]);
  const [weeklyReport, setWeeklyReport] = useState<Record<string, unknown> | null>(null);
  const [diffDoc, setDiffDoc] = useState<Record<string, unknown> | null>(null);
  const [actionRuns, setActionRuns] = useState<ActionRun[]>([]);
  const [loading, setLoading] = useState(true);

  const load = useCallback(async () => {
    if (!id) return;
    setLoading(true);
    const [snaps, reps, wr, diff, runs] = await Promise.all([
      listTrendSnapshots(id).catch(() => []),
      listReports(id, 10).catch(() => []),
      getDocument(id, "weekly-report").catch(() => null),
      getSummary(id, "brand-gap").catch(() => null),
      listActionRuns(id).catch(() => []),
    ]);
    setSnapshots(snaps as Snapshot[]);
    setReports(reps as Report[]);
    if (wr?.data) setWeeklyReport(wr.data as Record<string, unknown>);
    if (diff) setDiffDoc(diff as Record<string, unknown>);
    setActionRuns(runs as ActionRun[]);
    setLoading(false);
  }, [id]);

  useEffect(() => { load(); }, [load]);

  const handleSnapshot = async () => {
    await cmd.execute("create_trend_snapshot");
    setTimeout(load, 2000);
  };

  const handleReport = async () => {
    await cmd.execute("create_weekly_report");
    setTimeout(load, 3000);
  };

  return (
    <TabLayout
      title="Performance"
      description="추이, 리포트, 스냅샷, 성능 추적을 한곳에서 확인합니다"
      tabs={PERFORMANCE_TABS}
      basePath="workspace/performance"
      actions={
        <div className="flex items-center gap-2">
          <button type="button" onClick={handleReport} disabled={cmd.isRunning} className="rounded-xl border border-[var(--shell-border)] px-3 py-2 text-xs font-medium text-[var(--shell-text)] transition-colors hover:border-[var(--shell-accent)] hover:text-[var(--shell-accent)] disabled:opacity-50">
            {cmd.isRunning ? "Generating..." : "Generate Report"}
          </button>
          <button type="button" onClick={handleSnapshot} disabled={cmd.isRunning} className="rounded-xl border border-[var(--shell-border)] px-3 py-2 text-xs font-medium text-[var(--shell-text)] transition-colors hover:border-[var(--shell-accent)] hover:text-[var(--shell-accent)] disabled:opacity-50">
            {cmd.isRunning ? "Capturing..." : "Take Snapshot"}
          </button>
        </div>
      }
    >
      {loading ? (
        <div className="flex min-h-[30vh] items-center justify-center text-sm text-[var(--shell-text-muted)]">Loading...</div>
      ) : (
        <>
          {activeTab === "trends" && <TrendsTab snapshots={snapshots} weeklyReport={weeklyReport} />}
          {activeTab === "reports" && <ReportsTab reports={reports} snapshotCount={snapshots.length} actionCount={actionRuns.filter((r) => r.status === "complete" || r.status === "done").length} />}
          {activeTab === "snapshots" && <SnapshotsTab snapshots={snapshots} />}
          {activeTab === "forecast" && <ForecastTab diffDoc={diffDoc} snapshots={snapshots} />}
          {activeTab === "impact" && <ActionImpactTab actionRuns={actionRuns} />}
        </>
      )}
    </TabLayout>
  );
}

// ── Trends Tab ─────────────────────────────────────────────

function TrendsTab({ snapshots, weeklyReport }: { snapshots: Snapshot[]; weeklyReport: Record<string, unknown> | null }) {
  const latest = snapshots[snapshots.length - 1] ?? null;
  const previous = snapshots.length > 1 ? snapshots[snapshots.length - 2] : null;
  const engineBreakdown = Array.isArray(weeklyReport?.engineBreakdown) ? (weeklyReport.engineBreakdown as EngineBreakdown[]) : null;
  const snapshotEngines = latest?.engineBreakdown ?? [];
  const delta = latest && previous ? {
    mentionRate: latest.metrics.mentionRate - previous.metrics.mentionRate,
    exposureRate: latest.metrics.exposureRate - previous.metrics.exposureRate,
    weighted: latest.metrics.weightedMentionRate - previous.metrics.weightedMentionRate,
  } : null;

  return (
    <div className="space-y-6">
      {/* Metric cards with sparklines */}
      <div className="grid gap-4 sm:grid-cols-3">
        <TrendCard label="Mention Rate" value={`${latest?.metrics.mentionRate ?? 0}%`} delta={delta ? delta.mentionRate : undefined} snapshots={snapshots} valueKey="mentionRate" color="var(--shell-accent)" />
        <TrendCard label="Exposure Rate" value={`${latest?.metrics.exposureRate ?? 0}%`} delta={delta ? delta.exposureRate : undefined} snapshots={snapshots} valueKey="exposureRate" color="var(--shell-positive)" />
        <TrendCard label="Weighted Mention" value={`${latest?.metrics.weightedMentionRate ?? 0}%`} delta={delta ? delta.weighted : undefined} snapshots={snapshots} valueKey="weightedMentionRate" color="var(--shell-warning)" />
      </div>

      {/* Engine breakdown from weekly report */}
      {engineBreakdown && engineBreakdown.length > 0 && (
        <div className="rounded-2xl border border-[var(--shell-border)] bg-[var(--shell-panel)] p-5">
          <h3 className="text-sm font-semibold text-[var(--shell-text)]">Engine Breakdown</h3>
          <div className="mt-3 grid gap-3 sm:grid-cols-2 lg:grid-cols-4">
            {engineBreakdown.map((eng) => (
              <div key={eng.engine} className="rounded-xl border border-[var(--shell-border)] bg-[var(--shell-panel-soft)] p-4 text-center">
                <p className="text-xs uppercase tracking-wider text-[var(--shell-text-muted)]">{eng.engine}</p>
                <p className="mt-1 text-2xl font-semibold text-[var(--shell-text)]">{eng.mentionRate}%</p>
                {eng.change != null && eng.change !== 0 && (
                  <p className={`mt-0.5 text-xs ${eng.change > 0 ? "text-emerald-600" : "text-rose-500"}`}>
                    {eng.change > 0 ? "+" : ""}{eng.change}%
                  </p>
                )}
              </div>
            ))}
          </div>
        </div>
      )}

      {/* Engine breakdown from latest snapshot */}
      {snapshotEngines.length > 0 && !engineBreakdown && (
        <div className="rounded-2xl border border-[var(--shell-border)] bg-[var(--shell-panel)] p-5">
          <h3 className="text-sm font-semibold text-[var(--shell-text)]">Engine Breakdown (Latest Snapshot)</h3>
          <div className="mt-3 space-y-2">
            {snapshotEngines.map((eng, i) => (
              <div key={i} className="flex items-center justify-between rounded-xl border border-[var(--shell-border)] bg-[var(--shell-panel-soft)] px-4 py-3">
                <div className="flex items-center gap-2">
                  <span className={`inline-block h-2 w-2 rounded-full ${eng.mentioned ? "bg-emerald-500" : "bg-rose-500"}`} />
                  <span className="text-sm text-[var(--shell-text)]">{eng.engine}</span>
                </div>
                <div className="flex items-center gap-3 text-xs">
                  <span className="text-[var(--shell-text-muted)]">{eng.mentionRate}%</span>
                  <span className={`rounded-md px-2 py-0.5 text-[10px] font-medium ${eng.mentioned ? "bg-emerald-500/10 text-emerald-600" : "bg-rose-500/10 text-rose-500"}`}>
                    {eng.mentioned ? "Mentioned" : "Not mentioned"}
                  </span>
                </div>
              </div>
            ))}
          </div>
        </div>
      )}

      {/* Weekly headline */}
      {weeklyReport != null && typeof weeklyReport.headline === "string" && (
        <div className="rounded-2xl border border-[var(--shell-border)] bg-[var(--shell-panel)] p-5">
          <h3 className="text-sm font-semibold text-[var(--shell-text)]">Latest Weekly Report</h3>
          <p className="mt-2 text-lg font-semibold text-[var(--shell-text)]">{String(weeklyReport.headline)}</p>
          {Array.isArray(weeklyReport.overview) && (
            <ul className="mt-2 space-y-1">
              {(weeklyReport.overview as string[]).map((item, i) => (
                <li key={i} className="flex items-start gap-2 text-sm text-[var(--shell-text-muted)]">
                  <span className="mt-0.5 text-emerald-600">*</span>{item}
                </li>
              ))}
            </ul>
          )}
        </div>
      )}

      {snapshots.length === 0 && (
        <EmptyState icon={TrendingUp} title="No trend data" description="스냅샷을 찍으면 가시성 지표 추적이 시작됩니다" />
      )}
    </div>
  );
}

// ── Reports Tab ────────────────────────────────────────────

function ReportsTab({ reports, snapshotCount, actionCount }: { reports: Report[]; snapshotCount: number; actionCount: number }) {
  return (
    <div className="space-y-6">
      <div className="grid gap-4 sm:grid-cols-3">
        <MetricCard icon={FileText} label="Reports" value={String(reports.length)} color="text-blue-600" />
        <MetricCard icon={Camera} label="Snapshots" value={String(snapshotCount)} color="text-teal-600" />
        <MetricCard icon={Zap} label="Actions Done" value={String(actionCount)} color="text-emerald-600" />
      </div>

      {reports.length > 0 ? (
        <div className="space-y-4">
          {reports.map((r) => {
            const title = r.title || r.headline || r.weekLabel || r.period || "Report";
            const content = r.body || r.content || r.summary || "";
            const date = formatDate(r.createdAt);
            return (
              <div key={r.id} className="rounded-2xl border border-[var(--shell-border)] bg-[var(--shell-panel)] p-5">
                <div className="flex items-start justify-between gap-4">
                  <div>
                    <h4 className="text-sm font-semibold text-[var(--shell-text)]">{title}</h4>
                    {date && <p className="mt-0.5 text-[10px] text-[var(--shell-text-muted)]">{date}</p>}
                  </div>
                  <div className="flex gap-2 text-[10px] text-[var(--shell-text-muted)]">
                    {r.snapshotCount != null && <span className="rounded-md bg-[var(--shell-panel-soft)] px-2 py-1">{r.snapshotCount} snapshots</span>}
                    {r.actionsExecuted != null && <span className="rounded-md bg-[var(--shell-panel-soft)] px-2 py-1">{r.actionsExecuted} actions</span>}
                  </div>
                </div>
                {r.highlights && r.highlights.length > 0 && (
                  <div className="mt-3 space-y-1">
                    {r.highlights.map((h, i) => (
                      <div key={i} className="rounded-xl border border-[var(--shell-border)] bg-[var(--shell-panel-soft)] px-3 py-2 text-xs text-[var(--shell-text-muted)]">{h}</div>
                    ))}
                  </div>
                )}
                {r.overview && r.overview.length > 0 && !r.highlights?.length && (
                  <div className="mt-3 text-xs leading-relaxed text-[var(--shell-text-muted)]">
                    {r.overview.slice(0, 3).join(" | ")}
                  </div>
                )}
                {content && (
                  <p className="mt-3 line-clamp-4 whitespace-pre-wrap text-sm leading-relaxed text-[var(--shell-text-muted)]">{content}</p>
                )}
              </div>
            );
          })}
        </div>
      ) : (
        <EmptyState icon={FileText} title="No reports yet" description="Generate Report를 누르면 첫 주간 리포트가 생성됩니다" />
      )}
    </div>
  );
}

// ── Snapshots Tab ──────────────────────────────────────────

function SnapshotsTab({ snapshots }: { snapshots: Snapshot[] }) {
  if (snapshots.length === 0) {
    return <EmptyState icon={Camera} title="No snapshots" description="스냅샷을 찍으면 현재 가시성 지표가 기록됩니다" />;
  }

  return (
    <div className="space-y-6">
      <div className="grid gap-4 sm:grid-cols-2">
        <MetricCard icon={Camera} label="Total Snapshots" value={String(snapshots.length)} color="text-blue-600" />
        <MetricCard icon={Camera} label="Latest" value={snapshots[snapshots.length - 1]?.capturedAt?.slice(0, 10) ?? "--"} color="text-teal-600" />
      </div>

      <div className="overflow-x-auto rounded-2xl border border-[var(--shell-border)] bg-[var(--shell-panel)]">
        <table className="w-full text-left text-sm">
          <thead>
            <tr className="border-b border-[var(--shell-border)] text-[10px] uppercase tracking-wider text-[var(--shell-text-muted)]">
              <th className="px-4 py-3 font-medium">Date</th>
              <th className="px-4 py-3 font-medium text-right">Mention</th>
              <th className="px-4 py-3 font-medium text-right">Exposure</th>
              <th className="px-4 py-3 font-medium text-right">Weighted</th>
              <th className="px-4 py-3 font-medium text-right">Actions</th>
            </tr>
          </thead>
          <tbody>
            {snapshots.map((snap) => (
              <tr key={snap.id} className="border-b border-[var(--shell-border)]/50 transition-colors hover:bg-[var(--shell-panel-soft)]">
                <td className="whitespace-nowrap px-4 py-2.5 text-[var(--shell-text)]">{snap.capturedAt?.slice?.(0, 16)?.replace("T", " ") || "--"}</td>
                <td className="px-4 py-2.5 text-right tabular-nums text-[var(--shell-text-muted)]">{snap.metrics.mentionRate}%</td>
                <td className="px-4 py-2.5 text-right tabular-nums text-[var(--shell-text-muted)]">{snap.metrics.exposureRate}%</td>
                <td className="px-4 py-2.5 text-right tabular-nums text-[var(--shell-text-muted)]">{snap.metrics.weightedMentionRate}%</td>
                <td className="px-4 py-2.5 text-right text-xs text-[var(--shell-text-muted)]">
                  {(snap.actions ?? []).length > 0 ? `${snap.actions!.length} actions` : "--"}
                </td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>
    </div>
  );
}

// ── Forecast Tab ───────────────────────────────────────────

function ForecastTab({ diffDoc, snapshots }: { diffDoc: Record<string, unknown> | null; snapshots: Snapshot[] }) {
  const latest = snapshots[snapshots.length - 1] ?? null;
  const overallGapScore = (diffDoc?.overallGapScore as number) ?? 0;
  const dimensions = (diffDoc?.dimensions as Array<Record<string, unknown>>) ?? [];

  return (
    <div className="space-y-6">
      {/* Current metrics */}
      <div className="grid gap-4 sm:grid-cols-2 lg:grid-cols-4">
        <MetricCard icon={TrendingUp} label="Mention Rate" value={`${latest?.metrics.mentionRate ?? 0}%`} color="text-blue-600" />
        <MetricCard icon={TrendingUp} label="Exposure Rate" value={`${latest?.metrics.exposureRate ?? 0}%`} color="text-teal-600" />
        <MetricCard icon={Target} label="Gap Score" value={String(overallGapScore)} color={overallGapScore >= 70 ? "text-rose-500" : overallGapScore >= 35 ? "text-amber-500" : "text-emerald-600"} />
        <MetricCard icon={Target} label="Gap Dimensions" value={String(dimensions.length)} color="text-cyan-600" />
      </div>

      {/* Gap score hero */}
      {diffDoc && (
        <div className="rounded-2xl border border-[var(--shell-border)] bg-[var(--shell-panel)] p-6 text-center">
          <p className="text-xs text-[var(--shell-text-muted)]">Forecast: Gap to Close</p>
          <p className={`mt-1 text-5xl font-bold ${overallGapScore >= 70 ? "text-rose-500" : overallGapScore >= 35 ? "text-amber-500" : "text-emerald-600"}`}>
            {overallGapScore}<span className="text-lg text-[var(--shell-text-muted)]">/100</span>
          </p>
          <p className="mt-2 text-sm text-[var(--shell-text-muted)]">
            {overallGapScore >= 70 ? "Large gap -- significant improvement opportunity" : overallGapScore >= 35 ? "Moderate gap -- targeted improvements recommended" : "Small gap -- maintain current trajectory"}
          </p>
        </div>
      )}

      {/* Gap dimensions */}
      {dimensions.length > 0 && (
        <div className="rounded-2xl border border-[var(--shell-border)] bg-[var(--shell-panel)] p-5">
          <h3 className="text-sm font-semibold text-[var(--shell-text)]">Forecast by Dimension</h3>
          <div className="mt-3 space-y-3">
            {dimensions.map((dim, i) => {
              const severity = (dim.gapSeverity as number) ?? 0;
              const level = (dim.gapLevel as string) ?? "";
              const barColor = severity >= 70 ? "bg-rose-500" : severity >= 35 ? "bg-amber-500" : "bg-emerald-500";
              return (
                <div key={i} className="rounded-xl border border-[var(--shell-border)] bg-[var(--shell-panel-soft)] p-4">
                  <div className="flex items-center justify-between gap-3">
                    <span className="text-sm font-medium text-[var(--shell-text)]">{String(dim.dimension)}</span>
                    <span className={`rounded-md px-2 py-0.5 text-[10px] font-medium ${
                      level === "HIGH" ? "bg-rose-500/10 text-rose-500" : level === "MEDIUM" ? "bg-amber-500/10 text-amber-500" : "bg-emerald-500/10 text-emerald-600"
                    }`}>{level}</span>
                  </div>
                  <div className="mt-2 h-1.5 overflow-hidden rounded-full bg-[var(--shell-panel)]">
                    <div className={`h-full rounded-full ${barColor}`} style={{ width: `${severity}%` }} />
                  </div>
                  {dim.gapDescription != null && (
                    <p className="mt-2 text-xs text-[var(--shell-text-muted)]">{String(dim.gapDescription)}</p>
                  )}
                </div>
              );
            })}
          </div>
        </div>
      )}

      {!diffDoc && !latest && (
        <EmptyState icon={Target} title="No forecast data" description="분석을 실행하고 스냅샷을 찍으면 예측 추이를 볼 수 있습니다" />
      )}
    </div>
  );
}

// ── Action Impact Tab ──────────────────────────────────────

function ActionImpactTab({ actionRuns }: { actionRuns: ActionRun[] }) {
  const completed = actionRuns.filter((r) => r.status === "done" || r.status === "complete" || r.status === "completed" || r.status === "published");
  const withMetrics = completed.filter((r) => r.beforeMetrics && r.afterMetrics);

  return (
    <div className="space-y-6">
      <div className="grid gap-4 sm:grid-cols-3">
        <MetricCard icon={Zap} label="Completed Actions" value={String(completed.length)} color="text-emerald-600" />
        <MetricCard icon={Zap} label="With Metrics" value={String(withMetrics.length)} color="text-blue-600" />
        <MetricCard icon={Zap} label="Total Runs" value={String(actionRuns.length)} color="text-cyan-600" />
      </div>

      {/* Actions with before/after */}
      {withMetrics.length > 0 ? (
        <div className="space-y-4">
          {withMetrics.map((run) => {
            const mentionDelta = (run.afterMetrics!.mentionRate - run.beforeMetrics!.mentionRate);
            const exposureDelta = (run.afterMetrics!.exposureRate - run.beforeMetrics!.exposureRate);
            return (
              <div key={run.id} className="rounded-2xl border border-[var(--shell-border)] bg-[var(--shell-panel)] p-5">
                <div className="flex items-center justify-between gap-3">
                  <h4 className="text-sm font-medium text-[var(--shell-text)]">{run.title || run.id}</h4>
                  {run.platform && <span className="text-[10px] text-[var(--shell-text-muted)]">{run.platform}</span>}
                </div>
                <div className="mt-3 grid gap-3 sm:grid-cols-2">
                  <ImpactDelta label="Mention Rate" before={run.beforeMetrics!.mentionRate} after={run.afterMetrics!.mentionRate} delta={mentionDelta} />
                  <ImpactDelta label="Exposure Rate" before={run.beforeMetrics!.exposureRate} after={run.afterMetrics!.exposureRate} delta={exposureDelta} />
                </div>
              </div>
            );
          })}
        </div>
      ) : completed.length > 0 ? (
        <div className="rounded-2xl border border-[var(--shell-border)] bg-[var(--shell-panel)] p-5">
          <h3 className="text-sm font-semibold text-[var(--shell-text)]">Completed Actions ({completed.length})</h3>
          <p className="mt-1 text-xs text-[var(--shell-text-muted)]">Before/after metrics will be available once snapshots are taken around action execution</p>
          <div className="mt-3 space-y-2">
            {completed.slice(0, 10).map((run) => (
              <div key={run.id} className="flex items-center justify-between rounded-xl border border-[var(--shell-border)] bg-[var(--shell-panel-soft)] px-4 py-3">
                <span className="text-sm text-[var(--shell-text)]">{run.title || run.id}</span>
                <span className="rounded-md bg-emerald-500/10 px-2 py-0.5 text-[10px] font-medium text-emerald-600">{run.status}</span>
              </div>
            ))}
          </div>
        </div>
      ) : (
        <EmptyState icon={Zap} title="No action impact data" description="액션을 완료하고 스냅샷을 찍으면 전후 영향도를 추적할 수 있습니다" />
      )}
    </div>
  );
}

// ── Shared Components ──────────────────────────────────────

function TrendCard({ label, value, delta, snapshots, valueKey, color }: {
  label: string; value: string; delta?: number; snapshots: Snapshot[]; valueKey: keyof SnapshotMetrics; color: string;
}) {
  const values = snapshots.map((s) => s.metrics[valueKey] || 0);
  const max = Math.max(...values, 1);
  const points = values.map((v, i) => {
    const x = values.length === 1 ? 50 : (i / Math.max(values.length - 1, 1)) * 100;
    const y = 100 - (v / max) * 100;
    return `${x},${y}`;
  }).join(" ");

  return (
    <div className="rounded-2xl border border-[var(--shell-border)] bg-[var(--shell-panel)] p-5">
      <p className="text-[10px] uppercase tracking-wider text-[var(--shell-text-muted)]">{label}</p>
      <p className="mt-1 text-3xl font-semibold text-[var(--shell-text)]">{value}</p>
      {delta != null && (
        <p className={`mt-0.5 text-xs ${delta >= 0 ? "text-emerald-600" : "text-rose-500"}`}>
          {delta >= 0 ? "+" : ""}{delta}% vs previous
        </p>
      )}
      {snapshots.length > 1 && (
        <div className="mt-3">
          <svg viewBox="0 0 100 100" className="h-16 w-full overflow-visible">
            <polyline fill="none" stroke={color} strokeWidth="3" points={points} vectorEffect="non-scaling-stroke" />
            {values.map((v, i) => {
              const x = values.length === 1 ? 50 : (i / Math.max(values.length - 1, 1)) * 100;
              const y = 100 - (v / max) * 100;
              return <circle key={`${String(valueKey)}-${i}`} cx={x} cy={y} r="2" fill={color} />;
            })}
          </svg>
        </div>
      )}
    </div>
  );
}

function ImpactDelta({ label, before, after, delta }: { label: string; before: number; after: number; delta: number }) {
  return (
    <div className="rounded-xl border border-[var(--shell-border)] bg-[var(--shell-panel-soft)] p-3">
      <p className="text-[10px] uppercase tracking-wider text-[var(--shell-text-muted)]">{label}</p>
      <div className="mt-1 flex items-end gap-2">
        <span className="text-xs text-[var(--shell-text-muted)]">{before}%</span>
        <span className="text-[var(--shell-text-muted)]">→</span>
        <span className="text-sm font-semibold text-[var(--shell-text)]">{after}%</span>
        <span className={`text-xs font-medium ${delta >= 0 ? "text-emerald-600" : "text-rose-500"}`}>
          ({delta >= 0 ? "+" : ""}{delta}%)
        </span>
      </div>
    </div>
  );
}

function formatDate(raw?: { toDate?: () => Date } | Date | string): string {
  if (!raw) return "";
  let date: Date;
  if (typeof raw === "string") date = new Date(raw);
  else if (raw instanceof Date) date = raw;
  else if (typeof raw === "object" && "toDate" in raw && typeof raw.toDate === "function") date = raw.toDate();
  else return "";
  if (isNaN(date.getTime())) return "";
  return date.toLocaleDateString("en-US", { year: "numeric", month: "short", day: "numeric" });
}
