const KST_OFFSET_MS = 9 * 60 * 60 * 1000;

export function computeNextWeeklyRunAtKst(dayOfWeek: number, hourOfDay: number): Date {
  const nowUtcMs = Date.now();
  const nowKstMs = nowUtcMs + KST_OFFSET_MS;
  const nowKst = new Date(nowKstMs);

  const kstY = nowKst.getUTCFullYear();
  const kstM = nowKst.getUTCMonth();
  const kstD = nowKst.getUTCDate();
  const currentKstDay = nowKst.getUTCDay();

  let targetKstMs = Date.UTC(kstY, kstM, kstD, hourOfDay, 0, 0, 0);

  let diff = dayOfWeek - currentKstDay;
  if (diff < 0) diff += 7;
  if (diff === 0 && targetKstMs <= nowKstMs) diff += 7;

  targetKstMs += diff * 86400000;

  const targetUtcMs = targetKstMs - KST_OFFSET_MS;
  return new Date(targetUtcMs);
}
