// ─── Step 3 — 적중률 시계열 차트 (SVG) ─────────────────
function HitRateTrendChart({ trend }: { trend: Array<{ yearMonth: string; totalConverted: number; effective: number; hitRate: number }> }) {
  if (!trend || trend.length === 0) {
    return <div className="text-[11px] text-[var(--shell-text-muted)]">데이터 없음</div>;
  }

  const width = 720;
  const height = 160;
  const padding = { top: 8, right: 50, bottom: 30, left: 32 };
  const innerW = width - padding.left - padding.right;
  const innerH = height - padding.top - padding.bottom;

  // X = month index, dual Y: 좌측=count, 우측=hitRate %
  const maxCount = Math.max(1, ...trend.map((t) => t.totalConverted));
  const xFor = (i: number) => trend.length === 1
    ? padding.left + innerW / 2
    : padding.left + (i / (trend.length - 1)) * innerW;
  const yForRate = (v: number) => padding.top + (1 - v / 100) * innerH;
  const yForCount = (v: number) => padding.top + (1 - v / maxCount) * innerH;

  // Hit rate line points
  const hitRatePoints = trend.map((t, i) => `${xFor(i)},${yForRate(t.hitRate)}`).join(" ");

  return (
    <div className="w-full overflow-x-auto">
      <svg viewBox={`0 0 ${width} ${height}`} className="w-full" preserveAspectRatio="xMidYMid meet">
        {/* y-axis grid (좌: 0/25/50/75/100 %) */}
        {[0, 25, 50, 75, 100].map((y) => (
          <g key={y}>
            <line x1={padding.left} x2={width - padding.right} y1={yForRate(y)} y2={yForRate(y)} stroke="currentColor" strokeOpacity={0.08} strokeDasharray="2 4" />
            <text x={padding.left - 6} y={yForRate(y) + 3} textAnchor="end" className="fill-emerald-400 text-[9px]">{y}%</text>
          </g>
        ))}
        {/* y-axis right (count) */}
        <text x={width - padding.right + 6} y={padding.top + 4} textAnchor="start" className="fill-blue-400 text-[8px]">{maxCount}</text>
        <text x={width - padding.right + 6} y={height - padding.bottom} textAnchor="start" className="fill-blue-400 text-[8px]">0</text>

        {/* Count bars (좌측 y축) */}
        {trend.map((t, i) => {
          const barW = trend.length === 1 ? 30 : Math.max(8, innerW / trend.length - 4);
          const x = xFor(i) - barW / 2;
          const y = yForCount(t.totalConverted);
          const h = Math.max(0, height - padding.bottom - y);
          return (
            <g key={`b-${i}`}>
              <rect x={x} y={y} width={barW} height={h} fill="#60a5fa" fillOpacity={0.5} />
              {t.totalConverted > 0 && (
                <text x={xFor(i)} y={y - 3} textAnchor="middle" className="fill-blue-300 text-[9px] font-semibold">
                  {t.totalConverted}
                </text>
              )}
            </g>
          );
        })}

        {/* Hit rate line (우측 y축 = % 척도) */}
        {trend.length >= 2 && (
          <polyline points={hitRatePoints} fill="none" stroke="#34d399" strokeWidth="2" />
        )}
        {trend.map((t, i) => (
          <g key={`p-${i}`}>
            <circle cx={xFor(i)} cy={yForRate(t.hitRate)} r="4" fill="#34d399" stroke="white" strokeWidth="1.5" />
            {t.totalConverted > 0 && (
              <text x={xFor(i)} y={yForRate(t.hitRate) - 8} textAnchor="middle" className="fill-emerald-300 text-[9px] font-semibold">
                {t.hitRate.toFixed(0)}%
              </text>
            )}
          </g>
        ))}

        {/* X-axis labels */}
        {trend.map((t, i) => (
          <text key={`x-${i}`} x={xFor(i)} y={height - padding.bottom + 12} textAnchor="middle" className="fill-[var(--shell-text-soft)] text-[9px]">
            {t.yearMonth.slice(2)}
          </text>
        ))}
      </svg>
    </div>
  );
}

