import { getDoc, getDocs, query, where, orderBy, limit as fbLimit } from "firebase/firestore";
import { paths, SUMMARY_KEYS } from "../../../db/paths";
import type { DiagnosticCheck, DiagnosticRunner } from "./types";

const V3_COMMAND_TYPES = ["start_v3_measurement", "retry_v3_measurement"];

function extractIndexUrl(err: any): string | null {
  const msg = String(err?.message || err || "");
  const match = msg.match(/(https:\/\/console\.firebase\.google\.com\S+)/);
  return match ? match[1] : null;
}

async function safeGetV3Runs(boardId: string) {
  try {
    const snap = await getDocs(
      query(
        paths.runs(boardId),
        where("commandType", "in", V3_COMMAND_TYPES),
        orderBy("startedAt", "desc"),
        fbLimit(20),
      ),
    );
    return { docs: snap.docs, indexError: false, indexUrl: null as string | null };
  } catch (_e: any) {
    const indexUrl = extractIndexUrl(_e);
    const snap = await getDocs(query(paths.runs(boardId), fbLimit(50)));
    const filtered = snap.docs.filter((d) => {
      const ct = d.data().commandType;
      return V3_COMMAND_TYPES.includes(ct);
    });
    filtered.sort((a, b) => {
      const at = a.data().startedAt?.toDate?.() || new Date(a.data().startedAt || 0);
      const bt = b.data().startedAt?.toDate?.() || new Date(b.data().startedAt || 0);
      return bt.getTime() - at.getTime();
    });
    return { docs: filtered.slice(0, 20), indexError: true, indexUrl };
  }
}

function formatTs(v: any): string {
  if (!v) return "N/A";
  if (typeof v === "string") return v;
  if (v?.toDate) return v.toDate().toISOString();
  if (v?.seconds) return new Date(v.seconds * 1000).toISOString();
  return String(v);
}

export const runDashboardDiagnostics: DiagnosticRunner = async (boardId) => {
  const results: DiagnosticCheck[] = [];

  // --- GATE 1: summaries/measurement ---
  let summaryData: any = null;
  try {
    const snap = await getDoc(paths.summary(boardId, SUMMARY_KEYS.measurement));
    if (!snap.exists()) {
      results.push({ id: "g1-exists", label: "summaries/measurement 문서 존재", status: "fail", detail: "문서가 존재하지 않습니다. 서버에서 측정 완료 후 기록되지 않았을 수 있습니다." });
    } else {
      summaryData = snap.data();
      results.push({ id: "g1-exists", label: "summaries/measurement 문서 존재", status: "pass", detail: `writtenBy: ${summaryData?.writtenBy || "N/A"}, schemaVersion: ${summaryData?.schemaVersion || "N/A"}` });

      const hasRun = !!summaryData?.run;
      results.push({ id: "g1-run", label: "summaries/measurement.run 존재", status: hasRun ? "pass" : "warn", detail: hasRun ? `status: ${summaryData.run.status}, totalItems: ${summaryData.run.totalItems ?? "N/A"}` : "run 필드가 없습니다." });

      const hasAnalysis = !!summaryData?.analysis;
      results.push({ id: "g1-analysis", label: "summaries/measurement.analysis 존재", status: hasAnalysis ? "pass" : "fail", detail: hasAnalysis ? `brandMentionRate: ${summaryData.analysis.brandMentionRate ?? "N/A"}, engineBreakdown keys: ${Object.keys(summaryData.analysis.engineBreakdown || {}).join(", ") || "없음"}` : "analysis 필드가 null입니다. V3RealDashboardCard는 이 값이 없으면 '데이터 없음'을 표시합니다." });

      if (hasAnalysis) {
        const a = summaryData.analysis;
        const bmr = a.brandMentionRate;
        results.push({ id: "g1-rate", label: "brandMentionRate 값", status: bmr != null && bmr !== "" ? "pass" : "warn", detail: `값: ${JSON.stringify(bmr)} (parseFloat 결과: ${parseFloat(bmr as any) || 0})` });

        const wrd = a.weeklyReportData;
        results.push({ id: "g1-wrd", label: "weeklyReportData 존재", status: wrd ? "pass" : "warn", detail: wrd ? `globalEngine.totalQuestions: ${wrd?.globalEngine?.totalQuestions ?? "N/A"}, mentionPositionHistogram: ${JSON.stringify(wrd?.mentionPositionHistogram || "없음")}` : "weeklyReportData가 없습니다." });

        const eb = a.engineBreakdown || {};
        for (const eng of Object.keys(eb)) {
          const e = eb[eng];
          results.push({ id: `g1-eb-${eng}`, label: `engineBreakdown.${eng}`, status: (e?.total > 0 || e?.count > 0) ? "pass" : "warn", detail: `count: ${e?.count}, total: ${e?.total}, rate: ${e?.rate}` });
        }
      }
    }
  } catch (err: any) {
    results.push({ id: "g1-exists", label: "summaries/measurement 문서 존재", status: "fail", detail: `에러: ${err.message}` });
  }

  // --- GATE 2: runs 컬렉션 ---
  let runDocs: any[] = [];
  try {
    const { docs, indexError, indexUrl } = await safeGetV3Runs(boardId);
    runDocs = docs.map((d) => ({ id: d.id, ...d.data() }));
    const indexNote = indexError ? " (composite index 미생성 — fallback 사용)" : "";
    results.push({ id: "g2-runs", label: `V3 runs 개수 (commandType in ${V3_COMMAND_TYPES.join(", ")})`, status: runDocs.length > 0 ? "pass" : "fail", detail: `${runDocs.length}개 found${indexNote}` });
    if (indexError) {
      results.push({
        id: "g2-index",
        label: "Firestore composite index 필요",
        status: "warn",
        detail: "runs 컬렉션에 commandType + startedAt 복합 인덱스가 없습니다. 현재 fallback으로 동작하지만 성능이 떨어집니다.",
        link: indexUrl ? { url: indexUrl, text: "인덱스 생성하기 (Firebase Console)" } : undefined,
      });
    }

    for (const run of runDocs.slice(0, 5)) {
      const statusOk = run.status !== "pending";
      results.push({
        id: `g2-run-${run.id}`,
        label: `run/${run.id.slice(0, 8)}... 상태`,
        status: statusOk ? "pass" : "warn",
        detail: `status: ${run.status}, commandType: ${run.commandType}, totalItems: ${run.totalItems ?? "N/A"}, totalCalls: ${run.totalCalls ?? "N/A"}, startedAt: ${formatTs(run.startedAt)}, completedAt: ${formatTs(run.completedAt)}`,
      });
    }
  } catch (err: any) {
    results.push({ id: "g2-runs", label: "V3 runs 조회", status: "fail", detail: `에러: ${err.message}` });
  }

  // --- GATE 2.5: 직접 run doc 읽기 (쿼리 없이) ---
  if (runDocs.length === 0) {
    try {
      const allSnap = await getDocs(query(paths.runs(boardId), fbLimit(10)));
      const allRuns = allSnap.docs.map((d) => ({ id: d.id, ...d.data() }));
      if (allRuns.length > 0) {
        results.push({ id: "g2-all-runs", label: "runs 컬렉션 전체 (commandType 무관)", status: "warn", detail: `${allRuns.length}개 존재. commandType 값: ${[...new Set(allRuns.map((r: any) => r.commandType))].join(", ")}` });
        for (const run of allRuns.slice(0, 3)) {
          results.push({
            id: `g2-raw-${run.id}`,
            label: `run/${run.id.slice(0, 8)}... (raw)`,
            status: "warn",
            detail: `commandType: "${(run as any).commandType}", status: "${(run as any).status}", totalItems: ${(run as any).totalItems ?? "N/A"}`,
          });
        }
      } else {
        results.push({ id: "g2-all-runs", label: "runs 컬렉션 전체", status: "fail", detail: "runs 컬렉션에 문서가 하나도 없습니다." });
      }
    } catch (e: any) {
      results.push({ id: "g2-all-runs", label: "runs 컬렉션 전체 조회", status: "fail", detail: `에러: ${e.message}` });
    }
  }

  // --- GATE 3: analyses/v3/measurements/{runId} ---
  let analysisCount = 0;
  for (const run of runDocs.slice(0, 5)) {
    try {
      const snap = await getDoc(paths.v3MeasurementAnalysis(boardId, run.id));
      if (snap.exists()) {
        analysisCount++;
        const data = snap.data() as any;
        results.push({
          id: `g3-analysis-${run.id}`,
          label: `analyses/v3/measurements/${run.id.slice(0, 8)}...`,
          status: "pass",
          detail: `brandMentionRate: ${data.brandMentionRate ?? "N/A"}, engineBreakdown keys: ${Object.keys(data.engineBreakdown || {}).join(", ") || "없음"}, weeklyReportData: ${data.weeklyReportData ? "있음" : "없음"}`,
        });
      } else {
        results.push({
          id: `g3-analysis-${run.id}`,
          label: `analyses/v3/measurements/${run.id.slice(0, 8)}...`,
          status: "fail",
          detail: "문서 없음. getTrend에서 이 run은 스킵됩니다.",
        });
      }
    } catch (err: any) {
      results.push({
        id: `g3-analysis-${run.id}`,
        label: `analyses/v3/measurements/${run.id.slice(0, 8)}...`,
        status: "fail",
        detail: `에러: ${err.message}`,
      });
    }
  }

  // --- GATE 4: getTrend derivedTotal ---
  const nonPendingRuns = runDocs.filter((r) => r.status !== "pending");
  results.push({
    id: "g4-nonpending",
    label: "status !== 'pending'인 run 수",
    status: nonPendingRuns.length > 0 ? "pass" : "fail",
    detail: `전체 ${runDocs.length}개 중 ${nonPendingRuns.length}개 (pending 제외)`,
  });

  results.push({
    id: "g4-with-analysis",
    label: "analysis 문서가 있는 run 수 (= 추세 포인트 수)",
    status: analysisCount > 0 ? (analysisCount >= 2 ? "pass" : "warn") : "fail",
    detail: `${analysisCount}개 (1개: 숫자 카드, 2개 이상: 라인 차트)`,
  });

  return results;
};
